/* Cytaty z aktow prawnych – generowane automatycznie z PDF-ow w akty/ (build_quotes.py).
   kind: 'akt' = doslowny cytat przepisu; 'norma'/'ue' = cytat niedostepny. */
window.QUOTES = {"1": [{"ref": "N SEP-E-004:2014 – definicja szybu kablowego", "kind": "norma"}], "2": [{"ref": "§ 27 RPB – obiekty wymagające stosowania stałych urządzeń gaśniczych", "kind": "akt", "act": "rpb", "label": "§ 27", "text": "§ 27. […] 2) muzeach oraz zabytkach budowlanych, wyznaczonych przez Generalnego Konserwatora Zabytków w uzgodnieniu z Komendantem Głównym Państwowej Straży Pożarnej; 3) ośrodkach elektronicznego przetwarzania danych o znaczeniu krajowym. 2. Stosowanie stałych samoczynnych urządzeń gaśniczych wodnych jest wymagane w: 1) budynkach handlowych lub wystawowych: a) jednokondygnacyjnych, w strefie pożarowej zakwalifikowanej do kategorii zagrożenia ludzi ZL I o powierzchni powyżej 8000 m2, b) wielokondygnacyjnych, w strefie pożarowej zakwalifikowanej do kategorii zagrożenia ludzi ZL I o powierzchni powyżej 5000 m2; 2) w budynkach o liczbie miejsc służących celom gastronomicznym powyżej 600; 3) budynkach użyteczności publicznej wysokościowych; 4) budynkach zamieszkania zbiorowego wysokościowych. 3. […]"}], "3": [{"ref": "PN-EN 12845 – urządzenia tryskaczowe, oddzielenia", "kind": "norma"}], "4": [{"ref": "§ 259 ust. 1 pkt 1 WT – klasa odporności ogniowej podłóg podniesionych", "kind": "akt", "act": "wt", "label": "§ 259", "text": "§ 259. 1. Podłogi podniesione o więcej niż 0,2 m ponad poziom stropu lub innego podłoża powinny mieć: 1) niepalną konstrukcję nośną oraz co najmniej niezapalne płyty podłogi od strony przestrzeni podpodłogowej, mające klasę odporności ogniowej co najmniej R E I 30, a w budynku wysokościowym (WW) lub ze strefą pożarową o gęstości obciążenia ogniowego ponad 4000 MJ/m2 oraz w strefach pożarowych ZL II – co najmniej R E I 60; 2) przestrzeń podpodłogową podzieloną na sektory o powierzchni nie większej niż 1000 m2 przegrodami o klasie odporności ogniowej co najmniej E I 30, a w budynku wysokościowym (WW) lub ze strefą pożarową o gęstości obciążenia ogniowego ponad 4000 MJ/m2 – co najmniej E I 60."}], "5": [{"ref": "PN-EN 13200-1:2013 – obiekty widowiskowe, ewakuacja", "kind": "norma"}], "6": [{"ref": "§ 234 WT – ściany oddzielenia przeciwpożarowego a przekrycie dachu", "kind": "akt", "act": "wt", "label": "§ 234", "text": "§ 234. 1. Przepusty instalacyjne w elementach oddzielenia przeciwpożarowego powinny mieć klasę odporności ogniowej (E I) wymaganą dla tych elementów. 2. Dopuszcza się nieinstalowanie przepustów, o których mowa w ust. 1, dla pojedynczych rur instalacji wodnych, kanalizacyjnych i ogrzewczych, wprowadzanych przez ściany i stropy do pomieszczeń higienicznosanitarnych. 3. Przepusty instalacyjne o średnicy większej niż 0,04 m w ścianach i stropach pomieszczenia zamkniętego, dla których wymagana klasa odporności ogniowej jest nie niższa niż E I 60 lub R E I 60, a niebędących elementami oddzielenia przeciwpożarowego, powinny mieć klasę odporności ogniowej (E I) ścian i stropów tego pomieszczenia. 4. Przejścia instalacji przez zewnętrzne ściany budynku, znajdujące się poniżej poziomu terenu, powinny być zabezpieczone przed możliwością przenikania gazu do wnętrza budynku."}], "8": [{"ref": "§ 216, § 230 WT – warunki obniżenia wymagań przy zastosowaniu urządzeń gaśniczych", "kind": "akt", "act": "wt", "label": "§ 216", "text": "§ 216. […] 3) ścian zewnętrznych w budynku niskim ZL IV. 3. Dopuszcza się stosowanie w budynku PM ścian zewnętrznych klasy D z rdzeniem klasy E z uwagi na reakcję na ogień, jeżeli okładzina wewnętrzna jest niepalna, a ściana jest nierozprzestrzeniająca ognia przy działaniu ognia od strony elewacji. 4. Dopuszcza się stosowanie w budynku PM ścian wewnętrznych klasy D z uwagi na reakcję na ogień. 5. W ścianach zewnętrznych budynku ZL II dopuszcza się, z zastrzeżeniem ust. 8, zastosowanie izolacji cieplnej palnej, jeżeli osłaniająca ją od wewnątrz okładzina jest niepalna i ma klasę odporności ogniowej co najmniej: 1) w budynku klasy odporności pożarowej „B” – E I 60; 2) w budynku klasy odporności pożarowej „C” i „D” – E I 30. 6. Dopuszcza się stosowanie klap dymowych z materiałów łatwo zapalnych w dachach i stropodachach. 7. […]"}], "9": [{"ref": "PN-EN 12845 / NFPA – instalacje tryskaczowe ESFR", "kind": "norma"}], "10": [{"ref": "PN-EN 15004 – stałe urządzenia gaśnicze gazowe, czas retencji", "kind": "norma"}], "11": [{"ref": "PN-EN 13501-6 – klasyfikacja reakcji na ogień kabli (indeks „ca”)", "kind": "norma"}], "12": [{"ref": "§ 276 ust. 1 WT – usytuowanie garażu zamkniętego i otwartego", "kind": "akt", "act": "wt", "label": "§ 276", "text": "§ 276. 1. Usytuowanie garażu zamkniętego i otwartego powinno odpowiadać warunkom określonym w § 271 jak dla budynków PM o gęstości obciążenia ogniowego do 1000 MJ/m2, z zastrzeżeniem § 19."}, {"ref": "§ 271 WT – odległości między budynkami ze względu na bezpieczeństwo pożarowe", "kind": "akt", "act": "wt", "label": "§ 271", "text": "§ 271. 1. Odległość między zewnętrznymi ścianami budynków niebędącymi ścianami oddzielenia przeciwpożarowego, a mającymi na powierzchni większej niż 65% klasę odporności ogniowej (E), określoną w § 216 ust. 1 w 5 kolumnie tabeli, nie powinna, z zastrzeżeniem ust. 2 i 3, być mniejsza niż odległość w metrach określona w poniższej tabeli: Rodzaj budynku oraz dla budynku PM maksymalna gęstość obciążenia ogniowego strefy pożarowej PM Q w MJ/m2 Rodzaj budynku oraz dla budynku PM maksymalna gęstość obciążenia ogniowego strefy pożarowej PM Q w MJ/m2 ZL IN PM Q ≤ 1000 1000 < Q ≤ 4000 Q > 4000 1 2 3 4 5 6 ZL 8 8 8 15 20 IN 8 8 8 15 20 PM Q ≤ 1000 8 8 8 15 20 PM 1000 < Q ≤ 4000 15 15 15 15 20 PM Q > 4000 20 20 20 20 20 2. […]"}], "13": [{"ref": "§ 157 ust. 5 WT – gaz płynny tylko w budynkach niskich", "kind": "akt", "act": "wt", "label": "§ 157", "text": "5. Instalacje gazowe zasilane gazem płynnym mogą być wykonywane tylko w budynkach niskich."}, {"ref": "§ 8 WT – grupy wysokości budynków", "kind": "akt", "act": "wt", "label": "§ 8", "text": "§ 8. W celu określenia wymagań technicznych i użytkowych wprowadza się następujący podział budynków na grupy wysokości: 1) niskie (N) – do 12 m włącznie nad poziomem terenu lub mieszkalne o wysokości do 4 kondygnacji nadziemnych włącznie; 2) średniowysokie (SW) – ponad 12 m do 25 m włącznie nad poziomem terenu lub mieszkalne o wysokości ponad 4 do 9 kondygnacji nadziemnych włącznie; 3) wysokie (W) – ponad 25 m do 55 m włącznie nad poziomem terenu lub mieszkalne o wysokości ponad 9 do 18 kondygnacji nadziemnych włącznie; 4) wysokościowe (WW) – powyżej 55 m nad poziomem terenu."}], "14": [{"ref": "PN-EN 12845 – rozmieszczenie tryskaczy", "kind": "norma"}], "15": [{"ref": "§ 37 RPB – ocena zagrożenia wybuchem i wyznaczanie stref", "kind": "norma"}], "16": [{"ref": "PN-EN 12845 / § 20 RPB – zasilanie hydrantów wewnętrznych", "kind": "norma"}], "17": [{"ref": "N SEP-E-005 – przeciwpożarowy wyłącznik prądu (PWP)", "kind": "norma"}], "19": [{"ref": "§ 83 rozp. MI z 16.05.2023 (metro) – przeciwpożarowy wyłącznik prądu na stacji metra", "kind": "akt", "act": "metro", "label": "§ 83", "text": "§ 83. 1. Rozdzielnica zasilająca urządzenia telekomunikacyjne powinna być zasilana przez rezerwowe źródło zasilania o czasie podtrzymania napięcia nie krótszym niż 3 godziny. 2. Rozdzielnica zasilająca urządzenia srp powinna być zasilana przez przetwornicę o czasie podtrzymania napięcia przynajmniej 30 minut. 3. Przewody i kable elektryczne w tunelu powinny być ułożone w korytkach nad rurami wodociągowymi i kanalizacyjnymi oraz nad korytkami z kablami słaboprądowymi, lecz poniżej korytek z kablami średniego napięcia."}, {"ref": "§ 85 rozp. MI z 17.06.2011 (metro) – brzmienie poprzednie", "kind": "akt", "act": "metro", "label": "§ 85", "text": "§ 85. Na stacji metra w dyspozytorni stacji instaluje się przeciwpożarowy wyłącznik prądu odcinający dopływ energii elektrycznej do wszystkich odbiorników na stacji metra, z wyjątkiem obwodów zasilających instalacje i urządzenia, których funkcjonowanie jest niezbędne w czasie pożaru i prowadzenia akcji ratowniczo-gaśniczej."}], "21": [{"ref": "§ 214 WT – obniżenie klasy odporności pożarowej przy urządzeniach gaśniczych wodnych", "kind": "akt", "act": "wt", "label": "§ 214", "text": "§ 214. W budynkach wyposażonych w stałe samoczynne urządzenia gaśnicze wodne, z wyjątkiem budynków ZL II oraz wielokondygnacyjnych budynków wysokich (W) i wysokościowych (WW), dopuszcza się: 1) obniżenie klasy odporności pożarowej budynku o jedną w stosunku do wynikającej z § 212; 2) przyjęcie klasy „E” odporności pożarowej dla budynku jednokondygnacyjnego."}, {"ref": "§ 212 ust. 2 WT – klasy odporności pożarowej budynków ZL", "kind": "akt", "act": "wt", "label": "§ 212", "text": "2. Wymaganą klasę odporności pożarowej dla budynku, zaliczonego do jednej kategorii ZL, określa poniższa tabela: Budynek ZL I ZL II ZL III ZL IV ZL V 1 2 3 4 5 6 niski (N) „B” „B” „C” „D” „C” średniowysoki (SW) „B” „B” „B” „C” „B” wysoki (W) „B” „B” „B” „B” „B” wysokościowy (WW) „A” „A” „A” „B” „A”"}], "22": [{"ref": "§ 256 ust. 7 WT – droga od wyjścia z klatki schodowej do wyjścia na zewnątrz", "kind": "akt", "act": "wt", "label": "§ 256", "text": "7. Dopuszczalną długość drogi od wyjścia z klatki schodowej, o której mowa w ust. 2, do wyjścia na zewnątrz budynku określa się zgodnie z ust. 3."}, {"ref": "§ 256 ust. 3 WT – dopuszczalne długości dojść ewakuacyjnych", "kind": "akt", "act": "wt", "label": "§ 256", "text": "3. Dopuszczalne długości dojść ewakuacyjnych w strefach pożarowych określa poniższa tabela: Rodzaj strefy pożarowej Długość dojścia w m przy jednym dojściu przy co najmniej 2 dojściach1) 1 2 3 Z pomieszczeniem zagrożonym wybuchem 10 40 PM o gęstości obciążenia ogniowego Q > 500 MJ/m2 bez pomieszczenia zagrożonego wybuchem 302) 60 PM o gęstości obciążenia ogniowego Q ≤ 500 MJ/m2 bez pomieszczenia zagrożonego wybuchem 602) 100 ZL I, II i V 10 40 ZL III 302) 60 ZL IV 602) 100 1) Dla dojścia najkrótszego, przy czym dopuszcza się dla drugiego dojścia długość większą o 100% od najkrótszego. Dojścia te nie mogą się pokrywać ani krzyżować, przy czym dopuszcza się ich wspólny początkowy przebieg na długości nie większej niż 2 m. 2) W tym nie więcej niż 20 m na poziomej drodze ewakuacyjnej."}], "23": [{"ref": "PN-EN ISO 7010:2012 – zarejestrowane znaki bezpieczeństwa", "kind": "norma"}, {"ref": "PN-N-01256-01:1992 – znaki bezpieczeństwa, ochrona przeciwpożarowa (zastąpiona)", "kind": "norma"}], "25": [{"ref": "§ 249 WT – przeszklenia w narożach i przy oddzieleniach", "kind": "akt", "act": "wt", "label": "§ 249", "text": "§ 249. 1. Ściany wewnętrzne i stropy stanowiące obudowę klatki schodowej lub pochylni powinny mieć klasę odporności ogniowej określoną zgodnie z § 216, jak dla stropów budynku. 2. (uchylony). 3. Biegi i spoczniki schodów oraz pochylnie służące do ewakuacji powinny być wykonane z materiałów niepalnych i mieć klasę odporności ogniowej co najmniej: 1) w budynkach o klasie odporności pożarowej „A”, „B” i „C” – R 60; 2) w budynkach o klasie odporności pożarowej „D” i „E” – R 30. 4. Wymaganie klasy odporności ogniowej, o którym mowa w ust. 3, nie dotyczy klatek schodowych wydzielonych na każdej kondygnacji przedsionkami przeciwpożarowymi oraz schodów na antresolę w pomieszczeniu, w którym się ona znajduje, jeżeli antresola ta jest przeznaczona do użytku nie więcej niż 10 osób. 5. […]"}], "26": [{"ref": "PN-B / wytyczne oddymiania klatek schodowych", "kind": "norma"}], "27": [{"ref": "§ 24 ust. 3 RPB – zmniejszenie pojemności zbiorników w budynkach wysokich", "kind": "akt", "act": "rpb", "label": "§ 24", "text": "3. Dopuszcza się: 1) zmniejszenie pojemności zbiorników, o których mowa w ust. 2, do 50 m3, w przypadku budynków wysokich i wysokościowych o wysokości do 100 m: a) zawierających na wysokości powyżej 12 m jedynie strefy pożarowe zakwalifikowane do kategorii zagrożenia ludzi ZL IV, niezależnie od ich powierzchni, lub b) niezawierających stref pożarowych o powierzchni przekraczającej 750 m2; 2) stosowanie jednego wspólnego zbiornika o pojemności co najmniej 100 m3 dla grupy budynków wysokich i wysokościowych wzniesionych obok siebie, jeżeli zbiornik nie jest oddalony od żadnego z budynków o więcej niż 100 m; 3) stosowanie zbiorników o pojemności zmniejszonej niż wymienione w: a) ust. 2 i ust. 3 pkt 2 ‒ do 50 m3 w przypadku zapewnienia zasilania tych zbiorników w wodę z zewnętrznej sieci wodociągowej przeciwpożarowej o wydajności nie mniejszej niż 10 dm3/s, b) ust. 2 i ust. […]"}, {"ref": "§ 24 ust. 4 RPB – zasilanie bez zbiornika w budynkach wysokich ZL IV", "kind": "akt", "act": "rpb", "label": "§ 24", "text": "4. Dla budynków wysokich zakwalifikowanych do kategorii zagrożenia ludzi ZL IV dopuszcza się zasilanie instalacji wodociągowej przeciwpożarowej bezpośrednio z zewnętrznej sieci wodociągowej przeciwpożarowej o wydajności nie mniejszej niż 10 dm3/s, bez konieczności zapewnienia zbiorników, o których mowa w ust. 2 i 3."}], "29": [{"ref": "§ 12 RW – promień zewnętrznej krawędzi łuku drogi pożarowej ≥ 11 m", "kind": "akt", "act": "rw", "label": "§ 12", "text": "§ 12. […] 9. Droga pożarowa powinna zapewniać przejazd bez cofania lub powinna być zakończona placem manewrowym o wymiarach 20 m x 20 m, względnie można przewidzieć inne rozwiązania umożliwiające zawrócenie pojazdu, z zastrzeżeniem ust. 10. 10. Dopuszcza się wykonanie odcinka drogi pożarowej o długości nie większej niż 15 m, z którego wyjazd jest możliwy jedynie przez cofanie pojazdu. 11. Najmniejszy promień zewnętrznego łuku drogi pożarowej nie może wynosić mniej niż 11 m. 12. Drogi pożarowe oraz place manewrowe w miejscach innych niż wymienione w ust. 2 i 3 mogą być usytuowane w odległości mniejszej niż 5 m od chronionego budynku, pod warunkiem że ściana zewnętrzna budynku na tym odcinku oraz w odległości do 5 m od niego posiada klasę odporności ogniowej wymaganą dla ściany oddzielenia pożarowego tego budynku."}], "30": [{"ref": "PN-EN 1838 – oświetlenie awaryjne; § 181 WT", "kind": "norma"}], "31": [{"ref": "§ 37 RPB – pomieszczenia uznane za zagrożone wybuchem", "kind": "akt", "act": "rpb", "label": "§ 37", "text": "§ 37. […] U. poz. 1004 oraz z 2006 r. poz. 836)6). 6. Klasyfikację stref zagrożenia wybuchem określa Polska Norma dotycząca zapobiegania wybuchowi i ochronie przed wybuchem. 7. Pomieszczenie, w którym może wytworzyć się mieszanina wybuchowa, powstała z wydzielającej się takiej ilości palnych gazów, par, mgieł lub pyłów, której wybuch mógłby spowodować przyrost ciśnienia w tym pomieszczeniu przekraczający 5 kPa, określa się jako pomieszczenie zagrożone wybuchem. 8. Wytyczne w zakresie określania przyrostu ciśnienia w pomieszczeniu, jaki mógłby zostać spowodowany przez wybuch, określa załącznik do rozporządzenia. 9. W pomieszczeniu należy wyznaczyć strefę zagrożenia wybuchem, jeżeli może w nim występować mieszanina wybuchowa o objętości co najmniej 0,01 m3 w zwartej przestrzeni. […]"}], "32": [{"ref": "§ 239 WT – szerokość drzwi ewakuacyjnych", "kind": "akt", "act": "wt", "label": "§ 239", "text": "§ 239. 1. Łączną szerokość drzwi w świetle, stanowiących wyjścia ewakuacyjne z pomieszczenia, należy obliczać proporcjonalnie do liczby osób mogących przebywać w nim równocześnie, przyjmując co najmniej 0,6 m szerokości na 100 osób, przy czym najmniejsza szerokość drzwi w świetle ościeżnicy powinna wynosić 0,9 m, a w przypadku drzwi służących do ewakuacji do 3 osób – 0,8 m. 2. Drzwi stanowiące wyjście ewakuacyjne powinny otwierać się na zewnątrz pomieszczeń: 1) zagrożonych wybuchem; 2) do których jest możliwe niespodziewane przedostanie się mieszanin wybuchowych lub substancji trujących, duszących bądź innych, mogących utrudnić ewakuację; 3) przeznaczonych do jednoczesnego przebywania ponad 50 osób; 4) przeznaczonych dla ponad 6 osób o ograniczonej zdolności poruszania się. 3. […]"}], "33": [{"ref": "§ 237 WT – długość przejścia ewakuacyjnego i powiększenia", "kind": "akt", "act": "wt", "label": "§ 237", "text": "§ 237. 1. W pomieszczeniach, od najdalszego miejsca, w którym może przebywać człowiek, do wyjścia ewakuacyjnego na drogę ewakuacyjną lub do innej strefy pożarowej albo na zewnątrz budynku, powinno być zapewnione przejście, zwane dalej „przejściem ewakuacyjnym”, o długości nieprzekraczającej: 1) w strefach pożarowych ZL – 40 m; 2) w strefach pożarowych PM o gęstości obciążenia ogniowego przekraczającej 500 MJ/m2 w budynku o więcej niż jednej kondygnacji nadziemnej – 75 m; 3) w strefach pożarowych PM, o obciążeniu ogniowym nieprzekraczającym 500 MJ/m2, w budynku o więcej niż jednej kondygnacji nadziemnej oraz w strefach pożarowych PM w budynku o jednej kondygnacji nadziemnej bez względu na wielkość obciążenia ogniowego – 100 m. 2. W pomieszczeniu zagrożonym wybuchem długość przejścia ewakuacyjnego, o którym mowa w ust. 1 pkt 2 i 3, nie powinna przekraczać 40 m. 3. […]"}], "34": [{"ref": "PN-EN 12101-6 – systemy różnicowania ciśnień, wyposażenie rezerwowe", "kind": "norma"}], "35": [{"ref": "§ 212 ust. 2 i 3 WT – wymagana klasa odporności pożarowej i jej obniżenie", "kind": "akt", "act": "wt", "label": "§ 212", "text": "2. Wymaganą klasę odporności pożarowej dla budynku, zaliczonego do jednej kategorii ZL, określa poniższa tabela: Budynek ZL I ZL II ZL III ZL IV ZL V 1 2 3 4 5 6 niski (N) „B” „B” „C” „D” „C” średniowysoki (SW) „B” „B” „B” „C” „B” wysoki (W) „B” „B” „B” „B” „B” wysokościowy (WW) „A” „A” „A” „B” „A”"}, {"ref": "§ 212 ust. 6 i 7 WT – budynek o kondygnacjach różnych kategorii", "kind": "akt", "act": "wt", "label": "§ 212", "text": "6. W budynku wielokondygnacyjnym, którego kondygnacje są zaliczone do różnych kategorii ZL lub PM, klasy odporności pożarowej określa się dla poszczególnych kondygnacji odrębnie, zgodnie z zasadami określonymi w ust. 2–4."}], "36": [{"ref": "§ 15 RW – prześwit pod wiaduktami i estakadami nad drogą pożarową", "kind": "akt", "act": "rw", "label": "§ 15", "text": "§ 15. Wiadukty, estakady, przejścia i inne podobne urządzenia lub stałe elementy, usytuowane ponad drogami pożarowymi, powinny mieć prześwit o wysokości i szerokości nie mniejszej niż 4,5 m."}, {"ref": "§ 14 ust. 1 RW – wymiary przejazdów na dziedzińce", "kind": "akt", "act": "rw", "label": "§ 14", "text": "§ 14. 1. Przejazdy na dziedzińce i inne tereny obudowane powinny odpowiadać następującym warunkom: 1) wysokość przejazdu nie mniejsza niż 4,2 m, a w budownictwie jednorodzinnym — 3,2 m; 2) szerokość przejazdu nie mniejsza niż 3,6 m, w tym szerokość jezdni co najmniej 3 m; 3) odległość między przejazdami na jeden dziedziniec nie większa niż 150 m."}], "37": [{"ref": "§ 3–5 RW – przypadki niewymagające zewnętrznego zaopatrzenia w wodę", "kind": "akt", "act": "rw", "label": "§ 3", "text": "§ 3. […] 2) budynków użyteczności publicznej i zamieszkania zbiorowego oraz obiektów budowlanych produkcyjnych i magazynowych, znajdujących się poza granicami jednostek osadniczych wymienionych w pkt 1, o kubaturze brutto przekraczającej 2 500 m3 lub o powierzchni przekraczającej 500 m2, z wyjątkiem stacji paliw płynnych ze zbiornikami o łącznej pojemności do 200 m3 i stacji gazu płynnego; 3) obiektów budowlanych niebędących budynkami, przeznaczonych na potrzeby użyteczności publicznej lub do zamieszkania zbiorowego, w których znajduje się strefa pożarowa o powierzchni przekraczającej 1 000 m2 lub przeznaczona do jednoczesnego przebywania ponad 50 osób; 4) obiekty budowlane gospodarki rolnej o powierzchni strefy pożarowej przekraczającej 1 000 m2. 2. […]"}], "38": [{"ref": "§ 5 RW – wymagana ilość wody do zewnętrznego gaszenia pożaru", "kind": "akt", "act": "rw", "label": "§ 5", "text": "§ 5. 1. Wymagana ilość wody do celów przeciwpożarowych do zewnętrznego gaszenia pożaru dla budynków użyteczności publicznej i zamieszkania zbiorowego oraz innych obiektów budowlanych o takim przeznaczeniu, służąca do zewnętrznego gaszenia pożaru, wynosi: 1) dla budynku o kubaturze brutto do 5 000 m3 i o powierzchni wewnętrznej do 1 000 m2 — 10 dm3/s z co najmniej jednego hydrantu o średnicy 80 mm lub 100 m3 zapasu wody w przeciwpożarowym zbiorniku wodnym; 2) dla budynków niewymienionych w pkt 1 — 20 dm3/s łącznie z co najmniej dwóch hydrantów o średnicy 80 mm lub 200 m3 zapasu wody w przeciwpożarowym zbiorniku wodnym; 3) dla obiektów wymienionych w § 3 ust. 1 pkt 3 — 10 dm3/s z co najmniej jednego hydrantu o średnicy 80 mm lub 100 m3 zapasu wody w przeciwpożarowym zbiorniku wodnym. 2. […]"}], "40": [{"ref": "PKN-CEN/TS 54-14 – systemy sygnalizacji pożarowej, poziomy dźwięku", "kind": "norma"}], "41": [{"ref": "art. 56 ust. 1 Pb – zawiadomienie PSP o zakończeniu budowy", "kind": "akt", "act": "pb", "label": "art. 56", "text": "1. Inwestor, w stosunku do którego nałożono obowiązek uzyskania pozwolenia na użytkowanie obiektu budowlanego, jest obowiązany zawiadomić, zgodnie z właściwością wynikającą z przepisów szczególnych, organy: 1) (uchylony) 2) Państwowej Inspekcji Sanitarnej, 3) (uchylony) 4) Państwowej Straży Pożarnej – o zakończeniu budowy obiektu budowlanego i zamiarze przystąpienia do jego użytkowania. Organy zajmują stanowisko w sprawie zgodności wykonania obiektu budowlanego z projektem budowlanym. 1a. Przepisy ust. 1 stosuje się również w przypadku, gdy projekt budowlany obiektu budowlanego nieobjętego obowiązkiem uzyskania pozwolenia na użytkowanie wymagał uzgodnienia pod względem ochrony przeciwpożarowej lub wymagań higienicznych i zdrowotnych."}, {"ref": "art. 56 ust. 1a Pb – obiekty bez pozwolenia na użytkowanie z uzgodnionym projektem", "kind": "akt", "act": "pb", "label": "art. 56", "text": "1. Inwestor, w stosunku do którego nałożono obowiązek uzyskania pozwolenia na użytkowanie obiektu budowlanego, jest obowiązany zawiadomić, zgodnie z właściwością wynikającą z przepisów szczególnych, organy: 1) (uchylony) 2) Państwowej Inspekcji Sanitarnej, 3) (uchylony) 4) Państwowej Straży Pożarnej – o zakończeniu budowy obiektu budowlanego i zamiarze przystąpienia do jego użytkowania. Organy zajmują stanowisko w sprawie zgodności wykonania obiektu budowlanego z projektem budowlanym. 1a. Przepisy ust. 1 stosuje się również w przypadku, gdy projekt budowlany obiektu budowlanego nieobjętego obowiązkiem uzyskania pozwolenia na użytkowanie wymagał uzgodnienia pod względem ochrony przeciwpożarowej lub wymagań higienicznych i zdrowotnych."}], "42": [{"ref": "§ 10 RW – rozmieszczenie hydrantów zewnętrznych", "kind": "akt", "act": "rw", "label": "§ 10", "text": "§ 10. […] 2) od zewnętrznej krawędzi jezdni drogi lub ulicy — do 15 m; 3) najbliższego hydrantu od chronionego obiektu budowlanego — do 75 m; 4) innych niż wymienione w pkt 3 hydrantów wymaganych do ochrony obiektu budowlanego — do 150 m; 5) od ściany chronionego budynku — co najmniej 5 m. 7. Poza obszarami miejskimi odległość między hydrantami powinna być dostosowana do gęstości istniejącej i planowanej zabudowy. 8. Wydajność nominalna hydrantu zewnętrznego, przy ciśnieniu nominalnym 0,2 MPa mierzonym na zaworze hydrantowym podczas poboru wody, w zależności od jego średnicy nominalnej (DN), nie może być mniejsza niż: 1) dla hydrantu nadziemnego DN 80 — 10 dm3/s; 2) dla hydrantu nadziemnego DN 100 — 15 dm3/s; 3) dla hydrantu podziemnego DN 80 — 10 dm3/s; 4) dla hydrantu nadziemnego DN 80 na sieci, o której mowa w § 9 ust. 2 — 5 dm3/s. www.rcl.gov.pl Dziennik Ustaw Nr 124 — 9067 — Poz. 1030 9. […]"}], "43": [{"ref": "§ 4 RPB – obowiązki właścicieli/zarządców", "kind": "akt", "act": "rpb", "label": "§ 4", "text": "§ 4. […] 4) oznakowują znakami zgodnymi z Polskimi Normami: a) drogi i wyjścia ewakuacyjne z wyłączeniem budynków mieszkalnych oraz pomieszczenia, w których zgodnie z przepisami techniczno-budowlanymi są wymagane co najmniej 2 wyjścia ewakuacyjne, w sposób zapewniający dostarczenie informacji niezbędnych do ewakuacji, b) miejsca usytuowania urządzeń przeciwpożarowych i gaśnic, c) miejsca usytuowania elementów sterujących urządzeniami przeciwpożarowymi, d) miejsca usytuowania nasady umożliwiającej zasilanie instalacji wodociągowej przeciwpożarowej, kurków głównych instalacji gazowej oraz materiałów niebezpiecznych pożarowo, e) pomieszczenia i tereny z materiałami niebezpiecznymi pożarowo, f) drabiny ewakuacyjne, rękawy ratownicze, pojemniki z maskami ucieczkowymi, miejsca zbiórki do ewakuacji, miejsca lokalizacji kluczy do wyjść ewakuacyjnych, g) dźwigi dla straży pożarnej, h) przeciwpożarowe zbiorniki wodne, zbiorniki technologiczne stanowiące uzupełniające źródło wody do celów przeciwpożarowych, punkty poboru wody, stanowiska czerpania wody, i) drzwi przeciwpożarowe, j) drogi pożarowe, k) miejsca zaklasyfikowane jako strefy zagrożenia wybuchem; […]"}], "44": [{"ref": "§ 270 ust. 5 WT – klasy klap dymowych w wentylacji grawitacyjnej", "kind": "akt", "act": "wt", "label": "§ 270", "text": "5. Klapy dymowe w grawitacyjnej wentylacji oddymiającej powinny mieć klasę: 1) B300 30 – dla klap otwieranych automatycznie; 2) B600 30 – dla klap otwieranych wyłącznie w sposób ręczny. Rozdział 7 Usytuowanie budynków z uwagi na bezpieczeństwo pożarowe"}], "45": [{"ref": "PN-EN 13501-1 – klasyfikacja reakcji na ogień", "kind": "norma"}], "46": [{"ref": "§ 2 rozp. MEN z 31.12.2014 – wymagania ZL II lub uzgodnione z KW PSP", "kind": "akt", "act": "men", "label": "§ 2", "text": "§ 2. Lokal, w którym jest prowadzone przedszkole, znajduje się w użytkowanym budynku szkoły lub jego części spełniających wymagania określone w przepisach techniczno-budowlanych oraz przepisach dotyczących ochrony przeciwpożarowej dla kategorii zagrożenia ludzi ZL II lub wymagania uzgodnione z właściwym miejscowo komendantem wojewódzkim Państwowej Straży Pożarnej, w trybie określonym w tych przepisach."}, {"ref": "§ 3 pkt 2 rozp. MEN z 31.12.2014 – lokal na pierwszej kondygnacji nadziemnej", "kind": "akt", "act": "men", "label": "§ 3", "text": "§ 3. […] U. poz. 1255). Dokument podpisany przez Marek Głuch Data: 2015.01.07 15:43:03 CET 7) w strefie pożarowej, w której znajduje się lokal, nie występują inne lokale, w których są prowadzone przedszkola, inne formy wychowania przedszkolnego, ani lokale, w których jest sprawowana opieka nad dziećmi do lat 3 zgodnie z przepisami ustawy z dnia 4 lutego 2011 r. o opiece nad dziećmi w wieku do lat 3 (Dz. U. z 2013 r. poz. 1457); 8) w lokalu i na drogach ewakuacyjnych prowadzących z lokalu na zewnątrz budynku nie występują warunki techniczne będące podstawą do uznania budynku za zagrażający życiu ludzi, w odniesieniu do wymagań określonych dla kategorii zagrożenia ludzi ZL III, oraz są spełnione wymagania określone w przepisach dotyczących ochrony przeciwpożarowej budynków, innych obiektów budowlanych i terenów, odnoszące się do tej kategorii."}], "47": [{"ref": "§ 47 ust. 2 rozp. w sprawie baz i stacji paliw płynnych – zapas środka pianotwórczego i wody", "kind": "akt", "act": "paliwa", "label": "§ 47", "text": "2. Zapas środka pianotwórczego powinien wystarczać na okres co najmniej trzydziestominutowego jego zużycia, a zapas wody, na dwugodzinne zużycie do gaszenia pożaru największego zbiornika i jego obwałowania."}], "49": [{"ref": "PKN-CEN/TS 54-14:2006", "kind": "norma"}], "50": [{"ref": "§ 256 ust. 7 WT – droga od wyjścia z klatki schodowej do wyjścia na zewnątrz", "kind": "akt", "act": "wt", "label": "§ 256", "text": "7. Dopuszczalną długość drogi od wyjścia z klatki schodowej, o której mowa w ust. 2, do wyjścia na zewnątrz budynku określa się zgodnie z ust. 3."}, {"ref": "§ 256 ust. 3 WT – dojście w ZL III: 30 m, w tym do 20 m w poziomie", "kind": "akt", "act": "wt", "label": "§ 256", "text": "3. Dopuszczalne długości dojść ewakuacyjnych w strefach pożarowych określa poniższa tabela: Rodzaj strefy pożarowej Długość dojścia w m przy jednym dojściu przy co najmniej 2 dojściach1) 1 2 3 Z pomieszczeniem zagrożonym wybuchem 10 40 PM o gęstości obciążenia ogniowego Q > 500 MJ/m2 bez pomieszczenia zagrożonego wybuchem 302) 60 PM o gęstości obciążenia ogniowego Q ≤ 500 MJ/m2 bez pomieszczenia zagrożonego wybuchem 602) 100 ZL I, II i V 10 40 ZL III 302) 60 ZL IV 602) 100 1) Dla dojścia najkrótszego, przy czym dopuszcza się dla drugiego dojścia długość większą o 100% od najkrótszego. Dojścia te nie mogą się pokrywać ani krzyżować, przy czym dopuszcza się ich wspólny początkowy przebieg na długości nie większej niż 2 m. 2) W tym nie więcej niż 20 m na poziomej drodze ewakuacyjnej."}], "51": [{"ref": "§ 239 ust. 4 WT – szerokość drzwi z klatki schodowej na zewnątrz", "kind": "akt", "act": "wt", "label": "§ 239", "text": "4. Szerokość drzwi stanowiących wyjście ewakuacyjne z budynku, z zastrzeżeniem ust. 1, a także szerokość drzwi na drodze ewakuacyjnej z klatki schodowej, prowadzących na zewnątrz budynku lub do innej strefy pożarowej, powinna być nie mniejsza niż szerokość biegu klatki schodowej, określona zgodnie z § 68 ust. 1 i 2."}, {"ref": "§ 68 ust. 1 WT – szerokość biegu schodów w budynku wielorodzinnym 1,2 m", "kind": "akt", "act": "wt", "label": "§ 68", "text": "§ 68. 1. Graniczne wymiary schodów stałych w budynkach o różnym przeznaczeniu określa tabela: Przeznaczenie budynków Minimalna szerokość użytkowa (m) Maksymalna wysokość stopni (m) biegu spocznika 1 2 3 4 Budynki mieszkalne jednorodzinne i w zabudowie zagrodowej oraz mieszkania dwupoziomowe 0,8 0,8 0,19 Budynki mieszkalne wielorodzinne, budynki zamieszkania zbiorowego*) oraz budynki użyteczności publicznej*), z wyłączeniem budynków zakładów opieki zdrowotnej5), a także budynki produkcyjne*), magazynowo-składowe oraz usługowe, w których zatrudnia się ponad 10 osób 1,2 1,5 0,175 Przedszkola i żłobki 1,2 1,3 0,15 Budynki opieki zdrowotnej*) 1,4 1,5 0,15 Garaże wbudowane i wolno stojące (wielostanowiskowe) oraz budynki usługowe, w których zatrudnia się do 10 osób 0,9 0,9 0,19 We wszystkich budynkach niezależnie od ich przeznaczenia schody do kondygnacji podziemnej, pomieszczeń technicznych i […]"}], "52": [{"ref": "§ 227 ust. 4 pkt 1 WT – powiększenie strefy pożarowej ZL o 100%", "kind": "akt", "act": "wt", "label": "§ 227", "text": "4. Dopuszcza się powiększenie powierzchni stref pożarowych, o których mowa w ust. 1, z wyjątkiem stref pożarowych w wielokondygnacyjnych budynkach wysokich (W) i wysokościowych (WW), pod warunkiem zastosowania: 1) stałych samoczynnych urządzeń gaśniczych wodnych – o 100%; 2) samoczynnych urządzeń oddymiających uruchamianych za pomocą systemu wykrywania dymu – o 100%. Przy jednoczesnym stosowaniu urządzeń wymienionych w pkt 1 i 2 dopuszcza się powiększenie powierzchni stref pożarowych o 200%."}], "53": [{"ref": "§ 12 ust. 9 RW – zbliżenie drogi pożarowej do ściany", "kind": "akt", "act": "rw", "label": "§ 12", "text": "9. Droga pożarowa powinna zapewniać przejazd bez cofania lub powinna być zakończona placem manewrowym o wymiarach 20 m x 20 m, względnie można przewidzieć inne rozwiązania umożliwiające zawrócenie pojazdu, z zastrzeżeniem ust."}], "54": [{"ref": "§ 37 RPB – pomieszczenia uznane za zagrożone wybuchem", "kind": "akt", "act": "rpb", "label": "§ 37", "text": "§ 37. 1. W obiektach i na terenach przyległych, gdzie są prowadzone procesy technologiczne z użyciem materiałów mogących wytworzyć mieszaniny wybuchowe lub w których materiały takie są magazynowane, dokonuje się oceny zagrożenia wybuchem. 2. Ocena zagrożenia wybuchem obejmuje wskazanie pomieszczeń zagrożonych wybuchem, wyznaczenie w pomieszczeniach i przestrzeniach zewnętrznych odpowiednich stref zagrożenia wybuchem wraz z opracowaniem graficznej dokumentacji klasyfikacyjnej oraz wskazanie czynników mogących w nich zainicjować zapłon. 3. Graficzna dokumentacja klasyfikacyjna zawiera plany sytuacyjne obrazujące rodzaj i zasięg stref zagrożenia wybuchem oraz lokalizację i identyfikację źródeł emisji, zgodnie z zasadami określonymi w Polskich Normach. 4. Oceny zagrożenia wybuchem dokonują: inwestor, projektant lub użytkownik decydujący o procesie technologicznym. 5. […]"}], "55": [{"ref": "§ 2 ust. 1 pkt 9 RPB – definicja urządzeń przeciwpożarowych", "kind": "akt", "act": "rpb", "label": "§ 2", "text": "§ 2. 1. Ilekroć w rozporządzeniu jest mowa o: 1) materiałach niebezpiecznych pożarowo ‒ należy przez to rozumieć: a) gazy palne, b) ciecze palne o temperaturze zapłonu poniżej 328,15 K (55ºC), c) materiały wytwarzające w zetknięciu z wodą gazy palne, d) materiały zapalające się samorzutnie na powietrzu, e) materiały wybuchowe i wyroby pirotechniczne, f) materiały ulegające samorzutnemu rozkładowi lub polimeryzacji, g) materiały mające skłonności do samozapalenia, h) materiały inne niż wymienione w lit. a‒g, jeśli sposób ich składowania, przetwarzania lub innego wykorzystania może spowodować powstanie pożaru; 2) pasie przeciwpożarowym ‒ należy przez to rozumieć system drzewostanów różnej szerokości poddanych specjalnym zabiegom gospodarczym i porządkowym lub powierzchni wylesionych i oczyszczonych do warstwy mineralnej; […]"}], "57": [{"ref": "§ 3 ust. 1 rozp. w sprawie baz i stacji paliw płynnych – zakres stosowania", "kind": "akt", "act": "paliwa", "label": "§ 3", "text": "§ 3. 1. Przepisy rozporządzenia stosuje się przy budowie obiektów budowlanych przeznaczonych do magazynowania, przeładunku i dystrybucji ropy naftowej oraz produktów naftowych, a także przy przebudowie tych obiektów."}, {"ref": "§ 1 pkt 2 rozp. w sprawie baz i stacji paliw płynnych – definicja stacji paliw płynnych", "kind": "akt", "act": "paliwa", "label": "§ 1", "text": "§ 1. […] 4) stacja kontenerowa — zbiorniki i urządzenia do tymczasowego wydawania paliw płynnych, o konstrukcji umożliwiającej jej przemieszczanie; 5) baza paliw płynnych (terminal) — obiekt budowlany przeznaczony do magazynowania lub przeładunku ropy naftowej i produktów naftowych; 6) baza gazu płynnego — obiekt budowlany przeznaczony do magazynowania lub przeładunku gazu płynnego; 7) rurociąg przesyłowy dalekosiężny — rurociąg służący do przesyłania lub dystrybucji ropy naftowej lub produktów naftowych, do lub z instalacji znajdującej się na lądzie lub w wodzie, począwszy od ostatniego elementu odcinającego w granicach instalacji, łącznie z tym elementem i wszystkimi przyłączonymi urządzeniami przeznaczonymi specjalnie dla tych rurociągów z wyjątkiem rurociągów technologicznych w obrębie granic baz i stacji paliw płynnych na terenie portów, lotnisk oraz stacji kolejowych; […]"}], "58": [{"ref": "§ 28 ust. 1 pkt 10 RPB – system sygnalizacji pożarowej w budynkach użyteczności publicznej wysokich i wysokościowych", "kind": "akt", "act": "rpb", "label": "§ 28", "text": "§ 28. 1. Stosowanie systemu sygnalizacji pożarowej, obejmującego urządzenia sygnalizacyjno-alarmowe, służące do samoczynnego wykrywania i przekazywania informacji o pożarze, a także urządzenia odbiorcze alarmów pożarowych i urządzenia odbiorcze sygnałów uszkodzeniowych, jest wymagane w: 1) budynkach handlowych lub wystawowych: a) jednokondygnacyjnych o powierzchni strefy pożarowej powyżej 5000 m2, b) wielokondygnacyjnych o powierzchni strefy pożarowej powyżej 2500 m2; 2) teatrach o liczbie miejsc powyżej 300; 3) kinach o liczbie miejsc powyżej 600; 4) budynkach o liczbie miejsc służących celom gastronomicznym powyżej 300; 5) salach widowiskowych i sportowych o liczbie miejsc powyżej 1500; 6) szpitalach, z wyjątkiem psychiatrycznych, oraz w sanatoriach ‒ o liczbie łóżek powyżej 200 w budynku; 7) szpitalach psychiatrycznych o liczbie łóżek powyżej 100 w budynku; […]"}], "60": [{"ref": "§ 209, § 212 WT – klasa odporności pożarowej", "kind": "akt", "act": "wt", "label": "§ 209", "text": "§ 209. 1. Budynki oraz części budynków, stanowiące odrębne strefy pożarowe w rozumieniu § 226, z uwagi na przeznaczenie i sposób użytkowania, dzieli się na: 1) mieszkalne, zamieszkania zbiorowego i użyteczności publicznej charakteryzowane kategorią zagrożenia ludzi, określane dalej jako ZL; 2) produkcyjne i magazynowe, określane dalej jako PM; 3) inwentarskie (służące do hodowli inwentarza), określane dalej jako IN. 2. Budynki oraz części budynków, stanowiące odrębne strefy pożarowe, określane jako ZL, zalicza się do jednej lub do więcej niż jedna spośród następujących kategorii zagrożenia ludzi: 1) ZL I – zawierające pomieszczenia przeznaczone do jednoczesnego przebywania ponad 50 osób niebędących ich stałymi użytkownikami, a nieprzeznaczone przede wszystkim do użytku ludzi o ograniczonej zdolności poruszania się; […]"}], "61": [{"ref": "§ 234 ust. 1 WT – przepusty w elementach oddzielenia przeciwpożarowego", "kind": "akt", "act": "wt", "label": "§ 234", "text": "§ 234. 1. Przepusty instalacyjne w elementach oddzielenia przeciwpożarowego powinny mieć klasę odporności ogniowej (E I) wymaganą dla tych elementów."}, {"ref": "§ 232 ust. 4 WT – klasy elementów oddzielenia przeciwpożarowego", "kind": "akt", "act": "wt", "label": "§ 232", "text": "4. Wymaganą klasę odporności ogniowej elementów oddzielenia przeciwpożarowego oraz zamknięć znajdujących się w nich otworów określa poniższa tabela: Klasa odporności pożarowej budynku Klasa odporności ogniowej elementów oddzielenia przeciwpożarowego drzwi przeciwpożarowych lub innych zamknięć przeciwpożarowych drzwi z przedsionka przeciwpożarowego ścian i stropów, z wyjątkiem stropów w ZL stropów w ZL na korytarz i do pomieszczenia na klatkę schodową*) 1 2 3 4 5 6 „A” R E I 240 R E I 120 E I 120 E I 60 E 60 „B” i „C” R E I 120 R E I 60 E I 60 E I 30 E 30 „D” i „E” R E I 60 R E I 30 E I 30 E I 15 E 15 *) Dopuszcza się osadzenie tych drzwi w ścianie o klasie odporności ogniowej, określonej dla drzwi w kol. 6, znajdującej się między przedsionkiem a klatką schodową."}, {"ref": "§ 212 ust. 7 WT – klasa części podziemnej nie niższa niż C", "kind": "akt", "act": "wt", "label": "§ 212", "text": "7. Klasa odporności pożarowej części budynku nie powinna być niższa od klasy odporności pożarowej części budynku położonej nad nią, przy czym dla części podziemnej nie powinna być ona niższa niż „C”."}], "62": [{"ref": "przepisy techniczno-budowlane dla tuneli / § 28 RPB", "kind": "akt", "act": "rpb", "label": "§ 28", "text": "§ 28. 1. Stosowanie systemu sygnalizacji pożarowej, obejmującego urządzenia sygnalizacyjno-alarmowe, służące do samoczynnego wykrywania i przekazywania informacji o pożarze, a także urządzenia odbiorcze alarmów pożarowych i urządzenia odbiorcze sygnałów uszkodzeniowych, jest wymagane w: 1) budynkach handlowych lub wystawowych: a) jednokondygnacyjnych o powierzchni strefy pożarowej powyżej 5000 m2, b) wielokondygnacyjnych o powierzchni strefy pożarowej powyżej 2500 m2; 2) teatrach o liczbie miejsc powyżej 300; 3) kinach o liczbie miejsc powyżej 600; 4) budynkach o liczbie miejsc służących celom gastronomicznym powyżej 300; 5) salach widowiskowych i sportowych o liczbie miejsc powyżej 1500; 6) szpitalach, z wyjątkiem psychiatrycznych, oraz w sanatoriach ‒ o liczbie łóżek powyżej 200 w budynku; 7) szpitalach psychiatrycznych o liczbie łóżek powyżej 100 w budynku; […]"}], "64": [{"ref": "§ 232 ust. 6 WT – wypełnienie otworów materiałem przepuszczającym światło", "kind": "akt", "act": "wt", "label": "§ 232", "text": "6. W ścianie oddzielenia przeciwpożarowego dopuszcza się wypełnienie otworów materiałem przepuszczającym światło, takim jak luksfery, cegła szklana lub inne przeszklenie, jeżeli powierzchnia wypełnionych otworów nie przekracza 10% powierzchni ściany, przy czym klasa odporności ogniowej wypełnień nie powinna być niższa niż: Wymagana klasa odporności ogniowej ściany oddzielenia przeciwpożarowego Klasa odporności ogniowej wypełnienia otworu w ścianie będącej obudową drogi ewakuacyjnej innej 1 2 3 R E I 240 E I 120 E 120 R E I 120 E I 60 E 60 R E I 60 E I 30 E 30"}, {"ref": "§ 232 ust. 4 WT – klasa ściany oddzielenia przeciwpożarowego", "kind": "akt", "act": "wt", "label": "§ 232", "text": "4. Wymaganą klasę odporności ogniowej elementów oddzielenia przeciwpożarowego oraz zamknięć znajdujących się w nich otworów określa poniższa tabela: Klasa odporności pożarowej budynku Klasa odporności ogniowej elementów oddzielenia przeciwpożarowego drzwi przeciwpożarowych lub innych zamknięć przeciwpożarowych drzwi z przedsionka przeciwpożarowego ścian i stropów, z wyjątkiem stropów w ZL stropów w ZL na korytarz i do pomieszczenia na klatkę schodową*) 1 2 3 4 5 6 „A” R E I 240 R E I 120 E I 120 E I 60 E 60 „B” i „C” R E I 120 R E I 60 E I 60 E I 30 E 30 „D” i „E” R E I 60 R E I 30 E I 30 E I 15 E 15 *) Dopuszcza się osadzenie tych drzwi w ścianie o klasie odporności ogniowej, określonej dla drzwi w kol. 6, znajdującej się między przedsionkiem a klatką schodową."}], "65": [{"ref": "§ 39 RPB – lekki dach w pomieszczeniu zagrożonym wybuchem", "kind": "akt", "act": "rpb", "label": "§ 39", "text": "§ 39. […] 5) studnia z pompą oraz z: a) hydrantem zewnętrznym lub b) innym punktem poboru wody z nasadą tłoczną typu 75 lub 110 – o wydajności nie mniejszej niż 10 dm3/s. 5.7) Zbiornikiem sztucznym jest pojemnik albo grupa pojemników połączonych przewodami o średnicy co najmniej 300 mm w sposób umożliwiający dostęp do wymaganego zapasu wody z każdego stanowiska czerpania wody, w które jest wyposażony zbiornik. 6.7) Źródła wody do celów przeciwpożarowych, o których mowa w ust. 4 pkt 1‒3 i 5, powinny być wyposażone w stanowiska czerpania wody z utwardzoną nawierzchnią o nośności nie mniejszej niż wymagana dla dojazdów pożarowych. 7.8) Stanowiska czerpania wody przy źródłach wody do celów przeciwpożarowych, o których mowa w ust. 4 pkt 1‒3, powinny umożliwiać pobieranie wody z głębokości nie większej niż 4 m, mierząc od lustra wody do poziomu stanowiska czerpania wody, z wykorzystaniem autopomp lub motopomp pożarniczych. 8.8) Stanowisko czerpania wody powinno mieć szerokość co najmniej 4 m i długość co najmniej 12 m oraz być wykonane w sposób umożliwiający wjazd i wyjazd, a także postój samochodu ratowniczo-gaśniczego o długości 12 m. […]"}], "66": [{"ref": "§ 12 ust. 2 RW – odległość drogi pożarowej od ściany budynku", "kind": "akt", "act": "rw", "label": "§ 12", "text": "2. Droga pożarowa powinna przebiegać wzdłuż dłuższego boku budynku, o którym mowa w ust. 1 pkt 1—4, na całej jego długości, a w przypadku gdy krótszy bok budynku ma więcej niż 60 m — z jego dwóch stron, przy czym bliższa krawędź drogi pożarowej musi być oddalona od ściany budynku o 5—15 m dla obiektów zaliczanych do kategorii zagrożenia ludzi i o 5—25 m dla pozostałych obiektów. Pomiędzy tą drogą i ścianą budynku nie mogą występować stałe elementy zagospodarowania terenu lub drzewa i krzewy o wysokości przekraczającej 3 m, uniemożliwiające dostęp do elewacji budynku za pomocą podnośników i drabin mechanicznych."}, {"ref": "§ 13 ust. 1 RW – minimalna szerokość drogi pożarowej", "kind": "akt", "act": "rw", "label": "§ 13", "text": "§ 13. 1. Minimalna szerokość drogi pożarowej powinna wynosić co najmniej 4 m, a jej nachylenie podłużne nie może przekraczać 5 %: 1) w miejscach, o których mowa w § 12 ust. 2 i 3, oraz na odcinkach o długości 10 m od tych miejsc, zapewniających dojazd i wyjazd; 2) na odcinku o długości 15 m od miejsc doprowadzenia jej do budynku, o których mowa w § 12 ust. 6 pkt"}], "67": [{"ref": "§ 212 WT – klasa odporności pożarowej budynków ZL", "kind": "akt", "act": "wt", "label": "§ 212", "text": "§ 212. 1. Ustanawia się pięć klas odporności pożarowej budynków lub ich części, podanych w kolejności od najwyższej do najniższej i oznaczonych literami: „A”, „B”, „C”, „D” i „E”, a scharakteryzowanych w § 216. 2. Wymaganą klasę odporności pożarowej dla budynku, zaliczonego do jednej kategorii ZL, określa poniższa tabela: Budynek ZL I ZL II ZL III ZL IV ZL V 1 2 3 4 5 6 niski (N) „B” „B” „C” „D” „C” średniowysoki (SW) „B” „B” „B” „C” „B” wysoki (W) „B” „B” „B” „B” „B” wysokościowy (WW) „A” „A” „A” „B” „A” 3. Dopuszcza się obniżenie wymaganej klasy odporności pożarowej w budynkach wymienionych w poniższej tabeli do poziomu w niej określonego. Liczba kondygnacji nadziemnych ZL I ZL II ZL III 1 2 3 4 1 „D” „D” „D” 2*) „C” „C” „D” *) Gdy poziom stropu nad pierwszą kondygnacją nadziemną jest na wysokości nie większej niż 9 m nad poziomem terenu. 4. […]"}], "68": [{"ref": "art. 36a ustawy – Prawo budowlane", "kind": "akt", "act": "pb", "label": "art. 36a", "text": "Art. 36a. […] Projektant dokonuje kwalifikacji zamierzonego odstąpienia od projektu zagospodarowania działki lub terenu lub projektu architektoniczno-budowlanego lub innych warunków decyzji o pozwoleniu na budowę, a w przypadku uznania, że jest ono nieistotne, dołącza do dokumentacji budowy odpowiednie informacje (rysunek i opis) dotyczące tego odstąpienia. Nieistotne odstąpienie od zatwierdzonego projektu zagospodarowania działki lub terenu lub projektu architektoniczno-budowlanego, lub innych warunków decyzji o pozwoleniu na budowę nie wymaga uzyskania decyzji o zmianie pozwolenia na budowę oraz ponownego zgłoszenia."}], "69": [{"ref": "dyrektywa ATEX / PN-EN 60079-10-1 – dobór urządzeń do stref", "kind": "norma"}], "70": [{"ref": "PN-EN 15650 / PN-EN 13501-3 – klasyfikacja klap ppoż.", "kind": "norma"}], "71": [{"ref": "PN-EN 12845 / NFPA – tryskacze ESFR", "kind": "norma"}], "72": [{"ref": "§ 157 WT – zakaz stosowania gazu płynnego w budynkach wysokich i wysokościowych", "kind": "akt", "act": "wt", "label": "§ 157", "text": "§ 157. […] 3. Instalacja gazowa w budynku o wysokości większej niż 35 m ponad poziomem terenu może być doprowadzona tylko do pomieszczeń technicznych, w których są zainstalowane urządzenia gazowe, usytuowanych w piwnicy lub na najniższej kondygnacji nadziemnej, a także na najwyższej kondygnacji budynku lub nad tą kondygnacją, pod warunkiem zastosowania urządzeń stabilizujących ciśnienie gazu. 4. Zastosowanie instalacji gazowej w budynkach o wysokości ponad 25 m wymaga uzyskania pozytywnej opinii wydanej przez właściwego komendanta wojewódzkiego Państwowej Straży Pożarnej. 5. Instalacje gazowe zasilane gazem płynnym mogą być wykonywane tylko w budynkach niskich. 6. Zabrania się stosowania w jednym budynku gazu płynnego i gazu z sieci gazowej. 7. W budynku niskim, mającym w mieszkaniach instalację zasilaną gazem płynnym, dopuszcza się usytuowanie kotłowni gazowej zasilanej z sieci gazowej. 8. […]"}], "73": [{"ref": "§ 285 WT – część mieszkalna i gospodarcza w jednym budynku", "kind": "akt", "act": "wt", "label": "§ 285", "text": "§ 285. Dopuszcza się umieszczenie w jednym budynku części mieszkalnej i gospodarczej pod następującymi warunkami: 1) część mieszkalna oraz część gospodarcza mają odrębne wejścia; 2) między częścią mieszkalną a gospodarczą zostanie wykonana ściana o klasie odporności ogniowej co najmniej R E I 60. Rozdział 10 Wymagania przeciwpożarowe dla budynków tymczasowych"}], "74": [{"ref": "PN-B-02852:2001 – obliczanie gęstości obciążenia ogniowego", "kind": "norma"}, {"ref": "§ 212 ust. 4 WT – klasa odporności pożarowej budynku PM", "kind": "akt", "act": "wt", "label": "§ 212", "text": "4. Wymaganą klasę odporności pożarowej dla budynku PM oraz IN, z zastrzeżeniem § 282, określa poniższa tabela: Maksymalna gęstość obciążenia ogniowego strefy pożarowej w budynku Q [MJ/m2] Budynek o jednej kondygnacji nadziemnej (bez ograniczenia wysokości) Budynek wielokondygnacyjny niski średniowysoki wysoki wysokościowy (N) (SW) (W) (WW) 1 2 3 4 5 6 Q ≤ 500 „E” „D” „C” „B” „B” 500 < Q ≤ 1000 „D” „D” „C” „B” „B” 1000 < Q ≤ 2000 „C” „C” „C” „B” „B” 2000 < Q ≤ 4000 „B” „B” „B” * * Q > 4000 „A” „A” „A” * * * – Zgodnie z § 228 ust. 1 nie mogą występować takie budynki."}], "75": [{"ref": "PN-EN 12101-6:2007 – systemy różnicowania ciśnień, klasa B", "kind": "norma"}], "76": [{"ref": "PN-EN 60849:2001 – dźwiękowe systemy ostrzegawcze, zasilanie rezerwowe", "kind": "norma"}], "77": [{"ref": "PN-B-02877-4:2001 – grawitacyjne odprowadzanie dymu i ciepła", "kind": "norma"}], "78": [{"ref": "§ 227 ust. 1 WT – dopuszczalne powierzchnie stref pożarowych ZL", "kind": "akt", "act": "wt", "label": "§ 227", "text": "§ 227. 1. Dopuszczalne powierzchnie stref pożarowych ZL określa poniższa tabela: Kategoria zagrożenia ludzi Dopuszczalna powierzchnia strefy pożarowej w m2 w budynku o jednej kondygnacji nadziemnej (bez ograniczenia wysokości) w budynku wielokondygnacyjnym niskim (N) średniowysokim (SW) wysokim i wysokościowym (W) i (WW) 1 2 3 4 5 ZL I, ZL III, ZL IV, ZL V 10 000 8000 5000 2500 ZL II 8000 5000 3500 2000"}, {"ref": "§ 227 ust. 2 WT – strefa obejmująca część podziemną", "kind": "akt", "act": "wt", "label": "§ 227", "text": "2. Dopuszczalna powierzchnia strefy pożarowej ZL, obejmującej podziemną część budynku, nie powinna przekraczać 50% dopuszczalnej powierzchni strefy pożarowej tej samej kategorii zagrożenia ludzi, określonej w ust. 1 dla pierwszej nadziemnej kondygnacji tego budynku."}, {"ref": "§ 227 ust. 4 WT – powiększenie strefy przy tryskaczach i oddymianiu", "kind": "akt", "act": "wt", "label": "§ 227", "text": "4. Dopuszcza się powiększenie powierzchni stref pożarowych, o których mowa w ust. 1, z wyjątkiem stref pożarowych w wielokondygnacyjnych budynkach wysokich (W) i wysokościowych (WW), pod warunkiem zastosowania: 1) stałych samoczynnych urządzeń gaśniczych wodnych – o 100%; 2) samoczynnych urządzeń oddymiających uruchamianych za pomocą systemu wykrywania dymu – o 100%. Przy jednoczesnym stosowaniu urządzeń wymienionych w pkt 1 i 2 dopuszcza się powiększenie powierzchni stref pożarowych o 200%."}], "79": [{"ref": "§ 5 RW – wymagana ilość wody", "kind": "akt", "act": "rw", "label": "§ 5", "text": "§ 5. 1. Wymagana ilość wody do celów przeciwpożarowych do zewnętrznego gaszenia pożaru dla budynków użyteczności publicznej i zamieszkania zbiorowego oraz innych obiektów budowlanych o takim przeznaczeniu, służąca do zewnętrznego gaszenia pożaru, wynosi: 1) dla budynku o kubaturze brutto do 5 000 m3 i o powierzchni wewnętrznej do 1 000 m2 — 10 dm3/s z co najmniej jednego hydrantu o średnicy 80 mm lub 100 m3 zapasu wody w przeciwpożarowym zbiorniku wodnym; 2) dla budynków niewymienionych w pkt 1 — 20 dm3/s łącznie z co najmniej dwóch hydrantów o średnicy 80 mm lub 200 m3 zapasu wody w przeciwpożarowym zbiorniku wodnym; 3) dla obiektów wymienionych w § 3 ust. 1 pkt 3 — 10 dm3/s z co najmniej jednego hydrantu o średnicy 80 mm lub 100 m3 zapasu wody w przeciwpożarowym zbiorniku wodnym. 2. […]"}], "81": [{"ref": "§ 15 RW – prześwit pod wiaduktami i estakadami nad drogą pożarową", "kind": "akt", "act": "rw", "label": "§ 15", "text": "§ 15. Wiadukty, estakady, przejścia i inne podobne urządzenia lub stałe elementy, usytuowane ponad drogami pożarowymi, powinny mieć prześwit o wysokości i szerokości nie mniejszej niż 4,5 m."}, {"ref": "§ 14 ust. 1 RW – wymiary przejazdów na dziedzińce", "kind": "akt", "act": "rw", "label": "§ 14", "text": "§ 14. 1. Przejazdy na dziedzińce i inne tereny obudowane powinny odpowiadać następującym warunkom: 1) wysokość przejazdu nie mniejsza niż 4,2 m, a w budownictwie jednorodzinnym — 3,2 m; 2) szerokość przejazdu nie mniejsza niż 3,6 m, w tym szerokość jezdni co najmniej 3 m; 3) odległość między przejazdami na jeden dziedziniec nie większa niż 150 m."}], "82": [{"ref": "§ 158 WT – urządzenia sygnalizacyjno-odcinające dopływ gazu", "kind": "akt", "act": "wt", "label": "§ 158", "text": "§ 158. […] 4. Zabrania się instalowania urządzeń sygnalizacyjno-odcinających dopływ gazu do części mieszkalnej budynku wielorodzinnego. Nie dotyczy to indywidualnych urządzeń sygnalizacyjno-odcinających dopływ gazu do odrębnych mieszkań. 5. Urządzenia sygnalizacyjno-odcinające dopływ gazu należy stosować w tych pomieszczeniach, w których łączna nominalna moc cieplna zainstalowanych urządzeń gazowych jest większa niż 60 kW. 6. Zawór odcinający dopływ gazu do budynku, będący elementem składowym urządzenia sygnalizacyjno-odcinającego, powinien być instalowany poza budynkiem, między kurkiem głównym a wprowadzeniem przewodu do budynku. 7. Instalacja gazowa przyłączona do sieci gazowej wykonanej z przewodów metalowych powinna być zabezpieczona przed wpływem prądów błądzących przez zainstalowanie wstawki izolacyjnej na wprowadzeniu metalowej rury gazowej do budynku."}], "83": [{"ref": "§ 259 ust. 2 WT – osłony instalacji palnych w przestrzeni podpodłogowej", "kind": "akt", "act": "wt", "label": "§ 259", "text": "2. Przewody i kable elektryczne oraz inne instalacje wykonane z materiałów palnych, prowadzone w przestrzeni podpodłogowej podłogi podniesionej i w przestrzeni ponad sufitami podwieszonymi, wykorzystywanej do wentylacji lub ogrzewania pomieszczenia, powinny mieć osłonę lub obudowę o klasie odporności ogniowej co najmniej E I 30, a w budynku wysokościowym (WW) lub w budynkach ze strefą pożarową o gęstości obciążenia ogniowego ponad 4000 MJ/m2 – co najmniej E I 60."}, {"ref": "§ 259 ust. 1 WT – wymagania dla podłóg podniesionych o więcej niż 0,2 m", "kind": "akt", "act": "wt", "label": "§ 259", "text": "§ 259. 1. Podłogi podniesione o więcej niż 0,2 m ponad poziom stropu lub innego podłoża powinny mieć: 1) niepalną konstrukcję nośną oraz co najmniej niezapalne płyty podłogi od strony przestrzeni podpodłogowej, mające klasę odporności ogniowej co najmniej R E I 30, a w budynku wysokościowym (WW) lub ze strefą pożarową o gęstości obciążenia ogniowego ponad 4000 MJ/m2 oraz w strefach pożarowych ZL II – co najmniej R E I 60; 2) przestrzeń podpodłogową podzieloną na sektory o powierzchni nie większej niż 1000 m2 przegrodami o klasie odporności ogniowej co najmniej E I 30, a w budynku wysokościowym (WW) lub ze strefą pożarową o gęstości obciążenia ogniowego ponad 4000 MJ/m2 – co najmniej E I 60."}], "84": [{"ref": "PN-EN 13501-1 – klasyfikacja reakcji na ogień posadzek (indeks fl)", "kind": "norma"}], "85": [{"ref": "§ 111 WT / RPB – przechowywanie materiałów niebezpiecznych w garażach", "kind": "akt", "act": "wt", "label": "§ 111", "text": "§ 111. (uchylony)."}], "87": [{"ref": "§ 216 ust. 2 pkt 2 WT – dopuszczenie elementów słabo rozprzestrzeniających ogień", "kind": "akt", "act": "wt", "label": "§ 216", "text": "2. Elementy budynku, o których mowa w ust. 1, powinny być nierozprzestrzeniające ognia, przy czym dopuszcza się zastosowanie słabo rozprzestrzeniających ogień: 1) elementów budynku o jednej kondygnacji nadziemnej ZL IV oraz PM, o maksymalnej gęstości obciążenia ogniowego strefy pożarowej do 500 MJ/m2; 2) ścian wewnętrznych i zewnętrznych oraz elementów konstrukcji dachu i jego przekrycia w budynku PM niskim o maksymalnej gęstości obciążenia ogniowego strefy pożarowej do 1000 MJ/m2; 3) ścian zewnętrznych w budynku niskim ZL IV."}, {"ref": "§ 219 ust. 1 WT – przekrycie dachu ponad 1000 m2", "kind": "akt", "act": "wt", "label": "§ 219", "text": "§ 219. 1. Przekrycie dachu o powierzchni większej niż 1000 m2 powinno być nierozprzestrzeniające ognia, a palna izolacja cieplna przekrycia powinna być oddzielona od wnętrza budynku przegrodą o klasie odporności ogniowej nie niższej niż R E 15."}], "88": [{"ref": "§ 6–7 RW – ilość wody dla obiektów innych niż budynki", "kind": "akt", "act": "rw", "label": "§ 6", "text": "§ 6. […] U. Nr 243, poz. 2063 oraz z 2007 r. Nr 240, poz. 1753). 7. Wymaganą ilość wody do celów przeciwpożarowych do zewnętrznego gaszenia pożaru dla urządzeń technologicznych oraz składów i magazynów z gazami palnymi i cieczami o temperaturze zapłonu do 373,15 K (100 °C), zlokalizowanych poza budynkami, określa tabela nr 4 załącznika do rozporządzenia. 8. Wymagana ilość wody do celów przeciwpożarowych do zewnętrznego gaszenia pożaru dla silosów, komór i zasobników ze stałymi sypkimi materiałami palnymi oraz dla zbiorników z cieczami palnymi o temperaturze zapłonu powyżej 373,15 K (100 °C) wynosi 10 dm3/s. 9. Wymaganą ilość wody do celów przeciwpożarowych do zewnętrznego gaszenia pożaru dla obiektów budowlanych gospodarki rolnej należy zapewnić w następujących ilościach: 1) dla obiektów o powierzchni strefy pożarowej do 2 000 m2 — co najmniej 10 dm3/s; […]"}], "89": [{"ref": "§ 28, § 29 RPB – obowiązek SSP i DSO", "kind": "akt", "act": "rpb", "label": "§ 28", "text": "§ 28. 1. Stosowanie systemu sygnalizacji pożarowej, obejmującego urządzenia sygnalizacyjno-alarmowe, służące do samoczynnego wykrywania i przekazywania informacji o pożarze, a także urządzenia odbiorcze alarmów pożarowych i urządzenia odbiorcze sygnałów uszkodzeniowych, jest wymagane w: 1) budynkach handlowych lub wystawowych: a) jednokondygnacyjnych o powierzchni strefy pożarowej powyżej 5000 m2, b) wielokondygnacyjnych o powierzchni strefy pożarowej powyżej 2500 m2; 2) teatrach o liczbie miejsc powyżej 300; 3) kinach o liczbie miejsc powyżej 600; 4) budynkach o liczbie miejsc służących celom gastronomicznym powyżej 300; 5) salach widowiskowych i sportowych o liczbie miejsc powyżej 1500; 6) szpitalach, z wyjątkiem psychiatrycznych, oraz w sanatoriach ‒ o liczbie łóżek powyżej 200 w budynku; 7) szpitalach psychiatrycznych o liczbie łóżek powyżej 100 w budynku; […]"}], "90": [{"ref": "§ 237 WT – długość przejścia ewakuacyjnego i powiększenia", "kind": "akt", "act": "wt", "label": "§ 237", "text": "§ 237. […] 4. Jeżeli z przewidywanego przeznaczenia pomieszczenia nie wynika jednoznacznie sposób jego zagospodarowania, projektowa długość przejścia ewakuacyjnego nie może być większa niż 80% długości określonej w ust. 1 i 2. 5. W pomieszczeniach o wysokości przekraczającej 5 m długość przejść, o których mowa w ust. 1 i 2, może być powiększona o 25%. 6. Długości przejść, o których mowa w ust. 1 i 2, mogą być powiększone pod warunkiem zastosowania: 1) stałych samoczynnych urządzeń gaśniczych wodnych – o 50%; 2) samoczynnych urządzeń oddymiających uruchamianych za pomocą systemu wykrywania dymu – o 50%. 7. Powiększenia, o których mowa w ust. 5 i 6 pkt 1 i 2, podlegają sumowaniu. 8. Przejście, o którym mowa w ust. 1, nie powinno prowadzić łącznie przez więcej niż trzy pomieszczenia. 9. […]"}], "91": [{"ref": "§ 8, § 212 WT – definicja budynku niskiego i klasa odporności pożarowej", "kind": "akt", "act": "wt", "label": "§ 8", "text": "§ 8. W celu określenia wymagań technicznych i użytkowych wprowadza się następujący podział budynków na grupy wysokości: 1) niskie (N) – do 12 m włącznie nad poziomem terenu lub mieszkalne o wysokości do 4 kondygnacji nadziemnych włącznie; 2) średniowysokie (SW) – ponad 12 m do 25 m włącznie nad poziomem terenu lub mieszkalne o wysokości ponad 4 do 9 kondygnacji nadziemnych włącznie; 3) wysokie (W) – ponad 25 m do 55 m włącznie nad poziomem terenu lub mieszkalne o wysokości ponad 9 do 18 kondygnacji nadziemnych włącznie; 4) wysokościowe (WW) – powyżej 55 m nad poziomem terenu."}], "92": [{"ref": "§ 212, § 216 WT – klasa B, wymagane klasy odporności ogniowej elementów", "kind": "akt", "act": "wt", "label": "§ 212", "text": "§ 212. […] 5. Jeżeli część podziemna budynku jest zaliczona do ZL, klasę odporności pożarowej budynku ustala się, przyjmując jako liczbę jego kondygnacji lub jego wysokość odpowiednio: sumę kondygnacji lub wysokości części podziemnej i nadziemnej, przy czym do tego ustalenia nie bierze się pod uwagę tych części podziemnych budynku, które są oddzielone elementami oddzielenia przeciwpożarowego o klasie odporności ogniowej co najmniej R E I 120, zgodnie z oznaczeniem pod tabelą w § 216 ust. 1, i mają bezpośrednie wyjścia na zewnątrz. 6. W budynku wielokondygnacyjnym, którego kondygnacje są zaliczone do różnych kategorii ZL lub PM, klasy odporności pożarowej określa się dla poszczególnych kondygnacji odrębnie, zgodnie z zasadami określonymi w ust. 2–4. 7. […]"}], "93": [{"ref": "§ 271, § 272 WT – odległości między budynkami i od granicy działki", "kind": "akt", "act": "wt", "label": "§ 271", "text": "§ 271. […] Najmniejsza odległość budynków wymienionych w § 213, wykonanych z elementów nierozprzestrzeniających ognia, niezawierających pomieszczeń zagrożonych wybuchem oraz posiadających klasę odporności pożarowej wyższą niż wymagana zgodnie z § 212, od granicy (konturu) lasu zlokalizowanej na: 1) sąsiedniej działce – wynosi 4 m, 2) działce, na której sytuuje się budynek – nie określa się – jeżeli teren, na którym znajduje się granica (kontur) lasu, przeznaczony jest w miejscowym planie zagospodarowania przestrzennego pod zabudowę niezwiązaną z produkcją leśną, a w przypadku braku planu miejscowego – grunty leśne są objęte zgodą na zmianę przeznaczenia na cele nieleśne uzyskaną przy sporządzaniu miejscowych planów zagospodarowania przestrzennego, które utraciły moc na podstawie art. 1 lit. a ustawy z dnia 21 grudnia 2001 r. o zmianie ustawy o zagospodarowaniu przestrzennym (Dz. U. poz. […]"}], "94": [{"ref": "§ 261 WT – liczba siedzeń w rzędzie i odstępy między rzędami", "kind": "akt", "act": "wt", "label": "§ 261", "text": "§ 261. […] 2) szerokość przejść pomiędzy rzędami siedzeń nie mniejszą niż 0,45 m, przy czym odległość tę należy ustalać, biorąc pod uwagę odstęp między stałymi elementami siedzeń; 3) liczbę siedzeń w rzędzie nie większą niż 16 pomiędzy przejściami oraz 8 w rzędzie przyściennym, przy czym dopuszcza się zwiększenie liczby miejsc w rzędach odpowiednio do 40 i 20 pod warunkiem zwiększenia odstępu między rzędami siedzeń o 1 cm na każde dodatkowe siedzenie odpowiednio powyżej 16 lub 8; 4) szerokość przejść komunikacyjnych nie mniejszą niż 1,2 m przy liczbie osób do 150, a przy większej ich liczbie szerokość tę należy zwiększyć proporcjonalnie o 0,6 m na 100 osób; 5) rzędy siedzeń lub ławek trwale umocowane do podłogi albo siedzenia sztywno łączone ze sobą w rzędy oraz między rzędami."}], "95": [{"ref": "§ 216 ust. 8 WT – palna izolacja cieplna w ścianach", "kind": "akt", "act": "wt", "label": "§ 216", "text": "8. W budynku, na wysokości powyżej 25 m od poziomu terenu, okładzina elewacyjna i jej zamocowanie mechaniczne, a także izolacja cieplna ściany zewnętrznej, powinny być wykonane z materiałów niepalnych."}], "96": [{"ref": "§ 37 RPB / WT – wentylacja pomieszczeń zagrożonych wybuchem", "kind": "akt", "act": "wt", "label": "§ 37", "text": "§ 37. Przepływowe, szczelne osadniki podziemne, stanowiące część przydomowej oczyszczalni ścieków gospodarczo-bytowych, służące do wstępnego ich oczyszczania, mogą być sytuowane w bezpośrednim sąsiedztwie budynków jednorodzinnych, pod warunkiem wyprowadzenia ich odpowietrzenia przez instalację kanalizacyjną co najmniej 0,6 m powyżej górnej krawędzi okien i drzwi zewnętrznych w tych budynkach."}], "97": [{"ref": "§ 179 WT / rozp. dot. zbiorników gazu płynnego – odległości", "kind": "akt", "act": "wt", "label": "§ 179", "text": "§ 179. […] 2) powyżej 10 m3 – nie mniej niż połowa odległości określonej w tabeli w ust. 4 w kolumnach 2 i 3. 6. Odległość zbiorników z gazem płynnym od granicy działki budowlanej z tymi zbiornikami powinna być nie mniejsza niż połowa odległości określonej w tabeli w ust. 4 w kolumnach 2 i 3, przy zachowaniu wymaganej odległości od budynku danego rodzaju. 7. Odległości określone w tabeli w ust. 4 w kolumnie 2 mogą być zmniejszone do 50% w przypadku zastosowania wolno stojącej ściany oddzielenia przeciwpożarowego o klasie odporności ogniowej co najmniej R E I 120, usytuowanej pomiędzy zbiornikiem z gazem płynnym a budynkiem. Wymiary wolno stojącej ściany oraz jej odległość od zbiornika powinny być tak dobrane, aby osłonić zbiornik od tej części budynku, która znajduje się w odległości mniejszej niż określona w tabeli w ust. 4 w kolumnie 2 od dowolnego punktu zbiornika. 8. […]"}], "98": [{"ref": "§ 247 ust. 3 WT – usuwanie dymu z podziemnej kondygnacji z pomieszczeniem dla ponad 100 osób", "kind": "akt", "act": "wt", "label": "§ 247", "text": "3. W podziemnej kondygnacji budynku, w której znajduje się pomieszczenie przeznaczone dla ponad 100 osób, oraz budowli podziemnej z takim pomieszczeniem, należy zastosować rozwiązania techniczno-budowlane zapewniające usuwanie dymu z tego pomieszczenia i z dróg ewakuacyjnych."}], "99": [{"ref": "§ 24 ust. 2 i 3 RPB – zapas wody dla instalacji wodociągowej ppoż.", "kind": "akt", "act": "rpb", "label": "§ 24", "text": "2. Do zasilania w wodę instalacji wodociągowej przeciwpożarowej w budynkach wysokich i wysokościowych powinien być zapewniony zapas wody zgromadzony o łącznej pojemności nie mniejszej niż 100 m3 w jednym lub kilku zbiornikach przeznaczony wyłącznie do tego celu."}], "100": [{"ref": "PN-EN 13200-1 – obiekty widowiskowe, czas ewakuacji z widowni", "kind": "norma"}], "102": [{"ref": "§ 230 WT – warunki obniżenia klasy odporności pożarowej", "kind": "akt", "act": "wt", "label": "§ 230", "text": "§ 230. 1. W budynku jednokondygnacyjnym lub na ostatniej kondygnacji budynku wielokondygnacyjnego wielkości stref pożarowych PM, z wyjątkiem garaży, można powiększyć o 100%, jeżeli budynek nie zawiera pomieszczenia zagrożonego wybuchem i jest wykonany z elementów nierozprzestrzeniających ognia oraz zastosowano samoczynne urządzenia oddymiające. 2. W budynku jednokondygnacyjnym wielkości stref pożarowych PM, z wyjątkiem garażu, nie ogranicza się, pod warunkiem zastosowania stałych samoczynnych urządzeń gaśniczych wodnych i samoczynnych urządzeń oddymiających."}], "104": [{"ref": "§ 28 ust. 1 pkt 17 RPB – SSP w garażach podziemnych", "kind": "akt", "act": "rpb", "label": "§ 28", "text": "§ 28. 1. Stosowanie systemu sygnalizacji pożarowej, obejmującego urządzenia sygnalizacyjno-alarmowe, służące do samoczynnego wykrywania i przekazywania informacji o pożarze, a także urządzenia odbiorcze alarmów pożarowych i urządzenia odbiorcze sygnałów uszkodzeniowych, jest wymagane w: 1) budynkach handlowych lub wystawowych: a) jednokondygnacyjnych o powierzchni strefy pożarowej powyżej 5000 m2, b) wielokondygnacyjnych o powierzchni strefy pożarowej powyżej 2500 m2; 2) teatrach o liczbie miejsc powyżej 300; 3) kinach o liczbie miejsc powyżej 600; 4) budynkach o liczbie miejsc służących celom gastronomicznym powyżej 300; 5) salach widowiskowych i sportowych o liczbie miejsc powyżej 1500; 6) szpitalach, z wyjątkiem psychiatrycznych, oraz w sanatoriach ‒ o liczbie łóżek powyżej 200 w budynku; 7) szpitalach psychiatrycznych o liczbie łóżek powyżej 100 w budynku; […]"}], "105": [{"ref": "§ 253 ust. 1 WT – dźwig dla ekip ratowniczych", "kind": "akt", "act": "wt", "label": "§ 253", "text": "§ 253. 1. W budynku ZL I, ZL II, ZL III lub ZL V, mającym kondygnację z posadzką na wysokości powyżej 25 m ponad poziomem terenu przy najniżej położonym wejściu do budynku oraz w budynku wysokościowym (WW) ZL IV przynajmniej jeden dźwig powinien być przystosowany do potrzeb ekip ratowniczych, spełniając wymagania Polskiej Normy dotyczącej dźwigów dla straży pożarnej. Dźwig dla ekip ratowniczych powinien zapewniać dostęp do każdej strefy pożarowej na kondygnacji bezpośrednio lub drogami komunikacji ogólnej."}], "106": [{"ref": "PN-EN 60849 / PKN-CEN/TS 54-14 – poziomy dźwięku", "kind": "norma"}], "107": [{"ref": "PN-EN 12845 – zbiornik pośredni z uzupełnianiem", "kind": "norma"}], "108": [{"ref": "PKN-CEN/TS 54-14:2006 – strefy dozorowe", "kind": "norma"}], "109": [{"ref": "PN-EN 1838 – oświetlenie awaryjne, natężenie na drodze ewakuacyjnej", "kind": "norma"}], "110": [{"ref": "§ 228 ust. 1 WT – tabela powierzchni stref PM", "kind": "akt", "act": "wt", "label": "§ 228", "text": "§ 228. 1. Dopuszczalne powierzchnie stref pożarowych PM, z wyjątkiem garaży, określa poniższa tabela: Rodzaj stref pożarowych Gęstość obciążenia ogniowego Q [MJ/m2] Dopuszczalna powierzchnia strefy pożarowej w m2 w budynku o jednej kondygnacji nadziemnej (bez ograniczenia wysokości) w budynku wielokondygnacyjnym niskim i średniowysokim (N) i (SW) wysokim i wysokościowym (W) i (WW) 1 2 3 4 5 Strefy pożarowe z pomieszczeniem zagrożonym wybuchem Q > 4000 2000 < Q ≤ 4000 1000 < Q ≤ 2000 500 < Q ≤ 1000 Q ≤ 500 1000 2000 4000 6000 8000 * * 1000 2000 3000 * * * 500 1000 Strefy pożarowe pozostałe Q > 4000 2000 < Q ≤ 4000 1000 < Q ≤ 2000 500 < Q ≤ 1000 Q ≤ 500 2000 4000 8000 15 000 20 000 1000 2000 4000 8000 10 000 * * 1000 2500 5000 * Nie dopuszcza się takich przypadków."}, {"ref": "§ 229 ust. 1 i 2 WT – powiększenie o 150%", "kind": "akt", "act": "wt", "label": "§ 229", "text": "§ 229. 1. Dopuszcza się powiększenie powierzchni stref pożarowych, o których mowa w § 228, pod warunkiem ich ochrony: 1) stałymi samoczynnymi urządzeniami gaśniczymi wodnymi – o 100%; 2) samoczynnymi urządzeniami oddymiającymi – o 50%."}], "111": [{"ref": "§ 237 WT – długość przejścia ewakuacyjnego i powiększenia", "kind": "akt", "act": "wt", "label": "§ 237", "text": "§ 237. 1. W pomieszczeniach, od najdalszego miejsca, w którym może przebywać człowiek, do wyjścia ewakuacyjnego na drogę ewakuacyjną lub do innej strefy pożarowej albo na zewnątrz budynku, powinno być zapewnione przejście, zwane dalej „przejściem ewakuacyjnym”, o długości nieprzekraczającej: 1) w strefach pożarowych ZL – 40 m; 2) w strefach pożarowych PM o gęstości obciążenia ogniowego przekraczającej 500 MJ/m2 w budynku o więcej niż jednej kondygnacji nadziemnej – 75 m; 3) w strefach pożarowych PM, o obciążeniu ogniowym nieprzekraczającym 500 MJ/m2, w budynku o więcej niż jednej kondygnacji nadziemnej oraz w strefach pożarowych PM w budynku o jednej kondygnacji nadziemnej bez względu na wielkość obciążenia ogniowego – 100 m. 2. W pomieszczeniu zagrożonym wybuchem długość przejścia ewakuacyjnego, o którym mowa w ust. 1 pkt 2 i 3, nie powinna przekraczać 40 m. 3. […]"}], "112": [{"ref": "§ 6 ust. 10 pkt 1 RW – uzupełniający zapas wody dla obiektów PM", "kind": "akt", "act": "rw", "label": "§ 6", "text": "10. W przypadku gdy wydajność wodociągu stanowiącego źródło wody do celów przeciwpożarowych nie zapewnia ilości określonej w ust. 3—5 i 7—9, należy zapewnić uzupełniający zapas wody w zbiornikach przeciwpożarowych, technologicznych lub naturalnych, przystosowanych do poboru wody przez pompy pożarnicze: 1) dla obiektów budowlanych produkcyjnych i magazynowych wymienionych w ust. 3, w ilości równej iloczynowi brakującej wydajności wodociągu przez czas trwania pożaru przewidziany dla rozpatrywanej strefy pożarowej, ustalony w Polskiej Normie dotyczącej obliczania gęstości obciążenia ogniowego oraz wyznaczania względnego czasu trwania pożaru, jednak nie większy niż 4 godziny; 2) dla obiektów budowlanych wymienionych w ust. 4, 5 i 7—9, w ilości odpowiadającej 10 m3 zapasu wody na 1 dm3/s brakującej wydajności wodociągu."}, {"ref": "§ 6 ust. 3 RW – ilość wody według tabeli nr 2", "kind": "akt", "act": "rw", "label": "§ 6", "text": "3. Wymaganą ilość wody do celów przeciwpożarowych dla obiektów budowlanych produkcyjnych i magazynowych, z wyjątkiem wymienionych w ust. 4—8, służącą do zewnętrznego gaszenia pożaru, określa się, biorąc pod uwagę tę strefę pożarową, dla której jest ona największa, zgodnie z tabelą nr 2 załącznika do rozporządzenia. www.rcl.gov.pl Dziennik Ustaw Nr 124 — 9065 — Poz. 1030"}], "114": [{"ref": "art. 6a ust. 1 UOP – warunki stosowania rozwiązań zamiennych", "kind": "akt", "act": "uop", "label": "art. 6a", "text": "1. Wymagania ochrony przeciwpożarowej dotyczące obiektów budowlanych lub terenów mogą być w przypadkach określonych w przepisach dotyczących ochrony przeciwpożarowej spełnione w sposób inny niż określony w tych przepisach, jeżeli proponowane rozwiązania zamienne w stosunku do wymagań ochrony przeciwpożarowej ograniczają możliwość powstania pożaru, a w razie jego wystąpienia: 1) zapewniają zachowanie nośności konstrukcji przez określony czas; 2) zapewniają ograniczenie rozprzestrzeniania się ognia i dymu wewnątrz obiektu budowlanego; 3) zapewniają ograniczenie rozprzestrzeniania się pożaru na sąsiednie obiekty budowlane lub tereny przyległe; 4) zapewniają możliwość ewakuacji ludzi lub ich uratowania w inny sposób; 5) uwzględniają bezpieczeństwo ekip ratowniczych."}], "115": [{"ref": "§ 4 rozp. w sprawie uzgadniania projektu pod względem ochrony ppoż.", "kind": "akt", "act": "uzgadnianie", "label": "§ 4", "text": "§ 4. […] 2) w przypadku projektu architektoniczno-budowlanego, w szczególności: a) informacje o powierzchni wewnętrznej, wysokości i liczbie kondygnacji, b) charakterystykę zagrożenia pożarowego, w tym informacje o parametrach pożarowych materiałów niebezpiecznych pożarowo oraz zagrożeniach wynikających z procesów technologicznych, a także w zależności od potrzeb – charakterystykę pożarów przyjętych do celów projektowych, c) informacje o klasyfikacji pożarowej z uwagi na przeznaczenie i sposób użytkowania, d) informacje o kategorii zagrożenia ludzi oraz przewidywanej liczbie osób na każdej kondygnacji, a także w pomieszczeniach, których drzwi ewakuacyjne powinny otwierać się na zewnątrz pomieszczeń, e) informacje o podziale na strefy pożarowe, f) maksymalną gęstość obciążenia ogniowego poszczególnych stref pożarowych PM wraz z warunkami przyjętymi do jej określenia, g) informacje o klasie odporności pożarowej oraz odporności ogniowej i stopniu rozprzestrzeniania ognia przez elementy budowlane, h) informacje o występowaniu materiałów wybuchowych oraz zagrożenia wybuchem, w tym pomieszczeń zagrożonych wybuchem, i) informacje o warunkach i strategii ewakuacji ludzi lub ich uratowania w inny sposób, uwzględniające liczbę i stan sprawności osób przebywających w obiekcie, j) informacje o doborze urządzeń przeciwpożarowych oraz innych instalacji i urządzeń służących bezpieczeństwu pożarowemu wraz z określeniem zakresu i celu ich stosowania, ﻿ k) informacje o przygotowaniu obiektu budowlanego do prowadzenia działań ratowniczych, w tym informacje o punktach poboru wody do celów przeciwpożarowych, nasadach służących do zasilania urządzeń gaśniczych i innych rozwiązaniach przewidzianych do tych działań oraz dźwigach dla ekip ratowniczych i prowadzących do nich dojściach, l) informacje o usytuowaniu z uwagi na bezpieczeństwo pożarowe, w tym informacje o parametrach wpływających na odległości dopuszczalne, m) informacje o rozwiązaniach zamiennych w stosunku do wymagań ochrony przeciwpożarowej zastosowanych na podstawie zgody, o której mowa w art. 6c pkt 1 lub 2 ustawy z dnia 24 sierpnia 1991 r. o ochronie przeciwpożarowej, w zakresie rozwiązań objętych projektem architektoniczno-budowlanym; […]"}], "117": [{"ref": "§ 2 pkt 4 rozp. MSWiA w sprawie uzgadniania projektu – definicja scenariusza pożarowego", "kind": "norma"}], "119": [{"ref": "PN-EN 12845 / NFPA – tryskacze ESFR", "kind": "norma"}], "120": [{"ref": "§ 19 RPB – hydranty wewnętrzne w garażach", "kind": "akt", "act": "rpb", "label": "§ 19", "text": "§ 19. […] 4) Dodany przez § 1 rozporządzenia Ministra Spraw Wewnętrznych i Administracji z dnia 11 stycznia 2019 r. zmieniającego rozporządzenie w sprawie ochrony przeciwpożarowej budynków, innych obiektów budowlanych i terenów (Dz. U. poz. 67), które weszło w życie z dniem 29 stycznia 2019 r. 2. Hydranty 33 muszą być stosowane w garażu: 1) jednokondygnacyjnym zamkniętym o więcej niż 10 stanowiskach postojowych; 2) wielokondygnacyjnym. 3. Hydranty 52 muszą być stosowane: 1) w strefie pożarowej produkcyjnej i magazynowej o gęstości obciążenia ogniowego przekraczającej 500 MJ/m2 i powierzchni przekraczającej 200 m2; 2) w strefie pożarowej produkcyjnej i magazynowej o gęstości obciążenia ogniowego nieprzekraczającej 500 MJ/m2, w której znajduje się pomieszczenie o powierzchni przekraczającej 100 m2 i gęstości obciążenia ogniowego przekraczającej 1 000 MJ/m2; […]"}], "121": [{"ref": "PN-B-02857:2017-04 – przeciwpożarowe zbiorniki wodne", "kind": "norma"}], "122": [{"ref": "§ 164 WT – instalacje gazowe zasilające kotłownie", "kind": "akt", "act": "wt", "label": "§ 164", "text": "§ 164. 1. Przewodów instalacji gazowych nie należy prowadzić przez pomieszczenia mieszkalne oraz pomieszczenia, których sposób użytkowania może spowodować naruszenie stanu technicznego instalacji lub wpływać na parametry eksploatacyjne gazu. 2. Zabrania się prowadzenia przez pomieszczenia mieszkalne przewodów instalacji gazowej z zastosowaniem połączeń gwintowanych, a także z zastosowaniem innych sposobów łączenia rur, jeżeli mogą one stanowić zagrożenie dla bezpieczeństwa mieszkańców. 3. Przewody instalacji gazowej, w stosunku do przewodów innych instalacji stanowiących wyposażenie budynku (ogrzewczej wodociągowej, kanalizacyjnej, elektrycznej, piorunochronnej itp.), należy lokalizować w sposób zapewniający bezpieczeństwo ich użytkowania. Odległość między przewodami instalacji gazowej a innymi przewodami powinna umożliwiać wykonywanie prac konserwacyjnych. 4. […]"}], "123": [{"ref": "dyrektywa ATEX 2014/34/UE – kategorie urządzeń", "kind": "ue"}], "124": [{"ref": "PKN-CEN/TS 54-14:2006", "kind": "norma"}], "125": [{"ref": "§ 25 ust. 4 RPB – średnice przewodów zasilających hydranty wewnętrzne", "kind": "akt", "act": "rpb", "label": "§ 25", "text": "4. Średnice nominalne przewodów zasilających, w milimetrach, na których instaluje się hydranty wewnętrzne i zawory 52, powinny wynosić co najmniej: 1) DN 25 ‒ dla hydrantów 25; 2) DN 50 ‒ dla hydrantów 33 i 52; 3) DN 80 ‒ dla zaworów 52 na nawodnionych pionach w budynkach wysokich i wysokościowych."}], "127": [{"ref": "PN-EN 12845:2015-10 – urządzenia tryskaczowe", "kind": "norma"}], "129": [{"ref": "PKN-CEN/TS 54-14:2006 pkt A.6.5.1 – rozmieszczenie czujek pod stropami płaskimi", "kind": "norma"}], "130": [{"ref": "PN-EN 13501-4 – klasyfikacja ogniowa elementów systemów kontroli rozprzestrzeniania dymu", "kind": "norma"}, {"ref": "PN-EN 12101-8 – klapy odcinające wentylacji pożarowej", "kind": "norma"}], "133": [{"ref": "§ 9 ust. 7 RW – średnice przewodów z hydrantami zewnętrznymi", "kind": "akt", "act": "rw", "label": "§ 9", "text": "7. Wyrażone w milimetrach średnice nominalne (DN) przewodów wodociągowych wykonanych z rur stalowych, na których przewiduje się instalowanie hydrantów zewnętrznych przeciwpożarowych, powinny wynosić co najmniej: 1) DN 100 — w sieci obwodowej; 2) DN 125 — w sieci rozgałęzieniowej; 3) w odgałęzieniach sieci obwodowej — według obliczeń hydraulicznych; 4) DN 80 — przy rozbudowie lub modernizacji istniejącego wodociągu o wydajności 5 dm3/s w jednostce osadniczej o liczbie mieszkańców nieprzekraczającej 2 000."}], "135": [{"ref": "§ 208a WT – materiały niepalne; PN-EN 13501-1", "kind": "norma"}], "136": [{"ref": "§ 216 ust. 7 WT – antresola dla więcej niż 10 osób", "kind": "akt", "act": "wt", "label": "§ 216", "text": "7. Strop tworzący w pomieszczeniu dodatkowy poziom – antresolę, przeznaczoną do użytku dla więcej niż 10 osób, a także jej konstrukcja nośna, powinny odpowiadać wymaganiom wynikającym z klasy odporności pożarowej budynku, lecz nie mniejszym niż dla klasy „D”, z zastrzeżeniem § 214."}, {"ref": "§ 216 ust. 1 WT – klasy odporności ogniowej elementów budynku", "kind": "akt", "act": "wt", "label": "§ 216", "text": "§ 216. 1. Elementy budynku, odpowiednio do jego klasy odporności pożarowej, powinny spełniać, z zastrzeżeniem § 213 oraz § 237 ust. 9, co najmniej wymagania określone w poniższej tabeli: Klasa odporności pożarowej budynku Klasa odporności ogniowej elementów budynku5) *) główna konstrukcja nośna konstrukcja dachu strop1) ściana zewnętrzna1), 2) ściana wewnętrzna1) przekrycie dachu3) 1 2 3 4 5 6 7 „A” R 240 R 30 R E I 120 E I 120 (o↔i) E I 60 R E 30 „B” R 120 R 30 R E I 60 E I 60 (o↔i) E I 304) R E 30 „C” R 60 R 15 R E I 60 E I 30 (o↔i) E I 154) R E 15 „D” R 30 (–) R E I 30 E I 30 (o↔i) (–) (–) „E” (–) (–) (–) (–) (–) (–) *) Z zastrzeżeniem § 219 ust. 1. […]"}], "137": [{"ref": "art. 10 ust. 1 ustawy o wyrobach budowlanych", "kind": "akt", "act": "wyroby", "label": "art. 10", "text": "1. Dopuszczone do jednostkowego zastosowania w obiekcie budowlanym są wyroby budowlane, z wyłączeniem wyrobów, o których mowa w art. 5 ust. 1, wykonane według indywidualnej dokumentacji technicznej, sporządzonej przez projektanta obiektu lub z nim uzgodnionej, dla których producent wydał oświadczenie, że zapewniono zgodność wyrobu budowlanego z tą dokumentacją oraz z przepisami."}], "138": [{"ref": "PN-EN 12101-1 – kurtyny dymowe, klasyfikacja", "kind": "norma"}], "139": [{"ref": "§ 20 RPB / RW – zasilanie rezerwowe pompowni przeciwpożarowych", "kind": "akt", "act": "rpb", "label": "§ 20", "text": "§ 20. 1. Hydranty wewnętrzne oraz zawory 52 powinny być umieszczane przy drogach komunikacji ogólnej, w szczególności: 1) przy wejściach do budynku i klatek schodowych na każdej kondygnacji budynku, przy czym w budynkach wysokich i wysokościowych zaleca się lokalizację zaworów 52 w przedsionkach przeciwpożarowych, a dopuszcza na klatkach schodowych; 2) w przejściach i na korytarzach, w tym w holach i na korytarzach poszczególnych kondygnacji budynków wysokich i wysokościowych; 3) przy wejściach na poddasza; 4) przy wyjściach na przestrzeń otwartą lub przy wyjściach ewakuacyjnych z pomieszczeń produkcyjnych i magazynowych, w szczególności zagrożonych wybuchem. 2. […]"}], "141": [{"ref": "§ 37 RPB – pomieszczenia uznane za zagrożone wybuchem", "kind": "akt", "act": "rpb", "label": "§ 37", "text": "§ 37. 1. W obiektach i na terenach przyległych, gdzie są prowadzone procesy technologiczne z użyciem materiałów mogących wytworzyć mieszaniny wybuchowe lub w których materiały takie są magazynowane, dokonuje się oceny zagrożenia wybuchem. 2. Ocena zagrożenia wybuchem obejmuje wskazanie pomieszczeń zagrożonych wybuchem, wyznaczenie w pomieszczeniach i przestrzeniach zewnętrznych odpowiednich stref zagrożenia wybuchem wraz z opracowaniem graficznej dokumentacji klasyfikacyjnej oraz wskazanie czynników mogących w nich zainicjować zapłon. 3. Graficzna dokumentacja klasyfikacyjna zawiera plany sytuacyjne obrazujące rodzaj i zasięg stref zagrożenia wybuchem oraz lokalizację i identyfikację źródeł emisji, zgodnie z zasadami określonymi w Polskich Normach. 4. Oceny zagrożenia wybuchem dokonują: inwestor, projektant lub użytkownik decydujący o procesie technologicznym. 5. […]"}], "143": [{"ref": "PN-EN 12845 – urządzenia tryskaczowe suche", "kind": "norma"}], "144": [{"ref": "PN-B-02857:2017-04 – zbiornik przeciwpożarowy w budynku", "kind": "norma"}, {"ref": "§ 212 ust. 9 WT – pomieszczenia zbiorników przeciwpożarowych jako odrębna strefa pożarowa", "kind": "akt", "act": "wt", "label": "§ 212", "text": "9. Pomieszczenia, w których są umieszczone przeciwpożarowe zbiorniki wody lub innych środków gaśniczych, pompy wodne instalacji przeciwpożarowych, maszynownie wentylacji do celów przeciwpożarowych oraz rozdzielnie elektryczne, zasilające, niezbędne podczas pożaru, instalacje i urządzenia, powinny stanowić odrębną strefę pożarową."}], "145": [{"ref": "§ 12 ust. 1 pkt 2 RW – droga pożarowa do budynków SW, W i WW z ZL III, IV lub V", "kind": "akt", "act": "rw", "label": "§ 12", "text": "§ 12. 1. Drogę pożarową o utwardzonej nawierzchni, umożliwiającą dojazd pojazdów jednostek ochrony przeciwpożarowej do obiektu budowlanego o każdej porze roku, należy doprowadzić do: 1) budynku zawierającego strefę pożarową zakwalifikowaną do kategorii zagrożenia ludzi ZL I lub ZL II; 2) budynku należącego do grupy wysokości: średniowysoki, wysoki lub wysokościowy, zawierającego strefę pożarową zakwalifikowaną do kategorii zagrożenia ludzi ZL III, ZL IV lub ZL V; 3) budynku zawierającego strefę pożarową produkcyjną lub magazynową oraz do strefy pożarowej poza budynkiem, obejmującej urządzenia technologiczne, plac składowy lub wiatę, jeżeli gęstość obciążenia ogniowego wymienionych stref pożarowych przekracza 500 MJ/m2 i zachodzi co najmniej jeden z warunków: a) powierzchnia strefy pożarowej przekracza 1 000 m2, b) występuje pomieszczenie zagrożone wybuchem; […]"}, {"ref": "§ 12 ust. 1 pkt 5 lit. b RW – budynek niski ZL V z ponad 50 miejscami noclegowymi", "kind": "akt", "act": "rw", "label": "§ 12", "text": "§ 12. 1. Drogę pożarową o utwardzonej nawierzchni, umożliwiającą dojazd pojazdów jednostek ochrony przeciwpożarowej do obiektu budowlanego o każdej porze roku, należy doprowadzić do: 1) budynku zawierającego strefę pożarową zakwalifikowaną do kategorii zagrożenia ludzi ZL I lub ZL II; 2) budynku należącego do grupy wysokości: średniowysoki, wysoki lub wysokościowy, zawierającego strefę pożarową zakwalifikowaną do kategorii zagrożenia ludzi ZL III, ZL IV lub ZL V; 3) budynku zawierającego strefę pożarową produkcyjną lub magazynową oraz do strefy pożarowej poza budynkiem, obejmującej urządzenia technologiczne, plac składowy lub wiatę, jeżeli gęstość obciążenia ogniowego wymienionych stref pożarowych przekracza 500 MJ/m2 i zachodzi co najmniej jeden z warunków: a) powierzchnia strefy pożarowej przekracza 1 000 m2, b) występuje pomieszczenie zagrożone wybuchem; […]"}], "146": [{"ref": "PKN-CEN/TS 54-14:2006 – rozmieszczenie czujek, wpływ belek", "kind": "norma"}], "147": [{"ref": "§ 227 ust. 4 pkt 2 WT – powiększenie strefy o 100%", "kind": "akt", "act": "wt", "label": "§ 227", "text": "4. Dopuszcza się powiększenie powierzchni stref pożarowych, o których mowa w ust. 1, z wyjątkiem stref pożarowych w wielokondygnacyjnych budynkach wysokich (W) i wysokościowych (WW), pod warunkiem zastosowania: 1) stałych samoczynnych urządzeń gaśniczych wodnych – o 100%; 2) samoczynnych urządzeń oddymiających uruchamianych za pomocą systemu wykrywania dymu – o 100%. Przy jednoczesnym stosowaniu urządzeń wymienionych w pkt 1 i 2 dopuszcza się powiększenie powierzchni stref pożarowych o 200%."}, {"ref": "§ 237 ust. 6 pkt 2 WT – powiększenie przejścia o 50%", "kind": "akt", "act": "wt", "label": "§ 237", "text": "6. Długości przejść, o których mowa w ust. 1 i 2, mogą być powiększone pod warunkiem zastosowania: 1) stałych samoczynnych urządzeń gaśniczych wodnych – o 50%; 2) samoczynnych urządzeń oddymiających uruchamianych za pomocą systemu wykrywania dymu – o 50%."}], "148": [{"ref": "§ 181 ust. 3 pkt 1 lit. c WT – pomieszczenia wystawowe w muzeach", "kind": "akt", "act": "wt", "label": "§ 181", "text": "3. Awaryjne oświetlenie ewakuacyjne należy stosować: 1) w pomieszczeniach: a) widowni kin, teatrów i filharmonii oraz innych sal widowiskowych, b) audytoriów, sal konferencyjnych, czytelni, lokali rozrywkowych oraz sal sportowych, przeznaczonych dla ponad 200 osób, c) wystawowych w muzeach, d) o powierzchni netto ponad 1000 m2 w garażach oświetlonych wyłącznie światłem sztucznym, e) o powierzchni netto ponad 2000 m2 w budynkach użyteczności publicznej, budynkach zamieszkania zbiorowego oraz w budynkach produkcyjnych i magazynowych; 2) na drogach ewakuacyjnych: a) z pomieszczeń wymienionych w pkt 1, b) oświetlonych wyłącznie światłem sztucznym, c) w szpitalach i innych budynkach przeznaczonych przede wszystkim do użytku osób o ograniczonej zdolności poruszania się, d) w wysokich i wysokościowych budynkach użyteczności publicznej i zamieszkania zbiorowego."}, {"ref": "§ 181 ust. 3 pkt 2 lit. a WT – drogi ewakuacyjne z pomieszczeń wymienionych w pkt 1", "kind": "akt", "act": "wt", "label": "§ 181", "text": "3. Awaryjne oświetlenie ewakuacyjne należy stosować: 1) w pomieszczeniach: a) widowni kin, teatrów i filharmonii oraz innych sal widowiskowych, b) audytoriów, sal konferencyjnych, czytelni, lokali rozrywkowych oraz sal sportowych, przeznaczonych dla ponad 200 osób, c) wystawowych w muzeach, d) o powierzchni netto ponad 1000 m2 w garażach oświetlonych wyłącznie światłem sztucznym, e) o powierzchni netto ponad 2000 m2 w budynkach użyteczności publicznej, budynkach zamieszkania zbiorowego oraz w budynkach produkcyjnych i magazynowych; 2) na drogach ewakuacyjnych: a) z pomieszczeń wymienionych w pkt 1, b) oświetlonych wyłącznie światłem sztucznym, c) w szpitalach i innych budynkach przeznaczonych przede wszystkim do użytku osób o ograniczonej zdolności poruszania się, d) w wysokich i wysokościowych budynkach użyteczności publicznej i zamieszkania zbiorowego."}], "149": [{"ref": "§ 228 ust. 1 WT – tabela powierzchni stref PM", "kind": "akt", "act": "wt", "label": "§ 228", "text": "§ 228. 1. Dopuszczalne powierzchnie stref pożarowych PM, z wyjątkiem garaży, określa poniższa tabela: Rodzaj stref pożarowych Gęstość obciążenia ogniowego Q [MJ/m2] Dopuszczalna powierzchnia strefy pożarowej w m2 w budynku o jednej kondygnacji nadziemnej (bez ograniczenia wysokości) w budynku wielokondygnacyjnym niskim i średniowysokim (N) i (SW) wysokim i wysokościowym (W) i (WW) 1 2 3 4 5 Strefy pożarowe z pomieszczeniem zagrożonym wybuchem Q > 4000 2000 < Q ≤ 4000 1000 < Q ≤ 2000 500 < Q ≤ 1000 Q ≤ 500 1000 2000 4000 6000 8000 * * 1000 2000 3000 * * * 500 1000 Strefy pożarowe pozostałe Q > 4000 2000 < Q ≤ 4000 1000 < Q ≤ 2000 500 < Q ≤ 1000 Q ≤ 500 2000 4000 8000 15 000 20 000 1000 2000 4000 8000 10 000 * * 1000 2500 5000 * Nie dopuszcza się takich przypadków."}, {"ref": "§ 229 ust. 1 pkt 1 WT – powiększenie o 100%", "kind": "akt", "act": "wt", "label": "§ 229", "text": "§ 229. 1. Dopuszcza się powiększenie powierzchni stref pożarowych, o których mowa w § 228, pod warunkiem ich ochrony: 1) stałymi samoczynnymi urządzeniami gaśniczymi wodnymi – o 100%; 2) samoczynnymi urządzeniami oddymiającymi – o 50%."}], "150": [{"ref": "§ 237 WT – długość przejścia ewakuacyjnego i powiększenia", "kind": "akt", "act": "wt", "label": "§ 237", "text": "§ 237. 1. W pomieszczeniach, od najdalszego miejsca, w którym może przebywać człowiek, do wyjścia ewakuacyjnego na drogę ewakuacyjną lub do innej strefy pożarowej albo na zewnątrz budynku, powinno być zapewnione przejście, zwane dalej „przejściem ewakuacyjnym”, o długości nieprzekraczającej: 1) w strefach pożarowych ZL – 40 m; 2) w strefach pożarowych PM o gęstości obciążenia ogniowego przekraczającej 500 MJ/m2 w budynku o więcej niż jednej kondygnacji nadziemnej – 75 m; 3) w strefach pożarowych PM, o obciążeniu ogniowym nieprzekraczającym 500 MJ/m2, w budynku o więcej niż jednej kondygnacji nadziemnej oraz w strefach pożarowych PM w budynku o jednej kondygnacji nadziemnej bez względu na wielkość obciążenia ogniowego – 100 m. 2. W pomieszczeniu zagrożonym wybuchem długość przejścia ewakuacyjnego, o którym mowa w ust. 1 pkt 2 i 3, nie powinna przekraczać 40 m. 3. […]"}], "151": [{"ref": "§ 282 WT – zwolnienie budynków IN do 1500 m3 z wymagań klasy odporności pożarowej", "kind": "akt", "act": "wt", "label": "§ 282", "text": "§ 282. Od wymagań dotyczących klasy odporności pożarowej budynków, określonych w § 212, zwalnia się budynki IN o kubaturze brutto do 1500 m3."}, {"ref": "§ 209 ust. 4 WT – budynki do przechowywania płodów rolnych jako IN", "kind": "akt", "act": "wt", "label": "§ 209", "text": "4. Wymagania dotyczące bezpieczeństwa pożarowego budynków oraz części budynków stanowiących odrębne strefy pożarowe, określanych jako IN, odnoszą się również do takich budynków w zabudowie zagrodowej o kubaturze brutto nieprzekraczającej 1500 m3, jak stodoły, budynki do przechowywania płodów rolnych i budynki gospodarcze."}], "152": [{"ref": "PN-B-02852:2001 – obliczanie gęstości obciążenia ogniowego", "kind": "norma"}], "154": [{"ref": "§ 256 ust. 3 WT – długości dojść, drugie dojście dłuższe o 100%", "kind": "akt", "act": "wt", "label": "§ 256", "text": "3. Dopuszczalne długości dojść ewakuacyjnych w strefach pożarowych określa poniższa tabela: Rodzaj strefy pożarowej Długość dojścia w m przy jednym dojściu przy co najmniej 2 dojściach1) 1 2 3 Z pomieszczeniem zagrożonym wybuchem 10 40 PM o gęstości obciążenia ogniowego Q > 500 MJ/m2 bez pomieszczenia zagrożonego wybuchem 302) 60 PM o gęstości obciążenia ogniowego Q ≤ 500 MJ/m2 bez pomieszczenia zagrożonego wybuchem 602) 100 ZL I, II i V 10 40 ZL III 302) 60 ZL IV 602) 100 1) Dla dojścia najkrótszego, przy czym dopuszcza się dla drugiego dojścia długość większą o 100% od najkrótszego. Dojścia te nie mogą się pokrywać ani krzyżować, przy czym dopuszcza się ich wspólny początkowy przebieg na długości nie większej niż 2 m. 2) W tym nie więcej niż 20 m na poziomej drodze ewakuacyjnej."}, {"ref": "§ 209 ust. 5 WT – strefa zaliczona do więcej niż jednej kategorii ZL", "kind": "akt", "act": "wt", "label": "§ 209", "text": "5. Strefy pożarowe zaliczone, z uwagi na przeznaczenie i sposób użytkowania, do więcej niż jednej kategorii zagrożenia ludzi, powinny spełniać wymagania określone dla każdej z tych kategorii."}], "155": [{"ref": "§ 258 WT – wymagania dla posadzek na drogach ewakuacyjnych i w pomieszczeniach", "kind": "akt", "act": "wt", "label": "§ 258", "text": "§ 258. 1. W strefach pożarowych ZL I, ZL II, ZL III i ZL V stosowanie do wykończenia wnętrz materiałów i wyrobów łatwo zapalnych, których produkty rozkładu termicznego są bardzo toksyczne lub intensywnie dymiące, jest zabronione. 1a. W przypadku stosowania materiałów wykończeniowych luźno zwisających, w szczególności w kurtynach, zasłonach, draperiach, kotarach oraz żaluzjach, za łatwo zapalne uważa się materiały, których właściwości określone w badaniach zgodnych z Polskimi Normami odnoszącymi się do zapalności i rozprzestrzeniania płomienia przez wyroby włókiennicze nie spełniają co najmniej jednego z kryteriów: 1) ti ≥ 4 s; 2) ts ≤ 30 s; 3) nie następuje przepalenie trzeciej nitki; 4) nie występują płonące krople. 2. Na drogach komunikacji ogólnej, służących celom ewakuacji, stosowanie materiałów i wyrobów budowlanych łatwo zapalnych jest zabronione."}], "156": [{"ref": "§ 8, § 212 WT – klasa odporności pożarowej", "kind": "akt", "act": "wt", "label": "§ 8", "text": "§ 8. W celu określenia wymagań technicznych i użytkowych wprowadza się następujący podział budynków na grupy wysokości: 1) niskie (N) – do 12 m włącznie nad poziomem terenu lub mieszkalne o wysokości do 4 kondygnacji nadziemnych włącznie; 2) średniowysokie (SW) – ponad 12 m do 25 m włącznie nad poziomem terenu lub mieszkalne o wysokości ponad 4 do 9 kondygnacji nadziemnych włącznie; 3) wysokie (W) – ponad 25 m do 55 m włącznie nad poziomem terenu lub mieszkalne o wysokości ponad 9 do 18 kondygnacji nadziemnych włącznie; 4) wysokościowe (WW) – powyżej 55 m nad poziomem terenu."}], "157": [{"ref": "§ 47 ust. 2 rozp. w sprawie baz i stacji paliw płynnych – zapas środka pianotwórczego i wody", "kind": "akt", "act": "paliwa", "label": "§ 47", "text": "2. Zapas środka pianotwórczego powinien wystarczać na okres co najmniej trzydziestominutowego jego zużycia, a zapas wody, na dwugodzinne zużycie do gaszenia pożaru największego zbiornika i jego obwałowania."}], "158": [{"ref": "PN-EN 12845 – zbiornik pośredni", "kind": "norma"}], "159": [{"ref": "§ 6 ust. 10 pkt 1 RW – uzupełniający zapas wody dla obiektów PM", "kind": "akt", "act": "rw", "label": "§ 6", "text": "10. W przypadku gdy wydajność wodociągu stanowiącego źródło wody do celów przeciwpożarowych nie zapewnia ilości określonej w ust. 3—5 i 7—9, należy zapewnić uzupełniający zapas wody w zbiornikach przeciwpożarowych, technologicznych lub naturalnych, przystosowanych do poboru wody przez pompy pożarnicze: 1) dla obiektów budowlanych produkcyjnych i magazynowych wymienionych w ust. 3, w ilości równej iloczynowi brakującej wydajności wodociągu przez czas trwania pożaru przewidziany dla rozpatrywanej strefy pożarowej, ustalony w Polskiej Normie dotyczącej obliczania gęstości obciążenia ogniowego oraz wyznaczania względnego czasu trwania pożaru, jednak nie większy niż 4 godziny; 2) dla obiektów budowlanych wymienionych w ust. 4, 5 i 7—9, w ilości odpowiadającej 10 m3 zapasu wody na 1 dm3/s brakującej wydajności wodociągu."}], "160": [{"ref": "§ 2 pkt 4 rozp. MSWiA w sprawie uzgadniania projektu – definicja scenariusza pożarowego", "kind": "norma"}], "161": [{"ref": "§ 32 RPB – wyposażenie w gaśnice; rozp. MEN dot. lokalu przedszkola", "kind": "akt", "act": "rpb", "label": "§ 32", "text": "§ 32. […] 2) na każde 300 m2 powierzchni strefy pożarowej niewymienionej w pkt 1, z wyjątkiem zakwalifikowanej do kategorii zagrożenia ludzi ZL IV. 4. Wyposażenie w gaśnice magazynów, w których są składowane butle z gazem płynnym, oraz stacji paliw płynnych określa rozporządzenie Ministra Gospodarki z dnia 21 listopada 2005 r. w sprawie warunków technicznych, jakim powinny odpowiadać bazy i stacje paliw płynnych, rurociągi przesyłowe dalekosiężne służące do transportu ropy naftowej i produktów naftowych i ich usytuowanie. 5. Miejsce omłotów, niezależnie od wymaganych gaśnic, musi być wyposażone w pojemnik z wodą o objętości co najmniej 200 dm3, przygotowany do wykorzystania w celach gaśniczych z użyciem wiadra lub w inny równorzędny sposób."}], "162": [{"ref": "PN-EN 15004-1:2008 – urządzenia gaśnicze gazowe", "kind": "norma"}], "164": [{"ref": "art. 10 ust. 1 ustawy o wyrobach budowlanych – jednostkowe zastosowanie", "kind": "akt", "act": "wyroby", "label": "art. 10", "text": "1. Dopuszczone do jednostkowego zastosowania w obiekcie budowlanym są wyroby budowlane, z wyłączeniem wyrobów, o których mowa w art. 5 ust. 1, wykonane według indywidualnej dokumentacji technicznej, sporządzonej przez projektanta obiektu lub z nim uzgodnionej, dla których producent wydał oświadczenie, że zapewniono zgodność wyrobu budowlanego z tą dokumentacją oraz z przepisami."}, {"ref": "art. 5 ust. 1 ustawy o wyrobach budowlanych – wyroby objęte normą zharmonizowaną", "kind": "akt", "act": "wyroby", "label": "art. 5", "text": "1. Wyrób budowlany objęty normą zharmonizowaną lub zgodny z wydaną dla niego europejską oceną techniczną, może być wprowadzony do obrotu lub udostępniany na rynku krajowym wyłącznie zgodnie z rozporządzeniem Nr 305/2011. Wzór oznakowania CE określa załącznik II do rozporządzenia Parlamentu Europejskiego i Rady (WE) Nr 765/2008 z dnia 9 lipca 2008 r. ustanawiającego wymagania w zakresie akredytacji i nadzoru rynku odnoszące się do warunków wprowadzania produktów do obrotu i uchylającego rozporządzenie (EWG) nr 339/93 (Dz. Urz. UE L 218 z 13.08.2008, str. 30)."}], "166": [{"ref": "PN-EN 12845 – urządzenia tryskaczowe, punkt projektowy", "kind": "norma"}], "167": [{"ref": "§ 27, § 28, § 29 RPB – wyposażenie obiektów w urządzenia ppoż.", "kind": "akt", "act": "rpb", "label": "§ 27", "text": "§ 27. […] 2) muzeach oraz zabytkach budowlanych, wyznaczonych przez Generalnego Konserwatora Zabytków w uzgodnieniu z Komendantem Głównym Państwowej Straży Pożarnej; 3) ośrodkach elektronicznego przetwarzania danych o znaczeniu krajowym. 2. Stosowanie stałych samoczynnych urządzeń gaśniczych wodnych jest wymagane w: 1) budynkach handlowych lub wystawowych: a) jednokondygnacyjnych, w strefie pożarowej zakwalifikowanej do kategorii zagrożenia ludzi ZL I o powierzchni powyżej 8000 m2, b) wielokondygnacyjnych, w strefie pożarowej zakwalifikowanej do kategorii zagrożenia ludzi ZL I o powierzchni powyżej 5000 m2; 2) w budynkach o liczbie miejsc służących celom gastronomicznym powyżej 600; 3) budynkach użyteczności publicznej wysokościowych; 4) budynkach zamieszkania zbiorowego wysokościowych. 3. […]"}], "168": [{"ref": "PN-HD 60364-5-56 – instalacje bezpieczeństwa", "kind": "norma"}], "169": [{"ref": "§ 216 ust. 1 WT – klasa odporności ogniowej ściany zewnętrznej", "kind": "akt", "act": "wt", "label": "§ 216", "text": "§ 216. 1. Elementy budynku, odpowiednio do jego klasy odporności pożarowej, powinny spełniać, z zastrzeżeniem § 213 oraz § 237 ust. 9, co najmniej wymagania określone w poniższej tabeli: Klasa odporności pożarowej budynku Klasa odporności ogniowej elementów budynku5) *) główna konstrukcja nośna konstrukcja dachu strop1) ściana zewnętrzna1), 2) ściana wewnętrzna1) przekrycie dachu3) 1 2 3 4 5 6 7 „A” R 240 R 30 R E I 120 E I 120 (o↔i) E I 60 R E 30 „B” R 120 R 30 R E I 60 E I 60 (o↔i) E I 304) R E 30 „C” R 60 R 15 R E I 60 E I 30 (o↔i) E I 154) R E 15 „D” R 30 (–) R E I 30 E I 30 (o↔i) (–) (–) „E” (–) (–) (–) (–) (–) (–) *) Z zastrzeżeniem § 219 ust. 1. […]"}, {"ref": "§ 272 ust. 1 i 3 WT – usytuowanie przy granicy działki", "kind": "akt", "act": "wt", "label": "§ 272", "text": "§ 272. 1. Odległość ściany zewnętrznej wznoszonego budynku od granicy sąsiedniej niezabudowanej działki budowlanej powinna wynosić co najmniej połowę odległości określonej w § 271 ust. 1–7, przyjmując, że na działce niezabudowanej będzie usytuowany budynek o przeznaczeniu określonym w miejscowym planie zagospodarowania przestrzennego, przy czym dla budynków PM należy przyjmować, że będzie on miał gęstość obciążenia ogniowego strefy pożarowej Q większą od 1000 MJ/m2, lecz nie większą niż 4000 MJ/m2, a w przypadku braku takiego planu – budynek ZL ze ścianą zewnętrzną, o której mowa w § 271 ust. 1."}, {"ref": "§ 212 ust. 2 WT – klasa odporności pożarowej budynku", "kind": "akt", "act": "wt", "label": "§ 212", "text": "2. Wymaganą klasę odporności pożarowej dla budynku, zaliczonego do jednej kategorii ZL, określa poniższa tabela: Budynek ZL I ZL II ZL III ZL IV ZL V 1 2 3 4 5 6 niski (N) „B” „B” „C” „D” „C” średniowysoki (SW) „B” „B” „B” „C” „B” wysoki (W) „B” „B” „B” „B” „B” wysokościowy (WW) „A” „A” „A” „B” „A”"}], "172": [{"ref": "PN-EN 81-58:2005 – próba odporności ogniowej drzwi przystankowych", "kind": "norma"}], "173": [{"ref": "§ 181 ust. 3 pkt 1 lit. e WT – pomieszczenia ponad 2000 m2", "kind": "akt", "act": "wt", "label": "§ 181", "text": "3. Awaryjne oświetlenie ewakuacyjne należy stosować: 1) w pomieszczeniach: a) widowni kin, teatrów i filharmonii oraz innych sal widowiskowych, b) audytoriów, sal konferencyjnych, czytelni, lokali rozrywkowych oraz sal sportowych, przeznaczonych dla ponad 200 osób, c) wystawowych w muzeach, d) o powierzchni netto ponad 1000 m2 w garażach oświetlonych wyłącznie światłem sztucznym, e) o powierzchni netto ponad 2000 m2 w budynkach użyteczności publicznej, budynkach zamieszkania zbiorowego oraz w budynkach produkcyjnych i magazynowych; 2) na drogach ewakuacyjnych: a) z pomieszczeń wymienionych w pkt 1, b) oświetlonych wyłącznie światłem sztucznym, c) w szpitalach i innych budynkach przeznaczonych przede wszystkim do użytku osób o ograniczonej zdolności poruszania się, d) w wysokich i wysokościowych budynkach użyteczności publicznej i zamieszkania zbiorowego."}, {"ref": "§ 181 ust. 3 pkt 1 lit. d WT – garaże ponad 1000 m2", "kind": "akt", "act": "wt", "label": "§ 181", "text": "3. Awaryjne oświetlenie ewakuacyjne należy stosować: 1) w pomieszczeniach: a) widowni kin, teatrów i filharmonii oraz innych sal widowiskowych, b) audytoriów, sal konferencyjnych, czytelni, lokali rozrywkowych oraz sal sportowych, przeznaczonych dla ponad 200 osób, c) wystawowych w muzeach, d) o powierzchni netto ponad 1000 m2 w garażach oświetlonych wyłącznie światłem sztucznym, e) o powierzchni netto ponad 2000 m2 w budynkach użyteczności publicznej, budynkach zamieszkania zbiorowego oraz w budynkach produkcyjnych i magazynowych; 2) na drogach ewakuacyjnych: a) z pomieszczeń wymienionych w pkt 1, b) oświetlonych wyłącznie światłem sztucznym, c) w szpitalach i innych budynkach przeznaczonych przede wszystkim do użytku osób o ograniczonej zdolności poruszania się, d) w wysokich i wysokościowych budynkach użyteczności publicznej i zamieszkania zbiorowego."}], "175": [{"ref": "PN-B-02857:2017-04 – przeciwpożarowe zbiorniki wodne", "kind": "norma"}], "176": [{"ref": "§ 234 WT – wyprowadzenie ścian oddzielenia ppoż.", "kind": "akt", "act": "wt", "label": "§ 234", "text": "§ 234. 1. Przepusty instalacyjne w elementach oddzielenia przeciwpożarowego powinny mieć klasę odporności ogniowej (E I) wymaganą dla tych elementów. 2. Dopuszcza się nieinstalowanie przepustów, o których mowa w ust. 1, dla pojedynczych rur instalacji wodnych, kanalizacyjnych i ogrzewczych, wprowadzanych przez ściany i stropy do pomieszczeń higienicznosanitarnych. 3. Przepusty instalacyjne o średnicy większej niż 0,04 m w ścianach i stropach pomieszczenia zamkniętego, dla których wymagana klasa odporności ogniowej jest nie niższa niż E I 60 lub R E I 60, a niebędących elementami oddzielenia przeciwpożarowego, powinny mieć klasę odporności ogniowej (E I) ścian i stropów tego pomieszczenia. 4. Przejścia instalacji przez zewnętrzne ściany budynku, znajdujące się poniżej poziomu terenu, powinny być zabezpieczone przed możliwością przenikania gazu do wnętrza budynku."}], "177": [{"ref": "PN-EN 12845 – powierzchnia chroniona przez tryskacz", "kind": "norma"}], "178": [{"ref": "§ 212, § 216 WT – klasa D, wymagane klasy odporności ogniowej", "kind": "akt", "act": "wt", "label": "§ 212", "text": "§ 212. 1. Ustanawia się pięć klas odporności pożarowej budynków lub ich części, podanych w kolejności od najwyższej do najniższej i oznaczonych literami: „A”, „B”, „C”, „D” i „E”, a scharakteryzowanych w § 216. 2. Wymaganą klasę odporności pożarowej dla budynku, zaliczonego do jednej kategorii ZL, określa poniższa tabela: Budynek ZL I ZL II ZL III ZL IV ZL V 1 2 3 4 5 6 niski (N) „B” „B” „C” „D” „C” średniowysoki (SW) „B” „B” „B” „C” „B” wysoki (W) „B” „B” „B” „B” „B” wysokościowy (WW) „A” „A” „A” „B” „A” 3. Dopuszcza się obniżenie wymaganej klasy odporności pożarowej w budynkach wymienionych w poniższej tabeli do poziomu w niej określonego. Liczba kondygnacji nadziemnych ZL I ZL II ZL III 1 2 3 4 1 „D” „D” „D” 2*) „C” „C” „D” *) Gdy poziom stropu nad pierwszą kondygnacją nadziemną jest na wysokości nie większej niż 9 m nad poziomem terenu. 4. […]"}], "179": [{"ref": "PN-EN 60079-10-1:2016-02 – klasyfikacja przestrzeni", "kind": "norma"}], "180": [{"ref": "§ 19 RPB – hydranty wewnętrzne w strefach ZL", "kind": "akt", "act": "rpb", "label": "§ 19", "text": "§ 19. 1. Hydranty 25 muszą być stosowane w strefach pożarowych zakwalifikowanych do kategorii zagrożenia ludzi ZL: 1) na każdej kondygnacji budynku wysokiego i wysokościowego, z wyjątkiem kondygnacji obejmującej wyłącznie strefę pożarową zakwalifikowaną do kategorii zagrożenia ludzi ZL IV; […]"}], "181": [{"ref": "PN-B-02852:2001 – obliczanie gęstości obciążenia ogniowego", "kind": "norma"}], "182": [{"ref": "§ 232 ust. 2 WT – limit 15% powierzchni otworów i wyjątek dla garaży", "kind": "akt", "act": "wt", "label": "§ 232", "text": "2. W ścianie oddzielenia przeciwpożarowego łączna powierzchnia otworów, o których mowa w ust. 1, nie powinna przekraczać 15% powierzchni ściany, a w stropie oddzielenia przeciwpożarowego – 0,5% powierzchni stropu. Ograniczenia nie stosuje się do otworów w ścianach oddzielenia przeciwpożarowego w garażu, które znajdują się na drogach manewrowych."}], "183": [{"ref": "§ 225 WT – pas międzykondygnacyjny", "kind": "akt", "act": "wt", "label": "§ 225", "text": "§ 225. Elementy okładzin elewacyjnych powinny być mocowane do konstrukcji budynku w sposób uniemożliwiający ich odpadanie w przypadku pożaru w czasie krótszym niż wynikający z wymaganej klasy odporności ogniowej dla ściany zewnętrznej, określonej w § 216 ust. 1, odpowiednio do klasy odporności pożarowej budynku, w którym są one zamocowane. Rozdział 3 Strefy pożarowe i oddzielenia przeciwpożarowe"}], "185": [{"ref": "§ 249 WT – przeszklenia przy narożach/ścianach prostopadłych", "kind": "akt", "act": "wt", "label": "§ 249", "text": "§ 249. 1. Ściany wewnętrzne i stropy stanowiące obudowę klatki schodowej lub pochylni powinny mieć klasę odporności ogniowej określoną zgodnie z § 216, jak dla stropów budynku. 2. (uchylony). 3. Biegi i spoczniki schodów oraz pochylnie służące do ewakuacji powinny być wykonane z materiałów niepalnych i mieć klasę odporności ogniowej co najmniej: 1) w budynkach o klasie odporności pożarowej „A”, „B” i „C” – R 60; 2) w budynkach o klasie odporności pożarowej „D” i „E” – R 30. 4. Wymaganie klasy odporności ogniowej, o którym mowa w ust. 3, nie dotyczy klatek schodowych wydzielonych na każdej kondygnacji przedsionkami przeciwpożarowymi oraz schodów na antresolę w pomieszczeniu, w którym się ona znajduje, jeżeli antresola ta jest przeznaczona do użytku nie więcej niż 10 osób. 5. […]"}], "186": [{"ref": "§ 284 pkt 1 WT – drogi ewakuacyjne w budynkach inwentarskich", "kind": "akt", "act": "wt", "label": "§ 284", "text": "§ 284. Budynek IN powinien spełniać następujące wymagania ewakuacyjne: 1) odległość od najdalszego stanowiska dla zwierząt do wyjścia ewakuacyjnego nie powinna przekraczać przy ściółkowym utrzymaniu zwierząt – 50 m, a przy bezściółkowym – 75 m; 2) w bezściółkowym chowie bydła, trzody chlewnej i owiec, jeżeli liczba bydła i trzody chlewnej nie przekracza 15 sztuk, a owiec – 200 sztuk, należy stosować co najmniej jedno wyjście ewakuacyjne; 3) w budynku przeznaczonym dla większej liczby zwierząt aniżeli wymieniona w pkt 2 należy stosować co najmniej dwa wyjścia, a z pomieszczeń podzielonych na sekcje – co najmniej jedno wyjście ewakuacyjne z każdej sekcji; 4) wrota i drzwi w budynku inwentarskim powinny otwierać się na zewnątrz pomieszczenia."}], "187": [{"ref": "§ 247 ust. 1 WT – zabezpieczenie przed zadymieniem poziomych dróg ewakuacyjnych w budynkach W i WW", "kind": "akt", "act": "wt", "label": "§ 247", "text": "§ 247. 1. W budynku wysokim (W) i wysokościowym (WW), w strefach pożarowych innych niż ZL IV, należy zastosować rozwiązania techniczno-budowlane zabezpieczające przed zadymieniem poziomych dróg ewakuacyjnych."}, {"ref": "§ 243 ust. 1 i 2 WT – podział korytarzy co 50 m i wyłączenie", "kind": "akt", "act": "wt", "label": "§ 243", "text": "§ 243. 1. Korytarze stanowiące drogę ewakuacyjną w strefach pożarowych ZL powinny być podzielone na odcinki nie dłuższe niż 50 m przy zastosowaniu przegród z drzwiami dymoszczelnymi lub innych urządzeń technicznych, zapobiegających rozprzestrzenianiu się dymu."}], "188": [{"ref": "PKN-CEN/TS 54-14 – rozmieszczenie punktowych czujek dymu, stropy z belkami", "kind": "norma"}], "189": [{"ref": "PN-EN 12101-6 – systemy różnicowania ciśnień, kryterium przepływu dla klasy F", "kind": "norma"}], "190": [{"ref": "§ 246 ust. 6 WT – drzwi z pomieszczeń na drogi komunikacji ogólnej w ZL V", "kind": "akt", "act": "wt", "label": "§ 246", "text": "6. W budynku średniowysokim (SW) i wyższym, w strefie pożarowej ZL V, drzwi z pomieszczeń, z wyjątkiem higienicznosanitarnych, prowadzące na drogi komunikacji ogólnej, powinny mieć klasę odporności ogniowej co najmniej E I 30."}], "191": [{"ref": "§ 3–5 RW – przypadki niewymagające zewnętrznego zaopatrzenia w wodę", "kind": "akt", "act": "rw", "label": "§ 3", "text": "§ 3. 1. Zapewnienie przeciwpożarowego zaopatrzenia w wodę do zewnętrznego gaszenia pożaru jest wymagane dla: 1) jednostek osadniczych o liczbie mieszkańców przekraczającej 100 osób, niestanowiących zabudowy kolonijnej, a także znajdujących się w ich granicach: budynków użyteczności publicznej i zamieszkania zbiorowego oraz obiektów budowlanych produkcyjnych i magazynowych; 2) budynków użyteczności publicznej i zamieszkania zbiorowego oraz obiektów budowlanych produkcyjnych i magazynowych, znajdujących się poza granicami jednostek osadniczych wymienionych w pkt 1, o kubaturze brutto przekraczającej 2 500 m3 lub o powierzchni przekraczającej 500 m2, z wyjątkiem stacji paliw płynnych ze zbiornikami o łącznej pojemności do 200 m3 i stacji gazu płynnego; […]"}], "192": [{"ref": "§ 236 WT – kierunek otwierania drzwi ewakuacyjnych", "kind": "akt", "act": "wt", "label": "§ 236", "text": "§ 236. 1. Z pomieszczeń przeznaczonych na pobyt ludzi powinna być zapewniona możliwość ewakuacji w bezpieczne miejsce na zewnątrz budynku lub do sąsiedniej strefy pożarowej, bezpośrednio albo drogami komunikacji ogólnej, zwanymi dalej „drogami ewakuacyjnymi”. 2. Ze strefy pożarowej, o której mowa w ust. 1, powinno być wyjście bezpośrednio na zewnątrz budynku lub przez inną strefę pożarową, z zastrzeżeniem § 227 ust. 5. 3. Wyjścia z pomieszczeń na drogi ewakuacyjne powinny być zamykane drzwiami. 4. Drzwi stanowiące wyjście ewakuacyjne z budynku przeznaczonego dla więcej niż 50 osób powinny otwierać się na zewnątrz. Wymaganie to nie dotyczy budynku wpisanego do rejestru zabytków. 5. W wyjściu ewakuacyjnym z budynku dopuszcza się stosowanie drzwi rozsuwanych spełniających wymagania określone w § 240 ust. 4. 6. […]"}], "193": [{"ref": "§ 256 ust. 2 WT – klatka schodowa równorzędna wyjściu do innej strefy pożarowej", "kind": "akt", "act": "wt", "label": "§ 256", "text": "2. Za równorzędne wyjściu do innej strefy pożarowej, o którym mowa w ust. 1, uważa się wyjście do obudowanej klatki schodowej, zamykanej drzwiami o klasie odporności ogniowej co najmniej E I 30, wyposażonej w urządzenia zapobiegające zadymieniu lub służące do usuwania dymu, a w przypadku, o którym mowa w § 246 ust. 5 – zamykanej drzwiami dymoszczelnymi."}, {"ref": "§ 245 WT – klatki zamykane drzwiami dymoszczelnymi (nie dotyczy ZL IV)", "kind": "akt", "act": "wt", "label": "§ 245", "text": "§ 245. Klatki schodowe przeznaczone do ewakuacji ze strefy pożarowej: 1) ZL II w budynku niskim (N), 2) ZL I, ZL II, ZL III lub ZL V w budynku średniowysokim (SW), 3) PM o gęstości obciążenia ogniowego powyżej 500 MJ/m2 lub zawierającej pomieszczenie zagrożone wybuchem w budynku niskim (N) bądź średniowysokim (SW) – powinny być obudowane i zamykane drzwiami dymoszczelnymi oraz wyposażone w urządzenia zapobiegające zadymieniu lub służące do usuwania dymu, uruchamiane samoczynnie za pomocą systemu wykrywania dymu."}], "194": [{"ref": "§ 12 ust. 5 RW – połączenie dźwigu dla ekip ratowniczych z drogą pożarową", "kind": "akt", "act": "rw", "label": "§ 12", "text": "5. Każdy dźwig dla ekip ratowniczych w budynku powinien mieć połączenie z drogą pożarową dojściem, o którym mowa w ust. 4, przy czym wymieniona długość dojścia powinna obejmować również drogę ewakuacyjną w budynku."}, {"ref": "§ 12 ust. 4 RW – dojście o szerokości 1,5 m i długości do 50 m", "kind": "akt", "act": "rw", "label": "§ 12", "text": "4. Wyjścia z obiektów budowlanych, o których mowa w ust. 1 pkt 1—6, powinny mieć połączenie z drogą pożarową, dojściem o szerokości minimalnej 1,5 m i długości nie większej niż 50 m, w sposób zapewniający dotarcie bezpośrednio lub drogami ewakuacyjnymi do każdej strefy pożarowej w tych obiektach."}], "195": [{"ref": "PKN-CEN/TS 54-14:2006 – strefy dozorowe", "kind": "norma"}], "196": [{"ref": "§ 237 WT – długość przejścia ewakuacyjnego i powiększenia", "kind": "akt", "act": "wt", "label": "§ 237", "text": "§ 237. 1. W pomieszczeniach, od najdalszego miejsca, w którym może przebywać człowiek, do wyjścia ewakuacyjnego na drogę ewakuacyjną lub do innej strefy pożarowej albo na zewnątrz budynku, powinno być zapewnione przejście, zwane dalej „przejściem ewakuacyjnym”, o długości nieprzekraczającej: 1) w strefach pożarowych ZL – 40 m; 2) w strefach pożarowych PM o gęstości obciążenia ogniowego przekraczającej 500 MJ/m2 w budynku o więcej niż jednej kondygnacji nadziemnej – 75 m; 3) w strefach pożarowych PM, o obciążeniu ogniowym nieprzekraczającym 500 MJ/m2, w budynku o więcej niż jednej kondygnacji nadziemnej oraz w strefach pożarowych PM w budynku o jednej kondygnacji nadziemnej bez względu na wielkość obciążenia ogniowego – 100 m. 2. W pomieszczeniu zagrożonym wybuchem długość przejścia ewakuacyjnego, o którym mowa w ust. 1 pkt 2 i 3, nie powinna przekraczać 40 m. 3. […]"}], "197": [{"ref": "PN-EN 12845 – zbiornik pośredni", "kind": "norma"}], "198": [{"ref": "PN-B-02857:2017-04 – przeciwpożarowe zbiorniki wodne", "kind": "norma"}], "199": [{"ref": "§ 227 ust. 1 i 4 WT – powierzchnie stref ZL i ich powiększanie", "kind": "akt", "act": "wt", "label": "§ 227", "text": "§ 227. 1. Dopuszczalne powierzchnie stref pożarowych ZL określa poniższa tabela: Kategoria zagrożenia ludzi Dopuszczalna powierzchnia strefy pożarowej w m2 w budynku o jednej kondygnacji nadziemnej (bez ograniczenia wysokości) w budynku wielokondygnacyjnym niskim (N) średniowysokim (SW) wysokim i wysokościowym (W) i (WW) 1 2 3 4 5 ZL I, ZL III, ZL IV, ZL V 10 000 8000 5000 2500 ZL II 8000 5000 3500 2000"}], "200": [{"ref": "§ 6–7 RW – ilość wody dla obiektów innych niż budynki", "kind": "akt", "act": "rw", "label": "§ 6", "text": "§ 6. […] 1753). 7. Wymaganą ilość wody do celów przeciwpożarowych do zewnętrznego gaszenia pożaru dla urządzeń technologicznych oraz składów i magazynów z gazami palnymi i cieczami o temperaturze zapłonu do 373,15 K (100 °C), zlokalizowanych poza budynkami, określa tabela nr 4 załącznika do rozporządzenia. 8. Wymagana ilość wody do celów przeciwpożarowych do zewnętrznego gaszenia pożaru dla silosów, komór i zasobników ze stałymi sypkimi materiałami palnymi oraz dla zbiorników z cieczami palnymi o temperaturze zapłonu powyżej 373,15 K (100 °C) wynosi 10 dm3/s. 9. Wymaganą ilość wody do celów przeciwpożarowych do zewnętrznego gaszenia pożaru dla obiektów budowlanych gospodarki rolnej należy zapewnić w następujących ilościach: 1) dla obiektów o powierzchni strefy pożarowej do 2 000 m2 — co najmniej 10 dm3/s; 2) dla obiektów o powierzchni strefy pożarowej przekraczającej 2 000 m2 — co najmniej 15 dm3/s. 10. […]"}], "201": [{"ref": "§ 11 RPB / przepisy dot. magazynowania gazów palnych", "kind": "akt", "act": "rpb", "label": "§ 11", "text": "§ 11. 1. Dopuszcza się przechowywanie paliw płynnych klasy III, na potrzeby własne użytkownika, w zbiorniku naziemnym dwupłaszczowym o pojemności do 5 m3. 2. Zbiornik do przechowywania paliw płynnych klasy III na potrzeby własne użytkownika, o którym mowa w ust. 1, należy sytuować z zachowaniem następujących odległości: 1) 10 m ‒ od budynków mieszkalnych i budynków użyteczności publicznej; 2) 5 m ‒ od innych obiektów budowlanych i od granicy działki sąsiedniej. 3. Odległości, o których mowa w ust. 2, mogą być zmniejszone o połowę, pod warunkiem zastosowania pomiędzy budynkiem lub obiektem a zbiornikiem ściany oddzielenia przeciwpożarowego o klasie odporności ogniowej co najmniej REI 120 zasłaniającej zbiornik od strony budynku lub obiektu. 3) Ustawa utraciła moc na podstawie art. 174 ustawy z dnia 13 czerwca 2019 r. […]"}], "203": [{"ref": "§ 3 pkt 1a WT – definicja działki budowlanej", "kind": "akt", "act": "wt", "label": "§ 3", "text": "§ 3. Ilekroć w rozporządzeniu jest mowa o: 1) zabudowie śródmiejskiej – należy przez to rozumieć zgrupowanie intensywnej zabudowy na obszarze śródmieścia, określonej w miejscowym planie zagospodarowania przestrzennego, a w przypadku braku planu miejscowego w studium uwarunkowań i kierunków zagospodarowania przestrzennego gminy; 1a) działce budowlanej – należy przez to rozumieć nieruchomość gruntową lub działkę gruntu, której wielkość, cechy geometryczne, dostęp do drogi publicznej oraz wyposażenie w urządzenia infrastruktury technicznej spełniają wymogi realizacji obiektów budowlanych wynikające z rozporządzenia, odrębnych przepisów i aktów prawa miejscowego; 2) zabudowie jednorodzinnej – należy przez to rozumieć jeden budynek mieszkalny jednorodzinny lub zespół takich budynków, wraz z budynkami garażowymi i gospodarczymi; […]"}], "204": [{"ref": "§ 12 ust. 1 pkt 3 RW – droga pożarowa do stref PM o gęstości ponad 500 MJ/m2", "kind": "akt", "act": "rw", "label": "§ 12", "text": "§ 12. 1. Drogę pożarową o utwardzonej nawierzchni, umożliwiającą dojazd pojazdów jednostek ochrony przeciwpożarowej do obiektu budowlanego o każdej porze roku, należy doprowadzić do: 1) budynku zawierającego strefę pożarową zakwalifikowaną do kategorii zagrożenia ludzi ZL I lub ZL II; 2) budynku należącego do grupy wysokości: średniowysoki, wysoki lub wysokościowy, zawierającego strefę pożarową zakwalifikowaną do kategorii zagrożenia ludzi ZL III, ZL IV lub ZL V; 3) budynku zawierającego strefę pożarową produkcyjną lub magazynową oraz do strefy pożarowej poza budynkiem, obejmującej urządzenia technologiczne, plac składowy lub wiatę, jeżeli gęstość obciążenia ogniowego wymienionych stref pożarowych przekracza 500 MJ/m2 i zachodzi co najmniej jeden z warunków: a) powierzchnia strefy pożarowej przekracza 1 000 m2, b) występuje pomieszczenie zagrożone wybuchem; […]"}, {"ref": "§ 12 ust. 1 pkt 4 RW – droga pożarowa do stref PM poniżej 500 MJ/m2 i ponad 20 000 m2", "kind": "akt", "act": "rw", "label": "§ 12", "text": "§ 12. 1. Drogę pożarową o utwardzonej nawierzchni, umożliwiającą dojazd pojazdów jednostek ochrony przeciwpożarowej do obiektu budowlanego o każdej porze roku, należy doprowadzić do: 1) budynku zawierającego strefę pożarową zakwalifikowaną do kategorii zagrożenia ludzi ZL I lub ZL II; 2) budynku należącego do grupy wysokości: średniowysoki, wysoki lub wysokościowy, zawierającego strefę pożarową zakwalifikowaną do kategorii zagrożenia ludzi ZL III, ZL IV lub ZL V; 3) budynku zawierającego strefę pożarową produkcyjną lub magazynową oraz do strefy pożarowej poza budynkiem, obejmującej urządzenia technologiczne, plac składowy lub wiatę, jeżeli gęstość obciążenia ogniowego wymienionych stref pożarowych przekracza 500 MJ/m2 i zachodzi co najmniej jeden z warunków: a) powierzchnia strefy pożarowej przekracza 1 000 m2, b) występuje pomieszczenie zagrożone wybuchem; […]"}], "205": [{"ref": "§ 6 ust. 7 RW – woda do zewnętrznego gaszenia dla składów gazów i cieczy poza budynkami", "kind": "akt", "act": "rw", "label": "§ 6", "text": "7. Wymaganą ilość wody do celów przeciwpożarowych do zewnętrznego gaszenia pożaru dla urządzeń technologicznych oraz składów i magazynów z gazami palnymi i cieczami o temperaturze zapłonu do 373,15 K (100 °C), zlokalizowanych poza budynkami, określa tabela nr 4 załącznika do rozporządzenia."}], "207": [{"ref": "PN-EN 12845 załącznik E – urządzenia tryskaczowe w budynkach wysokich (wymagania jak dla OH3)", "kind": "norma"}, {"ref": "PN-EN 12845 załącznik A – klasyfikacja zagrożeń (biura OH1)", "kind": "norma"}], "208": [{"ref": "PN-EN 12845 – dobór tryskaczy w instalacjach suchych", "kind": "norma"}], "210": [{"ref": "§ 212 ust. 2 WT – klasy odporności pożarowej budynków ZL", "kind": "akt", "act": "wt", "label": "§ 212", "text": "2. Wymaganą klasę odporności pożarowej dla budynku, zaliczonego do jednej kategorii ZL, określa poniższa tabela: Budynek ZL I ZL II ZL III ZL IV ZL V 1 2 3 4 5 6 niski (N) „B” „B” „C” „D” „C” średniowysoki (SW) „B” „B” „B” „C” „B” wysoki (W) „B” „B” „B” „B” „B” wysokościowy (WW) „A” „A” „A” „B” „A”"}, {"ref": "§ 212 ust. 3 WT – obniżenie klasy w budynkach jedno- i dwukondygnacyjnych", "kind": "akt", "act": "wt", "label": "§ 212", "text": "3. Dopuszcza się obniżenie wymaganej klasy odporności pożarowej w budynkach wymienionych w poniższej tabeli do poziomu w niej określonego. Liczba kondygnacji nadziemnych ZL I ZL II ZL III 1 2 3 4 1 „D” „D” „D” 2*) „C” „C” „D” *) Gdy poziom stropu nad pierwszą kondygnacją nadziemną jest na wysokości nie większej niż 9 m nad poziomem terenu."}], "211": [{"ref": "PN-EN 13501-1 – klasyfikacja izolacji przewodów; WT", "kind": "norma"}], "212": [{"ref": "§ 28 ust. 1 pkt 3 RPB – obiekty wymagające SSP", "kind": "akt", "act": "rpb", "label": "§ 28", "text": "§ 28. 1. Stosowanie systemu sygnalizacji pożarowej, obejmującego urządzenia sygnalizacyjno-alarmowe, służące do samoczynnego wykrywania i przekazywania informacji o pożarze, a także urządzenia odbiorcze alarmów pożarowych i urządzenia odbiorcze sygnałów uszkodzeniowych, jest wymagane w: 1) budynkach handlowych lub wystawowych: a) jednokondygnacyjnych o powierzchni strefy pożarowej powyżej 5000 m2, b) wielokondygnacyjnych o powierzchni strefy pożarowej powyżej 2500 m2; 2) teatrach o liczbie miejsc powyżej 300; 3) kinach o liczbie miejsc powyżej 600; 4) budynkach o liczbie miejsc służących celom gastronomicznym powyżej 300; 5) salach widowiskowych i sportowych o liczbie miejsc powyżej 1500; 6) szpitalach, z wyjątkiem psychiatrycznych, oraz w sanatoriach ‒ o liczbie łóżek powyżej 200 w budynku; 7) szpitalach psychiatrycznych o liczbie łóżek powyżej 100 w budynku; […]"}], "213": [{"ref": "ustawa o wyrobach budowlanych – krajowa ocena techniczna", "kind": "norma"}], "215": [{"ref": "art. 3 pkt 7a ustawy – Prawo budowlane (definicja przebudowy)", "kind": "akt", "act": "pb", "label": "art. 3", "text": "Art. 3. […] 2) budynku – należy przez to rozumieć taki obiekt budowlany, który jest trwale związany z gruntem, wydzielony z przestrzeni za pomocą przegród budowlanych oraz posiada fundamenty i dach; 2a) budynku mieszkalnym jednorodzinnym – należy przez to rozumieć budynek wolno stojący albo budynek w zabudowie bliźniaczej, szeregowej lub grupowej, służący zaspokajaniu potrzeb mieszkaniowych, stanowiący konstrukcyjnie samodzielną całość, w którym dopuszcza się wydzielenie nie więcej niż dwóch lokali mieszkalnych albo jednego lokalu mieszkalnego i lokalu użytkowego o powierzchni całkowitej nieprzekraczającej 30 % powierzchni całkowitej budynku; […]"}], "216": [{"ref": "§ 3 ust. 1 pkt 1–3 rozp. MSWiA w sprawie uzgadniania projektu – obiekty wymagające uzgodnienia", "kind": "akt", "act": "uzgadnianie", "label": "§ 3", "text": "§ 3. 1. Obiektami budowlanymi istotnymi ze względu na konieczność zapewnienia ochrony życia, zdrowia, mienia lub środowiska przed pożarem, klęską żywiołową lub innym miejscowym zagrożeniem, których projekty zagospodarowania działki lub terenu, projekty architektoniczno-budowlane oraz projekty techniczne wymagają uzgodnienia, są: 1) budynek zawierający strefę pożarową zakwalifikowaną do kategorii zagrożenia ludzi ZL I, ZL II lub ZL V; 2) budynek średniowysoki (SW), wysoki (W) lub wysokościowy (WW), zawierający strefę pożarową zakwalifikowaną do kategorii zagrożenia ludzi ZL III lub ZL IV; 3) budynek niski (N) zawierający strefę pożarową o powierzchni przekraczającej 1000 m2, zakwalifikowaną do kategorii zagrożenia ludzi ZL III, obejmującą kondygnację nadziemną inną niż pierwsza; […]"}, {"ref": "§ 8 pkt 1 WT – budynek mieszkalny do 4 kondygnacji jest niski", "kind": "akt", "act": "wt", "label": "§ 8", "text": "§ 8. W celu określenia wymagań technicznych i użytkowych wprowadza się następujący podział budynków na grupy wysokości: 1) niskie (N) – do 12 m włącznie nad poziomem terenu lub mieszkalne o wysokości do 4 kondygnacji nadziemnych włącznie; 2) średniowysokie (SW) – ponad 12 m do 25 m włącznie nad poziomem terenu lub mieszkalne o wysokości ponad 4 do 9 kondygnacji nadziemnych włącznie; 3) wysokie (W) – ponad 25 m do 55 m włącznie nad poziomem terenu lub mieszkalne o wysokości ponad 9 do 18 kondygnacji nadziemnych włącznie; 4) wysokościowe (WW) – powyżej 55 m nad poziomem terenu."}], "217": [{"ref": "§ 216 ust. 8 WT; PN-B-02867", "kind": "norma"}], "218": [{"ref": "§ 29 RPB / PN-EN 54 – dźwiękowy system ostrzegawczy", "kind": "norma"}], "220": [{"ref": "PN-EN 12845 – wydatek tryskacza", "kind": "norma"}], "221": [{"ref": "§ 19 RPB – dobór hydrantów wewnętrznych", "kind": "akt", "act": "rpb", "label": "§ 19", "text": "§ 19. […] 2. Hydranty 33 muszą być stosowane w garażu: 1) jednokondygnacyjnym zamkniętym o więcej niż 10 stanowiskach postojowych; 2) wielokondygnacyjnym. 3. Hydranty 52 muszą być stosowane: 1) w strefie pożarowej produkcyjnej i magazynowej o gęstości obciążenia ogniowego przekraczającej 500 MJ/m2 i powierzchni przekraczającej 200 m2; 2) w strefie pożarowej produkcyjnej i magazynowej o gęstości obciążenia ogniowego nieprzekraczającej 500 MJ/m2, w której znajduje się pomieszczenie o powierzchni przekraczającej 100 m2 i gęstości obciążenia ogniowego przekraczającej 1 000 MJ/m2; 3) przy wejściu do pomieszczeń magazynowych lub technicznych o powierzchni przekraczającej 200 m2 i gęstości obciążenia ogniowego przekraczającej 500 MJ/m2, usytuowanych w strefie pożarowej zakwalifikowanej do kategorii zagrożenia ludzi ZL I, ZL II, ZL III lub ZL V, znajdującej się w budynku niskim albo średniowysokim. 4. […]"}], "223": [{"ref": "§ 245 pkt 1 WT – klatki schodowe w niskim budynku ZL II", "kind": "akt", "act": "wt", "label": "§ 245", "text": "§ 245. Klatki schodowe przeznaczone do ewakuacji ze strefy pożarowej: 1) ZL II w budynku niskim (N), 2) ZL I, ZL II, ZL III lub ZL V w budynku średniowysokim (SW), 3) PM o gęstości obciążenia ogniowego powyżej 500 MJ/m2 lub zawierającej pomieszczenie zagrożone wybuchem w budynku niskim (N) bądź średniowysokim (SW) – powinny być obudowane i zamykane drzwiami dymoszczelnymi oraz wyposażone w urządzenia zapobiegające zadymieniu lub służące do usuwania dymu, uruchamiane samoczynnie za pomocą systemu wykrywania dymu."}, {"ref": "§ 256 ust. 2 i 3 WT – klatka z drzwiami EI 30 i dojście 10 m w ZL II", "kind": "akt", "act": "wt", "label": "§ 256", "text": "2. Za równorzędne wyjściu do innej strefy pożarowej, o którym mowa w ust. 1, uważa się wyjście do obudowanej klatki schodowej, zamykanej drzwiami o klasie odporności ogniowej co najmniej E I 30, wyposażonej w urządzenia zapobiegające zadymieniu lub służące do usuwania dymu, a w przypadku, o którym mowa w § 246 ust. 5 – zamykanej drzwiami dymoszczelnymi."}], "225": [{"ref": "PN-B-02857:2017-04 – głębokość zbiornika i wysokość ssania", "kind": "norma"}, {"ref": "§ 4 ust. 6 RW – głębokość poboru wody z uzupełniających źródeł", "kind": "akt", "act": "rw", "label": "§ 4", "text": "6. Uzupełniające źródło wody, o którym mowa w ust. 5 pkt 1 i 2, powinno umożliwiać pobieranie wody z głębokości nie większej niż 4 m, licząc między lustrem wody a poziomem stanowiska czerpania wody, i być wyposażone w: 1) studzienkę ssawną lub inne urządzenie umożliwiające pobór wody, zabezpieczone przed zamuleniem i zamarzaniem; 2) stanowisko czerpania wody wraz z dojazdem."}], "226": [{"ref": "§ 227 WT – powiększanie powierzchni stref pożarowych", "kind": "akt", "act": "wt", "label": "§ 227", "text": "§ 227. […] 3. Zmniejszenie dopuszczalnej powierzchni strefy pożarowej, o której mowa w ust. 2, nie dotyczy przypadku, gdy wyjścia ewakuacyjne z kondygnacji podziemnej prowadzą bezpośrednio na zewnątrz budynku. 4. Dopuszcza się powiększenie powierzchni stref pożarowych, o których mowa w ust. 1, z wyjątkiem stref pożarowych w wielokondygnacyjnych budynkach wysokich (W) i wysokościowych (WW), pod warunkiem zastosowania: 1) stałych samoczynnych urządzeń gaśniczych wodnych – o 100%; 2) samoczynnych urządzeń oddymiających uruchamianych za pomocą systemu wykrywania dymu – o 100%. Przy jednoczesnym stosowaniu urządzeń wymienionych w pkt 1 i 2 dopuszcza się powiększenie powierzchni stref pożarowych o 200%. 5. Ze strefy pożarowej ZL II o powierzchni przekraczającej 750 m2 w budynku wielokondygnacyjnym, powinna być zapewniona możliwość ewakuacji ludzi do innej strefy pożarowej na tej samej kondygnacji."}], "227": [{"ref": "§ 17 RPB – praktyczne sprawdzenie warunków ewakuacji", "kind": "akt", "act": "rpb", "label": "§ 17", "text": "§ 17. […] 2. W przypadku obiektów, w których cyklicznie zmienia się jednocześnie grupa powyżej 50 użytkowników, w szczególności: szkół, przedszkoli, internatów, domów studenckich, praktycznego sprawdzenia organizacji oraz warunków ewakuacji należy dokonać ‒ co najmniej raz na rok, jednak w terminie nie dłuższym niż 3 miesiące od dnia rozpoczęcia korzystania z obiektu przez nowych użytkowników. 3. W przypadku obiektu zawierającego strefę pożarową zakwalifikowaną do kategorii zagrożenia ludzi ZL II oraz w budynkach zakwaterowania osadzonych zlokalizowanych na terenach zakładów karnych i aresztów śledczych, zakres i obszar budynku objęty praktycznym sprawdzeniem organizacji i warunków ewakuacji musi być uzgodniony z właściwym miejscowo komendantem powiatowym (miejskim) Państwowej Straży Pożarnej. 4. […]"}], "228": [{"ref": "§ 253 WT – wyjścia na strych/dach", "kind": "akt", "act": "wt", "label": "§ 253", "text": "§ 253. 1. W budynku ZL I, ZL II, ZL III lub ZL V, mającym kondygnację z posadzką na wysokości powyżej 25 m ponad poziomem terenu przy najniżej położonym wejściu do budynku oraz w budynku wysokościowym (WW) ZL IV przynajmniej jeden dźwig powinien być przystosowany do potrzeb ekip ratowniczych, spełniając wymagania Polskiej Normy dotyczącej dźwigów dla straży pożarnej. Dźwig dla ekip ratowniczych powinien zapewniać dostęp do każdej strefy pożarowej na kondygnacji bezpośrednio lub drogami komunikacji ogólnej. 2. Dojście do dźwigu dla ekip ratowniczych powinno prowadzić przez przedsionek przeciwpożarowy spełniający wymagania określone w § 232. 3. Ściany i stropy szybu dźwigu dla ekip ratowniczych powinny mieć klasę odporności ogniowej wymaganą jak dla stropów budynku, zgodnie z § 216. 4. Szyb dźwigu dla ekip ratowniczych powinien być wyposażony w urządzenia zapobiegające zadymieniu."}], "230": [{"ref": "§ 236 WT – kierunek otwierania drzwi ewakuacyjnych", "kind": "akt", "act": "wt", "label": "§ 236", "text": "§ 236. 1. Z pomieszczeń przeznaczonych na pobyt ludzi powinna być zapewniona możliwość ewakuacji w bezpieczne miejsce na zewnątrz budynku lub do sąsiedniej strefy pożarowej, bezpośrednio albo drogami komunikacji ogólnej, zwanymi dalej „drogami ewakuacyjnymi”. 2. Ze strefy pożarowej, o której mowa w ust. 1, powinno być wyjście bezpośrednio na zewnątrz budynku lub przez inną strefę pożarową, z zastrzeżeniem § 227 ust. 5. 3. Wyjścia z pomieszczeń na drogi ewakuacyjne powinny być zamykane drzwiami. 4. Drzwi stanowiące wyjście ewakuacyjne z budynku przeznaczonego dla więcej niż 50 osób powinny otwierać się na zewnątrz. Wymaganie to nie dotyczy budynku wpisanego do rejestru zabytków. 5. W wyjściu ewakuacyjnym z budynku dopuszcza się stosowanie drzwi rozsuwanych spełniających wymagania określone w § 240 ust. 4. 6. […]"}], "233": [{"ref": "§ 308 WT – wyłazy i klapy wyjściowe", "kind": "akt", "act": "wt", "label": "§ 308", "text": "§ 308. 1. W budynkach o dwóch lub więcej kondygnacjach nadziemnych należy zapewnić wyjście na dach co najmniej z jednej klatki schodowej, umożliwiające dostęp na dach i do urządzeń technicznych tam zainstalowanych. 2. W budynkach wysokich (W) i wysokościowych (WW) wyjścia, o których mowa w ust. 1, należy zapewnić z każdej klatki schodowej. 3. Jako wyjście z klatki schodowej na dach należy stosować drzwi o szerokości 0,8 m i wysokości co najmniej 1,9 m lub klapy wyłazowe o wymiarze 0,8 x 0,8 m w świetle, do których dostęp powinien odpowiadać warunkom określonym w § 101. 4. Na dachu o spadku ponad 25% oraz na dachu pokrytym materiałami łamliwymi (tłukącymi) należy wykonać stałe dojścia do kominów, urządzeń technicznych oraz anten radiowych i telewizyjnych. 5. Dojścia, o których mowa w ust. 4, na odcinkach o nachyleniu ponad 25% powinny mieć zabezpieczenia przed poślizgiem. 6. […]"}], "234": [{"ref": "§ 214 WT – obniżenie klasy odporności pożarowej przy stałych urządzeniach gaśniczych wodnych", "kind": "akt", "act": "wt", "label": "§ 214", "text": "§ 214. W budynkach wyposażonych w stałe samoczynne urządzenia gaśnicze wodne, z wyjątkiem budynków ZL II oraz wielokondygnacyjnych budynków wysokich (W) i wysokościowych (WW), dopuszcza się: 1) obniżenie klasy odporności pożarowej budynku o jedną w stosunku do wynikającej z § 212; 2) przyjęcie klasy „E” odporności pożarowej dla budynku jednokondygnacyjnego."}, {"ref": "§ 215 ust. 1 WT – klasa „E” dla jednokondygnacyjnego budynku PM bez urządzeń gaśniczych", "kind": "akt", "act": "wt", "label": "§ 215", "text": "§ 215. 1. Dopuszcza się przyjęcie klasy „E” odporności pożarowej dla jednokondygnacyjnego budynku PM o gęstości obciążenia ogniowego przekraczającej 500 MJ/m2, pod warunkiem zastosowania: 1) wszystkich elementów budynku nierozprzestrzeniających ognia; 2) samoczynnych urządzeń oddymiających w strefach pożarowych o powierzchni przekraczającej 1000 m2."}], "235": [{"ref": "PKN-CEN/TS 54-14:2006 – wpływ przegród na rozmieszczenie czujek", "kind": "norma"}], "236": [{"ref": "§ 230 ust. 2 WT – brak ograniczenia strefy PM w budynku jednokondygnacyjnym", "kind": "akt", "act": "wt", "label": "§ 230", "text": "2. W budynku jednokondygnacyjnym wielkości stref pożarowych PM, z wyjątkiem garażu, nie ogranicza się, pod warunkiem zastosowania stałych samoczynnych urządzeń gaśniczych wodnych i samoczynnych urządzeń oddymiających."}, {"ref": "§ 229 WT – powiększenie stref PM o 100%, 50% i 150%", "kind": "akt", "act": "wt", "label": "§ 229", "text": "§ 229. 1. Dopuszcza się powiększenie powierzchni stref pożarowych, o których mowa w § 228, pod warunkiem ich ochrony: 1) stałymi samoczynnymi urządzeniami gaśniczymi wodnymi – o 100%; 2) samoczynnymi urządzeniami oddymiającymi – o 50%. 2. Przy jednoczesnym stosowaniu urządzeń wymienionych w ust. 1 dopuszcza się powiększenie stref pożarowych o 150%."}], "237": [{"ref": "§ 261 pkt 1 WT – fotele w salach dla ponad 200 osób", "kind": "akt", "act": "wt", "label": "§ 261", "text": "§ 261. Pomieszczenia przeznaczone do jednoczesnego przebywania ponad 200 osób dorosłych lub 100 dzieci, w których miejsca do siedzenia są ustawione w rzędach, powinny mieć: 1) fotele i inne siedzenia trudno zapalne oraz niewydzielające produktów rozkładu i spalania, określonych jako bardzo toksyczne, zgodnie z Polską Normą dotyczącą badań wydzielania produktów toksycznych; określenie trudno zapalny przypisuje się fotelom i innym siedzeniom, które nie ulegają postępującemu tleniu i spalaniu płomieniowemu w warunkach określonych Polską Normą dotyczącą badania zapalności mebli tapicerowanych; 2) szerokość przejść pomiędzy rzędami siedzeń nie mniejszą niż 0,45 m, przy czym odległość tę należy ustalać, biorąc pod uwagę odstęp między stałymi elementami siedzeń; […]"}, {"ref": "§ 258 ust. 1 WT – materiały wykończeniowe łatwo zapalne", "kind": "akt", "act": "wt", "label": "§ 258", "text": "§ 258. 1. W strefach pożarowych ZL I, ZL II, ZL III i ZL V stosowanie do wykończenia wnętrz materiałów i wyrobów łatwo zapalnych, których produkty rozkładu termicznego są bardzo toksyczne lub intensywnie dymiące, jest zabronione. 1a. W przypadku stosowania materiałów wykończeniowych luźno zwisających, w szczególności w kurtynach, zasłonach, draperiach, kotarach oraz żaluzjach, za łatwo zapalne uważa się materiały, których właściwości określone w badaniach zgodnych z Polskimi Normami odnoszącymi się do zapalności i rozprzestrzeniania płomienia przez wyroby włókiennicze nie spełniają co najmniej jednego z kryteriów: 1) ti ≥ 4 s; 2) ts ≤ 30 s; 3) nie następuje przepalenie trzeciej nitki; 4) nie występują płonące krople."}], "238": [{"ref": "§ 278 ust. 2 i 3 WT – przejścia ewakuacyjne w garażach", "kind": "akt", "act": "wt", "label": "§ 278", "text": "2. W przypadku strefy pożarowej garażu obejmującej więcej niż dwie kondygnacje wyjścia ewakuacyjne należy zapewnić na poziomie każdej kondygnacji. Długość przejścia od stanowiska postojowego do najbliższego wyjścia ewakuacyjnego nie może przekraczać: 1) w garażu zamkniętym – 40 m; 2) w garażu otwartym – 60 m."}], "239": [{"ref": "PN-EN 60079-10-1 / ATEX – klasyfikacja stref", "kind": "norma"}], "240": [{"ref": "PKN-CEN/TS 54-14:2006 – promienie działania czujek", "kind": "norma"}], "241": [{"ref": "§ 212 ust. 4 WT – budynki jednokondygnacyjne; § 230 WT", "kind": "akt", "act": "wt", "label": "§ 212", "text": "4. Wymaganą klasę odporności pożarowej dla budynku PM oraz IN, z zastrzeżeniem § 282, określa poniższa tabela: Maksymalna gęstość obciążenia ogniowego strefy pożarowej w budynku Q [MJ/m2] Budynek o jednej kondygnacji nadziemnej (bez ograniczenia wysokości) Budynek wielokondygnacyjny niski średniowysoki wysoki wysokościowy (N) (SW) (W) (WW) 1 2 3 4 5 6 Q ≤ 500 „E” „D” „C” „B” „B” 500 < Q ≤ 1000 „D” „D” „C” „B” „B” 1000 < Q ≤ 2000 „C” „C” „C” „B” „B” 2000 < Q ≤ 4000 „B” „B” „B” * * Q > 4000 „A” „A” „A” * * * – Zgodnie z § 228 ust. 1 nie mogą występować takie budynki."}], "242": [{"ref": "§ 256 WT – obudowa poziomych dróg ewakuacyjnych", "kind": "akt", "act": "wt", "label": "§ 256", "text": "§ 256. 1. Długość drogi ewakuacyjnej od wyjścia z pomieszczenia na tę drogę do wyjścia do innej strefy pożarowej lub na zewnątrz budynku, zwanej dalej „dojściem ewakuacyjnym”, mierzy się wzdłuż osi drogi ewakuacyjnej. W przypadku zakończenia dojścia ewakuacyjnego przedsionkiem przeciwpożarowym, długość tę mierzy się do pierwszych drzwi tego przedsionka. 2. Za równorzędne wyjściu do innej strefy pożarowej, o którym mowa w ust. 1, uważa się wyjście do obudowanej klatki schodowej, zamykanej drzwiami o klasie odporności ogniowej co najmniej E I 30, wyposażonej w urządzenia zapobiegające zadymieniu lub służące do usuwania dymu, a w przypadku, o którym mowa w § 246 ust. 5 – zamykanej drzwiami dymoszczelnymi. 3. […]"}], "244": [{"ref": "§ 258 WT – wykończenie wnętrz na drogach ewakuacyjnych i w pomieszczeniach", "kind": "akt", "act": "wt", "label": "§ 258", "text": "§ 258. 1. W strefach pożarowych ZL I, ZL II, ZL III i ZL V stosowanie do wykończenia wnętrz materiałów i wyrobów łatwo zapalnych, których produkty rozkładu termicznego są bardzo toksyczne lub intensywnie dymiące, jest zabronione. 1a. W przypadku stosowania materiałów wykończeniowych luźno zwisających, w szczególności w kurtynach, zasłonach, draperiach, kotarach oraz żaluzjach, za łatwo zapalne uważa się materiały, których właściwości określone w badaniach zgodnych z Polskimi Normami odnoszącymi się do zapalności i rozprzestrzeniania płomienia przez wyroby włókiennicze nie spełniają co najmniej jednego z kryteriów: 1) ti ≥ 4 s; 2) ts ≤ 30 s; 3) nie następuje przepalenie trzeciej nitki; 4) nie występują płonące krople. 2. Na drogach komunikacji ogólnej, służących celom ewakuacji, stosowanie materiałów i wyrobów budowlanych łatwo zapalnych jest zabronione."}], "245": [{"ref": "§ 96 ust. 3 rozp. w sprawie baz i stacji paliw płynnych – pojemność zbiorników stacji kontenerowej", "kind": "akt", "act": "paliwa", "label": "§ 96", "text": "3. Pojemność zbiorników magazynowych dla produktów naftowych w stacji kontenerowej nie powinna przekraczać 30 m3."}], "246": [{"ref": "§ 132 ust. 2 WT – piece i trzony kuchenne na paliwo stałe", "kind": "akt", "act": "wt", "label": "§ 132", "text": "2. Dopuszcza się stosowanie pieców i trzonów kuchennych na paliwo stałe w budynkach o wysokości do 3 kondygnacji nadziemnych włącznie, jeżeli nie jest to sprzeczne z ustaleniami miejscowego planu zagospodarowania przestrzennego, przy czym w budynkach zakładów opieki zdrowotnej5), opieki społecznej, przeznaczonych dla dzieci i młodzieży, lokalach gastronomicznych oraz pomieszczeniach przeznaczonych do produkcji żywności i środków farmaceutycznych – pod warunkiem uzyskania zgody właściwego państwowego inspektora sanitarnego."}], "248": [{"ref": "PKN-CEN/TS 54-14:2006 pkt A.6.5.1 – nierówności stropu i promień działania czujek", "kind": "norma"}], "249": [{"ref": "PN-EN 12101-2 – klasyfikacja klap dymowych", "kind": "norma"}], "250": [{"ref": "PN-B-02852:2001 – obliczanie gęstości obciążenia ogniowego", "kind": "norma"}], "251": [{"ref": "§ 278 ust. 2 pkt 2 i ust. 3 WT – przejścia ewakuacyjne w garażach", "kind": "akt", "act": "wt", "label": "§ 278", "text": "2. W przypadku strefy pożarowej garażu obejmującej więcej niż dwie kondygnacje wyjścia ewakuacyjne należy zapewnić na poziomie każdej kondygnacji. Długość przejścia od stanowiska postojowego do najbliższego wyjścia ewakuacyjnego nie może przekraczać: 1) w garażu zamkniętym – 40 m; 2) w garażu otwartym – 60 m."}], "252": [{"ref": "§ 237 ust. 2 WT – przejście w pomieszczeniu zagrożonym wybuchem 40 m", "kind": "akt", "act": "wt", "label": "§ 237", "text": "2. W pomieszczeniu zagrożonym wybuchem długość przejścia ewakuacyjnego, o którym mowa w ust. 1 pkt 2 i 3, nie powinna przekraczać 40 m."}, {"ref": "§ 237 ust. 5 i 6 WT – powiększenia długości przejścia", "kind": "akt", "act": "wt", "label": "§ 237", "text": "5. W pomieszczeniach o wysokości przekraczającej 5 m długość przejść, o których mowa w ust. 1 i 2, może być powiększona o 25%."}], "254": [{"ref": "§ 284 pkt 2 WT – wyjścia ewakuacyjne w budynkach inwentarskich", "kind": "akt", "act": "wt", "label": "§ 284", "text": "§ 284. Budynek IN powinien spełniać następujące wymagania ewakuacyjne: 1) odległość od najdalszego stanowiska dla zwierząt do wyjścia ewakuacyjnego nie powinna przekraczać przy ściółkowym utrzymaniu zwierząt – 50 m, a przy bezściółkowym – 75 m; 2) w bezściółkowym chowie bydła, trzody chlewnej i owiec, jeżeli liczba bydła i trzody chlewnej nie przekracza 15 sztuk, a owiec – 200 sztuk, należy stosować co najmniej jedno wyjście ewakuacyjne; 3) w budynku przeznaczonym dla większej liczby zwierząt aniżeli wymieniona w pkt 2 należy stosować co najmniej dwa wyjścia, a z pomieszczeń podzielonych na sekcje – co najmniej jedno wyjście ewakuacyjne z każdej sekcji; 4) wrota i drzwi w budynku inwentarskim powinny otwierać się na zewnątrz pomieszczenia."}], "255": [{"ref": "art. 42 ust. 4b ustawy o odpadach – operat przeciwpożarowy", "kind": "akt", "act": "odpady-ustawa", "label": "art. 42", "text": "4. Do wniosków, o których mowa w ust. 1 i 2, dołącza się decyzję o środowiskowych uwarunkowaniach, o której mowa w art. 71 ustawy z dnia 3 października 2008 r. o udostępnianiu informacji o środowisku i jego ochronie, udziale społeczeństwa w ochronie środowiska oraz o ocenach oddziaływania na środowisko, o ile jest wymagana."}], "256": [{"ref": "§ 2 RPB – definicja materiałów niebezpiecznych pożarowo", "kind": "akt", "act": "rpb", "label": "§ 2", "text": "§ 2. 1. Ilekroć w rozporządzeniu jest mowa o: 1) materiałach niebezpiecznych pożarowo ‒ należy przez to rozumieć: a) gazy palne, b) ciecze palne o temperaturze zapłonu poniżej 328,15 K (55ºC), c) materiały wytwarzające w zetknięciu z wodą gazy palne, d) materiały zapalające się samorzutnie na powietrzu, e) materiały wybuchowe i wyroby pirotechniczne, f) materiały ulegające samorzutnemu rozkładowi lub polimeryzacji, g) materiały mające skłonności do samozapalenia, h) materiały inne niż wymienione w lit. a‒g, jeśli sposób ich składowania, przetwarzania lub innego wykorzystania może spowodować powstanie pożaru; 2) pasie przeciwpożarowym ‒ należy przez to rozumieć system drzewostanów różnej szerokości poddanych specjalnym zabiegom gospodarczym i porządkowym lub powierzchni wylesionych i oczyszczonych do warstwy mineralnej; […]"}], "257": [{"ref": "PN-EN 12101-6:2007 – systemy różnicowania ciśnień, wyposażenie rezerwowe", "kind": "norma"}], "258": [{"ref": "§ 34 ust. 1 rozp. MSWiA z 19.02.2020 – system sygnalizacji pożarowej w strefie z odpadami", "kind": "akt", "act": "odpady-rozp", "label": "§ 34", "text": "§ 34. 1. Strefę pożarową z odpadami stałymi o gęstości obciążenia ogniowego przekraczającej 1000 MJ/m2 i powierzch ni przekraczającej 2000 m2, która znajduje się w budynku, wyposaża się w system sygnalizacji pożarowej oraz urządzenia alarmowe zapewniające automatyczne przekazanie informacji o pożarze do osób, które są odpowiedzialne za jego weryfika cję oraz niezwłoczne zawiadomienie centrum powiadamiania ratunkowego lub jednostki ochrony przeciwpożarowej."}, {"ref": "§ 35 ust. 1 rozp. MSWiA z 19.02.2020 – stałe urządzenia gaśnicze", "kind": "akt", "act": "odpady-rozp", "label": "§ 35", "text": "§ 35. 1. Strefę pożarową z odpadami stałymi o gęstości obciążenia ogniowego przekraczającej 2000 MJ/m2 i powierzch ni przekraczającej 2000 m2, która znajduje się w budynku, wyposaża się w stałe urządzenia gaśnicze wodne lub pianowe, uruchamiane automatycznie lub ręcznie – w przypadku zapewnienia stałej obsługi tych urządzeń lub posiadania zakładowej straży pożarnej."}, {"ref": "§ 37 ust. 1 rozp. MSWiA z 19.02.2020 – samoczynne urządzenia oddymiające", "kind": "akt", "act": "odpady-rozp", "label": "§ 37", "text": "§ 37. 1. Strefę pożarową z odpadami stałymi o gęstości obciążenia ogniowego przekraczającej 1000 MJ/m2 i powierzch ni przekraczającej 1000 m2, która znajduje się w budynku, wyposaża się w samoczynne urządzenia oddymiające."}], "259": [{"ref": "§ 271 ust. 1, 2, 3 i 7 WT – odległości między budynkami", "kind": "akt", "act": "wt", "label": "§ 271", "text": "§ 271. 1. Odległość między zewnętrznymi ścianami budynków niebędącymi ścianami oddzielenia przeciwpożarowego, a mającymi na powierzchni większej niż 65% klasę odporności ogniowej (E), określoną w § 216 ust. 1 w 5 kolumnie tabeli, nie powinna, z zastrzeżeniem ust. 2 i 3, być mniejsza niż odległość w metrach określona w poniższej tabeli: Rodzaj budynku oraz dla budynku PM maksymalna gęstość obciążenia ogniowego strefy pożarowej PM Q w MJ/m2 Rodzaj budynku oraz dla budynku PM maksymalna gęstość obciążenia ogniowego strefy pożarowej PM Q w MJ/m2 ZL IN PM Q ≤ 1000 1000 < Q ≤ 4000 Q > 4000 1 2 3 4 5 6 ZL 8 8 8 15 20 IN 8 8 8 15 20 PM Q ≤ 1000 8 8 8 15 20 PM 1000 < Q ≤ 4000 15 15 15 15 20 PM Q > 4000 20 20 20 20 20"}], "260": [{"ref": "PN-B-02857:2017-04 – przeciwpożarowe zbiorniki wodne", "kind": "norma"}], "261": [{"ref": "PKN-CEN/TS 54-14:2006 – rozmieszczenie czujek", "kind": "norma"}], "262": [{"ref": "§ 227 ust. 4 WT – wyłączenie budynków W i WW", "kind": "akt", "act": "wt", "label": "§ 227", "text": "4. Dopuszcza się powiększenie powierzchni stref pożarowych, o których mowa w ust. 1, z wyjątkiem stref pożarowych w wielokondygnacyjnych budynkach wysokich (W) i wysokościowych (WW), pod warunkiem zastosowania: 1) stałych samoczynnych urządzeń gaśniczych wodnych – o 100%; 2) samoczynnych urządzeń oddymiających uruchamianych za pomocą systemu wykrywania dymu – o 100%. Przy jednoczesnym stosowaniu urządzeń wymienionych w pkt 1 i 2 dopuszcza się powiększenie powierzchni stref pożarowych o 200%."}], "263": [{"ref": "PN-EN 12845 – klasy zagrożenia przestrzeni ukrytych", "kind": "norma"}], "264": [{"ref": "PN-EN 12845 – instalacje suche, przyspieszacz", "kind": "norma"}], "265": [{"ref": "§ 4 ust. 3 RPB – pas ochronny przy placach składowych i obiektach tymczasowych", "kind": "akt", "act": "rpb", "label": "§ 4", "text": "3. Wokół placów składowych i składowisk przy obiektach oraz przy obiektach tymczasowych o konstrukcji palnej musi być zachowany pas ochronny o minimalnej szerokości 2 m i nawierzchni z materiałów niepalnych lub gruntowej oczyszczonej."}], "266": [{"ref": "§ 237 WT – długość przejścia ewakuacyjnego", "kind": "akt", "act": "wt", "label": "§ 237", "text": "§ 237. 1. W pomieszczeniach, od najdalszego miejsca, w którym może przebywać człowiek, do wyjścia ewakuacyjnego na drogę ewakuacyjną lub do innej strefy pożarowej albo na zewnątrz budynku, powinno być zapewnione przejście, zwane dalej „przejściem ewakuacyjnym”, o długości nieprzekraczającej: 1) w strefach pożarowych ZL – 40 m; 2) w strefach pożarowych PM o gęstości obciążenia ogniowego przekraczającej 500 MJ/m2 w budynku o więcej niż jednej kondygnacji nadziemnej – 75 m; 3) w strefach pożarowych PM, o obciążeniu ogniowym nieprzekraczającym 500 MJ/m2, w budynku o więcej niż jednej kondygnacji nadziemnej oraz w strefach pożarowych PM w budynku o jednej kondygnacji nadziemnej bez względu na wielkość obciążenia ogniowego – 100 m. 2. W pomieszczeniu zagrożonym wybuchem długość przejścia ewakuacyjnego, o którym mowa w ust. 1 pkt 2 i 3, nie powinna przekraczać 40 m. 3. […]"}], "267": [{"ref": "§ 36 ust. 1 rozp. MSWiA z 19.02.2020 – urządzenia gaśnicze pianowe w magazynie ciekłych odpadów palnych", "kind": "akt", "act": "odpady-rozp", "label": "§ 36", "text": "§ 36. 1. Magazyn ciekłych odpadów palnych wyposaża się w stałe lub półstałe urządzenia gaśnicze pianowe."}, {"ref": "§ 36 ust. 2 rozp. MSWiA z 19.02.2020 – zwolnienie dla magazynów do 200 m2", "kind": "akt", "act": "odpady-rozp", "label": "§ 36", "text": "2. Stałe lub półstałe urządzenia gaśnicze pianowe nie muszą być stosowane w magazynach o powierzchni nie większej niż 200 m2, które posiadają co najmniej jedno okno lub inny otwór w ścianie zewnętrznej, umożliwiające skuteczne podanie piany gaśniczej."}], "268": [{"ref": "§ 236 ust. 6 WT – liczba użytkowników według powierzchni pomieszczeń", "kind": "akt", "act": "wt", "label": "§ 236", "text": "6. Określając wymaganą szerokość i liczbę przejść, wyjść oraz dróg ewakuacyjnych w budynku, w którym z przeznaczenia i sposobu zagospodarowania pomieszczeń nie wynika jednoznacznie maksymalna liczba ich użytkowników, liczbę tę należy przyjmować w odniesieniu do powierzchni tych pomieszczeń, dla: 1) sal konferencyjnych, lokali gastronomiczno-rozrywkowych, poczekalni, holi, świetlic itp. – 1 m2/osobę; 2) pomieszczeń handlowo-usługowych – 4 m2/osobę; 3) pomieszczeń administracyjno-biurowych – 5 m2/osobę; 4) archiwów, bibliotek itp. – 7 m2/osobę; 5) magazynów – 30 m2/osobę."}], "269": [{"ref": "PN-B-02877-4:2001 – rozmieszczenie klap dymowych na dachu", "kind": "norma"}], "270": [{"ref": "PN-HD 60364-5-56:2010 – instalacje bezpieczeństwa", "kind": "norma"}], "271": [{"ref": "PN-EN 1838:2005 – oświetlenie awaryjne stref wysokiego ryzyka", "kind": "norma"}], "272": [{"ref": "PN-EN 1838:2005 – odległość rozpoznawania znaków", "kind": "norma"}], "274": [{"ref": "§ 28, § 29 RPB; WT – kurtyny przeciwpożarowe scen", "kind": "norma"}], "276": [{"ref": "§ 20 RPB – instalacja wodociągowa przeciwpożarowa (instalacja sucha)", "kind": "akt", "act": "rpb", "label": "§ 20", "text": "§ 20. […] 2) w przejściach i na korytarzach, w tym w holach i na korytarzach poszczególnych kondygnacji budynków wysokich i wysokościowych; 3) przy wejściach na poddasza; 4) przy wyjściach na przestrzeń otwartą lub przy wyjściach ewakuacyjnych z pomieszczeń produkcyjnych i magazynowych, w szczególności zagrożonych wybuchem. 2. Hydranty wewnętrzne oraz zawory 52 muszą znajdować się na każdej kondygnacji, przy czym w budynkach wysokich i wysokościowych należy stosować po dwa zawory 52 na każdym pionie na kondygnacji podziemnej i na kondygnacji położonej na wysokości powyżej 25 m oraz po jednym zaworze 52 na każdym pionie na pozostałych kondygnacjach. 3. Zasięg hydrantów wewnętrznych w poziomie obejmuje całą powierzchnię chronionego budynku, strefy pożarowej lub pomieszczenia, z uwzględnieniem: 1) długości odcinka węża hydrantu wewnętrznego określonej w normach, o których mowa w § 18 ust. 2; […]"}], "278": [{"ref": "§ 42 rozp. MRiRW z 13.01.2023 (budowle rolnicze) – odległość stanowisk postojowych od instalacji biogazu rolniczego", "kind": "akt", "act": "rolnicze", "label": "§ 42", "text": "§ 42. Odległości stanowisk postojowych dla pojazdów samochodowych i samojezdnych maszyn rolniczych od instalacji służących do otrzymywania biogazu rolniczego powinny wynosić co najmniej 10 m."}], "279": [{"ref": "PN-EN 60079-10-1 / ocena zagrożenia wybuchem", "kind": "norma"}], "280": [{"ref": "§ 12–13 RW – parametry drogi pożarowej", "kind": "akt", "act": "rw", "label": "§ 12", "text": "§ 12. […] Pomiędzy tą drogą i ścianą budynku nie mogą występować stałe elementy zagospodarowania terenu lub drzewa i krzewy o wysokości przekraczającej 3 m, uniemożliwiające dostęp do elewacji budynku za pomocą podnośników i drabin mechanicznych. 3. W przypadkach uzasadnionych warunkami lokalnymi, w szczególności architektonicznymi, droga pożarowa do budynków, o których mowa w ust. 1 pkt 1—4, może być poprowadzona w taki sposób, aby był zapewniony dostęp do: 1) 30 % obwodu zewnętrznego budynku, przy jego rozpiętości (największej szerokości) do 60 m, 2) 50 % obwodu zewnętrznego budynku, przy jego rozpiętości przekraczającej 60 m, 3) 100 % długości elewacji od frontu budynku, przy zabudowie pierzejowej — przy spełnieniu pozostałych wymagań określonych w ust. 2. 4. […]"}], "281": [{"ref": "§ 261 WT – liczba siedzeń w rzędzie", "kind": "akt", "act": "wt", "label": "§ 261", "text": "§ 261. […] 2) szerokość przejść pomiędzy rzędami siedzeń nie mniejszą niż 0,45 m, przy czym odległość tę należy ustalać, biorąc pod uwagę odstęp między stałymi elementami siedzeń; 3) liczbę siedzeń w rzędzie nie większą niż 16 pomiędzy przejściami oraz 8 w rzędzie przyściennym, przy czym dopuszcza się zwiększenie liczby miejsc w rzędach odpowiednio do 40 i 20 pod warunkiem zwiększenia odstępu między rzędami siedzeń o 1 cm na każde dodatkowe siedzenie odpowiednio powyżej 16 lub 8; 4) szerokość przejść komunikacyjnych nie mniejszą niż 1,2 m przy liczbie osób do 150, a przy większej ich liczbie szerokość tę należy zwiększyć proporcjonalnie o 0,6 m na 100 osób; 5) rzędy siedzeń lub ławek trwale umocowane do podłogi albo siedzenia sztywno łączone ze sobą w rzędy oraz między rzędami."}], "282": [{"ref": "§ 68 WT – szerokość schodów ewakuacyjnych", "kind": "akt", "act": "wt", "label": "§ 68", "text": "§ 68. […] 1. 3. Szerokość użytkowa schodów zewnętrznych do budynku powinna wynosić co najmniej 1,2 m, przy czym nie może być mniejsza niż szerokość użytkowa biegu schodowego w budynku, przyjęta zgodnie z wymaganiami określonymi w ust. 1 i 2. 4. Szerokość użytkową schodów stałych mierzy się między wewnętrznymi krawędziami poręczy, a w przypadku balustrady jednostronnej – między wykończoną powierzchnią ściany a wewnętrzną krawędzią poręczy tej balustrady. Szerokości te nie mogą być ograniczane przez zainstalowane urządzenia oraz elementy budynku."}], "283": [{"ref": "§ 253 WT – biegi i spoczniki schodów", "kind": "akt", "act": "wt", "label": "§ 253", "text": "§ 253. 1. W budynku ZL I, ZL II, ZL III lub ZL V, mającym kondygnację z posadzką na wysokości powyżej 25 m ponad poziomem terenu przy najniżej położonym wejściu do budynku oraz w budynku wysokościowym (WW) ZL IV przynajmniej jeden dźwig powinien być przystosowany do potrzeb ekip ratowniczych, spełniając wymagania Polskiej Normy dotyczącej dźwigów dla straży pożarnej. Dźwig dla ekip ratowniczych powinien zapewniać dostęp do każdej strefy pożarowej na kondygnacji bezpośrednio lub drogami komunikacji ogólnej. 2. Dojście do dźwigu dla ekip ratowniczych powinno prowadzić przez przedsionek przeciwpożarowy spełniający wymagania określone w § 232. 3. Ściany i stropy szybu dźwigu dla ekip ratowniczych powinny mieć klasę odporności ogniowej wymaganą jak dla stropów budynku, zgodnie z § 216. 4. Szyb dźwigu dla ekip ratowniczych powinien być wyposażony w urządzenia zapobiegające zadymieniu."}], "284": [{"ref": "§ 179 WT / rozp. dot. zbiorników gazu płynnego", "kind": "akt", "act": "wt", "label": "§ 179", "text": "§ 179. […] 8. Dla zbiornika z gazem płynnym o pojemności do 10 m3 zmniejszenie jego odległości od budynku, o której mowa w ust. 7, może mieć miejsce również wówczas, gdy pionowy pas ściany tego budynku o szerokości co najmniej równej rzutowi równoległemu zbiornika, powiększonej po 2 m z obu jego stron, oraz o wysokości równej wysokości budynku będzie miał klasę odporności ogniowej co najmniej R E I 120 i w tym pasie ściany nie będą znajdowały się otwory okienne i drzwiowe. 9. Odległość zbiornika z gazem płynnym od rzutu poziomego skrajnego przewodu elektroenergetycznej linii napowietrznej, a także od szyny zelektryfikowanej linii kolejowej lub tramwajowej powinna wynosić co najmniej: 1) 3 m – przy napięciu linii elektroenergetycznej lub sieci trakcyjnej do 1 kV; 2) 15 m – przy napięciu linii elektroenergetycznej lub sieci trakcyjnej równym lub większym od 1 kV. Rozdział 8 Instalacja elektryczna"}], "285": [{"ref": "§ 157 ust. 4 WT – opinia KW PSP dla instalacji gazowej w budynku ponad 25 m", "kind": "akt", "act": "wt", "label": "§ 157", "text": "4. Zastosowanie instalacji gazowej w budynkach o wysokości ponad 25 m wymaga uzyskania pozytywnej opinii wydanej przez właściwego komendanta wojewódzkiego Państwowej Straży Pożarnej."}, {"ref": "§ 157 ust. 3 WT – instalacja gazowa w budynku wyższym niż 35 m", "kind": "akt", "act": "wt", "label": "§ 157", "text": "3. Instalacja gazowa w budynku o wysokości większej niż 35 m ponad poziomem terenu może być doprowadzona tylko do pomieszczeń technicznych, w których są zainstalowane urządzenia gazowe, usytuowanych w piwnicy lub na najniższej kondygnacji nadziemnej, a także na najwyższej kondygnacji budynku lub nad tą kondygnacją, pod warunkiem zastosowania urządzeń stabilizujących ciśnienie gazu."}], "286": [{"ref": "§ 239 WT – drzwi na drogach ewakuacyjnych", "kind": "akt", "act": "wt", "label": "§ 239", "text": "§ 239. […] 2. Drzwi stanowiące wyjście ewakuacyjne powinny otwierać się na zewnątrz pomieszczeń: 1) zagrożonych wybuchem; 2) do których jest możliwe niespodziewane przedostanie się mieszanin wybuchowych lub substancji trujących, duszących bądź innych, mogących utrudnić ewakuację; 3) przeznaczonych do jednoczesnego przebywania ponad 50 osób; 4) przeznaczonych dla ponad 6 osób o ograniczonej zdolności poruszania się. 3. Wyjścia ewakuacyjne z pomieszczenia zagrożonego wybuchem na drogę ewakuacyjną powinny prowadzić przez przedsionki przeciwpożarowe odpowiadające wymaganiom § 232. 4. Szerokość drzwi stanowiących wyjście ewakuacyjne z budynku, z zastrzeżeniem ust. 1, a także szerokość drzwi na drodze ewakuacyjnej z klatki schodowej, prowadzących na zewnątrz budynku lub do innej strefy pożarowej, powinna być nie mniejsza niż szerokość biegu klatki schodowej, określona zgodnie z § 68 ust. 1 i 2. 5. […]"}], "287": [{"ref": "§ 228 ust. 1 i 2 WT", "kind": "akt", "act": "wt", "label": "§ 228", "text": "§ 228. 1. Dopuszczalne powierzchnie stref pożarowych PM, z wyjątkiem garaży, określa poniższa tabela: Rodzaj stref pożarowych Gęstość obciążenia ogniowego Q [MJ/m2] Dopuszczalna powierzchnia strefy pożarowej w m2 w budynku o jednej kondygnacji nadziemnej (bez ograniczenia wysokości) w budynku wielokondygnacyjnym niskim i średniowysokim (N) i (SW) wysokim i wysokościowym (W) i (WW) 1 2 3 4 5 Strefy pożarowe z pomieszczeniem zagrożonym wybuchem Q > 4000 2000 < Q ≤ 4000 1000 < Q ≤ 2000 500 < Q ≤ 1000 Q ≤ 500 1000 2000 4000 6000 8000 * * 1000 2000 3000 * * * 500 1000 Strefy pożarowe pozostałe Q > 4000 2000 < Q ≤ 4000 1000 < Q ≤ 2000 500 < Q ≤ 1000 Q ≤ 500 2000 4000 8000 15 000 20 000 1000 2000 4000 8000 10 000 * * 1000 2500 5000 * Nie dopuszcza się takich przypadków."}, {"ref": "§ 229 ust. 1 pkt 1 WT", "kind": "akt", "act": "wt", "label": "§ 229", "text": "§ 229. 1. Dopuszcza się powiększenie powierzchni stref pożarowych, o których mowa w § 228, pod warunkiem ich ochrony: 1) stałymi samoczynnymi urządzeniami gaśniczymi wodnymi – o 100%; 2) samoczynnymi urządzeniami oddymiającymi – o 50%."}], "288": [{"ref": "§ 237 WT – długość przejścia ewakuacyjnego", "kind": "akt", "act": "wt", "label": "§ 237", "text": "§ 237. 1. W pomieszczeniach, od najdalszego miejsca, w którym może przebywać człowiek, do wyjścia ewakuacyjnego na drogę ewakuacyjną lub do innej strefy pożarowej albo na zewnątrz budynku, powinno być zapewnione przejście, zwane dalej „przejściem ewakuacyjnym”, o długości nieprzekraczającej: 1) w strefach pożarowych ZL – 40 m; 2) w strefach pożarowych PM o gęstości obciążenia ogniowego przekraczającej 500 MJ/m2 w budynku o więcej niż jednej kondygnacji nadziemnej – 75 m; 3) w strefach pożarowych PM, o obciążeniu ogniowym nieprzekraczającym 500 MJ/m2, w budynku o więcej niż jednej kondygnacji nadziemnej oraz w strefach pożarowych PM w budynku o jednej kondygnacji nadziemnej bez względu na wielkość obciążenia ogniowego – 100 m. 2. W pomieszczeniu zagrożonym wybuchem długość przejścia ewakuacyjnego, o którym mowa w ust. 1 pkt 2 i 3, nie powinna przekraczać 40 m. 3. […]"}], "289": [{"ref": "§ 271 ust. 1 i 5 WT – odległości między budynkami i ich zwiększenie o 100%", "kind": "akt", "act": "wt", "label": "§ 271", "text": "§ 271. 1. Odległość między zewnętrznymi ścianami budynków niebędącymi ścianami oddzielenia przeciwpożarowego, a mającymi na powierzchni większej niż 65% klasę odporności ogniowej (E), określoną w § 216 ust. 1 w 5 kolumnie tabeli, nie powinna, z zastrzeżeniem ust. 2 i 3, być mniejsza niż odległość w metrach określona w poniższej tabeli: Rodzaj budynku oraz dla budynku PM maksymalna gęstość obciążenia ogniowego strefy pożarowej PM Q w MJ/m2 Rodzaj budynku oraz dla budynku PM maksymalna gęstość obciążenia ogniowego strefy pożarowej PM Q w MJ/m2 ZL IN PM Q ≤ 1000 1000 < Q ≤ 4000 Q > 4000 1 2 3 4 5 6 ZL 8 8 8 15 20 IN 8 8 8 15 20 PM Q ≤ 1000 8 8 8 15 20 PM 1000 < Q ≤ 4000 15 15 15 15 20 PM Q > 4000 20 20 20 20 20"}, {"ref": "§ 216 ust. 1 WT – klasa ściany zewnętrznej EI 60 w budynku klasy „B”", "kind": "akt", "act": "wt", "label": "§ 216", "text": "§ 216. 1. Elementy budynku, odpowiednio do jego klasy odporności pożarowej, powinny spełniać, z zastrzeżeniem § 213 oraz § 237 ust. 9, co najmniej wymagania określone w poniższej tabeli: Klasa odporności pożarowej budynku Klasa odporności ogniowej elementów budynku5) *) główna konstrukcja nośna konstrukcja dachu strop1) ściana zewnętrzna1), 2) ściana wewnętrzna1) przekrycie dachu3) 1 2 3 4 5 6 7 „A” R 240 R 30 R E I 120 E I 120 (o↔i) E I 60 R E 30 „B” R 120 R 30 R E I 60 E I 60 (o↔i) E I 304) R E 30 „C” R 60 R 15 R E I 60 E I 30 (o↔i) E I 154) R E 15 „D” R 30 (–) R E I 30 E I 30 (o↔i) (–) (–) „E” (–) (–) (–) (–) (–) (–) *) Z zastrzeżeniem § 219 ust. 1. […]"}, {"ref": "§ 212 ust. 2 WT – klasa „B” dla ZL III średniowysokiego", "kind": "akt", "act": "wt", "label": "§ 212", "text": "2. Wymaganą klasę odporności pożarowej dla budynku, zaliczonego do jednej kategorii ZL, określa poniższa tabela: Budynek ZL I ZL II ZL III ZL IV ZL V 1 2 3 4 5 6 niski (N) „B” „B” „C” „D” „C” średniowysoki (SW) „B” „B” „B” „C” „B” wysoki (W) „B” „B” „B” „B” „B” wysokościowy (WW) „A” „A” „A” „B” „A”"}], "290": [{"ref": "§ 228 ust. 1 WT – tabela powierzchni stref PM", "kind": "akt", "act": "wt", "label": "§ 228", "text": "§ 228. 1. Dopuszczalne powierzchnie stref pożarowych PM, z wyjątkiem garaży, określa poniższa tabela: Rodzaj stref pożarowych Gęstość obciążenia ogniowego Q [MJ/m2] Dopuszczalna powierzchnia strefy pożarowej w m2 w budynku o jednej kondygnacji nadziemnej (bez ograniczenia wysokości) w budynku wielokondygnacyjnym niskim i średniowysokim (N) i (SW) wysokim i wysokościowym (W) i (WW) 1 2 3 4 5 Strefy pożarowe z pomieszczeniem zagrożonym wybuchem Q > 4000 2000 < Q ≤ 4000 1000 < Q ≤ 2000 500 < Q ≤ 1000 Q ≤ 500 1000 2000 4000 6000 8000 * * 1000 2000 3000 * * * 500 1000 Strefy pożarowe pozostałe Q > 4000 2000 < Q ≤ 4000 1000 < Q ≤ 2000 500 < Q ≤ 1000 Q ≤ 500 2000 4000 8000 15 000 20 000 1000 2000 4000 8000 10 000 * * 1000 2500 5000 * Nie dopuszcza się takich przypadków."}], "291": [{"ref": "§ 216 ust. 8 WT – palna izolacja cieplna w ścianach", "kind": "akt", "act": "wt", "label": "§ 216", "text": "8. W budynku, na wysokości powyżej 25 m od poziomu terenu, okładzina elewacyjna i jej zamocowanie mechaniczne, a także izolacja cieplna ściany zewnętrznej, powinny być wykonane z materiałów niepalnych."}], "292": [{"ref": "§ 215 ust. 2 WT – zachowanie pierwotnej klasy elementów oddzielenia przeciwpożarowego", "kind": "akt", "act": "wt", "label": "§ 215", "text": "2. Obniżenie klasy odporności pożarowej budynku, w przypadkach wymienionych w ust. 1 oraz w § 214, nie zwalnia z zachowania wymaganej pierwotnie klasy odporności ogniowej elementów oddzielenia przeciwpożarowego, określonej w § 232."}, {"ref": "§ 232 ust. 4 WT – REI 120 dla klasy „B” i „C”", "kind": "akt", "act": "wt", "label": "§ 232", "text": "4. Wymaganą klasę odporności ogniowej elementów oddzielenia przeciwpożarowego oraz zamknięć znajdujących się w nich otworów określa poniższa tabela: Klasa odporności pożarowej budynku Klasa odporności ogniowej elementów oddzielenia przeciwpożarowego drzwi przeciwpożarowych lub innych zamknięć przeciwpożarowych drzwi z przedsionka przeciwpożarowego ścian i stropów, z wyjątkiem stropów w ZL stropów w ZL na korytarz i do pomieszczenia na klatkę schodową*) 1 2 3 4 5 6 „A” R E I 240 R E I 120 E I 120 E I 60 E 60 „B” i „C” R E I 120 R E I 60 E I 60 E I 30 E 30 „D” i „E” R E I 60 R E I 30 E I 30 E I 15 E 15 *) Dopuszcza się osadzenie tych drzwi w ścianie o klasie odporności ogniowej, określonej dla drzwi w kol. 6, znajdującej się między przedsionkiem a klatką schodową."}, {"ref": "§ 234 ust. 1 WT – klasa przepustów w elementach oddzielenia przeciwpożarowego", "kind": "akt", "act": "wt", "label": "§ 234", "text": "§ 234. 1. Przepusty instalacyjne w elementach oddzielenia przeciwpożarowego powinny mieć klasę odporności ogniowej (E I) wymaganą dla tych elementów."}], "293": [{"ref": "§ 256 ust. 3 WT – dojście w ZL IV: 60 m, w tym do 20 m w poziomie", "kind": "akt", "act": "wt", "label": "§ 256", "text": "3. Dopuszczalne długości dojść ewakuacyjnych w strefach pożarowych określa poniższa tabela: Rodzaj strefy pożarowej Długość dojścia w m przy jednym dojściu przy co najmniej 2 dojściach1) 1 2 3 Z pomieszczeniem zagrożonym wybuchem 10 40 PM o gęstości obciążenia ogniowego Q > 500 MJ/m2 bez pomieszczenia zagrożonego wybuchem 302) 60 PM o gęstości obciążenia ogniowego Q ≤ 500 MJ/m2 bez pomieszczenia zagrożonego wybuchem 602) 100 ZL I, II i V 10 40 ZL III 302) 60 ZL IV 602) 100 1) Dla dojścia najkrótszego, przy czym dopuszcza się dla drugiego dojścia długość większą o 100% od najkrótszego. Dojścia te nie mogą się pokrywać ani krzyżować, przy czym dopuszcza się ich wspólny początkowy przebieg na długości nie większej niż 2 m. 2) W tym nie więcej niż 20 m na poziomej drodze ewakuacyjnej."}, {"ref": "§ 256 ust. 4 WT – powiększenie długości dojść za urządzenia gaśnicze i oddymiające", "kind": "akt", "act": "wt", "label": "§ 256", "text": "4. Długości dojść ewakuacyjnych, o których mowa w ust. 3, mogą być powiększone pod warunkiem ochrony: 1) strefy pożarowej stałymi samoczynnymi urządzeniami gaśniczymi wodnymi – o 50%; 2) drogi ewakuacyjnej samoczynnymi urządzeniami oddymiającymi uruchamianymi za pomocą systemu wykrywania dymu – o 50%. Przy jednoczesnym stosowaniu tych urządzeń długość dojścia może być powiększona o 100%."}], "294": [{"ref": "§ 245, § 256 WT – obudowa i zabezpieczenie klatek schodowych", "kind": "akt", "act": "wt", "label": "§ 245", "text": "§ 245. Klatki schodowe przeznaczone do ewakuacji ze strefy pożarowej: 1) ZL II w budynku niskim (N), 2) ZL I, ZL II, ZL III lub ZL V w budynku średniowysokim (SW), 3) PM o gęstości obciążenia ogniowego powyżej 500 MJ/m2 lub zawierającej pomieszczenie zagrożone wybuchem w budynku niskim (N) bądź średniowysokim (SW) – powinny być obudowane i zamykane drzwiami dymoszczelnymi oraz wyposażone w urządzenia zapobiegające zadymieniu lub służące do usuwania dymu, uruchamiane samoczynnie za pomocą systemu wykrywania dymu."}], "295": [{"ref": "§ 256 ust. 3 i 4 WT – długości dojść ewakuacyjnych", "kind": "akt", "act": "wt", "label": "§ 256", "text": "3. Dopuszczalne długości dojść ewakuacyjnych w strefach pożarowych określa poniższa tabela: Rodzaj strefy pożarowej Długość dojścia w m przy jednym dojściu przy co najmniej 2 dojściach1) 1 2 3 Z pomieszczeniem zagrożonym wybuchem 10 40 PM o gęstości obciążenia ogniowego Q > 500 MJ/m2 bez pomieszczenia zagrożonego wybuchem 302) 60 PM o gęstości obciążenia ogniowego Q ≤ 500 MJ/m2 bez pomieszczenia zagrożonego wybuchem 602) 100 ZL I, II i V 10 40 ZL III 302) 60 ZL IV 602) 100 1) Dla dojścia najkrótszego, przy czym dopuszcza się dla drugiego dojścia długość większą o 100% od najkrótszego. Dojścia te nie mogą się pokrywać ani krzyżować, przy czym dopuszcza się ich wspólny początkowy przebieg na długości nie większej niż 2 m. 2) W tym nie więcej niż 20 m na poziomej drodze ewakuacyjnej."}], "296": [{"ref": "§ 278 ust. 1 WT – wyjścia ewakuacyjne ze strefy garażu", "kind": "akt", "act": "wt", "label": "§ 278", "text": "§ 278. 1. Ze strefy pożarowej garażu, która posiada więcej niż 25 stanowisk postojowych i nie jest wyposażona w instalację wentylacji oddymiającej lub ma powierzchnię przekraczającą 1500 m2, należy zapewnić co najmniej dwa wyjścia ewakuacyjne, przy czym jednym z tych wyjść może być wjazd lub wyjazd."}], "298": [{"ref": "rozp. MG z 21.11.2005 / § 179 WT – odległości zbiorników gazu", "kind": "akt", "act": "wt", "label": "§ 179", "text": "§ 179. […] Dopuszczalna odległość zbiorników z gazem płynnym od budynków produkcyjnych i magazynowych powinna wynosić dla zbiorników o pojemności: 1) do 10 m3 – nie mniej niż odległość określona w tabeli w ust. 4 w kolumnach 2 i 3; 2) powyżej 10 m3 – nie mniej niż połowa odległości określonej w tabeli w ust. 4 w kolumnach 2 i 3. 6. Odległość zbiorników z gazem płynnym od granicy działki budowlanej z tymi zbiornikami powinna być nie mniejsza niż połowa odległości określonej w tabeli w ust. 4 w kolumnach 2 i 3, przy zachowaniu wymaganej odległości od budynku danego rodzaju. 7. Odległości określone w tabeli w ust. 4 w kolumnie 2 mogą być zmniejszone do 50% w przypadku zastosowania wolno stojącej ściany oddzielenia przeciwpożarowego o klasie odporności ogniowej co najmniej R E I 120, usytuowanej pomiędzy zbiornikiem z gazem płynnym a budynkiem. […]"}], "300": [{"ref": "§ 44 ust. 2 rozp. MRiRW z 13.01.2023 – strefy bezpieczeństwa wokół biogazowni rolniczych", "kind": "akt", "act": "rolnicze", "label": "§ 44", "text": "2. W przypadku instalacji służących do otrzymywania biogazu rolniczego, które mają pojemność: 1) do 350 m3 – strefa bezpieczeństwa wynosi co najmniej 3 m; 2) ponad 350 m3 do 700 m3 – strefa bezpieczeństwa wynosi co najmniej 5 m; 3) ponad 700 m3 – strefa bezpieczeństwa wynosi co najmniej 8 m."}], "301": [{"ref": "§ 15 rozp. MSWiA z 19.02.2020 – magazynowanie opon w sekcji magazynowej", "kind": "akt", "act": "odpady-rozp", "label": "§ 15", "text": "§ 15. 1. W sekcji magazynowej całe lub rozdrobnione opony magazynuje się: 1) w zabezpieczonych przed osunięciem stosach lub pryzmach o powierzchni nie większej niż 60 m2 lub 2) w kontenerach stalowych spełniających wymagania, o których mowa w § 13 ust. 1 pkt 1. 2. Stosy lub pryzmy z całymi lub rozdrobnionymi oponami oddziela się między sobą pasami wolnej przestrzeni lub te renu o szerokości co najmniej 3 m."}], "302": [{"ref": "§ 10 RW – sieć wodociągowa przeciwpożarowa", "kind": "akt", "act": "rw", "label": "§ 10", "text": "§ 10. […] 6) na stanowisku czerpania wody należy umieścić zakaz parkowania. 10. Określenia potrzeb w zakresie instalowania hydrantów, o których mowa w ust. 9, dokonują właściwe miejscowo organy Państwowej Straży Pożarnej w ramach opiniowania projektów studium uwarunkowań i kierunków zagospodarowania przestrzennego gminy oraz projektów miejscowych planów zagospodarowania przestrzennego, w trybie określonym w przepisach o planowaniu i zagospodarowaniu przestrzennym. 11. Maksymalne ciśnienie hydrostatyczne w sieci wodociągowej przeciwpożarowej nie może przekraczać 1,6 MPa. 12. Miejsce usytuowania hydrantu zewnętrznego należy oznakować znakami zgodnymi z Polskimi Normami. 13. Hydranty zewnętrzne powinny być co najmniej raz w roku poddawane przeglądom i konserwacji przez właściciela sieci wodociągowej przeciwpożarowej. Rozdział 5 Pompownie przeciwpożarowe"}], "303": [{"ref": "§ 10 RW – hydranty zewnętrzne", "kind": "akt", "act": "rw", "label": "§ 10", "text": "§ 10. […] 2. Dopuszcza się instalowanie hydrantów podziemnych o średnicy nominalnej DN 80 w przypadkach, gdy zainstalowanie hydrantów nadziemnych jest szczególnie utrudnione lub niewskazane, na przykład ze względu na utrudnienia w ruchu. 3. W obiekcie budowlanym produkcyjnym i magazynowym, w którym wymagana ilość wody do celów przeciwpożarowych do zewnętrznego gaszenia pożaru przekracza 30 dm3/s, w zakładach rafineryjnych i petrochemicznych oraz na magistralnym przewodzie wodociągowym przeciwpożarowym należy instalować hydranty nadziemne o średnicy nominalnej DN 100. 4. Hydranty zewnętrzne zainstalowane na sieci wodociągowej przeciwpożarowej powinny być wyposażone w odcięcia umożliwiające odłączania ich od sieci. Odcięcia te muszą pozostawać w położeniu otwartym podczas normalnej eksploatacji sieci. 5. […]"}], "304": [{"ref": "§ 19 ust. 3 i 4 RPB – hydranty 52 i dopuszczenie hydrantów 33 w strefach PM", "kind": "akt", "act": "rpb", "label": "§ 19", "text": "3. Hydranty 52 muszą być stosowane: 1) w strefie pożarowej produkcyjnej i magazynowej o gęstości obciążenia ogniowego przekraczającej 500 MJ/m2 i powierzchni przekraczającej 200 m2; 2) w strefie pożarowej produkcyjnej i magazynowej o gęstości obciążenia ogniowego nieprzekraczającej 500 MJ/m2, w której znajduje się pomieszczenie o powierzchni przekraczającej 100 m2 i gęstości obciążenia ogniowego przekraczającej 1 000 MJ/m2; 3) przy wejściu do pomieszczeń magazynowych lub technicznych o powierzchni przekraczającej 200 m2 i gęstości obciążenia ogniowego przekraczającej 500 MJ/m2, usytuowanych w strefie pożarowej zakwalifikowanej do kategorii zagrożenia ludzi ZL I, ZL II, ZL III lub ZL V, znajdującej się w budynku niskim albo średniowysokim."}, {"ref": "§ 22 ust. 1 RPB – minimalna wydajność hydrantów wewnętrznych", "kind": "akt", "act": "rpb", "label": "§ 22", "text": "§ 22. 1. Minimalna wydajność poboru wody mierzona na wylocie prądownicy wynosi: 1) dla hydrantu 25 ‒ 1,0 dm3/s; 2) dla hydrantu 33 ‒ 1,5 dm3/s; 3) dla hydrantu 52 ‒ 2,5 dm3/s; 4) dla zaworu 52 ‒ 2,5 dm3/s."}, {"ref": "§ 23 RPB – jednoczesność poboru wody z hydrantów", "kind": "akt", "act": "rpb", "label": "§ 23", "text": "§ 23. Instalacja wodociągowa przeciwpożarowa powinna zapewniać możliwość jednoczesnego poboru wody na jednej kondygnacji budynku lub w jednej strefie pożarowej z: 1) jednego hydrantu wewnętrznego ‒ w budynku niskim lub średniowysokim, jeżeli powierzchnia strefy pożarowej nie przekracza 500 m2; 2) dwóch sąsiednich hydrantów wewnętrznych lub dwóch sąsiednich zaworów 52 ‒ w budynkach niewymienionych w pkt 1 i 3 oraz w budynku wysokim z jedną klatką schodową; 3) czterech sąsiednich hydrantów wewnętrznych lub zaworów 52: a) w budynku wysokim i wysokościowym na kondygnacjach podziemnych i kondygnacjach położonych na wysokości powyżej 25 m, b) w strefie pożarowej produkcyjnej i magazynowej o gęstości obciążenia ogniowego przekraczającej 500 MJ/m2 i powierzchni przekraczającej 3000 m2."}], "305": [{"ref": "§ 6 RW – ilość wody dla obiektów innych niż budynki", "kind": "akt", "act": "rw", "label": "§ 6", "text": "§ 6. […] Wymagana ilość wody do celów przeciwpożarowych do zewnętrznego gaszenia pożaru dla stacji paliw i stacji gazu płynnego oraz stacji gazu ziemnego wynosi 10 dm3/s. 5. Wymaganą ilość wody do celów przeciwpożarowych do zewnętrznego gaszenia pożaru dla zbiorników z gazami palnymi oraz z cieczami o temperaturze zapłonu do 373,15 K (100 °C) niebędącymi produktami naftowymi oraz dla zbiorników z produktami naftowymi o temperaturze zapłonu od 328,15 K (55 °C) do 373,15 K (100 °C), z wyjątkiem podgrzanych powyżej temperatury zapłonu, służącą do zewnętrznego gaszenia pożaru, określa tabela nr 3 załącznika do rozporządzenia. 6. […]"}], "306": [{"ref": "§ 12 RW – parametry drogi pożarowej", "kind": "akt", "act": "rw", "label": "§ 12", "text": "§ 12. […] 7) stanowiska czerpania wody do celów przeciwpożarowych. 2. Droga pożarowa powinna przebiegać wzdłuż dłuższego boku budynku, o którym mowa w ust. 1 pkt 1—4, na całej jego długości, a w przypadku gdy krótszy bok budynku ma więcej niż 60 m — z jego dwóch stron, przy czym bliższa krawędź drogi pożarowej musi być oddalona od ściany budynku o 5—15 m dla obiektów zaliczanych do kategorii zagrożenia ludzi i o 5—25 m dla pozostałych obiektów. Pomiędzy tą drogą i ścianą budynku nie mogą występować stałe elementy zagospodarowania terenu lub drzewa i krzewy o wysokości przekraczającej 3 m, uniemożliwiające dostęp do elewacji budynku za pomocą podnośników i drabin mechanicznych. 3. […]"}], "307": [{"ref": "§ 24 ust. 2 RPB – zapas wody 100 m3 w budynkach wysokich i wysokościowych", "kind": "akt", "act": "rpb", "label": "§ 24", "text": "2. Do zasilania w wodę instalacji wodociągowej przeciwpożarowej w budynkach wysokich i wysokościowych powinien być zapewniony zapas wody zgromadzony o łącznej pojemności nie mniejszej niż 100 m3 w jednym lub kilku zbiornikach przeznaczony wyłącznie do tego celu."}, {"ref": "§ 24 ust. 3 pkt 3 RPB – zmniejszenie pojemności zbiornika przy zasilaniu z sieci", "kind": "akt", "act": "rpb", "label": "§ 24", "text": "3. Dopuszcza się: 1) zmniejszenie pojemności zbiorników, o których mowa w ust. 2, do 50 m3, w przypadku budynków wysokich i wysokościowych o wysokości do 100 m: a) zawierających na wysokości powyżej 12 m jedynie strefy pożarowe zakwalifikowane do kategorii zagrożenia ludzi ZL IV, niezależnie od ich powierzchni, lub b) niezawierających stref pożarowych o powierzchni przekraczającej 750 m2; 2) stosowanie jednego wspólnego zbiornika o pojemności co najmniej 100 m3 dla grupy budynków wysokich i wysokościowych wzniesionych obok siebie, jeżeli zbiornik nie jest oddalony od żadnego z budynków o więcej niż 100 m; 3) stosowanie zbiorników o pojemności zmniejszonej niż wymienione w: a) ust. 2 i ust. 3 pkt 2 ‒ do 50 m3 w przypadku zapewnienia zasilania tych zbiorników w wodę z zewnętrznej sieci wodociągowej przeciwpożarowej o wydajności nie mniejszej niż 10 dm3/s, b) ust. 2 i ust. […]"}], "308": [{"ref": "PN-HD 60364-5-56:2019-01 – instalacje bezpieczeństwa, zabezpieczenia obwodów", "kind": "norma"}], "309": [{"ref": "PN-B-02857:2017-04 – uzbrojenie zbiornika w przewody ssawne", "kind": "norma"}], "310": [{"ref": "PKN-CEN/TS 54-14:2020-09 – dobór czujek ciepła", "kind": "norma"}], "311": [{"ref": "PN-EN 54-23 – sygnalizatory optyczne, typy środowiskowe A i B", "kind": "norma"}], "312": [{"ref": "PN-EN 12845+A1:2020-05 – instalacje suche", "kind": "norma"}], "313": [{"ref": "PN-EN 12845 – dobór parametrów urządzenia tryskaczowego", "kind": "norma"}], "314": [{"ref": "PN-EN 12845+A1:2020-05 – rozmieszczenie tryskaczy", "kind": "norma"}], "315": [{"ref": "PN-EN 15004 – gazy gaśnicze", "kind": "norma"}], "316": [{"ref": "PN-EN 12101-6:2007 – systemy różnicowania ciśnień, maksymalna różnica ciśnień i siła otwierania drzwi 100 N", "kind": "norma"}], "317": [{"ref": "PN-EN 12101-6:2007 – systemy różnicowania ciśnień", "kind": "norma"}], "318": [{"ref": "PN-EN 81-73:2020-12 – funkcjonowanie dźwigów w przypadku pożaru", "kind": "norma"}], "319": [{"ref": "PN-EN 1838:2013 – czas osiągania natężenia oświetlenia awaryjnego", "kind": "norma"}], "320": [{"ref": "PN-B-02877-4:2001 – instalacje grawitacyjne do odprowadzania dymu i ciepła, uruchamianie oddymiania klatek schodowych", "kind": "norma"}], "321": [{"ref": "§ 218 ust. 1 i 2 WT – dach budynku niższego przy ścianie z otworami budynku wyższego", "kind": "akt", "act": "wt", "label": "§ 218", "text": "§ 218. 1. Przekrycie dachu budynku niższego, usytuowanego bliżej niż 8 m lub przyległego do ściany z otworami budynku wyższego, z wyjątkiem przypadków wymienionych w § 273 ust. 1, w pasie o szerokości 8 m od tej ściany powinno być nierozprzestrzeniające ognia oraz w pasie tym: 1) konstrukcja dachu powinna mieć klasę odporności ogniowej co najmniej R 30; 2) przekrycie dachu powinno mieć klasę odporności ogniowej co najmniej R E 30."}, {"ref": "§ 218 ust. 4 WT – wyloty kanałów dopuszczone w pasie 8 m", "kind": "akt", "act": "wt", "label": "§ 218", "text": "4. Dopuszcza się sytuowanie wylotów kanałów wentylacyjnych i spalinowych od urządzeń gazowych oraz rur wentylujących piony kanalizacyjne w części połaci dachu lub stropodachu budynku niższego, o której mowa w ust. 1."}], "322": [{"ref": "§ 243 ust. 1 WT – podział korytarzy ewakuacyjnych w strefach ZL", "kind": "akt", "act": "wt", "label": "§ 243", "text": "§ 243. 1. Korytarze stanowiące drogę ewakuacyjną w strefach pożarowych ZL powinny być podzielone na odcinki nie dłuższe niż 50 m przy zastosowaniu przegród z drzwiami dymoszczelnymi lub innych urządzeń technicznych, zapobiegających rozprzestrzenianiu się dymu."}, {"ref": "§ 243 ust. 2 WT – zwolnienie przy zabezpieczeniu przed zadymieniem", "kind": "akt", "act": "wt", "label": "§ 243", "text": "2. Wymaganie, o którym mowa w ust. 1, nie dotyczy korytarzy, na których zastosowano rozwiązania techniczno-budowlane zabezpieczające przed zadymieniem."}], "323": [{"ref": "§ 212 ust. 4, § 230 WT", "kind": "akt", "act": "wt", "label": "§ 212", "text": "4. Wymaganą klasę odporności pożarowej dla budynku PM oraz IN, z zastrzeżeniem § 282, określa poniższa tabela: Maksymalna gęstość obciążenia ogniowego strefy pożarowej w budynku Q [MJ/m2] Budynek o jednej kondygnacji nadziemnej (bez ograniczenia wysokości) Budynek wielokondygnacyjny niski średniowysoki wysoki wysokościowy (N) (SW) (W) (WW) 1 2 3 4 5 6 Q ≤ 500 „E” „D” „C” „B” „B” 500 < Q ≤ 1000 „D” „D” „C” „B” „B” 1000 < Q ≤ 2000 „C” „C” „C” „B” „B” 2000 < Q ≤ 4000 „B” „B” „B” * * Q > 4000 „A” „A” „A” * * * – Zgodnie z § 228 ust. 1 nie mogą występować takie budynki."}], "324": [{"ref": "§ 228 ust. 1 WT", "kind": "akt", "act": "wt", "label": "§ 228", "text": "§ 228. 1. Dopuszczalne powierzchnie stref pożarowych PM, z wyjątkiem garaży, określa poniższa tabela: Rodzaj stref pożarowych Gęstość obciążenia ogniowego Q [MJ/m2] Dopuszczalna powierzchnia strefy pożarowej w m2 w budynku o jednej kondygnacji nadziemnej (bez ograniczenia wysokości) w budynku wielokondygnacyjnym niskim i średniowysokim (N) i (SW) wysokim i wysokościowym (W) i (WW) 1 2 3 4 5 Strefy pożarowe z pomieszczeniem zagrożonym wybuchem Q > 4000 2000 < Q ≤ 4000 1000 < Q ≤ 2000 500 < Q ≤ 1000 Q ≤ 500 1000 2000 4000 6000 8000 * * 1000 2000 3000 * * * 500 1000 Strefy pożarowe pozostałe Q > 4000 2000 < Q ≤ 4000 1000 < Q ≤ 2000 500 < Q ≤ 1000 Q ≤ 500 2000 4000 8000 15 000 20 000 1000 2000 4000 8000 10 000 * * 1000 2500 5000 * Nie dopuszcza się takich przypadków."}, {"ref": "§ 229 ust. 1 pkt 1 WT", "kind": "akt", "act": "wt", "label": "§ 229", "text": "§ 229. 1. Dopuszcza się powiększenie powierzchni stref pożarowych, o których mowa w § 228, pod warunkiem ich ochrony: 1) stałymi samoczynnymi urządzeniami gaśniczymi wodnymi – o 100%; 2) samoczynnymi urządzeniami oddymiającymi – o 50%."}], "325": [{"ref": "PN-EN 13501-1; § 208 WT", "kind": "norma"}], "326": [{"ref": "§ 216 ust. 2 pkt 1 WT – dopuszczenie elementów słabo rozprzestrzeniających ogień", "kind": "akt", "act": "wt", "label": "§ 216", "text": "2. Elementy budynku, o których mowa w ust. 1, powinny być nierozprzestrzeniające ognia, przy czym dopuszcza się zastosowanie słabo rozprzestrzeniających ogień: 1) elementów budynku o jednej kondygnacji nadziemnej ZL IV oraz PM, o maksymalnej gęstości obciążenia ogniowego strefy pożarowej do 500 MJ/m2; 2) ścian wewnętrznych i zewnętrznych oraz elementów konstrukcji dachu i jego przekrycia w budynku PM niskim o maksymalnej gęstości obciążenia ogniowego strefy pożarowej do 1000 MJ/m2; 3) ścian zewnętrznych w budynku niskim ZL IV."}], "327": [{"ref": "§ 8–9 RW – uzupełniający zapas wody", "kind": "akt", "act": "rw", "label": "§ 8", "text": "§ 8. 1. W przypadku braku źródła wody zapewniającego wymaganą ilość wody do celów przeciwpożarowych, właściwy miejscowo komendant powiatowy (miejski) Państwowej Straży Pożarnej na wniosek właściciela budynku, obiektu budowlanego lub terenu, może dopuścić na czas określony zastępcze źródło wody do celów przeciwpożarowych, w szczególności naturalny lub sztuczny zbiornik wody, studnię lub ciek wodny, wyposażone w stanowisko czerpania wody wraz z dojazdem. 2. Zastępcze źródło wody, o którym mowa w ust. 1, powinno zapewniać możliwość prowadzenia działań gaśniczych z użyciem sił i środków dostępnych w rejonie działania najbliższej jednostki ochrony przeciwpożarowej. 3. […]"}], "328": [{"ref": "§ 232 WT – klasy ścian oddzielenia przeciwpożarowego", "kind": "akt", "act": "wt", "label": "§ 232", "text": "§ 232. […] 6. W ścianie oddzielenia przeciwpożarowego dopuszcza się wypełnienie otworów materiałem przepuszczającym światło, takim jak luksfery, cegła szklana lub inne przeszklenie, jeżeli powierzchnia wypełnionych otworów nie przekracza 10% powierzchni ściany, przy czym klasa odporności ogniowej wypełnień nie powinna być niższa niż: Wymagana klasa odporności ogniowej ściany oddzielenia przeciwpożarowego Klasa odporności ogniowej wypełnienia otworu w ścianie będącej obudową drogi ewakuacyjnej innej 1 2 3 R E I 240 E I 120 E 120 R E I 120 E I 60 E 60 R E I 60 E I 30 E 30 7. Dopuszcza się stosowanie w strefach pożarowych PM otworu w ścianie oddzielenia przeciwpożarowego, służącego przeprowadzeniu urządzeń technologicznych, chronionego w sposób równoważny wymaganym dla tej ściany drzwiom przeciwpożarowym pod względem możliwości przeniesienia się przez ten otwór ognia lub dymu, w przypadku pożaru."}], "329": [{"ref": "§ 179 ust. 4 WT – odległości zbiorników gazu płynnego od budynków", "kind": "akt", "act": "wt", "label": "§ 179", "text": "4. Dopuszczalną odległość zbiorników z gazem płynnym od budynków mieszkalnych, budynków zamieszkania zbiorowego oraz budynków użyteczności publicznej, a także między zbiornikami, określa poniższa tabela: Nominalna pojemność zbiornika w m3 Odległość budynków mieszkalnych, budynków zamieszkania zbiorowego i budynków użyteczności publicznej od: Odległość od sąsiedniego zbiornika naziemnego lub podziemnego w m zbiornika naziemnego w m zbiornika podziemnego w m 1 2 3 4 do 3 3 1 1 powyżej 3 do 5 5 2,5 1 powyżej 5 do 7 7,5 3 1,5 powyżej 7 do 10 10 5 1,5 powyżej 10 do 40 20 10 ¼ sumy średnic dwóch sąsiednich zbiorników powyżej 40 do 65 30 15 powyżej 65 do 100 40 20"}, {"ref": "§ 179 ust. 6 WT – odległość od granicy działki", "kind": "akt", "act": "wt", "label": "§ 179", "text": "6. Odległość zbiorników z gazem płynnym od granicy działki budowlanej z tymi zbiornikami powinna być nie mniejsza niż połowa odległości określonej w tabeli w ust. 4 w kolumnach 2 i 3, przy zachowaniu wymaganej odległości od budynku danego rodzaju."}], "330": [{"ref": "§ 237 WT – długość przejścia ewakuacyjnego", "kind": "akt", "act": "wt", "label": "§ 237", "text": "§ 237. 1. W pomieszczeniach, od najdalszego miejsca, w którym może przebywać człowiek, do wyjścia ewakuacyjnego na drogę ewakuacyjną lub do innej strefy pożarowej albo na zewnątrz budynku, powinno być zapewnione przejście, zwane dalej „przejściem ewakuacyjnym”, o długości nieprzekraczającej: 1) w strefach pożarowych ZL – 40 m; 2) w strefach pożarowych PM o gęstości obciążenia ogniowego przekraczającej 500 MJ/m2 w budynku o więcej niż jednej kondygnacji nadziemnej – 75 m; 3) w strefach pożarowych PM, o obciążeniu ogniowym nieprzekraczającym 500 MJ/m2, w budynku o więcej niż jednej kondygnacji nadziemnej oraz w strefach pożarowych PM w budynku o jednej kondygnacji nadziemnej bez względu na wielkość obciążenia ogniowego – 100 m. 2. W pomieszczeniu zagrożonym wybuchem długość przejścia ewakuacyjnego, o którym mowa w ust. 1 pkt 2 i 3, nie powinna przekraczać 40 m. 3. […]"}], "331": [{"ref": "§ 216 WT – wymagane klasy odporności ogniowej elementów", "kind": "akt", "act": "wt", "label": "§ 216", "text": "§ 216. 1. Elementy budynku, odpowiednio do jego klasy odporności pożarowej, powinny spełniać, z zastrzeżeniem § 213 oraz § 237 ust. 9, co najmniej wymagania określone w poniższej tabeli: Klasa odporności pożarowej budynku Klasa odporności ogniowej elementów budynku5) *) główna konstrukcja nośna konstrukcja dachu strop1) ściana zewnętrzna1), 2) ściana wewnętrzna1) przekrycie dachu3) 1 2 3 4 5 6 7 „A” R 240 R 30 R E I 120 E I 120 (o↔i) E I 60 R E 30 „B” R 120 R 30 R E I 60 E I 60 (o↔i) E I 304) R E 30 „C” R 60 R 15 R E I 60 E I 30 (o↔i) E I 154) R E 15 „D” R 30 (–) R E I 30 E I 30 (o↔i) (–) (–) „E” (–) (–) (–) (–) (–) (–) *) Z zastrzeżeniem § 219 ust. 1. […]"}], "332": [{"ref": "§ 37 RPB / WT – wymagania dla pomieszczeń zagrożonych wybuchem", "kind": "akt", "act": "wt", "label": "§ 37", "text": "§ 37. Przepływowe, szczelne osadniki podziemne, stanowiące część przydomowej oczyszczalni ścieków gospodarczo-bytowych, służące do wstępnego ich oczyszczania, mogą być sytuowane w bezpośrednim sąsiedztwie budynków jednorodzinnych, pod warunkiem wyprowadzenia ich odpowietrzenia przez instalację kanalizacyjną co najmniej 0,6 m powyżej górnej krawędzi okien i drzwi zewnętrznych w tych budynkach."}], "334": [{"ref": "§ 16 RPB – warunki uznania budynku za zagrażający życiu ludzi", "kind": "akt", "act": "rpb", "label": "§ 16", "text": "§ 16. […] 2. Podstawą do stwierdzenia, że w budynku występują warunki techniczne, o których mowa w ust. 1, z zastrzeżeniem § 45, może być: 1) szerokość przejścia, dojścia lub wyjścia ewakuacyjnego albo biegu bądź spocznika klatki schodowej służącej ewakuacji, mniejsza o ponad jedną trzecią od określonej w przepisach techniczno-budowlanych; 2) długość przejścia lub dojścia ewakuacyjnego większa o ponad 100% od określonej w przepisach techniczno-budowlanych; 3) występowanie w pomieszczeniu strefy pożarowej zakwalifikowanej do kategorii zagrożenia ludzi ZL I, ZL II lub ZL V albo na drodze ewakuacyjnej: a) okładziny sufitu lub sufitu podwieszonego z materiału łatwo zapalnego lub kapiącego pod wpływem ognia, bądź wykładziny podłogowej z materiału łatwo zapalnego, b) okładziny ściennej z materiału łatwo zapalnego na drodze ewakuacyjnej, jeżeli nie zapewniono dwóch kierunków ewakuacji; […]"}], "335": [{"ref": "§ 67 pkt 1 rozp. w sprawie baz i stacji paliw płynnych – hydranty i działka wodne w bazach gazu płynnego", "kind": "akt", "act": "paliwa", "label": "§ 67", "text": "§ 67. Bazy gazu płynnego powinny być wyposażone w: 1) urządzenia i instalacje przeciwpożarowe wodne, przy czym przeciwpożarowe hydranty i działka Dziennik Ustaw Nr 243 — 15981 — Poz. 2063 wodne powinny być rozmieszczone w odległości co najmniej 20 m od chronionych obiektów, lecz nie dalej niż 100 m; 2) urządzenia wykrywające i alarmujące o niekontrolowanym wycieku gazu płynnego z odcięciem jego dopływu. Rozdział 2 Magazynowanie gazu płynnego w zbiornikach"}], "336": [{"ref": "PN-EN 12845 – klasyfikacja tryskaczy wg RTI", "kind": "norma"}], "337": [{"ref": "§ 55 ust. 1 pkt 1 rozp. w sprawie baz i stacji paliw płynnych – lokalizacja pompowni przeciwpożarowych", "kind": "akt", "act": "paliwa", "label": "§ 55", "text": "§ 55. 1. Pompownie przeciwpożarowe: 1) należy lokalizować w odległości nie mniejszej niż 25 m od osi obwałowania zbiornika lub jego ściany osłonowej; 2) mogą być wbudowane w inny obiekt budowlany, pod warunkiem zabezpieczenia tego obiektu elementami oddzieleń przeciwpożarowych o klasie odporności ogniowej co najmniej REI 120."}], "338": [{"ref": "§ 7 ust. 1 pkt 3 RW – ilość wody przy urządzeniach gaśniczych pianowych", "kind": "akt", "act": "rw", "label": "§ 7", "text": "§ 7. 1. Wymagana ilość wody do celów przeciwpożarowych dla stref pożarowych wyposażonych w stałe urządzenia gaśnicze i zabezpieczające zarówno przy wspólnym, jak i oddzielnym wykorzystywaniu wodociągu lub zapasu wody do zasilania tych urządzeń i zewnętrznego gaszenia pożaru, w obiektach budowlanych, o których mowa w § 5 ust. 1 i 3 oraz w § 6 ust. 3, 5 i 7, jest równa: 1) przy zastosowaniu urządzeń zraszaczowych zabezpieczających — sumie ilości wody do zasilania tych urządzeń i do zewnętrznego gaszenia pożaru; 2) przy zastosowaniu urządzeń gaśniczych tryskaczowych, zraszaczowych i mgłowych oraz sieci stałych działek gaśniczych — sumie ilości wody do zasilania tych urządzeń i zmniejszonej o 50 % ilości wody do zewnętrznego gaszenia pożaru, z tym że wymagana ilość wody powinna być nie mniejsza niż ilość wody do zewnętrznego gaszenia pożaru; […]"}], "339": [{"ref": "§ 12 ust. 1 pkt 3 RW – droga pożarowa do stref PM w budynkach i poza budynkami", "kind": "akt", "act": "rw", "label": "§ 12", "text": "§ 12. 1. Drogę pożarową o utwardzonej nawierzchni, umożliwiającą dojazd pojazdów jednostek ochrony przeciwpożarowej do obiektu budowlanego o każdej porze roku, należy doprowadzić do: 1) budynku zawierającego strefę pożarową zakwalifikowaną do kategorii zagrożenia ludzi ZL I lub ZL II; 2) budynku należącego do grupy wysokości: średniowysoki, wysoki lub wysokościowy, zawierającego strefę pożarową zakwalifikowaną do kategorii zagrożenia ludzi ZL III, ZL IV lub ZL V; 3) budynku zawierającego strefę pożarową produkcyjną lub magazynową oraz do strefy pożarowej poza budynkiem, obejmującej urządzenia technologiczne, plac składowy lub wiatę, jeżeli gęstość obciążenia ogniowego wymienionych stref pożarowych przekracza 500 MJ/m2 i zachodzi co najmniej jeden z warunków: a) powierzchnia strefy pożarowej przekracza 1 000 m2, b) występuje pomieszczenie zagrożone wybuchem; […]"}, {"ref": "§ 12 ust. 1 pkt 4 RW – budynki ze strefą PM poniżej 500 MJ/m2", "kind": "akt", "act": "rw", "label": "§ 12", "text": "§ 12. 1. Drogę pożarową o utwardzonej nawierzchni, umożliwiającą dojazd pojazdów jednostek ochrony przeciwpożarowej do obiektu budowlanego o każdej porze roku, należy doprowadzić do: 1) budynku zawierającego strefę pożarową zakwalifikowaną do kategorii zagrożenia ludzi ZL I lub ZL II; 2) budynku należącego do grupy wysokości: średniowysoki, wysoki lub wysokościowy, zawierającego strefę pożarową zakwalifikowaną do kategorii zagrożenia ludzi ZL III, ZL IV lub ZL V; 3) budynku zawierającego strefę pożarową produkcyjną lub magazynową oraz do strefy pożarowej poza budynkiem, obejmującej urządzenia technologiczne, plac składowy lub wiatę, jeżeli gęstość obciążenia ogniowego wymienionych stref pożarowych przekracza 500 MJ/m2 i zachodzi co najmniej jeden z warunków: a) powierzchnia strefy pożarowej przekracza 1 000 m2, b) występuje pomieszczenie zagrożone wybuchem; […]"}], "340": [{"ref": "PN-EN 12101-6:2007 – systemy różnicowania ciśnień, rozmieszczenie punktów nawiewu", "kind": "norma"}], "341": [{"ref": "§ 10 RW – hydranty zewnętrzne na sieci", "kind": "akt", "act": "rw", "label": "§ 10", "text": "§ 10. […] 2. Dopuszcza się instalowanie hydrantów podziemnych o średnicy nominalnej DN 80 w przypadkach, gdy zainstalowanie hydrantów nadziemnych jest szczególnie utrudnione lub niewskazane, na przykład ze względu na utrudnienia w ruchu. 3. W obiekcie budowlanym produkcyjnym i magazynowym, w którym wymagana ilość wody do celów przeciwpożarowych do zewnętrznego gaszenia pożaru przekracza 30 dm3/s, w zakładach rafineryjnych i petrochemicznych oraz na magistralnym przewodzie wodociągowym przeciwpożarowym należy instalować hydranty nadziemne o średnicy nominalnej DN 100. 4. Hydranty zewnętrzne zainstalowane na sieci wodociągowej przeciwpożarowej powinny być wyposażone w odcięcia umożliwiające odłączania ich od sieci. Odcięcia te muszą pozostawać w położeniu otwartym podczas normalnej eksploatacji sieci. 5. […]"}], "342": [{"ref": "§ 19 RPB – hydranty wewnętrzne (dotyczą budynków)", "kind": "akt", "act": "rpb", "label": "§ 19", "text": "§ 19. 1. Hydranty 25 muszą być stosowane w strefach pożarowych zakwalifikowanych do kategorii zagrożenia ludzi ZL: 1) na każdej kondygnacji budynku wysokiego i wysokościowego, z wyjątkiem kondygnacji obejmującej wyłącznie strefę pożarową zakwalifikowaną do kategorii zagrożenia ludzi ZL IV; […]"}], "343": [{"ref": "§ 8 RPB – składowanie gazu płynnego w punktach sprzedaży", "kind": "akt", "act": "rpb", "label": "§ 8", "text": "§ 8. 1. Podczas przechowywania cieczy o temperaturze zapłonu poniżej 328,15 K (55ºC) w budynkach, w strefach pożarowych zaliczonych do kategorii zagrożenia ludzi: 1) jest dopuszczalne przechowywanie w jednej strefie pożarowej, zakwalifikowanej do kategorii zagrożenia ludzi innej niż ZL IV oraz o przeznaczeniu innym niż handlowo-usługowe do 10 dm3 cieczy o temperaturze zapłonu poniżej 294,15 K (21ºC) oraz do 50 dm3 cieczy o temperaturze zapłonu 294,15÷328,15 K (21÷55ºC), a w mieszkaniach odpowiednio do 5 i do 20 dm3 cieczy; 2) jest dopuszczalne przechowywanie w pomieszczeniach handlowo-usługowych cieczy o temperaturze zapłonu do 328,15 K (55ºC) w takiej ilości, że gęstość obciążenia ogniowego stworzona przez te ciecze nie przekroczy 500 MJ/m2; […]"}], "344": [{"ref": "PN-EN 12845+A1:2020 – powierzchnia na stanowisko kontrolno-alarmowe", "kind": "norma"}], "345": [{"ref": "rozp. z 30.05.2000 – drogowe obiekty inżynierskie; PN-EN 12101-3", "kind": "norma"}], "346": [{"ref": "PN-B-02877-4:2001 – kurtyny dymowe", "kind": "norma"}], "347": [{"ref": "§ 19 RPB / PN-EN 671-2 – hydranty wewnętrzne 52", "kind": "norma"}], "348": [{"ref": "PN-B-02877-4:2001/Az1:2006 – odległość klap dymowych od ścian oddzielenia przeciwpożarowego (5 m i 7 m)", "kind": "norma"}], "349": [{"ref": "PN-B-02857:2017-04 – usytuowanie zbiornika względem obiektu chronionego", "kind": "norma"}, {"ref": "§ 4 ust. 5 RW – odległość uzupełniających źródeł wody", "kind": "akt", "act": "rw", "label": "§ 4", "text": "5. W przypadku gdy w jednostce osadniczej zasoby wody przeznaczonej dla ludności dostarczanej wodociągiem nie zapewniają ilości wymaganych do celów przeciwpożarowych, wykonuje się, w odległości nie większej niż 250 m od skrajnej zabudowy jednostki osadniczej lub chronionego obiektu budowlanego, co najmniej jedno z następujących uzupełniających źródeł wody: 1) studnię o wydajności nie mniejszej niż 10 dm3/s; 2) punkt czerpania wody przy naturalnym lub sztucznym zbiorniku wodnym o pojemności zapewniającej odpowiedni zapas wody albo na cieku wodnym o stałym przepływie wody nie mniejszym niż 20 dm3/s przy najniższym stanie wód; 3) przeciwpożarowy zbiornik wodny spełniający wymagania Polskiej Normy."}], "350": [{"ref": "PN-EN 1993-1-2 – projektowanie konstrukcji stalowych na warunki pożarowe", "kind": "norma"}], "351": [{"ref": "PKN-CEN/TS 54-14:2020 – rozmieszczenie czujek w korytarzach", "kind": "norma"}], "352": [{"ref": "PN-B-02857:2017 – przeciwpożarowe zbiorniki wodne", "kind": "norma"}], "353": [{"ref": "PN-B-02431-1:1999 – kotłownie gazowe", "kind": "norma"}], "354": [{"ref": "PN-EN 12845+A1:2020 – intensywność zraszania", "kind": "norma"}], "356": [{"ref": "dyrektywa ATEX – kategorie urządzeń i strefy pyłowe", "kind": "ue"}], "357": [{"ref": "§ 37 ust. 7 RPB – definicja pomieszczenia zagrożonego wybuchem", "kind": "akt", "act": "rpb", "label": "§ 37", "text": "7. Pomieszczenie, w którym może wytworzyć się mieszanina wybuchowa, powstała z wydzielającej się takiej ilości palnych gazów, par, mgieł lub pyłów, której wybuch mógłby spowodować przyrost ciśnienia w tym pomieszczeniu przekraczający 5 kPa, określa się jako pomieszczenie zagrożone wybuchem."}, {"ref": "§ 2 ust. 1 pkt 1 RPB – materiały niebezpieczne pożarowo", "kind": "akt", "act": "rpb", "label": "§ 2", "text": "§ 2. 1. Ilekroć w rozporządzeniu jest mowa o: 1) materiałach niebezpiecznych pożarowo ‒ należy przez to rozumieć: a) gazy palne, b) ciecze palne o temperaturze zapłonu poniżej 328,15 K (55ºC), c) materiały wytwarzające w zetknięciu z wodą gazy palne, d) materiały zapalające się samorzutnie na powietrzu, e) materiały wybuchowe i wyroby pirotechniczne, f) materiały ulegające samorzutnemu rozkładowi lub polimeryzacji, g) materiały mające skłonności do samozapalenia, h) materiały inne niż wymienione w lit. a‒g, jeśli sposób ich składowania, przetwarzania lub innego wykorzystania może spowodować powstanie pożaru; 2) pasie przeciwpożarowym ‒ należy przez to rozumieć system drzewostanów różnej szerokości poddanych specjalnym zabiegom gospodarczym i porządkowym lub powierzchni wylesionych i oczyszczonych do warstwy mineralnej; […]"}], "358": [{"ref": "§ 6 ust. 4 RW – ilość wody dla stacji paliw i stacji gazu", "kind": "akt", "act": "rw", "label": "§ 6", "text": "4. Wymagana ilość wody do celów przeciwpożarowych do zewnętrznego gaszenia pożaru dla stacji paliw i stacji gazu płynnego oraz stacji gazu ziemnego wynosi 10 dm3/s."}], "359": [{"ref": "PN-EN 671-1:2012 – hydranty wewnętrzne z wężem półsztywnym, efektywny zasięg rzutu", "kind": "norma"}], "361": [{"ref": "§ 261 WT – podłogi podniesione", "kind": "akt", "act": "wt", "label": "§ 261", "text": "§ 261. Pomieszczenia przeznaczone do jednoczesnego przebywania ponad 200 osób dorosłych lub 100 dzieci, w których miejsca do siedzenia są ustawione w rzędach, powinny mieć: 1) fotele i inne siedzenia trudno zapalne oraz niewydzielające produktów rozkładu i spalania, określonych jako bardzo toksyczne, zgodnie z Polską Normą dotyczącą badań wydzielania produktów toksycznych; określenie trudno zapalny przypisuje się fotelom i innym siedzeniom, które nie ulegają postępującemu tleniu i spalaniu płomieniowemu w warunkach określonych Polską Normą dotyczącą badania zapalności mebli tapicerowanych; 2) szerokość przejść pomiędzy rzędami siedzeń nie mniejszą niż 0,45 m, przy czym odległość tę należy ustalać, biorąc pod uwagę odstęp między stałymi elementami siedzeń; […]"}], "362": [{"ref": "PN-EN 54-5 – czujki ciepła, klasy", "kind": "norma"}], "364": [{"ref": "§ 218 ust. 1 WT – dach budynku niższego przy ścianie z otworami budynku wyższego", "kind": "akt", "act": "wt", "label": "§ 218", "text": "§ 218. 1. Przekrycie dachu budynku niższego, usytuowanego bliżej niż 8 m lub przyległego do ściany z otworami budynku wyższego, z wyjątkiem przypadków wymienionych w § 273 ust. 1, w pasie o szerokości 8 m od tej ściany powinno być nierozprzestrzeniające ognia oraz w pasie tym: 1) konstrukcja dachu powinna mieć klasę odporności ogniowej co najmniej R 30; 2) przekrycie dachu powinno mieć klasę odporności ogniowej co najmniej R E 30."}, {"ref": "§ 218 ust. 4 WT – wyloty kanałów dopuszczone w pasie 8 m", "kind": "akt", "act": "wt", "label": "§ 218", "text": "4. Dopuszcza się sytuowanie wylotów kanałów wentylacyjnych i spalinowych od urządzeń gazowych oraz rur wentylujących piony kanalizacyjne w części połaci dachu lub stropodachu budynku niższego, o której mowa w ust. 1."}], "365": [{"ref": "§ 179 ust. 2 WT – liczba i łączna pojemność zbiorników naziemnych w grupie", "kind": "akt", "act": "wt", "label": "§ 179", "text": "2. Liczba zbiorników naziemnych w grupie nie powinna przekraczać 6 sztuk, a ich łączna pojemność 100 m3. Odległość pomiędzy grupami zbiorników naziemnych powinna wynosić: 1) 7,5 m – w przypadku, gdy łączna pojemność zbiorników w grupie nie przekracza 30 m3; 2) 15 m – w przypadku, gdy łączna pojemność zbiorników w grupie przekracza 30 m3."}], "367": [{"ref": "PN-B-02857:2017 – przeciwpożarowe zbiorniki wodne", "kind": "norma"}], "368": [{"ref": "§ 2 RPB – definicja materiałów niebezpiecznych pożarowo", "kind": "akt", "act": "rpb", "label": "§ 2", "text": "§ 2. 1. Ilekroć w rozporządzeniu jest mowa o: 1) materiałach niebezpiecznych pożarowo ‒ należy przez to rozumieć: a) gazy palne, b) ciecze palne o temperaturze zapłonu poniżej 328,15 K (55ºC), c) materiały wytwarzające w zetknięciu z wodą gazy palne, d) materiały zapalające się samorzutnie na powietrzu, e) materiały wybuchowe i wyroby pirotechniczne, f) materiały ulegające samorzutnemu rozkładowi lub polimeryzacji, g) materiały mające skłonności do samozapalenia, h) materiały inne niż wymienione w lit. a‒g, jeśli sposób ich składowania, przetwarzania lub innego wykorzystania może spowodować powstanie pożaru; 2) pasie przeciwpożarowym ‒ należy przez to rozumieć system drzewostanów różnej szerokości poddanych specjalnym zabiegom gospodarczym i porządkowym lub powierzchni wylesionych i oczyszczonych do warstwy mineralnej; […]"}], "369": [{"ref": "PN-EN 12101-6 – systemy różnicowania ciśnień", "kind": "norma"}], "370": [{"ref": "§ 228 ust. 1 WT – dopuszczalne powierzchnie stref pożarowych PM", "kind": "akt", "act": "wt", "label": "§ 228", "text": "§ 228. 1. Dopuszczalne powierzchnie stref pożarowych PM, z wyjątkiem garaży, określa poniższa tabela: Rodzaj stref pożarowych Gęstość obciążenia ogniowego Q [MJ/m2] Dopuszczalna powierzchnia strefy pożarowej w m2 w budynku o jednej kondygnacji nadziemnej (bez ograniczenia wysokości) w budynku wielokondygnacyjnym niskim i średniowysokim (N) i (SW) wysokim i wysokościowym (W) i (WW) 1 2 3 4 5 Strefy pożarowe z pomieszczeniem zagrożonym wybuchem Q > 4000 2000 < Q ≤ 4000 1000 < Q ≤ 2000 500 < Q ≤ 1000 Q ≤ 500 1000 2000 4000 6000 8000 * * 1000 2000 3000 * * * 500 1000 Strefy pożarowe pozostałe Q > 4000 2000 < Q ≤ 4000 1000 < Q ≤ 2000 500 < Q ≤ 1000 Q ≤ 500 2000 4000 8000 15 000 20 000 1000 2000 4000 8000 10 000 * * 1000 2500 5000 * Nie dopuszcza się takich przypadków."}, {"ref": "§ 212 ust. 4 WT – klasy odporności pożarowej budynków PM", "kind": "akt", "act": "wt", "label": "§ 212", "text": "4. Wymaganą klasę odporności pożarowej dla budynku PM oraz IN, z zastrzeżeniem § 282, określa poniższa tabela: Maksymalna gęstość obciążenia ogniowego strefy pożarowej w budynku Q [MJ/m2] Budynek o jednej kondygnacji nadziemnej (bez ograniczenia wysokości) Budynek wielokondygnacyjny niski średniowysoki wysoki wysokościowy (N) (SW) (W) (WW) 1 2 3 4 5 6 Q ≤ 500 „E” „D” „C” „B” „B” 500 < Q ≤ 1000 „D” „D” „C” „B” „B” 1000 < Q ≤ 2000 „C” „C” „C” „B” „B” 2000 < Q ≤ 4000 „B” „B” „B” * * Q > 4000 „A” „A” „A” * * * – Zgodnie z § 228 ust. 1 nie mogą występować takie budynki."}], "371": [{"ref": "§ 6, § 8 RW – zapas wody do zewnętrznego gaszenia pożaru", "kind": "akt", "act": "rw", "label": "§ 6", "text": "§ 6. 1. Wodę dla obiektów budowlanych produkcyjnych i magazynowych, w ilości wymaganej do celów przeciwpożarowych do zewnętrznego gaszenia pożaru, należy zapewnić z urządzeń dostarczających ją do celów bytowo-gospodarczych i technologicznych lub z innych zasobów wody służących do tego celu. 2. W przypadku gdy w obiektach budowlanych produkcyjnych i magazynowych urządzenia i zasoby wody, o których mowa w ust. 1, nie zapewniają wymaganej ilości do celów przeciwpożarowych do zewnętrznego gaszenia pożaru, wykorzystuje się urządzenia służące do dostarczania wody do jednostek osadniczych lub uzupełniające źródła wody, o których mowa w § 4 ust. 5. 3. […]"}], "372": [{"ref": "§ 237 ust. 1 pkt 3 WT – przejście 100 m w jednokondygnacyjnym budynku PM", "kind": "akt", "act": "wt", "label": "§ 237", "text": "§ 237. 1. W pomieszczeniach, od najdalszego miejsca, w którym może przebywać człowiek, do wyjścia ewakuacyjnego na drogę ewakuacyjną lub do innej strefy pożarowej albo na zewnątrz budynku, powinno być zapewnione przejście, zwane dalej „przejściem ewakuacyjnym”, o długości nieprzekraczającej: 1) w strefach pożarowych ZL – 40 m; 2) w strefach pożarowych PM o gęstości obciążenia ogniowego przekraczającej 500 MJ/m2 w budynku o więcej niż jednej kondygnacji nadziemnej – 75 m; 3) w strefach pożarowych PM, o obciążeniu ogniowym nieprzekraczającym 500 MJ/m2, w budynku o więcej niż jednej kondygnacji nadziemnej oraz w strefach pożarowych PM w budynku o jednej kondygnacji nadziemnej bez względu na wielkość obciążenia ogniowego – 100 m."}, {"ref": "§ 237 ust. 4 WT – ograniczenie do 80% przy nieokreślonym zagospodarowaniu", "kind": "akt", "act": "wt", "label": "§ 237", "text": "4. Jeżeli z przewidywanego przeznaczenia pomieszczenia nie wynika jednoznacznie sposób jego zagospodarowania, projektowa długość przejścia ewakuacyjnego nie może być większa niż 80% długości określonej w ust. 1 i 2."}, {"ref": "§ 237 ust. 5–7 WT – powiększenia i ich sumowanie", "kind": "akt", "act": "wt", "label": "§ 237", "text": "5. W pomieszczeniach o wysokości przekraczającej 5 m długość przejść, o których mowa w ust. 1 i 2, może być powiększona o 25%."}], "373": [{"ref": "§ 256 ust. 3 i 4 WT – długości dojść ewakuacyjnych", "kind": "akt", "act": "wt", "label": "§ 256", "text": "3. Dopuszczalne długości dojść ewakuacyjnych w strefach pożarowych określa poniższa tabela: Rodzaj strefy pożarowej Długość dojścia w m przy jednym dojściu przy co najmniej 2 dojściach1) 1 2 3 Z pomieszczeniem zagrożonym wybuchem 10 40 PM o gęstości obciążenia ogniowego Q > 500 MJ/m2 bez pomieszczenia zagrożonego wybuchem 302) 60 PM o gęstości obciążenia ogniowego Q ≤ 500 MJ/m2 bez pomieszczenia zagrożonego wybuchem 602) 100 ZL I, II i V 10 40 ZL III 302) 60 ZL IV 602) 100 1) Dla dojścia najkrótszego, przy czym dopuszcza się dla drugiego dojścia długość większą o 100% od najkrótszego. Dojścia te nie mogą się pokrywać ani krzyżować, przy czym dopuszcza się ich wspólny początkowy przebieg na długości nie większej niż 2 m. 2) W tym nie więcej niż 20 m na poziomej drodze ewakuacyjnej."}], "374": [{"ref": "PN-EN 81-72:2020 – dźwigi dla straży pożarnej", "kind": "norma"}], "375": [{"ref": "§ 212 ust. 5 WT – doliczanie części podziemnej zaliczonej do ZL", "kind": "akt", "act": "wt", "label": "§ 212", "text": "5. Jeżeli część podziemna budynku jest zaliczona do ZL, klasę odporności pożarowej budynku ustala się, przyjmując jako liczbę jego kondygnacji lub jego wysokość odpowiednio: sumę kondygnacji lub wysokości części podziemnej i nadziemnej, przy czym do tego ustalenia nie bierze się pod uwagę tych części podziemnych budynku, które są oddzielone elementami oddzielenia przeciwpożarowego o klasie odporności ogniowej co najmniej R E I 120, zgodnie z oznaczeniem pod tabelą w § 216 ust. 1, i mają bezpośrednie wyjścia na zewnątrz."}, {"ref": "§ 212 ust. 2 WT – klasa B dla średniowysokiego budynku ZL III", "kind": "akt", "act": "wt", "label": "§ 212", "text": "2. Wymaganą klasę odporności pożarowej dla budynku, zaliczonego do jednej kategorii ZL, określa poniższa tabela: Budynek ZL I ZL II ZL III ZL IV ZL V 1 2 3 4 5 6 niski (N) „B” „B” „C” „D” „C” średniowysoki (SW) „B” „B” „B” „C” „B” wysoki (W) „B” „B” „B” „B” „B” wysokościowy (WW) „A” „A” „A” „B” „A”"}], "376": [{"ref": "§ 278 ust. 1 i 2 WT – wyjścia i przejścia w garażach", "kind": "akt", "act": "wt", "label": "§ 278", "text": "§ 278. 1. Ze strefy pożarowej garażu, która posiada więcej niż 25 stanowisk postojowych i nie jest wyposażona w instalację wentylacji oddymiającej lub ma powierzchnię przekraczającą 1500 m2, należy zapewnić co najmniej dwa wyjścia ewakuacyjne, przy czym jednym z tych wyjść może być wjazd lub wyjazd."}], "377": [{"ref": "§ 157 ust. 3 WT – instalacja gazowa w budynku wyższym niż 35 m", "kind": "akt", "act": "wt", "label": "§ 157", "text": "3. Instalacja gazowa w budynku o wysokości większej niż 35 m ponad poziomem terenu może być doprowadzona tylko do pomieszczeń technicznych, w których są zainstalowane urządzenia gazowe, usytuowanych w piwnicy lub na najniższej kondygnacji nadziemnej, a także na najwyższej kondygnacji budynku lub nad tą kondygnacją, pod warunkiem zastosowania urządzeń stabilizujących ciśnienie gazu."}, {"ref": "§ 157 ust. 4 WT – stanowisko komendanta wojewódzkiego PSP powyżej 25 m", "kind": "akt", "act": "wt", "label": "§ 157", "text": "4. Zastosowanie instalacji gazowej w budynkach o wysokości ponad 25 m wymaga uzyskania pozytywnej opinii wydanej przez właściwego komendanta wojewódzkiego Państwowej Straży Pożarnej."}], "378": [{"ref": "PN-EN 12845+A1:2020 – ochrona przestrzeni ukrytych", "kind": "norma"}], "379": [{"ref": "§ 55 ust. 1 pkt 1 rozp. w sprawie baz i stacji paliw płynnych – lokalizacja pompowni przeciwpożarowych", "kind": "akt", "act": "paliwa", "label": "§ 55", "text": "§ 55. 1. Pompownie przeciwpożarowe: 1) należy lokalizować w odległości nie mniejszej niż 25 m od osi obwałowania zbiornika lub jego ściany osłonowej; 2) mogą być wbudowane w inny obiekt budowlany, pod warunkiem zabezpieczenia tego obiektu elementami oddzieleń przeciwpożarowych o klasie odporności ogniowej co najmniej REI 120."}], "380": [{"ref": "§ 216 ust. 1 WT – odnośnik 3 do tabeli (kolumna 4 – strop)", "kind": "akt", "act": "wt", "label": "§ 216", "text": "§ 216. 1. Elementy budynku, odpowiednio do jego klasy odporności pożarowej, powinny spełniać, z zastrzeżeniem § 213 oraz § 237 ust. 9, co najmniej wymagania określone w poniższej tabeli: Klasa odporności pożarowej budynku Klasa odporności ogniowej elementów budynku5) *) główna konstrukcja nośna konstrukcja dachu strop1) ściana zewnętrzna1), 2) ściana wewnętrzna1) przekrycie dachu3) 1 2 3 4 5 6 7 „A” R 240 R 30 R E I 120 E I 120 (o↔i) E I 60 R E 30 „B” R 120 R 30 R E I 60 E I 60 (o↔i) E I 304) R E 30 „C” R 60 R 15 R E I 60 E I 30 (o↔i) E I 154) R E 15 „D” R 30 (–) R E I 30 E I 30 (o↔i) (–) (–) „E” (–) (–) (–) (–) (–) (–) *) Z zastrzeżeniem § 219 ust. 1. […]"}], "382": [{"ref": "PN-EN 12845+A1:2020 – tryskacze w poziomach pośrednich regałów i stanowiska kontrolno-alarmowe", "kind": "norma"}], "383": [{"ref": "§ 220 ust. 3 WT – przegrody zewnętrzne kotłowni gazowej ponad dachem", "kind": "akt", "act": "wt", "label": "§ 220", "text": "3. Nie stawia się wymagań w zakresie klasy odporności ogniowej dla przegród zewnętrznych kotłowni z kotłami na paliwo gazowe, zlokalizowanej ponad dachem budynku, przy zachowaniu warunku, iż przegrody te powinny być wykonane z materiałów niepalnych."}], "384": [{"ref": "§ 277 WT – oddymianie garaży", "kind": "akt", "act": "wt", "label": "§ 277", "text": "§ 277. […] 3. W garażu zamkniętym obejmującym więcej niż dwie kondygnacje podziemne lub znajdującym się poniżej drugiej kondygnacji podziemnej należy stosować stałe samoczynne urządzenia gaśnicze wodne. Wymagania nie stosuje się do strefy pożarowej garażu, która posiada bezpośredni wjazd lub wyjazd z budynku. 4. W strefie pożarowej garażu zamkniętego należy stosować instalację wentylacji oddymiającej uruchamianą za pomocą systemu wykrywania dymu, w przypadku gdy ta strefa nie posiada bezpośredniego wjazdu lub wyjazdu z budynku lub gdy jej powierzchnia przekracza 1500 m2. 5. W przypadku zastosowania rozwiązania, o którym mowa w ust. 2 pkt 1, klasa odporności ogniowej przewodów wentylacji oddymiającej powinna odpowiadać wymaganiom określonym w § 270 ust. 2 – jedynie z uwagi na kryterium szczelności ogniowej (E)."}], "385": [{"ref": "§ 19 ust. 3 pkt 2 RPB – hydranty 52 w strefie PM z pomieszczeniem o dużej gęstości obciążenia ogniowego", "kind": "akt", "act": "rpb", "label": "§ 19", "text": "3. Hydranty 52 muszą być stosowane: 1) w strefie pożarowej produkcyjnej i magazynowej o gęstości obciążenia ogniowego przekraczającej 500 MJ/m2 i powierzchni przekraczającej 200 m2; 2) w strefie pożarowej produkcyjnej i magazynowej o gęstości obciążenia ogniowego nieprzekraczającej 500 MJ/m2, w której znajduje się pomieszczenie o powierzchni przekraczającej 100 m2 i gęstości obciążenia ogniowego przekraczającej 1 000 MJ/m2; 3) przy wejściu do pomieszczeń magazynowych lub technicznych o powierzchni przekraczającej 200 m2 i gęstości obciążenia ogniowego przekraczającej 500 MJ/m2, usytuowanych w strefie pożarowej zakwalifikowanej do kategorii zagrożenia ludzi ZL I, ZL II, ZL III lub ZL V, znajdującej się w budynku niskim albo średniowysokim."}], "386": [{"ref": "PN-EN 12101-1:2007 – kurtyny dymowe", "kind": "norma"}], "387": [{"ref": "§ 12 RW – wymóg drogi pożarowej dla ZL V", "kind": "akt", "act": "rw", "label": "§ 12", "text": "§ 12. […] 4) budynku zawierającego strefę pożarową produkcyjną lub magazynową o gęstości obciążenia ogniowego poniżej 500 MJ/m2 o powierzchni przekraczającej 20 000 m2; 5) budynku niskiego: a) zawierającego strefę pożarową zakwalifikowaną do kategorii zagrożenia ludzi ZL III o powierzchni przekraczającej 1 000 m2, obejmującą kondygnację nadziemną inną niż pierwsza, lub b) zawierającego strefę pożarową zakwalifikowaną do kategorii zagrożenia ludzi ZL V i mającego ponad 50 miejsc noclegowych; www.rcl.gov.pl Dziennik Ustaw Nr 124 — 9068 — Poz. 1030 6) obiektu budowlanego innego niż budynek, przeznaczonego do użyteczności publicznej lub zamieszkania zbiorowego, w którym przewiduje się możliwość jednoczesnego przebywania w strefie pożarowej ponad 50 osób; 7) stanowiska czerpania wody do celów przeciwpożarowych. 2. […]"}], "388": [{"ref": "PN-EN 12845+A1:2020 – czas działania wg klasy zagrożenia", "kind": "norma"}], "389": [{"ref": "§ 181 ust. 3 pkt 1 lit. a WT – widownie sal widowiskowych", "kind": "akt", "act": "wt", "label": "§ 181", "text": "3. Awaryjne oświetlenie ewakuacyjne należy stosować: 1) w pomieszczeniach: a) widowni kin, teatrów i filharmonii oraz innych sal widowiskowych, b) audytoriów, sal konferencyjnych, czytelni, lokali rozrywkowych oraz sal sportowych, przeznaczonych dla ponad 200 osób, c) wystawowych w muzeach, d) o powierzchni netto ponad 1000 m2 w garażach oświetlonych wyłącznie światłem sztucznym, e) o powierzchni netto ponad 2000 m2 w budynkach użyteczności publicznej, budynkach zamieszkania zbiorowego oraz w budynkach produkcyjnych i magazynowych; 2) na drogach ewakuacyjnych: a) z pomieszczeń wymienionych w pkt 1, b) oświetlonych wyłącznie światłem sztucznym, c) w szpitalach i innych budynkach przeznaczonych przede wszystkim do użytku osób o ograniczonej zdolności poruszania się, d) w wysokich i wysokościowych budynkach użyteczności publicznej i zamieszkania zbiorowego."}, {"ref": "§ 181 ust. 3 pkt 1 lit. b i e WT – progi 200 osób i 2000 m2", "kind": "akt", "act": "wt", "label": "§ 181", "text": "3. Awaryjne oświetlenie ewakuacyjne należy stosować: 1) w pomieszczeniach: a) widowni kin, teatrów i filharmonii oraz innych sal widowiskowych, b) audytoriów, sal konferencyjnych, czytelni, lokali rozrywkowych oraz sal sportowych, przeznaczonych dla ponad 200 osób, c) wystawowych w muzeach, d) o powierzchni netto ponad 1000 m2 w garażach oświetlonych wyłącznie światłem sztucznym, e) o powierzchni netto ponad 2000 m2 w budynkach użyteczności publicznej, budynkach zamieszkania zbiorowego oraz w budynkach produkcyjnych i magazynowych; 2) na drogach ewakuacyjnych: a) z pomieszczeń wymienionych w pkt 1, b) oświetlonych wyłącznie światłem sztucznym, c) w szpitalach i innych budynkach przeznaczonych przede wszystkim do użytku osób o ograniczonej zdolności poruszania się, d) w wysokich i wysokościowych budynkach użyteczności publicznej i zamieszkania zbiorowego."}], "390": [{"ref": "§ 28 ust. 1 RPB – obiekty wymagające systemu sygnalizacji pożarowej", "kind": "akt", "act": "rpb", "label": "§ 28", "text": "§ 28. 1. Stosowanie systemu sygnalizacji pożarowej, obejmującego urządzenia sygnalizacyjno-alarmowe, służące do samoczynnego wykrywania i przekazywania informacji o pożarze, a także urządzenia odbiorcze alarmów pożarowych i urządzenia odbiorcze sygnałów uszkodzeniowych, jest wymagane w: 1) budynkach handlowych lub wystawowych: a) jednokondygnacyjnych o powierzchni strefy pożarowej powyżej 5000 m2, b) wielokondygnacyjnych o powierzchni strefy pożarowej powyżej 2500 m2; 2) teatrach o liczbie miejsc powyżej 300; 3) kinach o liczbie miejsc powyżej 600; 4) budynkach o liczbie miejsc służących celom gastronomicznym powyżej 300; 5) salach widowiskowych i sportowych o liczbie miejsc powyżej 1500; 6) szpitalach, z wyjątkiem psychiatrycznych, oraz w sanatoriach ‒ o liczbie łóżek powyżej 200 w budynku; 7) szpitalach psychiatrycznych o liczbie łóżek powyżej 100 w budynku; […]"}, {"ref": "§ 28 ust. 2 RPB – wyłączenie dla terenów zamkniętych służących obronności państwa", "kind": "akt", "act": "rpb", "label": "§ 28", "text": "2. Wymagania, o których mowa w ust. 1 pkt 4 i 11, nie dotyczą budynków, które są zlokalizowane na terenach zamkniętych służących obronności państwa, oraz budynków zakwaterowania osadzonych, które zlokalizowane są na terenach zakładów karnych i aresztów śledczych."}], "391": [{"ref": "§ 12 RW – wymóg drogi pożarowej", "kind": "akt", "act": "rw", "label": "§ 12", "text": "§ 12. […] 4) budynku zawierającego strefę pożarową produkcyjną lub magazynową o gęstości obciążenia ogniowego poniżej 500 MJ/m2 o powierzchni przekraczającej 20 000 m2; 5) budynku niskiego: a) zawierającego strefę pożarową zakwalifikowaną do kategorii zagrożenia ludzi ZL III o powierzchni przekraczającej 1 000 m2, obejmującą kondygnację nadziemną inną niż pierwsza, lub b) zawierającego strefę pożarową zakwalifikowaną do kategorii zagrożenia ludzi ZL V i mającego ponad 50 miejsc noclegowych; www.rcl.gov.pl Dziennik Ustaw Nr 124 — 9068 — Poz. 1030 6) obiektu budowlanego innego niż budynek, przeznaczonego do użyteczności publicznej lub zamieszkania zbiorowego, w którym przewiduje się możliwość jednoczesnego przebywania w strefie pożarowej ponad 50 osób; 7) stanowiska czerpania wody do celów przeciwpożarowych. 2. […]"}], "392": [{"ref": "§ 12 ust. 6 pkt 1 RW – okna dla ekip ratowniczych w klatkach schodowych", "kind": "akt", "act": "rw", "label": "§ 12", "text": "6. Wymagań, o których mowa w ust. 2 i 3, nie stosuje się, gdy są spełnione łącznie następujące warunki: 1) w budynku o więcej niż 3 kondygnacjach nadziemnych, na każdej kondygnacji powyżej trzeciej nadziemnej, do wysokości 25 m, każda klatka schodowa służąca ewakuacji ma okno dla ekip ratowniczych, umożliwiające dostęp z zewnątrz przez otwór o dolnej krawędzi położonej nie wyżej niż 90 cm nad poziomem posadzki oraz o wysokości i szerokości odpowiednio co najmniej 110 cm i 60 cm, lub ma zapewnione dotarcie do takiego okna poziomą drogą ewakuacyjną o długości nieprzekraczającej 50 m; […]"}], "394": [{"ref": "PN-EN 1838:2013 – czas osiągania natężenia", "kind": "norma"}], "395": [{"ref": "§ 4 rozp. w sprawie uzgadniania projektu pod względem ochrony ppoż.", "kind": "akt", "act": "uzgadnianie", "label": "§ 4", "text": "§ 4. […] Podstawę uzgodnienia stanowią niezbędne do stwierdzenia zgodności projektu z wymaganiami ochrony przeciwpożarowej dane dotyczące warunków ochrony przeciwpożarowej obiektu budowlanego, zależne od jego przeznaczenia, sposobu użytkowania, prowadzonego procesu technologicznego, sposobu magazynowania lub składowania, warunków technicznych oraz występujących w nim zagrożeń pożarowych, obejmujące: 1) w przypadku projektu zagospodarowania działki lub terenu, w szczególności: a) informacje o powierzchni zabudowy, wysokości i liczbie kondygnacji, b) informacje o klasyfikacji pożarowej z uwagi na przeznaczenie i sposób użytkowania, c) informacje o klasie odporności pożarowej oraz odporności ogniowej i stopniu rozprzestrzeniania ognia przez ściany zewnętrzne i dachy, d) informacje o występowaniu zagrożenia wybuchem, w tym informacje dotyczące pomieszczeń zagrożonych wybuchem oraz stref zagrożenia wybuchem w przestrzeni zewnętrznej, e) informacje o usytuowaniu z uwagi na bezpieczeństwo pożarowe, w tym informacje o odległościach od sąsiadujących obiektów budowlanych, działek lub terenów oraz parametrach wpływających na odległości dopuszczalne, f) informacje o przygotowaniu obiektu budowlanego i terenu do prowadzenia działań ratowniczych, w tym informacje o: – drogach pożarowych oraz dojściach dla ekip ratowniczych, – zaopatrzeniu w wodę do zewnętrznego gaszenia pożaru, w tym o wymaganej ilości wody do celów przeciwpożarowych, urządzeniach i innych rozwiązaniach w zakresie przeciwpożarowego zaopatrzenia w wodę, usytuowaniu źródeł wody do celów przeciwpożarowych, hydrantów zewnętrznych lub innych punktów poboru wody oraz stanowisk czerpania wody wraz z dojazdami dla pojazdów pożarniczych, g) informacje o rozwiązaniach zamiennych w stosunku do wymagań ochrony przeciwpożarowej, zastosowanych na podstawie zgody, o której mowa w art. 6c pkt 1 lub 2 ustawy z dnia 24 sierpnia 1991 r. o ochronie przeciwpożarowej, w zakresie rozwiązań objętych projektem zagospodarowania działki lub terenu; […]"}], "396": [{"ref": "PN-EN 12101-2:2017 – urządzenia do grawitacyjnego odprowadzania dymu", "kind": "norma"}], "397": [{"ref": "§ 3–5 RW – wymagane zaopatrzenie w wodę", "kind": "akt", "act": "rw", "label": "§ 3", "text": "§ 3. 1. Zapewnienie przeciwpożarowego zaopatrzenia w wodę do zewnętrznego gaszenia pożaru jest wymagane dla: 1) jednostek osadniczych o liczbie mieszkańców przekraczającej 100 osób, niestanowiących zabudowy kolonijnej, a także znajdujących się w ich granicach: budynków użyteczności publicznej i zamieszkania zbiorowego oraz obiektów budowlanych produkcyjnych i magazynowych; 2) budynków użyteczności publicznej i zamieszkania zbiorowego oraz obiektów budowlanych produkcyjnych i magazynowych, znajdujących się poza granicami jednostek osadniczych wymienionych w pkt 1, o kubaturze brutto przekraczającej 2 500 m3 lub o powierzchni przekraczającej 500 m2, z wyjątkiem stacji paliw płynnych ze zbiornikami o łącznej pojemności do 200 m3 i stacji gazu płynnego; […]"}], "398": [{"ref": "PKN-CEN/TS 54-14:2020 – promienie działania czujek", "kind": "norma"}], "399": [{"ref": "dyrektywa ATEX – kategorie urządzeń i strefy gazowe", "kind": "ue"}], "400": [{"ref": "PN-B-02857:2017-04 – przewody ssawne zbiornika", "kind": "norma"}], "401": [{"ref": "§ 245, § 246 WT – obudowa i oddzielenie klatek schodowych", "kind": "akt", "act": "wt", "label": "§ 245", "text": "§ 245. Klatki schodowe przeznaczone do ewakuacji ze strefy pożarowej: 1) ZL II w budynku niskim (N), 2) ZL I, ZL II, ZL III lub ZL V w budynku średniowysokim (SW), 3) PM o gęstości obciążenia ogniowego powyżej 500 MJ/m2 lub zawierającej pomieszczenie zagrożone wybuchem w budynku niskim (N) bądź średniowysokim (SW) – powinny być obudowane i zamykane drzwiami dymoszczelnymi oraz wyposażone w urządzenia zapobiegające zadymieniu lub służące do usuwania dymu, uruchamiane samoczynnie za pomocą systemu wykrywania dymu."}], "402": [{"ref": "PN-EN 1363-2:2001 – badania odporności ogniowej, procedury dodatkowe", "kind": "norma"}], "403": [{"ref": "§ 179 WT / rozp. dot. zbiorników gazu płynnego", "kind": "akt", "act": "wt", "label": "§ 179", "text": "§ 179. […] 2) powyżej 10 m3 – nie mniej niż połowa odległości określonej w tabeli w ust. 4 w kolumnach 2 i 3. 6. Odległość zbiorników z gazem płynnym od granicy działki budowlanej z tymi zbiornikami powinna być nie mniejsza niż połowa odległości określonej w tabeli w ust. 4 w kolumnach 2 i 3, przy zachowaniu wymaganej odległości od budynku danego rodzaju. 7. Odległości określone w tabeli w ust. 4 w kolumnie 2 mogą być zmniejszone do 50% w przypadku zastosowania wolno stojącej ściany oddzielenia przeciwpożarowego o klasie odporności ogniowej co najmniej R E I 120, usytuowanej pomiędzy zbiornikiem z gazem płynnym a budynkiem. Wymiary wolno stojącej ściany oraz jej odległość od zbiornika powinny być tak dobrane, aby osłonić zbiornik od tej części budynku, która znajduje się w odległości mniejszej niż określona w tabeli w ust. 4 w kolumnie 2 od dowolnego punktu zbiornika. 8. […]"}], "404": [{"ref": "PN-EN 12101-13:2022 rozdział 1 – zakres normy (budynki do 60 m)", "kind": "norma"}, {"ref": "PN-EN 12101-13:2022 załącznik D – projektowanie SRC w budynkach wyższych niż 60 m", "kind": "norma"}], "405": [{"ref": "§ 91 rozp. MG z 26.04.2013 – wentylacja i wykrywanie metanu w pomieszczeniach sprężarek gazu", "kind": "akt", "act": "gaz-sieci", "label": "§ 91", "text": "§ 91. 1. Pomieszczenia, w których znajdują się sprężarki gazu ziemnego, powinny być wyposażone w systemy wentylacji naturalnej i wentylacji mechanicznej awaryjnej, zapewniającej wymianę powietrza w ilości uniemożliwiającej przekroczenie dolnej granicy wybuchowości, o której mowa w ust. 2 pkt 1. System awaryjnej wentylacji mechanicznej powinien być sprzężony z automatycznym systemem wykrywania metanu. 2. Automatyczny systemem wykrywania metanu powinien, przy przekroczeniu: 1) \u000710% dolnej granicy wybuchowości – włączyć alarm i awaryjną wentylację mechaniczną; 2) \u000740% dolnej granicy wybuchowości – wyłączyć napęd sprężarki gazu ziemnego, odciąć i odgazować układy technologiczne."}], "406": [{"ref": "§ 211 ust. 2 WT – wyłączenia dla budynków na terenie zakładów karnych", "kind": "akt", "act": "wt", "label": "§ 211", "text": "2. Przepisów § 236 ust. 4 oraz § 239 ust. 2 pkt 3 i 4 nie stosuje się do budynków zlokalizowanych na terenie zakładów karnych i aresztów śledczych."}, {"ref": "§ 239 ust. 2 WT – kierunek otwierania drzwi ewakuacyjnych", "kind": "akt", "act": "wt", "label": "§ 239", "text": "2. Drzwi stanowiące wyjście ewakuacyjne powinny otwierać się na zewnątrz pomieszczeń: 1) zagrożonych wybuchem; 2) do których jest możliwe niespodziewane przedostanie się mieszanin wybuchowych lub substancji trujących, duszących bądź innych, mogących utrudnić ewakuację; 3) przeznaczonych do jednoczesnego przebywania ponad 50 osób; 4) przeznaczonych dla ponad 6 osób o ograniczonej zdolności poruszania się."}], "407": [{"ref": "§ 8 ust. 2 rozp. MRiRW z 13.01.2023 – odległości silosów o pojemności ponad 100 ton", "kind": "akt", "act": "rolnicze", "label": "§ 8", "text": "2. Odległość silosów na zboże i pasze o pojemności większej niż 100 ton powinna wynosić co najmniej: 1) 10 m od pomieszczeń przeznaczonych na pobyt ludzi oraz od budynków inwentarskich, jednak nie mniej niż 15 m od okien i drzwi w tych pomieszczeniach oraz budynkach; 2) 8 m od budynków innych niż budynki inwentarskie; 3) 15 m od instalacji służących do otrzymywania biogazu rolniczego; 4) 15 m od składu węgla i koksu; 5) 4 m od granicy działki sąsiedniej."}], "408": [{"ref": "§ 232 ust. 6 WT – przeszklenia w ścianie oddzielenia przeciwpożarowego", "kind": "akt", "act": "wt", "label": "§ 232", "text": "6. W ścianie oddzielenia przeciwpożarowego dopuszcza się wypełnienie otworów materiałem przepuszczającym światło, takim jak luksfery, cegła szklana lub inne przeszklenie, jeżeli powierzchnia wypełnionych otworów nie przekracza 10% powierzchni ściany, przy czym klasa odporności ogniowej wypełnień nie powinna być niższa niż: Wymagana klasa odporności ogniowej ściany oddzielenia przeciwpożarowego Klasa odporności ogniowej wypełnienia otworu w ścianie będącej obudową drogi ewakuacyjnej innej 1 2 3 R E I 240 E I 120 E 120 R E I 120 E I 60 E 60 R E I 60 E I 30 E 30"}, {"ref": "§ 232 ust. 4 WT – klasa REI 120 dla budynku klasy „C”", "kind": "akt", "act": "wt", "label": "§ 232", "text": "4. Wymaganą klasę odporności ogniowej elementów oddzielenia przeciwpożarowego oraz zamknięć znajdujących się w nich otworów określa poniższa tabela: Klasa odporności pożarowej budynku Klasa odporności ogniowej elementów oddzielenia przeciwpożarowego drzwi przeciwpożarowych lub innych zamknięć przeciwpożarowych drzwi z przedsionka przeciwpożarowego ścian i stropów, z wyjątkiem stropów w ZL stropów w ZL na korytarz i do pomieszczenia na klatkę schodową*) 1 2 3 4 5 6 „A” R E I 240 R E I 120 E I 120 E I 60 E 60 „B” i „C” R E I 120 R E I 60 E I 60 E I 30 E 30 „D” i „E” R E I 60 R E I 30 E I 30 E I 15 E 15 *) Dopuszcza się osadzenie tych drzwi w ścianie o klasie odporności ogniowej, określonej dla drzwi w kol. 6, znajdującej się między przedsionkiem a klatką schodową."}], "409": [{"ref": "§ 37 ust. 1 rozp. MSWiA z 19.02.2020 – urządzenia oddymiające w strefie z odpadami stałymi", "kind": "akt", "act": "odpady-rozp", "label": "§ 37", "text": "§ 37. 1. Strefę pożarową z odpadami stałymi o gęstości obciążenia ogniowego przekraczającej 1000 MJ/m2 i powierzch ni przekraczającej 1000 m2, która znajduje się w budynku, wyposaża się w samoczynne urządzenia oddymiające."}, {"ref": "§ 35 rozp. MSWiA z 19.02.2020 – stałe urządzenia gaśnicze w strefie z odpadami stałymi", "kind": "akt", "act": "odpady-rozp", "label": "§ 35", "text": "§ 35. 1. Strefę pożarową z odpadami stałymi o gęstości obciążenia ogniowego przekraczającej 2000 MJ/m2 i powierzch ni przekraczającej 2000 m2, która znajduje się w budynku, wyposaża się w stałe urządzenia gaśnicze wodne lub pianowe, uruchamiane automatycznie lub ręcznie – w przypadku zapewnienia stałej obsługi tych urządzeń lub posiadania zakładowej straży pożarnej. 2. Urządzenia gaśnicze, o których mowa w ust. 1, stosuje się do ochrony lokalnej obszarów magazynowania stałych odpadów palnych, jeżeli w strefie pożarowej z odpadami stałymi gęstość obciążenia ogniowego przekracza 4000 MJ/m2 na przynajmniej jednej dowolnie wybranej jednostce 500 m2 powierzchni magazynowania tych odpadów."}], "410": [{"ref": "§ 261 WT – liczba siedzeń w rzędzie i odstępy", "kind": "akt", "act": "wt", "label": "§ 261", "text": "§ 261. […] 2) szerokość przejść pomiędzy rzędami siedzeń nie mniejszą niż 0,45 m, przy czym odległość tę należy ustalać, biorąc pod uwagę odstęp między stałymi elementami siedzeń; 3) liczbę siedzeń w rzędzie nie większą niż 16 pomiędzy przejściami oraz 8 w rzędzie przyściennym, przy czym dopuszcza się zwiększenie liczby miejsc w rzędach odpowiednio do 40 i 20 pod warunkiem zwiększenia odstępu między rzędami siedzeń o 1 cm na każde dodatkowe siedzenie odpowiednio powyżej 16 lub 8; 4) szerokość przejść komunikacyjnych nie mniejszą niż 1,2 m przy liczbie osób do 150, a przy większej ich liczbie szerokość tę należy zwiększyć proporcjonalnie o 0,6 m na 100 osób; 5) rzędy siedzeń lub ławek trwale umocowane do podłogi albo siedzenia sztywno łączone ze sobą w rzędy oraz między rzędami."}], "411": [{"ref": "§ 221 ust. 1 WT – lekki dach nad pomieszczeniem zagrożonym wybuchem", "kind": "akt", "act": "wt", "label": "§ 221", "text": "§ 221. 1. Nad pomieszczeniem zagrożonym wybuchem należy stosować lekki dach, wykonany z materiałów co najmniej trudno zapalnych, o masie nieprzekraczającej 75 kg/m2 rzutu, licząc bez elementów konstrukcji nośnej dachu, takich jak podciągi, wiązary i belki."}, {"ref": "§ 221 ust. 2 WT – zwolnienie przy urządzeniach odciążających ponad 0,065 m2/m3", "kind": "akt", "act": "wt", "label": "§ 221", "text": "2. Przepis ust. 1 nie dotyczy pomieszczenia, w którym łączna powierzchnia urządzeń odciążających (przeciwwybuchowych), jak przepony, klapy oraz otwory oszklone szkłem zwykłym, jest większa niż 0,065 m2/m3 kubatury pomieszczenia."}], "413": [{"ref": "PN-EN 1992-1-2:2008 – Eurokod 2, warunki pożarowe", "kind": "norma"}], "414": [{"ref": "§ 39 ust. 4 pkt 5 RPB – studnia jako źródło wody do celów przeciwpożarowych w lasach", "kind": "akt", "act": "rpb", "label": "§ 39", "text": "§ 39. […] 5) studnia z pompą oraz z: a) hydrantem zewnętrznym lub b) innym punktem poboru wody z nasadą tłoczną typu 75 lub 110 – o wydajności nie mniejszej niż 10 dm3/s. 5.7) Zbiornikiem sztucznym jest pojemnik albo grupa pojemników połączonych przewodami o średnicy co najmniej 300 mm w sposób umożliwiający dostęp do wymaganego zapasu wody z każdego stanowiska czerpania wody, w które jest wyposażony zbiornik. 6.7) Źródła wody do celów przeciwpożarowych, o których mowa w ust. 4 pkt 1‒3 i 5, powinny być wyposażone w stanowiska czerpania wody z utwardzoną nawierzchnią o nośności nie mniejszej niż wymagana dla dojazdów pożarowych. 7.8) Stanowiska czerpania wody przy źródłach wody do celów przeciwpożarowych, o których mowa w ust. 4 pkt 1‒3, powinny umożliwiać pobieranie wody z głębokości nie większej niż 4 m, mierząc od lustra wody do poziomu stanowiska czerpania wody, z wykorzystaniem autopomp lub motopomp pożarniczych. 8.8) Stanowisko czerpania wody powinno mieć szerokość co najmniej 4 m i długość co najmniej 12 m oraz być wykonane w sposób umożliwiający wjazd i wyjazd, a także postój samochodu ratowniczo-gaśniczego o długości 12 m. […]"}], "415": [{"ref": "PN-EN 12845+A1:2020 – sekcje tandemowe", "kind": "norma"}], "416": [{"ref": "§ 19 RPB – hydranty wewnętrzne w garażach", "kind": "akt", "act": "rpb", "label": "§ 19", "text": "§ 19. […] 4) Dodany przez § 1 rozporządzenia Ministra Spraw Wewnętrznych i Administracji z dnia 11 stycznia 2019 r. zmieniającego rozporządzenie w sprawie ochrony przeciwpożarowej budynków, innych obiektów budowlanych i terenów (Dz. U. poz. 67), które weszło w życie z dniem 29 stycznia 2019 r. 2. Hydranty 33 muszą być stosowane w garażu: 1) jednokondygnacyjnym zamkniętym o więcej niż 10 stanowiskach postojowych; 2) wielokondygnacyjnym. 3. Hydranty 52 muszą być stosowane: 1) w strefie pożarowej produkcyjnej i magazynowej o gęstości obciążenia ogniowego przekraczającej 500 MJ/m2 i powierzchni przekraczającej 200 m2; 2) w strefie pożarowej produkcyjnej i magazynowej o gęstości obciążenia ogniowego nieprzekraczającej 500 MJ/m2, w której znajduje się pomieszczenie o powierzchni przekraczającej 100 m2 i gęstości obciążenia ogniowego przekraczającej 1 000 MJ/m2; […]"}], "417": [{"ref": "§ 216 ust. 5 WT – palna izolacja cieplna w ścianach zewnętrznych budynku ZL II", "kind": "akt", "act": "wt", "label": "§ 216", "text": "5. W ścianach zewnętrznych budynku ZL II dopuszcza się, z zastrzeżeniem ust. 8, zastosowanie izolacji cieplnej palnej, jeżeli osłaniająca ją od wewnątrz okładzina jest niepalna i ma klasę odporności ogniowej co najmniej: 1) w budynku klasy odporności pożarowej „B” – E I 60; 2) w budynku klasy odporności pożarowej „C” i „D” – E I 30."}], "418": [{"ref": "PN-B-02852:2001 – obliczanie gęstości obciążenia ogniowego", "kind": "norma"}], "419": [{"ref": "§ 216, § 219 WT – rozprzestrzenianie ognia przez elementy", "kind": "akt", "act": "wt", "label": "§ 216", "text": "§ 216. […] 4. 4) Dla ścian komór zsypu wymaga się klasy E I 60, a dla drzwi komór zsypu klasy E I 30. 5) Klasa odporności ogniowej dotyczy elementów wraz z uszczelnieniami złączy i dylatacjami. 2. Elementy budynku, o których mowa w ust. 1, powinny być nierozprzestrzeniające ognia, przy czym dopuszcza się zastosowanie słabo rozprzestrzeniających ogień: 1) elementów budynku o jednej kondygnacji nadziemnej ZL IV oraz PM, o maksymalnej gęstości obciążenia ogniowego strefy pożarowej do 500 MJ/m2; 2) ścian wewnętrznych i zewnętrznych oraz elementów konstrukcji dachu i jego przekrycia w budynku PM niskim o maksymalnej gęstości obciążenia ogniowego strefy pożarowej do 1000 MJ/m2; 3) ścian zewnętrznych w budynku niskim ZL IV. 3. […]"}], "420": [{"ref": "§ 5 ust. 1 pkt 3 rozp. MSWiA w sprawie uzgadniania projektu – kiedy opracowuje się scenariusz pożarowy", "kind": "norma"}, {"ref": "§ 28 ust. 1 pkt 17 RPB – SSP w garażach podziemnych", "kind": "akt", "act": "rpb", "label": "§ 28", "text": "§ 28. 1. Stosowanie systemu sygnalizacji pożarowej, obejmującego urządzenia sygnalizacyjno-alarmowe, służące do samoczynnego wykrywania i przekazywania informacji o pożarze, a także urządzenia odbiorcze alarmów pożarowych i urządzenia odbiorcze sygnałów uszkodzeniowych, jest wymagane w: 1) budynkach handlowych lub wystawowych: a) jednokondygnacyjnych o powierzchni strefy pożarowej powyżej 5000 m2, b) wielokondygnacyjnych o powierzchni strefy pożarowej powyżej 2500 m2; 2) teatrach o liczbie miejsc powyżej 300; 3) kinach o liczbie miejsc powyżej 600; 4) budynkach o liczbie miejsc służących celom gastronomicznym powyżej 300; 5) salach widowiskowych i sportowych o liczbie miejsc powyżej 1500; 6) szpitalach, z wyjątkiem psychiatrycznych, oraz w sanatoriach ‒ o liczbie łóżek powyżej 200 w budynku; 7) szpitalach psychiatrycznych o liczbie łóżek powyżej 100 w budynku; […]"}, {"ref": "§ 277 ust. 4 WT – wentylacja oddymiająca w garażu zamkniętym", "kind": "akt", "act": "wt", "label": "§ 277", "text": "4. W strefie pożarowej garażu zamkniętego należy stosować instalację wentylacji oddymiającej uruchamianą za pomocą systemu wykrywania dymu, w przypadku gdy ta strefa nie posiada bezpośredniego wjazdu lub wyjazdu z budynku lub gdy jej powierzchnia przekracza 1500 m2."}], "421": [{"ref": "§ 19 ust. 3 pkt 1 RPB – hydranty 52 w strefach PM", "kind": "akt", "act": "rpb", "label": "§ 19", "text": "3. Hydranty 52 muszą być stosowane: 1) w strefie pożarowej produkcyjnej i magazynowej o gęstości obciążenia ogniowego przekraczającej 500 MJ/m2 i powierzchni przekraczającej 200 m2; 2) w strefie pożarowej produkcyjnej i magazynowej o gęstości obciążenia ogniowego nieprzekraczającej 500 MJ/m2, w której znajduje się pomieszczenie o powierzchni przekraczającej 100 m2 i gęstości obciążenia ogniowego przekraczającej 1 000 MJ/m2; 3) przy wejściu do pomieszczeń magazynowych lub technicznych o powierzchni przekraczającej 200 m2 i gęstości obciążenia ogniowego przekraczającej 500 MJ/m2, usytuowanych w strefie pożarowej zakwalifikowanej do kategorii zagrożenia ludzi ZL I, ZL II, ZL III lub ZL V, znajdującej się w budynku niskim albo średniowysokim."}, {"ref": "§ 19 ust. 6 RPB – zawory 52 w budynkach W i WW o więcej niż jednej kondygnacji", "kind": "akt", "act": "rpb", "label": "§ 19", "text": "§ 19. […] 2. Hydranty 33 muszą być stosowane w garażu: 1) jednokondygnacyjnym zamkniętym o więcej niż 10 stanowiskach postojowych; 2) wielokondygnacyjnym. 3. Hydranty 52 muszą być stosowane: 1) w strefie pożarowej produkcyjnej i magazynowej o gęstości obciążenia ogniowego przekraczającej 500 MJ/m2 i powierzchni przekraczającej 200 m2; 2) w strefie pożarowej produkcyjnej i magazynowej o gęstości obciążenia ogniowego nieprzekraczającej 500 MJ/m2, w której znajduje się pomieszczenie o powierzchni przekraczającej 100 m2 i gęstości obciążenia ogniowego przekraczającej 1 000 MJ/m2; 3) przy wejściu do pomieszczeń magazynowych lub technicznych o powierzchni przekraczającej 200 m2 i gęstości obciążenia ogniowego przekraczającej 500 MJ/m2, usytuowanych w strefie pożarowej zakwalifikowanej do kategorii zagrożenia ludzi ZL I, ZL II, ZL III lub ZL V, znajdującej się w budynku niskim albo średniowysokim. 4. […]"}, {"ref": "§ 181 ust. 3 WT – awaryjne oświetlenie ewakuacyjne", "kind": "akt", "act": "wt", "label": "§ 181", "text": "3. Awaryjne oświetlenie ewakuacyjne należy stosować: 1) w pomieszczeniach: a) widowni kin, teatrów i filharmonii oraz innych sal widowiskowych, b) audytoriów, sal konferencyjnych, czytelni, lokali rozrywkowych oraz sal sportowych, przeznaczonych dla ponad 200 osób, c) wystawowych w muzeach, d) o powierzchni netto ponad 1000 m2 w garażach oświetlonych wyłącznie światłem sztucznym, e) o powierzchni netto ponad 2000 m2 w budynkach użyteczności publicznej, budynkach zamieszkania zbiorowego oraz w budynkach produkcyjnych i magazynowych; 2) na drogach ewakuacyjnych: a) z pomieszczeń wymienionych w pkt 1, b) oświetlonych wyłącznie światłem sztucznym, c) w szpitalach i innych budynkach przeznaczonych przede wszystkim do użytku osób o ograniczonej zdolności poruszania się, d) w wysokich i wysokościowych budynkach użyteczności publicznej i zamieszkania zbiorowego."}], "422": [{"ref": "PN-EN IEC 60079-10-1:2021-09 – klasyfikacja przestrzeni", "kind": "norma"}], "423": [{"ref": "§ 222 WT – usytuowanie pomieszczenia zagrożonego wybuchem", "kind": "akt", "act": "wt", "label": "§ 222", "text": "§ 222. 1. Pomieszczenie zagrożone wybuchem należy sytuować na najwyższej kondygnacji budynku. Wymaganie to nie dotyczy budynków na terenach zamkniętych. 2. Dopuszcza się inne usytuowanie pomieszczeń, o których mowa w ust. 1, pod warunkiem zastosowania odpowiednich instalacji i urządzeń przeciwwybuchowych, uzgodnionych z właściwym komendantem wojewódzkim Państwowej Straży Pożarnej."}, {"ref": "§ 221 ust. 2 WT – powierzchnia urządzeń odciążających 0,065 m2/m3", "kind": "akt", "act": "wt", "label": "§ 221", "text": "2. Przepis ust. 1 nie dotyczy pomieszczenia, w którym łączna powierzchnia urządzeń odciążających (przeciwwybuchowych), jak przepony, klapy oraz otwory oszklone szkłem zwykłym, jest większa niż 0,065 m2/m3 kubatury pomieszczenia."}], "424": [{"ref": "§ 228 ust. 1 i 2 WT – powierzchnie stref PM, część podziemna", "kind": "akt", "act": "wt", "label": "§ 228", "text": "§ 228. 1. Dopuszczalne powierzchnie stref pożarowych PM, z wyjątkiem garaży, określa poniższa tabela: Rodzaj stref pożarowych Gęstość obciążenia ogniowego Q [MJ/m2] Dopuszczalna powierzchnia strefy pożarowej w m2 w budynku o jednej kondygnacji nadziemnej (bez ograniczenia wysokości) w budynku wielokondygnacyjnym niskim i średniowysokim (N) i (SW) wysokim i wysokościowym (W) i (WW) 1 2 3 4 5 Strefy pożarowe z pomieszczeniem zagrożonym wybuchem Q > 4000 2000 < Q ≤ 4000 1000 < Q ≤ 2000 500 < Q ≤ 1000 Q ≤ 500 1000 2000 4000 6000 8000 * * 1000 2000 3000 * * * 500 1000 Strefy pożarowe pozostałe Q > 4000 2000 < Q ≤ 4000 1000 < Q ≤ 2000 500 < Q ≤ 1000 Q ≤ 500 2000 4000 8000 15 000 20 000 1000 2000 4000 8000 10 000 * * 1000 2500 5000 * Nie dopuszcza się takich przypadków."}], "425": [{"ref": "PN-EN 15004-1:2019 – bezpieczeństwo ludzi, minimalne środki bezpieczeństwa a NOAEL i LOAEL", "kind": "norma"}], "426": [{"ref": "PN-EN 13565 / rozp. MG – urządzenia pianowe zbiorników", "kind": "norma"}], "427": [{"ref": "PN-EN 12101-13:2022 pkt 5.2 – zastosowanie klasy 1 i klasy 2 systemów różnicowania ciśnień", "kind": "norma"}], "428": [{"ref": "PN-EN 12845+A1:2020 – zasilanie pomp", "kind": "norma"}], "429": [{"ref": "PN-B-02857:2017 – przeciwpożarowe zbiorniki wodne", "kind": "norma"}], "430": [{"ref": "§ 12 ust. 1 pkt 3 RW – droga pożarowa do stref PM, placów składowych i wiat", "kind": "akt", "act": "rw", "label": "§ 12", "text": "§ 12. 1. Drogę pożarową o utwardzonej nawierzchni, umożliwiającą dojazd pojazdów jednostek ochrony przeciwpożarowej do obiektu budowlanego o każdej porze roku, należy doprowadzić do: 1) budynku zawierającego strefę pożarową zakwalifikowaną do kategorii zagrożenia ludzi ZL I lub ZL II; 2) budynku należącego do grupy wysokości: średniowysoki, wysoki lub wysokościowy, zawierającego strefę pożarową zakwalifikowaną do kategorii zagrożenia ludzi ZL III, ZL IV lub ZL V; 3) budynku zawierającego strefę pożarową produkcyjną lub magazynową oraz do strefy pożarowej poza budynkiem, obejmującej urządzenia technologiczne, plac składowy lub wiatę, jeżeli gęstość obciążenia ogniowego wymienionych stref pożarowych przekracza 500 MJ/m2 i zachodzi co najmniej jeden z warunków: a) powierzchnia strefy pożarowej przekracza 1 000 m2, b) występuje pomieszczenie zagrożone wybuchem; […]"}, {"ref": "§ 12 ust. 1 pkt 4 RW – budynki ze strefą PM poniżej 500 MJ/m2", "kind": "akt", "act": "rw", "label": "§ 12", "text": "§ 12. 1. Drogę pożarową o utwardzonej nawierzchni, umożliwiającą dojazd pojazdów jednostek ochrony przeciwpożarowej do obiektu budowlanego o każdej porze roku, należy doprowadzić do: 1) budynku zawierającego strefę pożarową zakwalifikowaną do kategorii zagrożenia ludzi ZL I lub ZL II; 2) budynku należącego do grupy wysokości: średniowysoki, wysoki lub wysokościowy, zawierającego strefę pożarową zakwalifikowaną do kategorii zagrożenia ludzi ZL III, ZL IV lub ZL V; 3) budynku zawierającego strefę pożarową produkcyjną lub magazynową oraz do strefy pożarowej poza budynkiem, obejmującej urządzenia technologiczne, plac składowy lub wiatę, jeżeli gęstość obciążenia ogniowego wymienionych stref pożarowych przekracza 500 MJ/m2 i zachodzi co najmniej jeden z warunków: a) powierzchnia strefy pożarowej przekracza 1 000 m2, b) występuje pomieszczenie zagrożone wybuchem; […]"}], "431": [{"ref": "§ 219 ust. 2 WT – oddzielenie poddasza użytkowego od palnej konstrukcji dachu", "kind": "akt", "act": "wt", "label": "§ 219", "text": "2. W budynkach ZL III, ZL IV i ZL V poddasze użytkowe przeznaczone na cele mieszkalne lub biurowe powinno być oddzielone od palnej konstrukcji i palnego przekrycia dachu przegrodami o klasie odporności ogniowej: 1) w budynku niskim – E I 30; 2) w budynku średniowysokim i wysokim – E I 60."}], "432": [{"ref": "PKN-CEN/TS 54-14:2020 – dobór czujek ciepła", "kind": "norma"}], "433": [{"ref": "PN-EN 12845+A1:2020 – zbiorniki hydroforowe", "kind": "norma"}], "434": [{"ref": "PN-EN 1992-1-2:2008 – Eurokod 2, Metoda A", "kind": "norma"}], "435": [{"ref": "§ 8 ust. 1 pkt 1 RPB – limity cieczy palnych w strefach ZL innych niż handlowo-usługowe", "kind": "akt", "act": "rpb", "label": "§ 8", "text": "§ 8. 1. Podczas przechowywania cieczy o temperaturze zapłonu poniżej 328,15 K (55ºC) w budynkach, w strefach pożarowych zaliczonych do kategorii zagrożenia ludzi: 1) jest dopuszczalne przechowywanie w jednej strefie pożarowej, zakwalifikowanej do kategorii zagrożenia ludzi innej niż ZL IV oraz o przeznaczeniu innym niż handlowo-usługowe do 10 dm3 cieczy o temperaturze zapłonu poniżej 294,15 K (21ºC) oraz do 50 dm3 cieczy o temperaturze zapłonu 294,15÷328,15 K (21÷55ºC), a w mieszkaniach odpowiednio do 5 i do 20 dm3 cieczy; 2) jest dopuszczalne przechowywanie w pomieszczeniach handlowo-usługowych cieczy o temperaturze zapłonu do 328,15 K (55ºC) w takiej ilości, że gęstość obciążenia ogniowego stworzona przez te ciecze nie przekroczy 500 MJ/m2; […]"}, {"ref": "§ 8 ust. 1 pkt 2 RPB – ciecze palne w pomieszczeniach handlowo-usługowych", "kind": "akt", "act": "rpb", "label": "§ 8", "text": "§ 8. 1. Podczas przechowywania cieczy o temperaturze zapłonu poniżej 328,15 K (55ºC) w budynkach, w strefach pożarowych zaliczonych do kategorii zagrożenia ludzi: 1) jest dopuszczalne przechowywanie w jednej strefie pożarowej, zakwalifikowanej do kategorii zagrożenia ludzi innej niż ZL IV oraz o przeznaczeniu innym niż handlowo-usługowe do 10 dm3 cieczy o temperaturze zapłonu poniżej 294,15 K (21ºC) oraz do 50 dm3 cieczy o temperaturze zapłonu 294,15÷328,15 K (21÷55ºC), a w mieszkaniach odpowiednio do 5 i do 20 dm3 cieczy; 2) jest dopuszczalne przechowywanie w pomieszczeniach handlowo-usługowych cieczy o temperaturze zapłonu do 328,15 K (55ºC) w takiej ilości, że gęstość obciążenia ogniowego stworzona przez te ciecze nie przekroczy 500 MJ/m2; […]"}], "436": [{"ref": "PKN-CEN/TS 54-14:2020 – zasysające czujki dymu", "kind": "norma"}], "437": [{"ref": "§ 6 ust. 3 RW – ilość wody dla obiektów PM", "kind": "akt", "act": "rw", "label": "§ 6", "text": "3. Wymaganą ilość wody do celów przeciwpożarowych dla obiektów budowlanych produkcyjnych i magazynowych, z wyjątkiem wymienionych w ust. 4—8, służącą do zewnętrznego gaszenia pożaru, określa się, biorąc pod uwagę tę strefę pożarową, dla której jest ona największa, zgodnie z tabelą nr 2 załącznika do rozporządzenia. www.rcl.gov.pl Dziennik Ustaw Nr 124 — 9065 — Poz. 1030"}], "438": [{"ref": "PN-EN 12101-8:2012 – klapy odcinające wentylacji pożarowej", "kind": "norma"}], "439": [{"ref": "§ 3 ust. 1 rozp. MSWiA w sprawie uzgadniania projektu – obiekty wymagające uzgodnienia", "kind": "akt", "act": "uzgadnianie", "label": "§ 3", "text": "§ 3. 1. Obiektami budowlanymi istotnymi ze względu na konieczność zapewnienia ochrony życia, zdrowia, mienia lub środowiska przed pożarem, klęską żywiołową lub innym miejscowym zagrożeniem, których projekty zagospodarowania działki lub terenu, projekty architektoniczno-budowlane oraz projekty techniczne wymagają uzgodnienia, są: 1) budynek zawierający strefę pożarową zakwalifikowaną do kategorii zagrożenia ludzi ZL I, ZL II lub ZL V; 2) budynek średniowysoki (SW), wysoki (W) lub wysokościowy (WW), zawierający strefę pożarową zakwalifikowaną do kategorii zagrożenia ludzi ZL III lub ZL IV; 3) budynek niski (N) zawierający strefę pożarową o powierzchni przekraczającej 1000 m2, zakwalifikowaną do kategorii zagrożenia ludzi ZL III, obejmującą kondygnację nadziemną inną niż pierwsza; […]"}, {"ref": "§ 28 ust. 1 pkt 1 lit. a RPB – SSP w jednokondygnacyjnych budynkach handlowych powyżej 5000 m2", "kind": "akt", "act": "rpb", "label": "§ 28", "text": "§ 28. 1. Stosowanie systemu sygnalizacji pożarowej, obejmującego urządzenia sygnalizacyjno-alarmowe, służące do samoczynnego wykrywania i przekazywania informacji o pożarze, a także urządzenia odbiorcze alarmów pożarowych i urządzenia odbiorcze sygnałów uszkodzeniowych, jest wymagane w: 1) budynkach handlowych lub wystawowych: a) jednokondygnacyjnych o powierzchni strefy pożarowej powyżej 5000 m2, b) wielokondygnacyjnych o powierzchni strefy pożarowej powyżej 2500 m2; 2) teatrach o liczbie miejsc powyżej 300; 3) kinach o liczbie miejsc powyżej 600; 4) budynkach o liczbie miejsc służących celom gastronomicznym powyżej 300; 5) salach widowiskowych i sportowych o liczbie miejsc powyżej 1500; 6) szpitalach, z wyjątkiem psychiatrycznych, oraz w sanatoriach ‒ o liczbie łóżek powyżej 200 w budynku; 7) szpitalach psychiatrycznych o liczbie łóżek powyżej 100 w budynku; […]"}], "440": [{"ref": "PN-EN 1993-1-2 – zabezpieczenia ogniochronne konstrukcji stalowych", "kind": "norma"}], "441": [{"ref": "§ 2 ust. 2 pkt 1 rozp. Ministra Cyfryzacji z 4.12.2019 – zabezpieczenia pomieszczeń i klasa odporności pożarowej budynku", "kind": "akt", "act": "cyfryzacja", "label": "§ 2", "text": "2. 1. Podmioty świadczące usługi z zakresu cyberbezpieczeństwa oraz wewnętrzne struktury organizacyjne operatorów usług kluczowych odpowiedzialne za cyberbezpieczeństwo są obowiązane spełniać następujące warunki techniczne: 1) dysponować sprzętem komputerowym oraz wyspecjalizowanymi narzędziami informatycznymi umożliwiającymi: a) rejestrowanie zgłoszeń incydentów, b) analizę kodu oprogramowania uznanego za szkodliwe, c) badanie odporności systemów informacyjnych na przełamanie lub ominięcie zabezpieczeń, d) zabezpieczanie informacji potrzebnych do analizy powłamaniowej pozwalające na określenie wpływu incydentu poważnego na świadczenie usługi kluczowej, w tym informacji dotyczących: – rodzajów usług kluczowych, na które incydent miał wpływ, – liczby użytkowników usługi kluczowej, na których incydent miał wpływ, – momentu wystąpienia i wykrycia incydentu oraz czasu jego trwania, – zasięgu […]"}], "442": [{"ref": "§ 181 ust. 3 pkt 1 lit. c WT – pomieszczenia wystawowe w muzeach", "kind": "akt", "act": "wt", "label": "§ 181", "text": "3. Awaryjne oświetlenie ewakuacyjne należy stosować: 1) w pomieszczeniach: a) widowni kin, teatrów i filharmonii oraz innych sal widowiskowych, b) audytoriów, sal konferencyjnych, czytelni, lokali rozrywkowych oraz sal sportowych, przeznaczonych dla ponad 200 osób, c) wystawowych w muzeach, d) o powierzchni netto ponad 1000 m2 w garażach oświetlonych wyłącznie światłem sztucznym, e) o powierzchni netto ponad 2000 m2 w budynkach użyteczności publicznej, budynkach zamieszkania zbiorowego oraz w budynkach produkcyjnych i magazynowych; 2) na drogach ewakuacyjnych: a) z pomieszczeń wymienionych w pkt 1, b) oświetlonych wyłącznie światłem sztucznym, c) w szpitalach i innych budynkach przeznaczonych przede wszystkim do użytku osób o ograniczonej zdolności poruszania się, d) w wysokich i wysokościowych budynkach użyteczności publicznej i zamieszkania zbiorowego."}, {"ref": "§ 181 ust. 3 pkt 1 lit. d i e WT – progi 1000 m2 (garaże) i 2000 m2", "kind": "akt", "act": "wt", "label": "§ 181", "text": "3. Awaryjne oświetlenie ewakuacyjne należy stosować: 1) w pomieszczeniach: a) widowni kin, teatrów i filharmonii oraz innych sal widowiskowych, b) audytoriów, sal konferencyjnych, czytelni, lokali rozrywkowych oraz sal sportowych, przeznaczonych dla ponad 200 osób, c) wystawowych w muzeach, d) o powierzchni netto ponad 1000 m2 w garażach oświetlonych wyłącznie światłem sztucznym, e) o powierzchni netto ponad 2000 m2 w budynkach użyteczności publicznej, budynkach zamieszkania zbiorowego oraz w budynkach produkcyjnych i magazynowych; 2) na drogach ewakuacyjnych: a) z pomieszczeń wymienionych w pkt 1, b) oświetlonych wyłącznie światłem sztucznym, c) w szpitalach i innych budynkach przeznaczonych przede wszystkim do użytku osób o ograniczonej zdolności poruszania się, d) w wysokich i wysokościowych budynkach użyteczności publicznej i zamieszkania zbiorowego."}], "443": [{"ref": "§ 214 WT – obniżenie klasy odporności pożarowej przy urządzeniach gaśniczych wodnych (nie dotyczy ZL II)", "kind": "akt", "act": "wt", "label": "§ 214", "text": "§ 214. W budynkach wyposażonych w stałe samoczynne urządzenia gaśnicze wodne, z wyjątkiem budynków ZL II oraz wielokondygnacyjnych budynków wysokich (W) i wysokościowych (WW), dopuszcza się: 1) obniżenie klasy odporności pożarowej budynku o jedną w stosunku do wynikającej z § 212; 2) przyjęcie klasy „E” odporności pożarowej dla budynku jednokondygnacyjnego."}, {"ref": "§ 227 ust. 4 WT – powiększenie powierzchni strefy pożarowej o 100%", "kind": "akt", "act": "wt", "label": "§ 227", "text": "4. Dopuszcza się powiększenie powierzchni stref pożarowych, o których mowa w ust. 1, z wyjątkiem stref pożarowych w wielokondygnacyjnych budynkach wysokich (W) i wysokościowych (WW), pod warunkiem zastosowania: 1) stałych samoczynnych urządzeń gaśniczych wodnych – o 100%; 2) samoczynnych urządzeń oddymiających uruchamianych za pomocą systemu wykrywania dymu – o 100%. Przy jednoczesnym stosowaniu urządzeń wymienionych w pkt 1 i 2 dopuszcza się powiększenie powierzchni stref pożarowych o 200%."}], "444": [{"ref": "PKN-CEN/TS 54-14:2020 – rozmieszczenie czujek ciepła", "kind": "norma"}], "445": [{"ref": "zał. nr 3 WT; PN-EN 13501-5 – klasyfikacja przekryć dachów", "kind": "norma"}], "446": [{"ref": "PN-EN 15004-1:2019 – czas utrzymywania stężenia", "kind": "norma"}], "447": [{"ref": "PN-EN 13501-2:2023 – klasyfikacja ogniowa (kryterium W)", "kind": "norma"}], "449": [{"ref": "§ 157 ust. 5–7 WT – gaz płynny tylko w budynkach niskich i wyjątek dla kotłowni", "kind": "akt", "act": "wt", "label": "§ 157", "text": "5. Instalacje gazowe zasilane gazem płynnym mogą być wykonywane tylko w budynkach niskich."}, {"ref": "§ 177 WT – butle do 11 kg, nie więcej niż dwie w mieszkaniu", "kind": "akt", "act": "wt", "label": "§ 177", "text": "§ 177. Urządzenia gazowe instalowane w budynku mogą być zasilane gazem płynnym z indywidualnych butli o nominalnej zawartości gazu do 11 kg, pod warunkiem spełnienia następujących wymagań: 1) w jednym mieszkaniu, warsztacie lub lokalu użytkowym nie należy instalować więcej niż dwóch butli; 2) w pomieszczeniu, w którym instaluje się butlę, należy zachować temperaturę niższą niż 35°C; 3) butlę należy instalować wyłącznie w pozycji pionowej; 4) butlę należy zabezpieczyć przed uszkodzeniami mechanicznymi; 5) między butlą a urządzeniem promieniującym ciepło, z wyłączeniem zestawów urządzeń gazowych z butlami, należy zachować odległość co najmniej 1,5 m; 6) butli nie należy umieszczać w odległości mniejszej niż 1 m od urządzeń mogących powodować iskrzenie; […]"}, {"ref": "§ 8 pkt 1 WT – budynek mieszkalny do 4 kondygnacji jest niski", "kind": "akt", "act": "wt", "label": "§ 8", "text": "§ 8. W celu określenia wymagań technicznych i użytkowych wprowadza się następujący podział budynków na grupy wysokości: 1) niskie (N) – do 12 m włącznie nad poziomem terenu lub mieszkalne o wysokości do 4 kondygnacji nadziemnych włącznie; 2) średniowysokie (SW) – ponad 12 m do 25 m włącznie nad poziomem terenu lub mieszkalne o wysokości ponad 4 do 9 kondygnacji nadziemnych włącznie; 3) wysokie (W) – ponad 25 m do 55 m włącznie nad poziomem terenu lub mieszkalne o wysokości ponad 9 do 18 kondygnacji nadziemnych włącznie; 4) wysokościowe (WW) – powyżej 55 m nad poziomem terenu."}], "450": [{"ref": "§ 275 ust. 1 i 3 WT – klasa odporności pożarowej garażu", "kind": "akt", "act": "wt", "label": "§ 275", "text": "§ 275. 1. Klasę odporności pożarowej garażu należy przyjmować, jak dla budynku PM o gęstości obciążenia ogniowego do 500 MJ/m2, pod warunkiem wykonania jego elementów jako nierozprzestrzeniających ognia, niekapiących i nieodpadających pod wpływem ognia, jeżeli przepisy rozporządzenia nie stanowią inaczej."}, {"ref": "§ 212 ust. 4 WT – klasa „C” dla PM o Q do 500 MJ/m2 w budynku średniowysokim", "kind": "akt", "act": "wt", "label": "§ 212", "text": "4. Wymaganą klasę odporności pożarowej dla budynku PM oraz IN, z zastrzeżeniem § 282, określa poniższa tabela: Maksymalna gęstość obciążenia ogniowego strefy pożarowej w budynku Q [MJ/m2] Budynek o jednej kondygnacji nadziemnej (bez ograniczenia wysokości) Budynek wielokondygnacyjny niski średniowysoki wysoki wysokościowy (N) (SW) (W) (WW) 1 2 3 4 5 6 Q ≤ 500 „E” „D” „C” „B” „B” 500 < Q ≤ 1000 „D” „D” „C” „B” „B” 1000 < Q ≤ 2000 „C” „C” „C” „B” „B” 2000 < Q ≤ 4000 „B” „B” „B” * * Q > 4000 „A” „A” „A” * * * – Zgodnie z § 228 ust. 1 nie mogą występować takie budynki."}], "451": [{"ref": "§ 10 RW – sieć wodociągowa przeciwpożarowa", "kind": "akt", "act": "rw", "label": "§ 10", "text": "§ 10. […] 4) dla hydrantu nadziemnego DN 80 na sieci, o której mowa w § 9 ust. 2 — 5 dm3/s. www.rcl.gov.pl Dziennik Ustaw Nr 124 — 9067 — Poz. 1030 9. Dla zapewnienia możliwości intensywnego czerpania wody do celów przeciwpożarowych na sieciach wodociągowych o średnicy nominalnej nie mniejszej niż DN 250 powinny być instalowane hydranty nadziemne, spełniające następujące wymagania: 1) średnica nominalna hydrantu powinna wynosić DN 100 lub DN 150; 2) wydajność nominalna przy ciśnieniu nominalnym 0,2 MPa mierzonym na zaworze hydrantowym podczas poboru wody nie może być mniejsza niż 20 dm3/s; 3) hydranty powinny być usytuowane w miejscach dostępnych z głównych dróg komunikacyjnych na terenie jednostki osadniczej; 4) miejsce usytuowania hydrantu należy oznakować znakami zgodnymi z Polskimi Normami wraz z podaniem na znaku dodatkowym wielkości charakterystycznych hydrantu; […]"}], "454": [{"ref": "§ 256 ust. 3 WT – dojście w ZL IV: 60 m, w tym do 20 m w poziomie", "kind": "akt", "act": "wt", "label": "§ 256", "text": "3. Dopuszczalne długości dojść ewakuacyjnych w strefach pożarowych określa poniższa tabela: Rodzaj strefy pożarowej Długość dojścia w m przy jednym dojściu przy co najmniej 2 dojściach1) 1 2 3 Z pomieszczeniem zagrożonym wybuchem 10 40 PM o gęstości obciążenia ogniowego Q > 500 MJ/m2 bez pomieszczenia zagrożonego wybuchem 302) 60 PM o gęstości obciążenia ogniowego Q ≤ 500 MJ/m2 bez pomieszczenia zagrożonego wybuchem 602) 100 ZL I, II i V 10 40 ZL III 302) 60 ZL IV 602) 100 1) Dla dojścia najkrótszego, przy czym dopuszcza się dla drugiego dojścia długość większą o 100% od najkrótszego. Dojścia te nie mogą się pokrywać ani krzyżować, przy czym dopuszcza się ich wspólny początkowy przebieg na długości nie większej niż 2 m. 2) W tym nie więcej niż 20 m na poziomej drodze ewakuacyjnej."}, {"ref": "§ 256 ust. 4 WT – warunki powiększenia długości dojść", "kind": "akt", "act": "wt", "label": "§ 256", "text": "4. Długości dojść ewakuacyjnych, o których mowa w ust. 3, mogą być powiększone pod warunkiem ochrony: 1) strefy pożarowej stałymi samoczynnymi urządzeniami gaśniczymi wodnymi – o 50%; 2) drogi ewakuacyjnej samoczynnymi urządzeniami oddymiającymi uruchamianymi za pomocą systemu wykrywania dymu – o 50%. Przy jednoczesnym stosowaniu tych urządzeń długość dojścia może być powiększona o 100%."}], "455": [{"ref": "PN-B-02431-1:1999 – kotłownie gazowe", "kind": "norma"}], "456": [{"ref": "§ 10 RW – zasilanie sieci wodociągowej przeciwpożarowej", "kind": "akt", "act": "rw", "label": "§ 10", "text": "§ 10. […] 2) dla hydrantu nadziemnego DN 100 — 15 dm3/s; 3) dla hydrantu podziemnego DN 80 — 10 dm3/s; 4) dla hydrantu nadziemnego DN 80 na sieci, o której mowa w § 9 ust. 2 — 5 dm3/s. www.rcl.gov.pl Dziennik Ustaw Nr 124 — 9067 — Poz. 1030 9. Dla zapewnienia możliwości intensywnego czerpania wody do celów przeciwpożarowych na sieciach wodociągowych o średnicy nominalnej nie mniejszej niż DN 250 powinny być instalowane hydranty nadziemne, spełniające następujące wymagania: 1) średnica nominalna hydrantu powinna wynosić DN 100 lub DN 150; 2) wydajność nominalna przy ciśnieniu nominalnym 0,2 MPa mierzonym na zaworze hydrantowym podczas poboru wody nie może być mniejsza niż 20 dm3/s; 3) hydranty powinny być usytuowane w miejscach dostępnych z głównych dróg komunikacyjnych na terenie jednostki osadniczej; […]"}], "457": [{"ref": "§ 12 RW – wymóg drogi pożarowej", "kind": "akt", "act": "rw", "label": "§ 12", "text": "§ 12. […] 2) budynku należącego do grupy wysokości: średniowysoki, wysoki lub wysokościowy, zawierającego strefę pożarową zakwalifikowaną do kategorii zagrożenia ludzi ZL III, ZL IV lub ZL V; 3) budynku zawierającego strefę pożarową produkcyjną lub magazynową oraz do strefy pożarowej poza budynkiem, obejmującej urządzenia technologiczne, plac składowy lub wiatę, jeżeli gęstość obciążenia ogniowego wymienionych stref pożarowych przekracza 500 MJ/m2 i zachodzi co najmniej jeden z warunków: a) powierzchnia strefy pożarowej przekracza 1 000 m2, b) występuje pomieszczenie zagrożone wybuchem; 4) budynku zawierającego strefę pożarową produkcyjną lub magazynową o gęstości obciążenia ogniowego poniżej 500 MJ/m2 o powierzchni przekraczającej 20 000 m2; […]"}], "458": [{"ref": "PN-EN 12845+A1:2020 – źródła zasilania wodą", "kind": "norma"}], "459": [{"ref": "PN-EN 12101-13:2022 tabela 1 – kryteria przepływu powietrza i różnicy ciśnień dla klas 1 i 2", "kind": "norma"}], "460": [{"ref": "art. 10 ustawy o wyrobach budowlanych", "kind": "akt", "act": "wyroby", "label": "art. 10", "text": "Art. 10. 1. Dopuszczone do jednostkowego zastosowania w obiekcie budowlanym są wyroby budowlane, z wyłączeniem wyrobów, o których mowa w art. 5 ust. 1, wykonane według indywidualnej dokumentacji technicznej, sporządzonej przez projektanta obiektu lub z nim uzgodnionej, dla których producent wydał oświadczenie, że zapewniono zgodność wyrobu budowlanego z tą dokumentacją oraz z przepisami. 2. Indywidualna dokumentacja techniczna, o której mowa w ust. 1, powinna zawierać opis rozwiązania konstrukcyjnego, charakterystykę materiałową i informację dotyczącą projektowanych właściwości użytkowych wyrobu budowlanego oraz określać warunki jego zastosowania w danym obiekcie budowlanym, a także, w miarę potrzeb, instrukcję obsługi i eksploatacji. 3. Oświadczenie, o którym mowa w ust. 1, powinno zawierać: 1) nazwę i adres wydającego oświadczenie; 2) nazwę wyrobu budowlanego i miejsce jego wytworzenia; […]"}], "461": [{"ref": "§ 28 ust. 1 pkt 8 RPB – SSP w domach pomocy społecznej powyżej 100 łóżek", "kind": "akt", "act": "rpb", "label": "§ 28", "text": "§ 28. 1. Stosowanie systemu sygnalizacji pożarowej, obejmującego urządzenia sygnalizacyjno-alarmowe, służące do samoczynnego wykrywania i przekazywania informacji o pożarze, a także urządzenia odbiorcze alarmów pożarowych i urządzenia odbiorcze sygnałów uszkodzeniowych, jest wymagane w: 1) budynkach handlowych lub wystawowych: a) jednokondygnacyjnych o powierzchni strefy pożarowej powyżej 5000 m2, b) wielokondygnacyjnych o powierzchni strefy pożarowej powyżej 2500 m2; 2) teatrach o liczbie miejsc powyżej 300; 3) kinach o liczbie miejsc powyżej 600; 4) budynkach o liczbie miejsc służących celom gastronomicznym powyżej 300; 5) salach widowiskowych i sportowych o liczbie miejsc powyżej 1500; 6) szpitalach, z wyjątkiem psychiatrycznych, oraz w sanatoriach ‒ o liczbie łóżek powyżej 200 w budynku; 7) szpitalach psychiatrycznych o liczbie łóżek powyżej 100 w budynku; […]"}], "463": [{"ref": "PKN-CEN/TS 54-14:2020 – rozmieszczenie liniowych czujek dymu, czujki dodatkowe na niższych poziomach", "kind": "norma"}], "464": [{"ref": "§ 271 ust. 1 i 5 WT – odległości między budynkami i zwiększenie o 100%", "kind": "akt", "act": "wt", "label": "§ 271", "text": "§ 271. 1. Odległość między zewnętrznymi ścianami budynków niebędącymi ścianami oddzielenia przeciwpożarowego, a mającymi na powierzchni większej niż 65% klasę odporności ogniowej (E), określoną w § 216 ust. 1 w 5 kolumnie tabeli, nie powinna, z zastrzeżeniem ust. 2 i 3, być mniejsza niż odległość w metrach określona w poniższej tabeli: Rodzaj budynku oraz dla budynku PM maksymalna gęstość obciążenia ogniowego strefy pożarowej PM Q w MJ/m2 Rodzaj budynku oraz dla budynku PM maksymalna gęstość obciążenia ogniowego strefy pożarowej PM Q w MJ/m2 ZL IN PM Q ≤ 1000 1000 < Q ≤ 4000 Q > 4000 1 2 3 4 5 6 ZL 8 8 8 15 20 IN 8 8 8 15 20 PM Q ≤ 1000 8 8 8 15 20 PM 1000 < Q ≤ 4000 15 15 15 15 20 PM Q > 4000 20 20 20 20 20"}, {"ref": "§ 212 ust. 4 WT – klasa „B” dla PM niskiego wielokondygnacyjnego przy Q od 2000 do 4000 MJ/m2", "kind": "akt", "act": "wt", "label": "§ 212", "text": "4. Wymaganą klasę odporności pożarowej dla budynku PM oraz IN, z zastrzeżeniem § 282, określa poniższa tabela: Maksymalna gęstość obciążenia ogniowego strefy pożarowej w budynku Q [MJ/m2] Budynek o jednej kondygnacji nadziemnej (bez ograniczenia wysokości) Budynek wielokondygnacyjny niski średniowysoki wysoki wysokościowy (N) (SW) (W) (WW) 1 2 3 4 5 6 Q ≤ 500 „E” „D” „C” „B” „B” 500 < Q ≤ 1000 „D” „D” „C” „B” „B” 1000 < Q ≤ 2000 „C” „C” „C” „B” „B” 2000 < Q ≤ 4000 „B” „B” „B” * * Q > 4000 „A” „A” „A” * * * – Zgodnie z § 228 ust. 1 nie mogą występować takie budynki."}, {"ref": "§ 216 ust. 1 WT – ściana zewnętrzna EI 60 w klasie „B”", "kind": "akt", "act": "wt", "label": "§ 216", "text": "§ 216. 1. Elementy budynku, odpowiednio do jego klasy odporności pożarowej, powinny spełniać, z zastrzeżeniem § 213 oraz § 237 ust. 9, co najmniej wymagania określone w poniższej tabeli: Klasa odporności pożarowej budynku Klasa odporności ogniowej elementów budynku5) *) główna konstrukcja nośna konstrukcja dachu strop1) ściana zewnętrzna1), 2) ściana wewnętrzna1) przekrycie dachu3) 1 2 3 4 5 6 7 „A” R 240 R 30 R E I 120 E I 120 (o↔i) E I 60 R E 30 „B” R 120 R 30 R E I 60 E I 60 (o↔i) E I 304) R E 30 „C” R 60 R 15 R E I 60 E I 30 (o↔i) E I 154) R E 15 „D” R 30 (–) R E I 30 E I 30 (o↔i) (–) (–) „E” (–) (–) (–) (–) (–) (–) *) Z zastrzeżeniem § 219 ust. 1. […]"}], "465": [{"ref": "PKN-CEN/TS 54-14:2020 – rozmieszczenie czujek ciepła", "kind": "norma"}], "466": [{"ref": "dyrektywa ATEX – kategorie urządzeń a strefy", "kind": "ue"}], "467": [{"ref": "PN-EN 12845+A1:2020 załącznik P – tryskacze ESFR, wymagania dla dachów i świetlików", "kind": "norma"}], "468": [{"ref": "§ 269 ust. 5 WT – lokalizacja filtrów, komór pyłowych i cyklonów do palnych pyłów", "kind": "akt", "act": "wt", "label": "§ 269", "text": "5. Filtry, komory pyłowe i cyklony do palnych pyłów powinny być zlokalizowane w pomieszczeniach wydzielonych elementami oddzielenia przeciwpożarowego lub też na zewnątrz budynku, w miejscu bezpiecznym dla tych urządzeń oraz dla otoczenia."}], "469": [{"ref": "§ 258 ust. 1 WT – zakaz materiałów łatwo zapalnych intensywnie dymiących w ZL I, II, III i V", "kind": "akt", "act": "wt", "label": "§ 258", "text": "§ 258. 1. W strefach pożarowych ZL I, ZL II, ZL III i ZL V stosowanie do wykończenia wnętrz materiałów i wyrobów łatwo zapalnych, których produkty rozkładu termicznego są bardzo toksyczne lub intensywnie dymiące, jest zabronione. 1a. W przypadku stosowania materiałów wykończeniowych luźno zwisających, w szczególności w kurtynach, zasłonach, draperiach, kotarach oraz żaluzjach, za łatwo zapalne uważa się materiały, których właściwości określone w badaniach zgodnych z Polskimi Normami odnoszącymi się do zapalności i rozprzestrzeniania płomienia przez wyroby włókiennicze nie spełniają co najmniej jednego z kryteriów: 1) ti ≥ 4 s; 2) ts ≤ 30 s; 3) nie następuje przepalenie trzeciej nitki; 4) nie występują płonące krople."}], "470": [{"ref": "PN-B-02877-4:2001/Az1:2006 – usytuowanie klap dymowych", "kind": "norma"}], "471": [{"ref": "§ 26 ust. 1 rozp. MSWiA z 19.02.2020 – limity ilości ciekłych odpadów palnych w strefie pożarowej", "kind": "akt", "act": "odpady-rozp", "label": "§ 26", "text": "§ 26. 1. W magazynie ciekłych odpadów palnych ilość magazynowanych odpadów w strefie pożarowej nie może prze kraczać: 1) 50 m3 – w przypadku ciekłych odpadów palnych o temperaturze zapłonu do 60°C oraz odpadowego oleju gazowego, oleju napędowego i lekkiego oleju opałowego o temperaturze zapłonu do 75°C; 2) 200 m3 – w przypadku ciekłych odpadów palnych o temperaturze zapłonu powyżej 60°C oraz odpadowego oleju ga zowego, oleju napędowego i lekkiego oleju opałowego o temperaturze zapłonu powyżej 75°C."}, {"ref": "§ 26 ust. 2 rozp. MSWiA z 19.02.2020 – zwiększenie limitów przy urządzeniach gaśniczych", "kind": "akt", "act": "odpady-rozp", "label": "§ 26", "text": "2. Dopuszcza się zwiększenie o 200% ilości, o których mowa w ust. 1, jeżeli strefa pożarowa z odpadami ciekłymi jest chroniona przez stałe samoczynne urządzenia gaśnicze przeznaczone do gaszenia pożarów cieczy palnych znajdujących się w tej strefie."}], "472": [{"ref": "PN-EN 13501-4 – klasyfikacja elementów systemów kontroli rozprzestrzeniania dymu (C300, C10000, Cmod)", "kind": "norma"}], "474": [{"ref": "PN-B-02857:2017 – przeciwpożarowe zbiorniki wodne", "kind": "norma"}], "475": [{"ref": "PN-EN 81-72:2020 – dźwigi dla straży pożarnej, czas dojazdu", "kind": "norma"}], "476": [{"ref": "§ 28, § 29 RPB; § 181 WT", "kind": "akt", "act": "wt", "label": "§ 28", "text": "§ 28. 1. Działka budowlana, na której sytuowane są budynki, powinna być wyposażona w kanalizację umożliwiającą odprowadzenie wód opadowych do sieci kanalizacji deszczowej lub ogólnospławnej. 2. W przypadku budynków niskich lub budynków, dla których nie ma możliwości przyłączenia do sieci kanalizacji deszczowej lub ogólnospławnej, dopuszcza się odprowadzenie wód opadowych na własny teren nieutwardzony, do dołów chłonnych lub do zbiorników retencyjnych."}], "478": [{"ref": "§ 179 WT – zbiorniki gazu płynnego", "kind": "akt", "act": "wt", "label": "§ 179", "text": "§ 179. […] 4. Dopuszczalną odległość zbiorników z gazem płynnym od budynków mieszkalnych, budynków zamieszkania zbiorowego oraz budynków użyteczności publicznej, a także między zbiornikami, określa poniższa tabela: Nominalna pojemność zbiornika w m3 Odległość budynków mieszkalnych, budynków zamieszkania zbiorowego i budynków użyteczności publicznej od: Odległość od sąsiedniego zbiornika naziemnego lub podziemnego w m zbiornika naziemnego w m zbiornika podziemnego w m 1 2 3 4 do 3 3 1 1 powyżej 3 do 5 5 2,5 1 powyżej 5 do 7 7,5 3 1,5 powyżej 7 do 10 10 5 1,5 powyżej 10 do 40 20 10 ¼ sumy średnic dwóch sąsiednich zbiorników powyżej 40 do 65 30 15 powyżej 65 do 100 40 20 5. Dopuszczalna odległość zbiorników z gazem płynnym od budynków produkcyjnych i magazynowych powinna wynosić dla zbiorników o pojemności: 1) do 10 m3 – nie mniej niż odległość określona w tabeli w ust. 4 w kolumnach 2 i 3; […]"}], "479": [{"ref": "§ 37 RPB / WT – urządzenia odciążające", "kind": "akt", "act": "wt", "label": "§ 37", "text": "§ 37. Przepływowe, szczelne osadniki podziemne, stanowiące część przydomowej oczyszczalni ścieków gospodarczo-bytowych, służące do wstępnego ich oczyszczania, mogą być sytuowane w bezpośrednim sąsiedztwie budynków jednorodzinnych, pod warunkiem wyprowadzenia ich odpowietrzenia przez instalację kanalizacyjną co najmniej 0,6 m powyżej górnej krawędzi okien i drzwi zewnętrznych w tych budynkach."}], "480": [{"ref": "§ 27 ust. 2 RPB – stałe samoczynne urządzenia gaśnicze wodne", "kind": "akt", "act": "rpb", "label": "§ 27", "text": "2. Stosowanie stałych samoczynnych urządzeń gaśniczych wodnych jest wymagane w: 1) budynkach handlowych lub wystawowych: a) jednokondygnacyjnych, w strefie pożarowej zakwalifikowanej do kategorii zagrożenia ludzi ZL I o powierzchni powyżej 8000 m2, b) wielokondygnacyjnych, w strefie pożarowej zakwalifikowanej do kategorii zagrożenia ludzi ZL I o powierzchni powyżej 5000 m2; 2) w budynkach o liczbie miejsc służących celom gastronomicznym powyżej 600; 3) budynkach użyteczności publicznej wysokościowych; 4) budynkach zamieszkania zbiorowego wysokościowych."}, {"ref": "§ 29 ust. 1 RPB – dźwiękowy system ostrzegawczy", "kind": "akt", "act": "rpb", "label": "§ 29", "text": "§ 29. 1. Stosowanie dźwiękowego systemu ostrzegawczego, umożliwiającego rozgłaszanie sygnałów ostrzegawczych i komunikatów głosowych na potrzeby bezpieczeństwa osób przebywających w obiekcie, nadawanych automatycznie po otrzymaniu sygnału z systemu sygnalizacji pożarowej, a także przez operatora, jest wymagane w: 1) budynkach handlowych lub wystawowych: a) jednokondygnacyjnych, zawierających strefę pożarową zakwalifikowaną do kategorii zagrożenia ludzi ZL I o powierzchni powyżej 8000 m2, b) wielokondygnacyjnych, zawierających strefę pożarową zakwalifikowaną do kategorii zagrożenia ludzi ZL I o powierzchni powyżej 5000 m2; 2) salach widowiskowych i sportowych o liczbie miejsc powyżej 1500; 3) kinach i teatrach o liczbie miejsc powyżej 600; […]"}], "481": [{"ref": "§ 267 WT – przewody wentylacyjne", "kind": "akt", "act": "wt", "label": "§ 267", "text": "§ 267. […] 5. W kuchni lub w aneksie kuchennym w mieszkaniu dopuszcza się stosowanie przewodów wentylacji wywiewnej z materiałów co najmniej trudno zapalnych. 6. Elastyczne elementy łączące, służące do połączenia sztywnych przewodów wentylacyjnych z elementami instalacji lub urządzeniami, z wyjątkiem wentylatorów, powinny być wykonane z materiałów co najmniej trudno zapalnych, posiadać długość nie większą niż 4 m, przy czym nie powinny być prowadzone przez elementy oddzielenia przeciwpożarowego. 7. Elastyczne elementy łączące wentylatory z przewodami wentylacyjnymi powinny być wykonane z materiałów co najmniej trudno zapalnych, przy czym ich długość nie powinna przekraczać 0,25 m. 8. Izolacje cieplne i akustyczne zastosowane w instalacjach: wodociągowej, kanalizacyjnej i ogrzewczej powinny być wykonane w sposób zapewniający nierozprzestrzenianie ognia."}], "482": [{"ref": "PN-B-02877-4:2025-07 – napływ powietrza kompensacyjnego do klatek schodowych", "kind": "norma"}], "483": [{"ref": "§ 223 ust. 1 WT – pasy międzykondygnacyjne 0,8 m w budynku wielokondygnacyjnym", "kind": "akt", "act": "wt", "label": "§ 223", "text": "§ 223. 1. W ścianach zewnętrznych budynku wielokondygnacyjnego, z zastrzeżeniem § 224, powinny być pasy międzykondygnacyjne o wysokości co najmniej 0,8 m."}, {"ref": "§ 224 ust. 1 WT – pas 1,2 m nad strefą PM o Q powyżej 1000 MJ/m2", "kind": "akt", "act": "wt", "label": "§ 224", "text": "§ 224. 1. W ścianach zewnętrznych budynku wielokondygnacyjnego nad strefą pożarową PM, o gęstości obciążenia ogniowego powyżej 1000 MJ/m2, wysokość pasa międzykondygnacyjnego powinna wynosić co najmniej 1,2 m."}], "484": [{"ref": "§ 12 ust. 1 pkt 3 RW – droga pożarowa do budynków ze strefą PM ponad 500 MJ/m2", "kind": "akt", "act": "rw", "label": "§ 12", "text": "§ 12. 1. Drogę pożarową o utwardzonej nawierzchni, umożliwiającą dojazd pojazdów jednostek ochrony przeciwpożarowej do obiektu budowlanego o każdej porze roku, należy doprowadzić do: 1) budynku zawierającego strefę pożarową zakwalifikowaną do kategorii zagrożenia ludzi ZL I lub ZL II; 2) budynku należącego do grupy wysokości: średniowysoki, wysoki lub wysokościowy, zawierającego strefę pożarową zakwalifikowaną do kategorii zagrożenia ludzi ZL III, ZL IV lub ZL V; 3) budynku zawierającego strefę pożarową produkcyjną lub magazynową oraz do strefy pożarowej poza budynkiem, obejmującej urządzenia technologiczne, plac składowy lub wiatę, jeżeli gęstość obciążenia ogniowego wymienionych stref pożarowych przekracza 500 MJ/m2 i zachodzi co najmniej jeden z warunków: a) powierzchnia strefy pożarowej przekracza 1 000 m2, b) występuje pomieszczenie zagrożone wybuchem; […]"}, {"ref": "§ 226 ust. 3 WT – sposób obliczania powierzchni strefy pożarowej", "kind": "akt", "act": "wt", "label": "§ 226", "text": "3. Powierzchnia strefy pożarowej jest obliczana jako powierzchnia wewnętrzna budynku lub jego części, przy czym wlicza się do niej także powierzchnię antresoli."}], "485": [{"ref": "§ 267 WT – przejścia przewodów wentylacyjnych", "kind": "akt", "act": "wt", "label": "§ 267", "text": "§ 267. […] U. poz. 248), które weszło w życie z dniem 17 lutego 2022 r. 1b.9) W budynkach mieszkalnych jednorodzinnych, w których wydzielono dwa lokale mieszkalne albo jeden lokal mieszkalny i lokal użytkowy, oraz w budynkach mieszkalnych wielorodzinnych, w obrębie jednego lokalu mieszkalnego, dopuszcza się stosowanie przewodów wentylacyjnych o klasie reakcji na ogień co najmniej E pod warunkiem zainstalowania w miejscu przejścia przewodów wentylacyjnych przez przegrody wydzielające lokal mieszkalny lub lokal użytkowy: 1) w budynkach niskich (N) i średniowysokich (SW) – zabezpieczenia ogniochronnego o klasie odporności ogniowej co najmniej E I 30; 2) w budynkach wysokich (W) i wysokościowych (WW) – przeciwpożarowej klapy odcinającej o klasie odporności ogniowej co najmniej E I S 60. 2. […]"}], "486": [{"ref": "§ 258 WT – wykończenie wnętrz; wskaźnik toksyczności", "kind": "akt", "act": "wt", "label": "§ 258", "text": "§ 258. 1. W strefach pożarowych ZL I, ZL II, ZL III i ZL V stosowanie do wykończenia wnętrz materiałów i wyrobów łatwo zapalnych, których produkty rozkładu termicznego są bardzo toksyczne lub intensywnie dymiące, jest zabronione. 1a. W przypadku stosowania materiałów wykończeniowych luźno zwisających, w szczególności w kurtynach, zasłonach, draperiach, kotarach oraz żaluzjach, za łatwo zapalne uważa się materiały, których właściwości określone w badaniach zgodnych z Polskimi Normami odnoszącymi się do zapalności i rozprzestrzeniania płomienia przez wyroby włókiennicze nie spełniają co najmniej jednego z kryteriów: 1) ti ≥ 4 s; 2) ts ≤ 30 s; 3) nie następuje przepalenie trzeciej nitki; 4) nie występują płonące krople. 2. Na drogach komunikacji ogólnej, służących celom ewakuacji, stosowanie materiałów i wyrobów budowlanych łatwo zapalnych jest zabronione."}], "487": [{"ref": "§ 4 rozp. w sprawie uzgadniania projektu pod względem ochrony ppoż.", "kind": "akt", "act": "uzgadnianie", "label": "§ 4", "text": "§ 4. […] Podstawę uzgodnienia stanowią niezbędne do stwierdzenia zgodności projektu z wymaganiami ochrony przeciwpożarowej dane dotyczące warunków ochrony przeciwpożarowej obiektu budowlanego, zależne od jego przeznaczenia, sposobu użytkowania, prowadzonego procesu technologicznego, sposobu magazynowania lub składowania, warunków technicznych oraz występujących w nim zagrożeń pożarowych, obejmujące: 1) w przypadku projektu zagospodarowania działki lub terenu, w szczególności: a) informacje o powierzchni zabudowy, wysokości i liczbie kondygnacji, b) informacje o klasyfikacji pożarowej z uwagi na przeznaczenie i sposób użytkowania, c) informacje o klasie odporności pożarowej oraz odporności ogniowej i stopniu rozprzestrzeniania ognia przez ściany zewnętrzne i dachy, d) informacje o występowaniu zagrożenia wybuchem, w tym informacje dotyczące pomieszczeń zagrożonych wybuchem oraz stref zagrożenia wybuchem w przestrzeni zewnętrznej, e) informacje o usytuowaniu z uwagi na bezpieczeństwo pożarowe, w tym informacje o odległościach od sąsiadujących obiektów budowlanych, działek lub terenów oraz parametrach wpływających na odległości dopuszczalne, f) informacje o przygotowaniu obiektu budowlanego i terenu do prowadzenia działań ratowniczych, w tym informacje o: – drogach pożarowych oraz dojściach dla ekip ratowniczych, – zaopatrzeniu w wodę do zewnętrznego gaszenia pożaru, w tym o wymaganej ilości wody do celów przeciwpożarowych, urządzeniach i innych rozwiązaniach w zakresie przeciwpożarowego zaopatrzenia w wodę, usytuowaniu źródeł wody do celów przeciwpożarowych, hydrantów zewnętrznych lub innych punktów poboru wody oraz stanowisk czerpania wody wraz z dojazdami dla pojazdów pożarniczych, g) informacje o rozwiązaniach zamiennych w stosunku do wymagań ochrony przeciwpożarowej, zastosowanych na podstawie zgody, o której mowa w art. 6c pkt 1 lub 2 ustawy z dnia 24 sierpnia 1991 r. o ochronie przeciwpożarowej, w zakresie rozwiązań objętych projektem zagospodarowania działki lub terenu; […]"}], "489": [{"ref": "PKN-CEN/TS 54-14:2020 – promień działania czujek punktowych i ich odległość od ścian", "kind": "norma"}], "490": [{"ref": "§ 277 ust. 1 i 2 WT – powierzchnia strefy pożarowej garażu zamkniętego", "kind": "akt", "act": "wt", "label": "§ 277", "text": "§ 277. 1. Powierzchnia strefy pożarowej w nadziemnym lub podziemnym garażu zamkniętym nie powinna przekraczać 5000 m2."}], "491": [{"ref": "§ 12 ust. 1 pkt 3 RW – strefy PM ponad 500 MJ/m2 z pomieszczeniem zagrożonym wybuchem", "kind": "akt", "act": "rw", "label": "§ 12", "text": "§ 12. 1. Drogę pożarową o utwardzonej nawierzchni, umożliwiającą dojazd pojazdów jednostek ochrony przeciwpożarowej do obiektu budowlanego o każdej porze roku, należy doprowadzić do: 1) budynku zawierającego strefę pożarową zakwalifikowaną do kategorii zagrożenia ludzi ZL I lub ZL II; 2) budynku należącego do grupy wysokości: średniowysoki, wysoki lub wysokościowy, zawierającego strefę pożarową zakwalifikowaną do kategorii zagrożenia ludzi ZL III, ZL IV lub ZL V; 3) budynku zawierającego strefę pożarową produkcyjną lub magazynową oraz do strefy pożarowej poza budynkiem, obejmującej urządzenia technologiczne, plac składowy lub wiatę, jeżeli gęstość obciążenia ogniowego wymienionych stref pożarowych przekracza 500 MJ/m2 i zachodzi co najmniej jeden z warunków: a) powierzchnia strefy pożarowej przekracza 1 000 m2, b) występuje pomieszczenie zagrożone wybuchem; […]"}, {"ref": "§ 12 ust. 1 pkt 4 RW – strefy PM poniżej 500 MJ/m2 i ponad 20 000 m2", "kind": "akt", "act": "rw", "label": "§ 12", "text": "§ 12. 1. Drogę pożarową o utwardzonej nawierzchni, umożliwiającą dojazd pojazdów jednostek ochrony przeciwpożarowej do obiektu budowlanego o każdej porze roku, należy doprowadzić do: 1) budynku zawierającego strefę pożarową zakwalifikowaną do kategorii zagrożenia ludzi ZL I lub ZL II; 2) budynku należącego do grupy wysokości: średniowysoki, wysoki lub wysokościowy, zawierającego strefę pożarową zakwalifikowaną do kategorii zagrożenia ludzi ZL III, ZL IV lub ZL V; 3) budynku zawierającego strefę pożarową produkcyjną lub magazynową oraz do strefy pożarowej poza budynkiem, obejmującej urządzenia technologiczne, plac składowy lub wiatę, jeżeli gęstość obciążenia ogniowego wymienionych stref pożarowych przekracza 500 MJ/m2 i zachodzi co najmniej jeden z warunków: a) powierzchnia strefy pożarowej przekracza 1 000 m2, b) występuje pomieszczenie zagrożone wybuchem; […]"}], "492": [{"ref": "§ 227 ust. 2 pkt 5 projektu WT z 9.06.2025 – drewniane elementy konstrukcji dachu hali sportowej", "kind": "akt", "act": "wt-projekt", "label": "§ 227", "text": "2. Elementy budynku, o których mowa w ust. 1, wykonuje się jako NRO, przy czym dopuszcza się SRO w przypadku: 1) elementów budynku, z wyłączeniem przekrycia dachu, w budynku o jednej kondygnacji nadziemnej ZL IV oraz PM, o maksymalnej gęstości obciążenia ogniowego strefy pożarowej do 500 MJ/m2; 2) ścian wewnętrznych i zewnętrznych w budynku PM niskim (N) o maksymalnej gęstości obciążenia ogniowego strefy pożarowej do 1000 MJ/m2; 3) ścian zewnętrznych w budynku niskim (N) ZL IV; […]"}, {"ref": "§ 212 ust. 3 WT – klasa „D” dla jednokondygnacyjnego budynku ZL I", "kind": "akt", "act": "wt", "label": "§ 212", "text": "3. Dopuszcza się obniżenie wymaganej klasy odporności pożarowej w budynkach wymienionych w poniższej tabeli do poziomu w niej określonego. Liczba kondygnacji nadziemnych ZL I ZL II ZL III 1 2 3 4 1 „D” „D” „D” 2*) „C” „C” „D” *) Gdy poziom stropu nad pierwszą kondygnacją nadziemną jest na wysokości nie większej niż 9 m nad poziomem terenu."}], "494": [{"ref": "PN-EN 13501-4 – klasyfikacja HOT 400/30 klap do systemów wentylacji pożarowej", "kind": "norma"}, {"ref": "PN-EN 12101-8 – klapy odcinające do systemów wentylacji pożarowej", "kind": "norma"}], "495": [{"ref": "§ 19 ust. 1 RPB – hydranty 25 w strefach ZL", "kind": "akt", "act": "rpb", "label": "§ 19", "text": "§ 19. 1. Hydranty 25 muszą być stosowane w strefach pożarowych zakwalifikowanych do kategorii zagrożenia ludzi ZL: 1) na każdej kondygnacji budynku wysokiego i wysokościowego, z wyjątkiem kondygnacji obejmującej wyłącznie strefę pożarową zakwalifikowaną do kategorii zagrożenia ludzi ZL IV; 2) na każdej kondygnacji budynku innego niż tymczasowy, niskiego i średniowysokiego: a) w strefie pożarowej o powierzchni przekraczającej 200 m2, zakwalifikowanej do kategorii zagrożenia ludzi ZL I, ZL II lub ZL V, b) w strefie pożarowej zakwalifikowanej do kategorii zagrożenia ludzi ZL III: – o powierzchni przekraczającej 200 m2 w budynku średniowysokim, przy czym jeżeli jest to strefa pożarowa obejmująca tylko pierwszą kondygnację nadziemną, a nad nią znajdują się wyłącznie strefy pożarowe ZL IV, jedynie wtedy, gdy powierzchnia tej strefy pożarowej przekracza 1000 m2, – o powierzchni przekraczającej  […]"}, {"ref": "§ 19 ust. 3 RPB – hydranty 52", "kind": "akt", "act": "rpb", "label": "§ 19", "text": "3. Hydranty 52 muszą być stosowane: 1) w strefie pożarowej produkcyjnej i magazynowej o gęstości obciążenia ogniowego przekraczającej 500 MJ/m2 i powierzchni przekraczającej 200 m2; 2) w strefie pożarowej produkcyjnej i magazynowej o gęstości obciążenia ogniowego nieprzekraczającej 500 MJ/m2, w której znajduje się pomieszczenie o powierzchni przekraczającej 100 m2 i gęstości obciążenia ogniowego przekraczającej 1 000 MJ/m2; 3) przy wejściu do pomieszczeń magazynowych lub technicznych o powierzchni przekraczającej 200 m2 i gęstości obciążenia ogniowego przekraczającej 500 MJ/m2, usytuowanych w strefie pożarowej zakwalifikowanej do kategorii zagrożenia ludzi ZL I, ZL II, ZL III lub ZL V, znajdującej się w budynku niskim albo średniowysokim."}], "496": [{"ref": "PN-B-02857:2017-04 – przeciwpożarowe zbiorniki wodne", "kind": "norma"}], "497": [{"ref": "§ 246 ust. 2 WT – klatki schodowe w budynkach wysokich i wysokościowych", "kind": "akt", "act": "wt", "label": "§ 246", "text": "2. Klatki schodowe i przedsionki przeciwpożarowe, stanowiące drogę ewakuacyjną w budynku wysokim (W) dla stref pożarowych innych niż ZL IV i PM oraz w budynku wysokościowym (WW), powinny być wyposażone w urządzenia zapobiegające ich zadymieniu."}, {"ref": "§ 211 ust. 1 WT – wyłączenia dla budynków zakwaterowania osadzonych", "kind": "akt", "act": "wt", "label": "§ 211", "text": "§ 211. 1. Przepisów § 242 ust. 1, § 243 ust. 1, § 245 pkt 2 oraz § 256 ust. 3, w zakresie kategorii ZL V, nie stosuje się do budynków i pomieszczeń przeznaczonych do zakwaterowania osób osadzonych."}], "498": [{"ref": "§ 245 WT – liczba klatek schodowych", "kind": "akt", "act": "wt", "label": "§ 245", "text": "§ 245. Klatki schodowe przeznaczone do ewakuacji ze strefy pożarowej: 1) ZL II w budynku niskim (N), 2) ZL I, ZL II, ZL III lub ZL V w budynku średniowysokim (SW), 3) PM o gęstości obciążenia ogniowego powyżej 500 MJ/m2 lub zawierającej pomieszczenie zagrożone wybuchem w budynku niskim (N) bądź średniowysokim (SW) – powinny być obudowane i zamykane drzwiami dymoszczelnymi oraz wyposażone w urządzenia zapobiegające zadymieniu lub służące do usuwania dymu, uruchamiane samoczynnie za pomocą systemu wykrywania dymu."}], "499": [{"ref": "§ 216 ust. 7 WT – wymagania dla stropu antresoli dla więcej niż 10 osób", "kind": "akt", "act": "wt", "label": "§ 216", "text": "7. Strop tworzący w pomieszczeniu dodatkowy poziom – antresolę, przeznaczoną do użytku dla więcej niż 10 osób, a także jej konstrukcja nośna, powinny odpowiadać wymaganiom wynikającym z klasy odporności pożarowej budynku, lecz nie mniejszym niż dla klasy „D”, z zastrzeżeniem § 214."}, {"ref": "§ 212 ust. 4 WT – klasa „B” dla wielokondygnacyjnego budynku wysokiego PM", "kind": "akt", "act": "wt", "label": "§ 212", "text": "4. Wymaganą klasę odporności pożarowej dla budynku PM oraz IN, z zastrzeżeniem § 282, określa poniższa tabela: Maksymalna gęstość obciążenia ogniowego strefy pożarowej w budynku Q [MJ/m2] Budynek o jednej kondygnacji nadziemnej (bez ograniczenia wysokości) Budynek wielokondygnacyjny niski średniowysoki wysoki wysokościowy (N) (SW) (W) (WW) 1 2 3 4 5 6 Q ≤ 500 „E” „D” „C” „B” „B” 500 < Q ≤ 1000 „D” „D” „C” „B” „B” 1000 < Q ≤ 2000 „C” „C” „C” „B” „B” 2000 < Q ≤ 4000 „B” „B” „B” * * Q > 4000 „A” „A” „A” * * * – Zgodnie z § 228 ust. 1 nie mogą występować takie budynki."}, {"ref": "§ 214 WT – wyłączenie budynków wysokich wielokondygnacyjnych z obniżenia klasy", "kind": "akt", "act": "wt", "label": "§ 214", "text": "§ 214. W budynkach wyposażonych w stałe samoczynne urządzenia gaśnicze wodne, z wyjątkiem budynków ZL II oraz wielokondygnacyjnych budynków wysokich (W) i wysokościowych (WW), dopuszcza się: 1) obniżenie klasy odporności pożarowej budynku o jedną w stosunku do wynikającej z § 212; 2) przyjęcie klasy „E” odporności pożarowej dla budynku jednokondygnacyjnego."}], "500": [{"ref": "§ 24 ust. 3 pkt 3 RPB – zmniejszenie pojemności zbiornika przy zasilaniu z sieci", "kind": "akt", "act": "rpb", "label": "§ 24", "text": "3. Dopuszcza się: 1) zmniejszenie pojemności zbiorników, o których mowa w ust. 2, do 50 m3, w przypadku budynków wysokich i wysokościowych o wysokości do 100 m: a) zawierających na wysokości powyżej 12 m jedynie strefy pożarowe zakwalifikowane do kategorii zagrożenia ludzi ZL IV, niezależnie od ich powierzchni, lub b) niezawierających stref pożarowych o powierzchni przekraczającej 750 m2; 2) stosowanie jednego wspólnego zbiornika o pojemności co najmniej 100 m3 dla grupy budynków wysokich i wysokościowych wzniesionych obok siebie, jeżeli zbiornik nie jest oddalony od żadnego z budynków o więcej niż 100 m; 3) stosowanie zbiorników o pojemności zmniejszonej niż wymienione w: a) ust. 2 i ust. 3 pkt 2 ‒ do 50 m3 w przypadku zapewnienia zasilania tych zbiorników w wodę z zewnętrznej sieci wodociągowej przeciwpożarowej o wydajności nie mniejszej niż 10 dm3/s, b) ust. 2 i ust. […]"}, {"ref": "§ 24 ust. 5 RPB – dodatkowa nasada 75 mm jako warunek dopuszczeń", "kind": "akt", "act": "rpb", "label": "§ 24", "text": "5. Warunkiem zastosowania dopuszczeń, o których mowa w ust. 3 pkt 3 i ust. 4, jest wyprowadzenie w elewacjach budynku, od strony drogi pożarowej, dodatkowej nasady o średnicy 75 mm, umożliwiającej zasilanie instalacji wodociągowej przeciwpożarowej z samochodów gaśniczych."}], "501": [{"ref": "§ 271 ust. 1, 5 i 7 WT – odległości między budynkami, zwiększenie o 100% i zmniejszenie o 25%", "kind": "akt", "act": "wt", "label": "§ 271", "text": "§ 271. 1. Odległość między zewnętrznymi ścianami budynków niebędącymi ścianami oddzielenia przeciwpożarowego, a mającymi na powierzchni większej niż 65% klasę odporności ogniowej (E), określoną w § 216 ust. 1 w 5 kolumnie tabeli, nie powinna, z zastrzeżeniem ust. 2 i 3, być mniejsza niż odległość w metrach określona w poniższej tabeli: Rodzaj budynku oraz dla budynku PM maksymalna gęstość obciążenia ogniowego strefy pożarowej PM Q w MJ/m2 Rodzaj budynku oraz dla budynku PM maksymalna gęstość obciążenia ogniowego strefy pożarowej PM Q w MJ/m2 ZL IN PM Q ≤ 1000 1000 < Q ≤ 4000 Q > 4000 1 2 3 4 5 6 ZL 8 8 8 15 20 IN 8 8 8 15 20 PM Q ≤ 1000 8 8 8 15 20 PM 1000 < Q ≤ 4000 15 15 15 15 20 PM Q > 4000 20 20 20 20 20"}, {"ref": "§ 212 ust. 4 WT – klasa „B” dla PM wielokondygnacyjnego przy Q od 2000 do 4000 MJ/m2", "kind": "akt", "act": "wt", "label": "§ 212", "text": "4. Wymaganą klasę odporności pożarowej dla budynku PM oraz IN, z zastrzeżeniem § 282, określa poniższa tabela: Maksymalna gęstość obciążenia ogniowego strefy pożarowej w budynku Q [MJ/m2] Budynek o jednej kondygnacji nadziemnej (bez ograniczenia wysokości) Budynek wielokondygnacyjny niski średniowysoki wysoki wysokościowy (N) (SW) (W) (WW) 1 2 3 4 5 6 Q ≤ 500 „E” „D” „C” „B” „B” 500 < Q ≤ 1000 „D” „D” „C” „B” „B” 1000 < Q ≤ 2000 „C” „C” „C” „B” „B” 2000 < Q ≤ 4000 „B” „B” „B” * * Q > 4000 „A” „A” „A” * * * – Zgodnie z § 228 ust. 1 nie mogą występować takie budynki."}, {"ref": "§ 214 WT – obniżenie klasy w budynku z urządzeniami gaśniczymi", "kind": "akt", "act": "wt", "label": "§ 214", "text": "§ 214. W budynkach wyposażonych w stałe samoczynne urządzenia gaśnicze wodne, z wyjątkiem budynków ZL II oraz wielokondygnacyjnych budynków wysokich (W) i wysokościowych (WW), dopuszcza się: 1) obniżenie klasy odporności pożarowej budynku o jedną w stosunku do wynikającej z § 212; 2) przyjęcie klasy „E” odporności pożarowej dla budynku jednokondygnacyjnego."}], "503": [{"ref": "§ 228 ust. 1 WT", "kind": "akt", "act": "wt", "label": "§ 228", "text": "§ 228. 1. Dopuszczalne powierzchnie stref pożarowych PM, z wyjątkiem garaży, określa poniższa tabela: Rodzaj stref pożarowych Gęstość obciążenia ogniowego Q [MJ/m2] Dopuszczalna powierzchnia strefy pożarowej w m2 w budynku o jednej kondygnacji nadziemnej (bez ograniczenia wysokości) w budynku wielokondygnacyjnym niskim i średniowysokim (N) i (SW) wysokim i wysokościowym (W) i (WW) 1 2 3 4 5 Strefy pożarowe z pomieszczeniem zagrożonym wybuchem Q > 4000 2000 < Q ≤ 4000 1000 < Q ≤ 2000 500 < Q ≤ 1000 Q ≤ 500 1000 2000 4000 6000 8000 * * 1000 2000 3000 * * * 500 1000 Strefy pożarowe pozostałe Q > 4000 2000 < Q ≤ 4000 1000 < Q ≤ 2000 500 < Q ≤ 1000 Q ≤ 500 2000 4000 8000 15 000 20 000 1000 2000 4000 8000 10 000 * * 1000 2500 5000 * Nie dopuszcza się takich przypadków."}, {"ref": "§ 229 ust. 1 pkt 2 WT", "kind": "akt", "act": "wt", "label": "§ 229", "text": "§ 229. 1. Dopuszcza się powiększenie powierzchni stref pożarowych, o których mowa w § 228, pod warunkiem ich ochrony: 1) stałymi samoczynnymi urządzeniami gaśniczymi wodnymi – o 100%; 2) samoczynnymi urządzeniami oddymiającymi – o 50%."}], "504": [{"ref": "§ 9 ust. 1 i 2 RW – sieć wodociągowa przeciwpożarowa", "kind": "akt", "act": "rw", "label": "§ 9", "text": "§ 9. 1. Sieć wodociągowa stanowiąca źródło wody do celów przeciwpożarowych, zwana dalej „siecią wodociągową przeciwpożarową”, powinna być zasilana z pompowni przeciwpożarowej, zbiornika wieżowego, studni lub innych urządzeń, zapewniających wymaganą wydajność i ciśnienie w hydrantach zewnętrznych, nawet tych niekorzystnie ulokowanych, przez co najmniej 2 godziny."}], "505": [{"ref": "§ 10 RW – hydranty zewnętrzne, stanowisko czerpania", "kind": "akt", "act": "rw", "label": "§ 10", "text": "§ 10. […] 3) hydranty powinny być usytuowane w miejscach dostępnych z głównych dróg komunikacyjnych na terenie jednostki osadniczej; 4) miejsce usytuowania hydrantu należy oznakować znakami zgodnymi z Polskimi Normami wraz z podaniem na znaku dodatkowym wielkości charakterystycznych hydrantu; 5) przy hydrancie należy przewidzieć stanowisko czerpania wody o wymiarach zapewniających swobodny dostęp do hydrantu; 6) na stanowisku czerpania wody należy umieścić zakaz parkowania. 10. Określenia potrzeb w zakresie instalowania hydrantów, o których mowa w ust. 9, dokonują właściwe miejscowo organy Państwowej Straży Pożarnej w ramach opiniowania projektów studium uwarunkowań i kierunków zagospodarowania przestrzennego gminy oraz projektów miejscowych planów zagospodarowania przestrzennego, w trybie określonym w przepisach o planowaniu i zagospodarowaniu przestrzennym. 11. […]"}], "506": [{"ref": "art. 7 UOP – dopuszczenie wyrobów służących ochronie przeciwpożarowej", "kind": "akt", "act": "uop", "label": "art. 7", "text": "Art. 7. 1. Wyroby służące zapewnieniu bezpieczeństwa publicznego lub ochronie zdrowia i życia oraz mienia, wprowadzane do użytkowania w jednostkach ochrony przeciwpożarowej oraz wykorzystywane przez te jednostki do alarmowania o pożarze lub innym zagrożeniu oraz do prowadzenia działań ratowniczych, a także wyroby stanowiące podręczny sprzęt gaśniczy, mogą być stosowane wyłącznie po uprzednim uzyskaniu dopuszczenia do użytkowania. 2. Dopuszczenia do użytkowania wyrobów, o których mowa w ust. 1, zwane dalej „dopuszczeniami”, w formie świadectwa dopuszczenia, wydają instytuty badawcze Państwowej Straży Pożarnej wskazane przez ministra właściwego do spraw wewnętrznych. 3. Dopuszczenia są wydawane na czas określony, nie dłuższy niż 5 lat. 4. […]"}], "507": [{"ref": "PN-EN 12845+A1:2020 – hydrofory jako zasilanie wodą urządzeń tryskaczowych", "kind": "norma"}], "508": [{"ref": "§ 6–7 RW – wymagana ilość wody dla stref poza budynkami", "kind": "akt", "act": "rw", "label": "§ 6", "text": "§ 6. […] 6. Wymaganą ilość wody do celów przeciwpożarowych do zewnętrznego gaszenia pożaru dla zbiorników z produktami naftowymi, z wyjątkiem występujących na stacjach paliw i stacjach gazu płynnego oraz wymienionych w ust. 5, określa się zgodnie z przepisami rozporządzenia Ministra Gospodarki z dnia 21 listopada 2005 r. w sprawie warunków technicznych, jakim powinny odpowiadać bazy i stacje paliw płynnych, rurociągi przesyłowe dalekosiężne służące do transportu ropy naftowej i produktów naftowych i ich usytuowanie (Dz. U. Nr 243, poz. 2063 oraz z 2007 r. Nr 240, poz. 1753). 7. Wymaganą ilość wody do celów przeciwpożarowych do zewnętrznego gaszenia pożaru dla urządzeń technologicznych oraz składów i magazynów z gazami palnymi i cieczami o temperaturze zapłonu do 373,15 K (100 °C), zlokalizowanych poza budynkami, określa tabela nr 4 załącznika do rozporządzenia. 8. […]"}, {"ref": "PN-B-02857 – przeciwpożarowe zbiorniki wodne (obliczanie zapasu)", "kind": "norma"}], "509": [{"ref": "§ 5 ust. 1 rozp. MRiRW z 13.01.2023 (budowle rolnicze) – dojścia i dojazdy dla jednostek ochrony przeciwpożarowej", "kind": "akt", "act": "rolnicze", "label": "§ 5", "text": "§ 5. 1. Do budowli rolniczych i urządzeń budowlanych z nimi związanych zapewnia się dojścia i dojazdy odpowiednie do przeznaczenia i sposobu użytkowania tych budowli i urządzeń oraz przystosowane do prowadzenia działań ratowniczych przez jednostki ochrony przeciwpożarowej, w tym umożliwiające dojazd pojazdów jednostek ochrony przeciwpożarowej o każdej porze roku, jeżeli gęstość obciążenia ogniowego strefy pożarowej przekracza 500 MJ/m2 i zachodzi co najmniej jeden z warunków: 1) powierzchnia strefy pożarowej przekracza 1000 m2; 2) występuje strefa zagrożenia wybuchem wewnątrz budowli rolniczych."}], "510": [{"ref": "PN-EN 1838:2025-05 – oświetlenie strefy otwartej (antypaniczne)", "kind": "norma"}], "511": [{"ref": "PN-EN 12101-13:2022 pkt 5.2 – zastosowanie klasy 1 i klasy 2", "kind": "norma"}, {"ref": "PN-EN 12101-13:2022 tabela 1 – minimalna różnica ciśnień i prędkość przepływu", "kind": "norma"}], "512": [{"ref": "PKN-CEN/TS 54-14:2020 – wpływ wentylacji i ruchu powietrza na rozmieszczenie czujek", "kind": "norma"}], "514": [{"ref": "PN-EN 12845+A1:2020 – przyłączanie tryskaczy", "kind": "norma"}], "515": [{"ref": "PN-EN 12845+A1:2020 – uzupełnianie zapasu wody", "kind": "norma"}], "516": [{"ref": "PN-EN 15004-1 – stałe urządzenia gaśnicze gazowe, urządzenie wstrzymujące", "kind": "norma"}], "517": [{"ref": "§ 249 ust. 3 WT – biegi i spoczniki z materiałów niepalnych o klasie R 60 lub R 30", "kind": "akt", "act": "wt", "label": "§ 249", "text": "3. Biegi i spoczniki schodów oraz pochylnie służące do ewakuacji powinny być wykonane z materiałów niepalnych i mieć klasę odporności ogniowej co najmniej: 1) w budynkach o klasie odporności pożarowej „A”, „B” i „C” – R 60; 2) w budynkach o klasie odporności pożarowej „D” i „E” – R 30."}, {"ref": "§ 249 ust. 4 WT – zwolnienie dla klatek z przedsionkami przeciwpożarowymi", "kind": "akt", "act": "wt", "label": "§ 249", "text": "4. Wymaganie klasy odporności ogniowej, o którym mowa w ust. 3, nie dotyczy klatek schodowych wydzielonych na każdej kondygnacji przedsionkami przeciwpożarowymi oraz schodów na antresolę w pomieszczeniu, w którym się ona znajduje, jeżeli antresola ta jest przeznaczona do użytku nie więcej niż 10 osób."}, {"ref": "§ 246 ust. 1 WT – przedsionki przeciwpożarowe w budynkach W i WW", "kind": "akt", "act": "wt", "label": "§ 246", "text": "§ 246. 1. W budynku wysokim (W) i wysokościowym (WW), z zastrzeżeniem ust. 4, należy zapewnić możliwość ewakuacji do co najmniej dwóch klatek schodowych, które powinny być obudowane i oddzielone od poziomych dróg komunikacyjnych lub ewakuacyjnych oraz pomieszczeń, przedsionkiem przeciwpożarowym, odpowiadającym wymaganiom określonym w § 232."}], "519": [{"ref": "PN-EN 81-72:2020-12 – dźwigi dla straży pożarnej", "kind": "norma"}], "520": [{"ref": "§ 7 pkt 1 rozp. MRiRW z 13.01.2023 – odległości zbiorników biogazu rolniczego", "kind": "akt", "act": "rolnicze", "label": "§ 7", "text": "§ 7. Odległości komór fermentacyjnych i zbiorników biogazu rolniczego powinny wynosić co najmniej: 1) 20 m od pomieszczeń przeznaczonych na pobyt ludzi oraz od budynków inwentarskich; 2) 20 m od budynków innych niż budynki inwentarskie, niepowiązanych technologicznie z instalacją służącą do otrzymywania biogazu rolniczego; 3) 15 m od składu węgla i koksu; 4) 15 m od komór fermentacyjnych i zbiorników biogazu rolniczego, które są elementem odrębnych instalacji służących do otrzymywania biogazu rolniczego; 5) 25 m od studni lub ujęć wód, jeżeli nie ustanowiono strefy ochronnej na podstawie przepisów ustawy z dnia 20 lipca 2017 r. – Prawo wodne (Dz. U. z 2022 r. poz. 2625 i 2687), linii brzegu wód powierzchniowych oraz pasa morskiego; 6) 15 m od silosów na zboże i pasze; 7) 5 m od granicy działki sąsiedniej."}], "521": [{"ref": "§ 234 ust. 1 i 3 WT – przepusty instalacyjne", "kind": "akt", "act": "wt", "label": "§ 234", "text": "§ 234. 1. Przepusty instalacyjne w elementach oddzielenia przeciwpożarowego powinny mieć klasę odporności ogniowej (E I) wymaganą dla tych elementów."}, {"ref": "§ 216 ust. 1 WT – klasa B, ściana wewnętrzna EI 30", "kind": "akt", "act": "wt", "label": "§ 216", "text": "§ 216. 1. Elementy budynku, odpowiednio do jego klasy odporności pożarowej, powinny spełniać, z zastrzeżeniem § 213 oraz § 237 ust. 9, co najmniej wymagania określone w poniższej tabeli: Klasa odporności pożarowej budynku Klasa odporności ogniowej elementów budynku5) *) główna konstrukcja nośna konstrukcja dachu strop1) ściana zewnętrzna1), 2) ściana wewnętrzna1) przekrycie dachu3) 1 2 3 4 5 6 7 „A” R 240 R 30 R E I 120 E I 120 (o↔i) E I 60 R E 30 „B” R 120 R 30 R E I 60 E I 60 (o↔i) E I 304) R E 30 „C” R 60 R 15 R E I 60 E I 30 (o↔i) E I 154) R E 15 „D” R 30 (–) R E I 30 E I 30 (o↔i) (–) (–) „E” (–) (–) (–) (–) (–) (–) *) Z zastrzeżeniem § 219 ust. 1. […]"}], "522": [{"ref": "PN-B-02877-4:2025-07 – wymiary stref dymowych", "kind": "norma"}], "524": [{"ref": "PN-EN 12845+A1:2020 – tryskacze w regałach", "kind": "norma"}], "525": [{"ref": "§ 249 ust. 3 pkt 1 WT – biegi i spoczniki R 60 w budynkach klasy A, B i C", "kind": "akt", "act": "wt", "label": "§ 249", "text": "3. Biegi i spoczniki schodów oraz pochylnie służące do ewakuacji powinny być wykonane z materiałów niepalnych i mieć klasę odporności ogniowej co najmniej: 1) w budynkach o klasie odporności pożarowej „A”, „B” i „C” – R 60; 2) w budynkach o klasie odporności pożarowej „D” i „E” – R 30."}, {"ref": "§ 249 ust. 5 WT – schody z materiałów palnych tylko w klasie D lub E", "kind": "akt", "act": "wt", "label": "§ 249", "text": "5. W budynku niskim o klasie odporności pożarowej „D” lub „E” w obudowanych klatkach schodowych, zamykanych drzwiami o klasie odporności ogniowej co najmniej E I 30, dopuszcza się wykonanie biegów i spoczników schodów z materiałów palnych."}, {"ref": "§ 212 ust. 2 WT – klasa C dla niskiego budynku ZL V", "kind": "akt", "act": "wt", "label": "§ 212", "text": "2. Wymaganą klasę odporności pożarowej dla budynku, zaliczonego do jednej kategorii ZL, określa poniższa tabela: Budynek ZL I ZL II ZL III ZL IV ZL V 1 2 3 4 5 6 niski (N) „B” „B” „C” „D” „C” średniowysoki (SW) „B” „B” „B” „C” „B” wysoki (W) „B” „B” „B” „B” „B” wysokościowy (WW) „A” „A” „A” „B” „A”"}], "526": [{"ref": "§ 10 RW – sieć wodociągowa przeciwpożarowa", "kind": "akt", "act": "rw", "label": "§ 10", "text": "§ 10. […] 2) dla hydrantu nadziemnego DN 100 — 15 dm3/s; 3) dla hydrantu podziemnego DN 80 — 10 dm3/s; 4) dla hydrantu nadziemnego DN 80 na sieci, o której mowa w § 9 ust. 2 — 5 dm3/s. www.rcl.gov.pl Dziennik Ustaw Nr 124 — 9067 — Poz. 1030 9. Dla zapewnienia możliwości intensywnego czerpania wody do celów przeciwpożarowych na sieciach wodociągowych o średnicy nominalnej nie mniejszej niż DN 250 powinny być instalowane hydranty nadziemne, spełniające następujące wymagania: 1) średnica nominalna hydrantu powinna wynosić DN 100 lub DN 150; 2) wydajność nominalna przy ciśnieniu nominalnym 0,2 MPa mierzonym na zaworze hydrantowym podczas poboru wody nie może być mniejsza niż 20 dm3/s; 3) hydranty powinny być usytuowane w miejscach dostępnych z głównych dróg komunikacyjnych na terenie jednostki osadniczej; […]"}], "527": [{"ref": "§ 256 ust. 3 (odnośnik 2) i ust. 4 WT – długości dojść ewakuacyjnych", "kind": "akt", "act": "wt", "label": "§ 256", "text": "3. Dopuszczalne długości dojść ewakuacyjnych w strefach pożarowych określa poniższa tabela: Rodzaj strefy pożarowej Długość dojścia w m przy jednym dojściu przy co najmniej 2 dojściach1) 1 2 3 Z pomieszczeniem zagrożonym wybuchem 10 40 PM o gęstości obciążenia ogniowego Q > 500 MJ/m2 bez pomieszczenia zagrożonego wybuchem 302) 60 PM o gęstości obciążenia ogniowego Q ≤ 500 MJ/m2 bez pomieszczenia zagrożonego wybuchem 602) 100 ZL I, II i V 10 40 ZL III 302) 60 ZL IV 602) 100 1) Dla dojścia najkrótszego, przy czym dopuszcza się dla drugiego dojścia długość większą o 100% od najkrótszego. Dojścia te nie mogą się pokrywać ani krzyżować, przy czym dopuszcza się ich wspólny początkowy przebieg na długości nie większej niż 2 m. 2) W tym nie więcej niż 20 m na poziomej drodze ewakuacyjnej."}], "528": [{"ref": "§ 249 ust. 6 WT – ściana zewnętrzna przy klatce schodowej", "kind": "akt", "act": "wt", "label": "§ 249", "text": "6. Odległość między ścianą zewnętrzną, stanowiącą obudowę klatki schodowej przeznaczonej do ewakuacji, o której mowa w § 245, 246 i 256 ust. 2, a inną ścianą zewnętrzną tego samego lub innego budynku powinna być ustalona zgodnie z § 271. Przepisu nie stosuje się, jeżeli co najmniej jedna z tych ścian posiada co najmniej klasę odporności ogniowej zgodnie z § 216, jak dla stropu budynku z tą klatką schodową, w pasie terenu określonym zgodnie z § 271."}, {"ref": "§ 271 ust. 1, 4 i 11 WT – odległości i pas terenu przy ścianach pod kątem", "kind": "akt", "act": "wt", "label": "§ 271", "text": "§ 271. 1. Odległość między zewnętrznymi ścianami budynków niebędącymi ścianami oddzielenia przeciwpożarowego, a mającymi na powierzchni większej niż 65% klasę odporności ogniowej (E), określoną w § 216 ust. 1 w 5 kolumnie tabeli, nie powinna, z zastrzeżeniem ust. 2 i 3, być mniejsza niż odległość w metrach określona w poniższej tabeli: Rodzaj budynku oraz dla budynku PM maksymalna gęstość obciążenia ogniowego strefy pożarowej PM Q w MJ/m2 Rodzaj budynku oraz dla budynku PM maksymalna gęstość obciążenia ogniowego strefy pożarowej PM Q w MJ/m2 ZL IN PM Q ≤ 1000 1000 < Q ≤ 4000 Q > 4000 1 2 3 4 5 6 ZL 8 8 8 15 20 IN 8 8 8 15 20 PM Q ≤ 1000 8 8 8 15 20 PM 1000 < Q ≤ 4000 15 15 15 15 20 PM Q > 4000 20 20 20 20 20"}, {"ref": "§ 216 ust. 1 i 2 WT – klasa REI 60 stropu w klasie B i nierozprzestrzenianie ognia", "kind": "akt", "act": "wt", "label": "§ 216", "text": "§ 216. 1. Elementy budynku, odpowiednio do jego klasy odporności pożarowej, powinny spełniać, z zastrzeżeniem § 213 oraz § 237 ust. 9, co najmniej wymagania określone w poniższej tabeli: Klasa odporności pożarowej budynku Klasa odporności ogniowej elementów budynku5) *) główna konstrukcja nośna konstrukcja dachu strop1) ściana zewnętrzna1), 2) ściana wewnętrzna1) przekrycie dachu3) 1 2 3 4 5 6 7 „A” R 240 R 30 R E I 120 E I 120 (o↔i) E I 60 R E 30 „B” R 120 R 30 R E I 60 E I 60 (o↔i) E I 304) R E 30 „C” R 60 R 15 R E I 60 E I 30 (o↔i) E I 154) R E 15 „D” R 30 (–) R E I 30 E I 30 (o↔i) (–) (–) „E” (–) (–) (–) (–) (–) (–) *) Z zastrzeżeniem § 219 ust. 1. […]"}], "529": [{"ref": "§ 6, § 8 RW – zapas wody do zewnętrznego gaszenia", "kind": "akt", "act": "rw", "label": "§ 6", "text": "§ 6. […] 2. W przypadku gdy w obiektach budowlanych produkcyjnych i magazynowych urządzenia i zasoby wody, o których mowa w ust. 1, nie zapewniają wymaganej ilości do celów przeciwpożarowych do zewnętrznego gaszenia pożaru, wykorzystuje się urządzenia służące do dostarczania wody do jednostek osadniczych lub uzupełniające źródła wody, o których mowa w § 4 ust. 5. 3. Wymaganą ilość wody do celów przeciwpożarowych dla obiektów budowlanych produkcyjnych i magazynowych, z wyjątkiem wymienionych w ust. 4—8, służącą do zewnętrznego gaszenia pożaru, określa się, biorąc pod uwagę tę strefę pożarową, dla której jest ona największa, zgodnie z tabelą nr 2 załącznika do rozporządzenia. www.rcl.gov.pl Dziennik Ustaw Nr 124 — 9065 — Poz. 1030 4. Wymagana ilość wody do celów przeciwpożarowych do zewnętrznego gaszenia pożaru dla stacji paliw i stacji gazu płynnego oraz stacji gazu ziemnego wynosi 10 dm3/s. 5. […]"}], "530": [{"ref": "PN-B-02877-4:2025-07 – powietrze kompensacyjne", "kind": "norma"}], "531": [{"ref": "§ 212 ust. 9 WT – rozdzielnia zasilająca urządzenia przeciwpożarowe jako odrębna strefa pożarowa", "kind": "akt", "act": "wt", "label": "§ 212", "text": "9. Pomieszczenia, w których są umieszczone przeciwpożarowe zbiorniki wody lub innych środków gaśniczych, pompy wodne instalacji przeciwpożarowych, maszynownie wentylacji do celów przeciwpożarowych oraz rozdzielnie elektryczne, zasilające, niezbędne podczas pożaru, instalacje i urządzenia, powinny stanowić odrębną strefę pożarową."}, {"ref": "§ 212 ust. 7 WT – klasa co najmniej „C” dla części podziemnej", "kind": "akt", "act": "wt", "label": "§ 212", "text": "7. Klasa odporności pożarowej części budynku nie powinna być niższa od klasy odporności pożarowej części budynku położonej nad nią, przy czym dla części podziemnej nie powinna być ona niższa niż „C”."}, {"ref": "§ 232 ust. 4 WT – REI 120 dla klasy „B” i „C”", "kind": "akt", "act": "wt", "label": "§ 232", "text": "4. Wymaganą klasę odporności ogniowej elementów oddzielenia przeciwpożarowego oraz zamknięć znajdujących się w nich otworów określa poniższa tabela: Klasa odporności pożarowej budynku Klasa odporności ogniowej elementów oddzielenia przeciwpożarowego drzwi przeciwpożarowych lub innych zamknięć przeciwpożarowych drzwi z przedsionka przeciwpożarowego ścian i stropów, z wyjątkiem stropów w ZL stropów w ZL na korytarz i do pomieszczenia na klatkę schodową*) 1 2 3 4 5 6 „A” R E I 240 R E I 120 E I 120 E I 60 E 60 „B” i „C” R E I 120 R E I 60 E I 60 E I 30 E 30 „D” i „E” R E I 60 R E I 30 E I 30 E I 15 E 15 *) Dopuszcza się osadzenie tych drzwi w ścianie o klasie odporności ogniowej, określonej dla drzwi w kol. 6, znajdującej się między przedsionkiem a klatką schodową."}], "532": [{"ref": "§ 262 ust. 2 WT – podział przestrzeni nad sufitem podwieszonym", "kind": "akt", "act": "wt", "label": "§ 262", "text": "2. Przestrzeń między sufitem podwieszonym i stropem powinna być podzielona na sektory o powierzchni nie większej niż 1000 m2, a w korytarzach – przegrodami co 50 m, wykonanymi z materiałów niepalnych."}, {"ref": "§ 243 ust. 1 i 2 WT – podział korytarzy co 50 m i wyłączenie", "kind": "akt", "act": "wt", "label": "§ 243", "text": "§ 243. 1. Korytarze stanowiące drogę ewakuacyjną w strefach pożarowych ZL powinny być podzielone na odcinki nie dłuższe niż 50 m przy zastosowaniu przegród z drzwiami dymoszczelnymi lub innych urządzeń technicznych, zapobiegających rozprzestrzenianiu się dymu."}, {"ref": "§ 247 ust. 1 WT – zabezpieczenie przed zadymieniem w budynkach W i WW", "kind": "akt", "act": "wt", "label": "§ 247", "text": "§ 247. 1. W budynku wysokim (W) i wysokościowym (WW), w strefach pożarowych innych niż ZL IV, należy zastosować rozwiązania techniczno-budowlane zabezpieczające przed zadymieniem poziomych dróg ewakuacyjnych."}], "533": [{"ref": "§ 12 RW – parametry drogi pożarowej", "kind": "akt", "act": "rw", "label": "§ 12", "text": "§ 12. […] 2) budynku należącego do grupy wysokości: średniowysoki, wysoki lub wysokościowy, zawierającego strefę pożarową zakwalifikowaną do kategorii zagrożenia ludzi ZL III, ZL IV lub ZL V; 3) budynku zawierającego strefę pożarową produkcyjną lub magazynową oraz do strefy pożarowej poza budynkiem, obejmującej urządzenia technologiczne, plac składowy lub wiatę, jeżeli gęstość obciążenia ogniowego wymienionych stref pożarowych przekracza 500 MJ/m2 i zachodzi co najmniej jeden z warunków: a) powierzchnia strefy pożarowej przekracza 1 000 m2, b) występuje pomieszczenie zagrożone wybuchem; 4) budynku zawierającego strefę pożarową produkcyjną lub magazynową o gęstości obciążenia ogniowego poniżej 500 MJ/m2 o powierzchni przekraczającej 20 000 m2; […]"}], "534": [{"ref": "§ 245 WT – liczba klatek schodowych w budynkach wysokich", "kind": "akt", "act": "wt", "label": "§ 245", "text": "§ 245. Klatki schodowe przeznaczone do ewakuacji ze strefy pożarowej: 1) ZL II w budynku niskim (N), 2) ZL I, ZL II, ZL III lub ZL V w budynku średniowysokim (SW), 3) PM o gęstości obciążenia ogniowego powyżej 500 MJ/m2 lub zawierającej pomieszczenie zagrożone wybuchem w budynku niskim (N) bądź średniowysokim (SW) – powinny być obudowane i zamykane drzwiami dymoszczelnymi oraz wyposażone w urządzenia zapobiegające zadymieniu lub służące do usuwania dymu, uruchamiane samoczynnie za pomocą systemu wykrywania dymu."}], "535": [{"ref": "PKN-CEN/TS 54-14:2020 – dobór czujek płomienia", "kind": "norma"}], "536": [{"ref": "§ 24 ust. 3 pkt 1 RPB – zmniejszenie zbiornika do 50 m3", "kind": "akt", "act": "rpb", "label": "§ 24", "text": "3. Dopuszcza się: 1) zmniejszenie pojemności zbiorników, o których mowa w ust. 2, do 50 m3, w przypadku budynków wysokich i wysokościowych o wysokości do 100 m: a) zawierających na wysokości powyżej 12 m jedynie strefy pożarowe zakwalifikowane do kategorii zagrożenia ludzi ZL IV, niezależnie od ich powierzchni, lub b) niezawierających stref pożarowych o powierzchni przekraczającej 750 m2; 2) stosowanie jednego wspólnego zbiornika o pojemności co najmniej 100 m3 dla grupy budynków wysokich i wysokościowych wzniesionych obok siebie, jeżeli zbiornik nie jest oddalony od żadnego z budynków o więcej niż 100 m; 3) stosowanie zbiorników o pojemności zmniejszonej niż wymienione w: a) ust. 2 i ust. 3 pkt 2 ‒ do 50 m3 w przypadku zapewnienia zasilania tych zbiorników w wodę z zewnętrznej sieci wodociągowej przeciwpożarowej o wydajności nie mniejszej niż 10 dm3/s, b) ust. 2 i ust. […]"}, {"ref": "§ 24 ust. 3 pkt 3 lit. c RPB – zmniejszenie do 6 m3 przy sieci 10 dm3/s", "kind": "akt", "act": "rpb", "label": "§ 24", "text": "3. Dopuszcza się: 1) zmniejszenie pojemności zbiorników, o których mowa w ust. 2, do 50 m3, w przypadku budynków wysokich i wysokościowych o wysokości do 100 m: a) zawierających na wysokości powyżej 12 m jedynie strefy pożarowe zakwalifikowane do kategorii zagrożenia ludzi ZL IV, niezależnie od ich powierzchni, lub b) niezawierających stref pożarowych o powierzchni przekraczającej 750 m2; 2) stosowanie jednego wspólnego zbiornika o pojemności co najmniej 100 m3 dla grupy budynków wysokich i wysokościowych wzniesionych obok siebie, jeżeli zbiornik nie jest oddalony od żadnego z budynków o więcej niż 100 m; 3) stosowanie zbiorników o pojemności zmniejszonej niż wymienione w: a) ust. 2 i ust. 3 pkt 2 ‒ do 50 m3 w przypadku zapewnienia zasilania tych zbiorników w wodę z zewnętrznej sieci wodociągowej przeciwpożarowej o wydajności nie mniejszej niż 10 dm3/s, b) ust. 2 i ust. […]"}, {"ref": "§ 24 ust. 5 RPB – warunek dodatkowej nasady 75 mm", "kind": "akt", "act": "rpb", "label": "§ 24", "text": "5. Warunkiem zastosowania dopuszczeń, o których mowa w ust. 3 pkt 3 i ust. 4, jest wyprowadzenie w elewacjach budynku, od strony drogi pożarowej, dodatkowej nasady o średnicy 75 mm, umożliwiającej zasilanie instalacji wodociągowej przeciwpożarowej z samochodów gaśniczych."}], "537": [{"ref": "§ 278 ust. 1 WT – wyjścia ewakuacyjne ze strefy garażu", "kind": "akt", "act": "wt", "label": "§ 278", "text": "§ 278. 1. Ze strefy pożarowej garażu, która posiada więcej niż 25 stanowisk postojowych i nie jest wyposażona w instalację wentylacji oddymiającej lub ma powierzchnię przekraczającą 1500 m2, należy zapewnić co najmniej dwa wyjścia ewakuacyjne, przy czym jednym z tych wyjść może być wjazd lub wyjazd."}], "538": [{"ref": "PN-B-02877-4:2025-07 – wymagania dla klap dymowych", "kind": "norma"}], "539": [{"ref": "§ 9 ust. 2 RPB – przechowywanie wyrobów pirotechnicznych widowiskowych", "kind": "akt", "act": "rpb", "label": "§ 9", "text": "2. Wyroby pirotechniczne widowiskowe przechowuje się w oddzielnych magazynach lub pomieszczeniach zaplecza, przeznaczonych wyłącznie do tego celu, wydzielonych ścianami wewnętrznymi i stropami o klasie odporności ogniowej odpowiednio co najmniej EI 60 i REI 60 i zamykanych drzwiami o klasie odporności ogniowej co najmniej EI 30."}], "540": [{"ref": "§ 19 ust. 3 pkt 2 i ust. 4 RPB – dobór hydrantów wewnętrznych", "kind": "akt", "act": "rpb", "label": "§ 19", "text": "3. Hydranty 52 muszą być stosowane: 1) w strefie pożarowej produkcyjnej i magazynowej o gęstości obciążenia ogniowego przekraczającej 500 MJ/m2 i powierzchni przekraczającej 200 m2; 2) w strefie pożarowej produkcyjnej i magazynowej o gęstości obciążenia ogniowego nieprzekraczającej 500 MJ/m2, w której znajduje się pomieszczenie o powierzchni przekraczającej 100 m2 i gęstości obciążenia ogniowego przekraczającej 1 000 MJ/m2; 3) przy wejściu do pomieszczeń magazynowych lub technicznych o powierzchni przekraczającej 200 m2 i gęstości obciążenia ogniowego przekraczającej 500 MJ/m2, usytuowanych w strefie pożarowej zakwalifikowanej do kategorii zagrożenia ludzi ZL I, ZL II, ZL III lub ZL V, znajdującej się w budynku niskim albo średniowysokim."}], "541": [{"ref": "PN-EN 12845+A1:2020 – typy tryskaczy i ograniczenia stosowania tryskaczy przyściennych", "kind": "norma"}], "542": [{"ref": "PN-B-02857:2017-04 – przeciwpożarowe zbiorniki wodne, usytuowanie stanowiska czerpania wody", "kind": "norma"}], "543": [{"ref": "§ 8 ust. 1 i 2 rozp. MRiRW z 13.01.2023 – odległości silosów na zboże i pasze", "kind": "akt", "act": "rolnicze", "label": "§ 8", "text": "§ 8. 1. Odległość silosów na zboże i pasze o pojemności do 100 ton powinna wynosić co najmniej: 1) 8 m od pomieszczeń przeznaczonych na pobyt ludzi; 2) 8 m od budynków innych niż budynki inwentarskie i gospodarcze; 3) 15 m od instalacji służących do otrzymywania biogazu rolniczego; 4) 15 m od składu węgla i koksu; 5) 4 m od granicy działki sąsiedniej."}], "544": [{"ref": "§ 261 WT – liczba siedzeń w rzędzie (limit 20 w rzędzie przyściennym)", "kind": "akt", "act": "wt", "label": "§ 261", "text": "§ 261. […] 2) szerokość przejść pomiędzy rzędami siedzeń nie mniejszą niż 0,45 m, przy czym odległość tę należy ustalać, biorąc pod uwagę odstęp między stałymi elementami siedzeń; 3) liczbę siedzeń w rzędzie nie większą niż 16 pomiędzy przejściami oraz 8 w rzędzie przyściennym, przy czym dopuszcza się zwiększenie liczby miejsc w rzędach odpowiednio do 40 i 20 pod warunkiem zwiększenia odstępu między rzędami siedzeń o 1 cm na każde dodatkowe siedzenie odpowiednio powyżej 16 lub 8; 4) szerokość przejść komunikacyjnych nie mniejszą niż 1,2 m przy liczbie osób do 150, a przy większej ich liczbie szerokość tę należy zwiększyć proporcjonalnie o 0,6 m na 100 osób; 5) rzędy siedzeń lub ławek trwale umocowane do podłogi albo siedzenia sztywno łączone ze sobą w rzędy oraz między rzędami."}], "545": [{"ref": "PN-EN 12101-13:2022 – klasy systemów różnicowania ciśnień", "kind": "norma"}], "546": [{"ref": "rozp. dot. sprzedaży materiałów wybuchowych/broni; § 240 WT", "kind": "akt", "act": "wt", "label": "§ 240", "text": "§ 240. […] 5. W bramach i ścianach przesuwanych na drogach ewakuacyjnych powinny znajdować się drzwi otwierane ręcznie albo w bezpośrednim sąsiedztwie tych bram i ścian powinny być umieszczone i wyraźnie oznakowane drzwi przeznaczone do celów ewakuacji. 6. Drzwi, bramy i inne zamknięcia otworów o wymaganej klasie odporności ogniowej lub dymoszczelności powinny być zaopatrzone w urządzenia, zapewniające samoczynne zamykanie otworu w razie pożaru. Należy też zapewnić możliwość ręcznego otwierania drzwi służących do ewakuacji. 7. Drzwi stanowiące wyjście ewakuacyjne z pomieszczenia, w którym może przebywać jednocześnie więcej niż 300 osób, oraz drzwi na drodze ewakuacyjnej z tego pomieszczenia, powinny być wyposażone w urządzenia przeciwpaniczne."}], "548": [{"ref": "§ 37 RPB – ocena zagrożenia wybuchem", "kind": "norma"}], "549": [{"ref": "dyrektywa ATEX – kategorie urządzeń a strefy pyłowe", "kind": "ue"}], "550": [{"ref": "PKN-CEN/TS 54-14:2020 – rozmieszczenie czujek ciepła", "kind": "norma"}], "551": [{"ref": "§ 268 ust. 1 pkt 5 WT – wydzielenie maszynowni wentylacyjnych i klimatyzacyjnych", "kind": "akt", "act": "wt", "label": "§ 268", "text": "§ 268. 1. Instalacje wentylacji mechanicznej i klimatyzacji w budynkach, z wyjątkiem budynków jednorodzinnych i rekreacji indywidualnej, powinny spełniać następujące wymagania: 1) przewody wentylacyjne powinny być wykonane i prowadzone w taki sposób, aby w przypadku pożaru nie oddziaływały siłą większą niż 1 kN na elementy budowlane, a także aby przechodziły przez przegrody w sposób umożliwiający kompensacje wydłużeń przewodu; 2) zamocowania przewodów do elementów budowlanych powinny być wykonane z materiałów niepalnych, zapewniających przejęcie siły powstającej w przypadku pożaru w czasie nie krótszym niż wymagany dla klasy odporności ogniowej przewodu lub klapy odcinającej; 3) w przewodach wentylacyjnych nie należy prowadzić innych instalacji; 4) filtry i tłumiki powinny być zabezpieczone przed przeniesieniem się do ich wnętrza palących się cząstek; […]"}, {"ref": "§ 8 WT – grupy wysokości budynków", "kind": "akt", "act": "wt", "label": "§ 8", "text": "§ 8. W celu określenia wymagań technicznych i użytkowych wprowadza się następujący podział budynków na grupy wysokości: 1) niskie (N) – do 12 m włącznie nad poziomem terenu lub mieszkalne o wysokości do 4 kondygnacji nadziemnych włącznie; 2) średniowysokie (SW) – ponad 12 m do 25 m włącznie nad poziomem terenu lub mieszkalne o wysokości ponad 4 do 9 kondygnacji nadziemnych włącznie; 3) wysokie (W) – ponad 25 m do 55 m włącznie nad poziomem terenu lub mieszkalne o wysokości ponad 9 do 18 kondygnacji nadziemnych włącznie; 4) wysokościowe (WW) – powyżej 55 m nad poziomem terenu."}], "552": [{"ref": "§ 272 ust. 1 WT – odległość od granicy niezabudowanej działki budowlanej", "kind": "akt", "act": "wt", "label": "§ 272", "text": "§ 272. 1. Odległość ściany zewnętrznej wznoszonego budynku od granicy sąsiedniej niezabudowanej działki budowlanej powinna wynosić co najmniej połowę odległości określonej w § 271 ust. 1–7, przyjmując, że na działce niezabudowanej będzie usytuowany budynek o przeznaczeniu określonym w miejscowym planie zagospodarowania przestrzennego, przy czym dla budynków PM należy przyjmować, że będzie on miał gęstość obciążenia ogniowego strefy pożarowej Q większą od 1000 MJ/m2, lecz nie większą niż 4000 MJ/m2, a w przypadku braku takiego planu – budynek ZL ze ścianą zewnętrzną, o której mowa w § 271 ust. 1."}, {"ref": "§ 271 ust. 1 i 2 WT – odległość ZL–ZL i zwiększenie o 50% przy dachu rozprzestrzeniającym ogień", "kind": "akt", "act": "wt", "label": "§ 271", "text": "§ 271. 1. Odległość między zewnętrznymi ścianami budynków niebędącymi ścianami oddzielenia przeciwpożarowego, a mającymi na powierzchni większej niż 65% klasę odporności ogniowej (E), określoną w § 216 ust. 1 w 5 kolumnie tabeli, nie powinna, z zastrzeżeniem ust. 2 i 3, być mniejsza niż odległość w metrach określona w poniższej tabeli: Rodzaj budynku oraz dla budynku PM maksymalna gęstość obciążenia ogniowego strefy pożarowej PM Q w MJ/m2 Rodzaj budynku oraz dla budynku PM maksymalna gęstość obciążenia ogniowego strefy pożarowej PM Q w MJ/m2 ZL IN PM Q ≤ 1000 1000 < Q ≤ 4000 Q > 4000 1 2 3 4 5 6 ZL 8 8 8 15 20 IN 8 8 8 15 20 PM Q ≤ 1000 8 8 8 15 20 PM 1000 < Q ≤ 4000 15 15 15 15 20 PM Q > 4000 20 20 20 20 20"}], "553": [{"ref": "PN-EN 12845+A1:2020 – dobór temperatury tryskaczy", "kind": "norma"}], "555": [{"ref": "§ 217 ust. 1 pkt 1 WT – klasa ścian oddzielających mieszkania", "kind": "akt", "act": "wt", "label": "§ 217", "text": "§ 217. 1. W budynkach ZL IV i ZL V klasa odporności ogniowej przegród wewnętrznych oddzielających mieszkania lub samodzielne pomieszczenia mieszkalne od dróg komunikacji ogólnej oraz od innych mieszkań i samodzielnych pomieszczeń mieszkalnych, z zastrzeżeniem § 216 ust. 1, powinna wynosić co najmniej: 1) dla ścian w budynku: a) niskim i średniowysokim – E I 30, b) wysokim i wysokościowym – E I 60; 2) dla stropów w budynku zawierającym 2 mieszkania – R E I 30."}, {"ref": "§ 8 pkt 2 WT – budynek mieszkalny do 9 kondygnacji jest średniowysoki", "kind": "akt", "act": "wt", "label": "§ 8", "text": "§ 8. W celu określenia wymagań technicznych i użytkowych wprowadza się następujący podział budynków na grupy wysokości: 1) niskie (N) – do 12 m włącznie nad poziomem terenu lub mieszkalne o wysokości do 4 kondygnacji nadziemnych włącznie; 2) średniowysokie (SW) – ponad 12 m do 25 m włącznie nad poziomem terenu lub mieszkalne o wysokości ponad 4 do 9 kondygnacji nadziemnych włącznie; 3) wysokie (W) – ponad 25 m do 55 m włącznie nad poziomem terenu lub mieszkalne o wysokości ponad 9 do 18 kondygnacji nadziemnych włącznie; 4) wysokościowe (WW) – powyżej 55 m nad poziomem terenu."}], "556": [{"ref": "PKN-CEN/TS 54-14:2020-09 – rozmieszczenie czujek pod stropami i dachami pochyłymi", "kind": "norma"}], "559": [{"ref": "PN-EN 81-72:2020 – dźwigi dla straży pożarnej", "kind": "norma"}], "560": [{"ref": "§ 5–6 RW – wymagana ilość wody do zewnętrznego gaszenia", "kind": "akt", "act": "rw", "label": "§ 5", "text": "§ 5. 1. Wymagana ilość wody do celów przeciwpożarowych do zewnętrznego gaszenia pożaru dla budynków użyteczności publicznej i zamieszkania zbiorowego oraz innych obiektów budowlanych o takim przeznaczeniu, służąca do zewnętrznego gaszenia pożaru, wynosi: 1) dla budynku o kubaturze brutto do 5 000 m3 i o powierzchni wewnętrznej do 1 000 m2 — 10 dm3/s z co najmniej jednego hydrantu o średnicy 80 mm lub 100 m3 zapasu wody w przeciwpożarowym zbiorniku wodnym; 2) dla budynków niewymienionych w pkt 1 — 20 dm3/s łącznie z co najmniej dwóch hydrantów o średnicy 80 mm lub 200 m3 zapasu wody w przeciwpożarowym zbiorniku wodnym; 3) dla obiektów wymienionych w § 3 ust. 1 pkt 3 — 10 dm3/s z co najmniej jednego hydrantu o średnicy 80 mm lub 100 m3 zapasu wody w przeciwpożarowym zbiorniku wodnym. 2. […]"}], "1001": [{"ref": "§ 306 pkt 2 projektu WT (projekt z 9.06.2025 r.) – instalowanie urządzeń fotowoltaicznych na dachu", "kind": "akt", "act": "wt-projekt", "label": "§ 306", "text": "§ 306. Urządzenie fotowoltaiczne na dachu budynku instaluje się w sposób ograniczający możliwość rozprzestrzeniania się pożaru pomiędzy strefami pożarowymi, przy spełnieniu łącznie następujących warunków: 1) dach, na którym instaluje się urządzenie fotowoltaiczne, jest NRO, a izolacja cieplna przekrycia dachu ma klasę reakcji na ogień inną niż F; 2) urządzenie fotowoltaiczne na dachu budynku instaluje się w sektorze o powierzchni nieprzekraczającej 1600 m2 i o rozpiętości nie większej niż 40 m; 3) między sektorami, o których mowa w pkt 2, jest zachowana odległość co najmniej 5 m; 4) urządzenie fotowoltaiczne instaluje się w odległości co najmniej 2,5 m od ściany oddzielenia przeciwpożarowego; warunku nie stosuje się, jeżeli ściana oddzielenia przeciwpożarowego jest wyprowadzona ponad górną krawędź urządzenia fotowoltaicznego, na wysokość co najmniej 0,3 m; […]"}], "1002": [{"ref": "§ 306 pkt 3 projektu WT (projekt z 9.06.2025 r.)", "kind": "akt", "act": "wt-projekt", "label": "§ 306", "text": "§ 306. Urządzenie fotowoltaiczne na dachu budynku instaluje się w sposób ograniczający możliwość rozprzestrzeniania się pożaru pomiędzy strefami pożarowymi, przy spełnieniu łącznie następujących warunków: 1) dach, na którym instaluje się urządzenie fotowoltaiczne, jest NRO, a izolacja cieplna przekrycia dachu ma klasę reakcji na ogień inną niż F; 2) urządzenie fotowoltaiczne na dachu budynku instaluje się w sektorze o powierzchni nieprzekraczającej 1600 m2 i o rozpiętości nie większej niż 40 m; 3) między sektorami, o których mowa w pkt 2, jest zachowana odległość co najmniej 5 m; 4) urządzenie fotowoltaiczne instaluje się w odległości co najmniej 2,5 m od ściany oddzielenia przeciwpożarowego; warunku nie stosuje się, jeżeli ściana oddzielenia przeciwpożarowego jest wyprowadzona ponad górną krawędź urządzenia fotowoltaicznego, na wysokość co najmniej 0,3 m; […]"}], "1003": [{"ref": "§ 306 pkt 4 projektu WT (projekt z 9.06.2025 r.)", "kind": "akt", "act": "wt-projekt", "label": "§ 306", "text": "§ 306. […] 2) urządzenie fotowoltaiczne na dachu budynku instaluje się w sektorze o powierzchni nieprzekraczającej 1600 m2 i o rozpiętości nie większej niż 40 m; 3) między sektorami, o których mowa w pkt 2, jest zachowana odległość co najmniej 5 m; 4) urządzenie fotowoltaiczne instaluje się w odległości co najmniej 2,5 m od ściany oddzielenia przeciwpożarowego; warunku nie stosuje się, jeżeli ściana oddzielenia przeciwpożarowego jest wyprowadzona ponad górną krawędź urządzenia fotowoltaicznego, na wysokość co najmniej 0,3 m; 5) urządzenie fotowoltaiczne instaluje się w odległości co najmniej 2 m od urządzenia służących do usuwania dymu."}], "1004": [{"ref": "§ 306 pkt 5 projektu WT (projekt z 9.06.2025 r.)", "kind": "akt", "act": "wt-projekt", "label": "§ 306", "text": "§ 306. […] 2) urządzenie fotowoltaiczne na dachu budynku instaluje się w sektorze o powierzchni nieprzekraczającej 1600 m2 i o rozpiętości nie większej niż 40 m; 3) między sektorami, o których mowa w pkt 2, jest zachowana odległość co najmniej 5 m; 4) urządzenie fotowoltaiczne instaluje się w odległości co najmniej 2,5 m od ściany oddzielenia przeciwpożarowego; warunku nie stosuje się, jeżeli ściana oddzielenia przeciwpożarowego jest wyprowadzona ponad górną krawędź urządzenia fotowoltaicznego, na wysokość co najmniej 0,3 m; 5) urządzenie fotowoltaiczne instaluje się w odległości co najmniej 2 m od urządzenia służących do usuwania dymu."}], "1005": [{"ref": "§ 307 pkt 2 projektu WT (projekt z 9.06.2025 r.)", "kind": "akt", "act": "wt-projekt", "label": "§ 307", "text": "§ 307. Urządzenie fotowoltaiczne na ścianie zewnętrznej budynku instaluje się w sposób ograniczający możliwość rozprzestrzeniania się pożaru pomiędzy kondygnacjami, przy spełnieniu łącznie następujących warunków: 1) ściana zewnętrzna, na której instaluje się urządzenie fotowoltaiczne ma klasę odporności ogniowej co najmniej EI 30 oraz jest NRO, a izolacja cieplna tej ściany ma klasę reakcji na ogień inną niż F; 2) urządzenie fotowoltaiczne instaluje się na wysokości nie większej niż 25 m od poziomu terenu; 3) urządzenie fotowoltaiczne instaluje się w odległości co najmniej 2 m od otworów okiennych, drzwiowych lub innych, umożliwiających rozprzestrzenianie się ognia, niezamkniętych zamknięciami przeciwpożarowymi, o klasie odporności ogniowej EI ściany zewnętrznej, na której są zainstalowane te urządzenia; […]"}], "1006": [{"ref": "§ 308 projektu WT (projekt z 9.06.2025 r.) – urządzenia fotowoltaiczne zintegrowane z budynkiem", "kind": "akt", "act": "wt-projekt", "label": "§ 308", "text": "§ 308. 1. Urządzenia fotowoltaiczne mogą być zintegrowane z budynkiem i stanowić jego ścianę zewnętrzną lub dach, jeżeli znajdują się na wysokości nie większej niż 25 m od poziomu terenu. 2. Dopuszcza się wykonanie urządzenia fotowoltaicznego, o których mowa w ust. 1, na wysokości powyżej 25 m, jeżeli budynek jest wyposażony w stałe samoczynne urządzenia gaśnicze wodne."}], "1007": [{"ref": "§ 305 ust. 1 i 2 projektu WT (projekt z 9.06.2025 r.) – usytuowanie falownika", "kind": "akt", "act": "wt-projekt", "label": "§ 305", "text": "§ 305. 1. Falownik umieszcza się na zewnątrz budynku lub w pomieszczeniu nieprzeznaczonym na pobyt ludzi, w odległości co najmniej 2 m od elementu budynku wykonanego z materiałów o klasie reakcji na ogień innej niż A1 lub A2, d0, w miejscu zapewniającym odpowiednią wentylację."}], "1008": [{"ref": "§ 303 ust. 1 i 2 projektu WT (projekt z 9.06.2025 r.) – prowadzenie przewodów DC", "kind": "akt", "act": "wt-projekt", "label": "§ 303", "text": "§ 303. 1. Przewód instalacji elektrycznej z urządzeniami fotowoltaicznymi, zwanej dalej „instalacją fotowoltaiczną”, po stronie prądu stałego prowadzi się na zewnątrz budynku."}], "1009": [{"ref": "§ 305 ust. 3 projektu WT (projekt z 9.06.2025 r.)", "kind": "akt", "act": "wt-projekt", "label": "§ 305", "text": "3. Instalację fotowoltaiczną wyposaża się w co najmniej następujące środki ochrony: 1) urządzenie do monitorowania stanu izolacji po stronie prądu stałego; 2) urządzenie do wykrywania zwarć łukowych."}], "1010": [{"ref": "§ 311 ust. 2 projektu WT (projekt z 9.06.2025 r.) – magazyny energii, progi detekcji", "kind": "akt", "act": "wt-projekt", "label": "§ 311", "text": "2. Urządzenia detekcyjne po przekroczeniu stężenia progowego: 1) 10 % dolnej granicy wybuchowości – mają uruchamiać sygnalizację alarmową i wentylację zapewniającą dwukrotne zwiększenie liczby wymian powietrza, w stosunku do liczby wymian powietrza w warunkach normalnej pracy; 2) 30 % dolnej granicy wybuchowości – mają odłączać akumulatory od źródeł zasilania do czasu rozcieńczenia atmosfery poniżej dopuszczalnego stężenia gazu."}], "1011": [{"ref": "§ 311 ust. 2 pkt 2 projektu WT (projekt z 9.06.2025 r.)", "kind": "akt", "act": "wt-projekt", "label": "§ 311", "text": "2. Urządzenia detekcyjne po przekroczeniu stężenia progowego: 1) 10 % dolnej granicy wybuchowości – mają uruchamiać sygnalizację alarmową i wentylację zapewniającą dwukrotne zwiększenie liczby wymian powietrza, w stosunku do liczby wymian powietrza w warunkach normalnej pracy; 2) 30 % dolnej granicy wybuchowości – mają odłączać akumulatory od źródeł zasilania do czasu rozcieńczenia atmosfery poniżej dopuszczalnego stężenia gazu."}], "1012": [{"ref": "§ 310 ust. 1–3 projektu WT (projekt z 9.06.2025 r.) – wyłącznik awaryjny magazynu energii", "kind": "akt", "act": "wt-projekt", "label": "§ 310", "text": "§ 310. 1. Budynek, w którym jednym ze źródeł energii elektrycznej jest akumulatorowy system magazynowania energii elektrycznej, wyposaża się w przeznaczony do użycia przez ekipy ratownicze wyłącznik awaryjny, odłączający ten system od wszystkich obwodów wejściowych i wyjściowych."}], "1013": [{"ref": "§ 237 WT – długość przejścia ewakuacyjnego i dopuszczalne powiększenia", "kind": "akt", "act": "wt", "label": "§ 237", "text": "§ 237. 1. W pomieszczeniach, od najdalszego miejsca, w którym może przebywać człowiek, do wyjścia ewakuacyjnego na drogę ewakuacyjną lub do innej strefy pożarowej albo na zewnątrz budynku, powinno być zapewnione przejście, zwane dalej „przejściem ewakuacyjnym”, o długości nieprzekraczającej: 1) w strefach pożarowych ZL – 40 m; 2) w strefach pożarowych PM o gęstości obciążenia ogniowego przekraczającej 500 MJ/m2 w budynku o więcej niż jednej kondygnacji nadziemnej – 75 m; 3) w strefach pożarowych PM, o obciążeniu ogniowym nieprzekraczającym 500 MJ/m2, w budynku o więcej niż jednej kondygnacji nadziemnej oraz w strefach pożarowych PM w budynku o jednej kondygnacji nadziemnej bez względu na wielkość obciążenia ogniowego – 100 m. 2. W pomieszczeniu zagrożonym wybuchem długość przejścia ewakuacyjnego, o którym mowa w ust. 1 pkt 2 i 3, nie powinna przekraczać 40 m. 3. […]"}], "1014": [{"ref": "§ 237 WT – długość przejścia ewakuacyjnego", "kind": "akt", "act": "wt", "label": "§ 237", "text": "§ 237. […] 3. Dopuszcza się prowadzenie przez pomieszczenie zagrożone wybuchem przejścia ewakuacyjnego z innego pomieszczenia, jeżeli pomieszczenia te są powiązane funkcjonalnie. 4. Jeżeli z przewidywanego przeznaczenia pomieszczenia nie wynika jednoznacznie sposób jego zagospodarowania, projektowa długość przejścia ewakuacyjnego nie może być większa niż 80% długości określonej w ust. 1 i 2. 5. W pomieszczeniach o wysokości przekraczającej 5 m długość przejść, o których mowa w ust. 1 i 2, może być powiększona o 25%. 6. Długości przejść, o których mowa w ust. 1 i 2, mogą być powiększone pod warunkiem zastosowania: 1) stałych samoczynnych urządzeń gaśniczych wodnych – o 50%; 2) samoczynnych urządzeń oddymiających uruchamianych za pomocą systemu wykrywania dymu – o 50%. 7. Powiększenia, o których mowa w ust. 5 i 6 pkt 1 i 2, podlegają sumowaniu. 8. […]"}], "1015": [{"ref": "§ 239 WT – szerokość drzwi stanowiących wyjścia ewakuacyjne", "kind": "akt", "act": "wt", "label": "§ 239", "text": "§ 239. 1. Łączną szerokość drzwi w świetle, stanowiących wyjścia ewakuacyjne z pomieszczenia, należy obliczać proporcjonalnie do liczby osób mogących przebywać w nim równocześnie, przyjmując co najmniej 0,6 m szerokości na 100 osób, przy czym najmniejsza szerokość drzwi w świetle ościeżnicy powinna wynosić 0,9 m, a w przypadku drzwi służących do ewakuacji do 3 osób – 0,8 m. 2. Drzwi stanowiące wyjście ewakuacyjne powinny otwierać się na zewnątrz pomieszczeń: 1) zagrożonych wybuchem; 2) do których jest możliwe niespodziewane przedostanie się mieszanin wybuchowych lub substancji trujących, duszących bądź innych, mogących utrudnić ewakuację; 3) przeznaczonych do jednoczesnego przebywania ponad 50 osób; 4) przeznaczonych dla ponad 6 osób o ograniczonej zdolności poruszania się. 3. […]"}], "1016": [{"ref": "§ 12 RW – parametry drogi pożarowej (promień zewnętrznej krawędzi łuku)", "kind": "akt", "act": "rw", "label": "§ 12", "text": "§ 12. […] 9. Droga pożarowa powinna zapewniać przejazd bez cofania lub powinna być zakończona placem manewrowym o wymiarach 20 m x 20 m, względnie można przewidzieć inne rozwiązania umożliwiające zawrócenie pojazdu, z zastrzeżeniem ust. 10. 10. Dopuszcza się wykonanie odcinka drogi pożarowej o długości nie większej niż 15 m, z którego wyjazd jest możliwy jedynie przez cofanie pojazdu. 11. Najmniejszy promień zewnętrznego łuku drogi pożarowej nie może wynosić mniej niż 11 m. 12. Drogi pożarowe oraz place manewrowe w miejscach innych niż wymienione w ust. 2 i 3 mogą być usytuowane w odległości mniejszej niż 5 m od chronionego budynku, pod warunkiem że ściana zewnętrzna budynku na tym odcinku oraz w odległości do 5 m od niego posiada klasę odporności ogniowej wymaganą dla ściany oddzielenia pożarowego tego budynku."}], "1017": [{"ref": "PN-EN 1838 – oświetlenie awaryjne, czasy osiągania natężenia", "kind": "norma"}], "1018": [{"ref": "§ 2 RPB – definicja materiałów niebezpiecznych pożarowo", "kind": "akt", "act": "rpb", "label": "§ 2", "text": "§ 2. 1. Ilekroć w rozporządzeniu jest mowa o: 1) materiałach niebezpiecznych pożarowo ‒ należy przez to rozumieć: a) gazy palne, b) ciecze palne o temperaturze zapłonu poniżej 328,15 K (55ºC), c) materiały wytwarzające w zetknięciu z wodą gazy palne, d) materiały zapalające się samorzutnie na powietrzu, e) materiały wybuchowe i wyroby pirotechniczne, f) materiały ulegające samorzutnemu rozkładowi lub polimeryzacji, g) materiały mające skłonności do samozapalenia, h) materiały inne niż wymienione w lit. a‒g, jeśli sposób ich składowania, przetwarzania lub innego wykorzystania może spowodować powstanie pożaru; 2) pasie przeciwpożarowym ‒ należy przez to rozumieć system drzewostanów różnej szerokości poddanych specjalnym zabiegom gospodarczym i porządkowym lub powierzchni wylesionych i oczyszczonych do warstwy mineralnej; […]"}], "1019": [{"ref": "§ 37 RPB – ocena zagrożenia wybuchem i wyznaczanie stref", "kind": "norma"}], "1020": [{"ref": "dyrektywa ATEX 2014/34/UE – kategorie urządzeń a strefy zagrożenia wybuchem", "kind": "ue"}], "1021": [{"ref": "PN-EN 12845 – wydatek tryskacza (współczynnik wypływu K)", "kind": "norma"}], "1022": [{"ref": "§ 256 WT – podział korytarzy stanowiących drogi ewakuacyjne", "kind": "akt", "act": "wt", "label": "§ 256", "text": "§ 256. 1. Długość drogi ewakuacyjnej od wyjścia z pomieszczenia na tę drogę do wyjścia do innej strefy pożarowej lub na zewnątrz budynku, zwanej dalej „dojściem ewakuacyjnym”, mierzy się wzdłuż osi drogi ewakuacyjnej. W przypadku zakończenia dojścia ewakuacyjnego przedsionkiem przeciwpożarowym, długość tę mierzy się do pierwszych drzwi tego przedsionka. 2. Za równorzędne wyjściu do innej strefy pożarowej, o którym mowa w ust. 1, uważa się wyjście do obudowanej klatki schodowej, zamykanej drzwiami o klasie odporności ogniowej co najmniej E I 30, wyposażonej w urządzenia zapobiegające zadymieniu lub służące do usuwania dymu, a w przypadku, o którym mowa w § 246 ust. 5 – zamykanej drzwiami dymoszczelnymi. 3. […]"}], "1023": [{"ref": "§ 6–9 RW / PN-B-02857 – zapas wody (wzór obliczeniowy nie jest podany wprost w rozporządzeniu)", "kind": "norma"}], "1024": [{"ref": "§ 236 WT – kierunek otwierania drzwi ewakuacyjnych", "kind": "akt", "act": "wt", "label": "§ 236", "text": "§ 236. 1. Z pomieszczeń przeznaczonych na pobyt ludzi powinna być zapewniona możliwość ewakuacji w bezpieczne miejsce na zewnątrz budynku lub do sąsiedniej strefy pożarowej, bezpośrednio albo drogami komunikacji ogólnej, zwanymi dalej „drogami ewakuacyjnymi”. 2. Ze strefy pożarowej, o której mowa w ust. 1, powinno być wyjście bezpośrednio na zewnątrz budynku lub przez inną strefę pożarową, z zastrzeżeniem § 227 ust. 5. 3. Wyjścia z pomieszczeń na drogi ewakuacyjne powinny być zamykane drzwiami. 4. Drzwi stanowiące wyjście ewakuacyjne z budynku przeznaczonego dla więcej niż 50 osób powinny otwierać się na zewnątrz. Wymaganie to nie dotyczy budynku wpisanego do rejestru zabytków. 5. W wyjściu ewakuacyjnym z budynku dopuszcza się stosowanie drzwi rozsuwanych spełniających wymagania określone w § 240 ust. 4. 6. […]"}]};
